window.CLINICAL_ATLAS = [{"id":"mental-health","title":"Mental health","description":"Twenty-one presentations covering mood, anxiety, trauma, psychosis, dependence and complex risk. Each includes three changed circumstances.","icon":"01","reviewed":"2026-11-11","cases":[{"id":"mh-depression","title":"Depression: first presentation","summary":"Establish severity through symptoms, functioning and context","presentation":"An adult reports six weeks of loss of interest, low mood and reduced functioning. They ask whether medication is the only option.","assessment":["Establish severity through symptoms, functioning and context","Ask directly about suicide, self-harm, intent, access and previous attempts","Check previous elevated mood, psychosis, substances, medicines and physical contributors","Explore prior treatment, support and the patient’s priorities"],"management":[{"step":"1. Formulate together","detail":"Explain the working diagnosis and how it relates to symptoms; distinguish severity from a questionnaire score alone."},{"step":"2. Choose treatment","detail":"For less severe depression discuss guided self-help and psychological options; antidepressants are not routinely first-line unless preferred. More severe illness needs a discussion of psychological and medication options, including combined treatment."},{"step":"3. Prescribe thoughtfully","detail":"If medication is chosen, check suitability, interactions and overdose risk; discuss onset, adverse effects, adherence and withdrawal. Use current prescribing guidance for the actual medicine."},{"step":"4. Make the plan practical","detail":"Address work, financial stress, sleep, activity and support without implying that lifestyle replaces needed treatment. Agree a written safety plan when appropriate."}],"discussion":[{"cue":"Does this mean tablets are my only option?","response":"Depression can affect sleep, energy and concentration as well as mood. We can compare suitable treatment choices and choose a first step that fits how much this is affecting you and what matters to you.","simple":"There are different suitable treatments. Let’s discuss how this affects you and choose a plan together.","why":"Connect the assessment and functional impact to a shared treatment discussion.","id":"mh-depression-talk-1"},{"cue":"I would rather try a talking treatment. Is that allowed?","response":"Your preference matters. Let’s discuss which psychological or supported self-help options fit the severity and your needs, what is available and how we will review things while you wait. If the assessment suggests a more active or combined plan, I will explain why.","simple":"Let’s discuss an appropriate talking treatment and a review plan. I will explain if the assessment suggests other treatment as well.","why":"For less severe depression, antidepressants are not routinely first-line unless preferred; more severe illness needs discussion of the appropriate options rather than assuming the same plan for everyone.","id":"mh-depression-talk-2"},{"cue":"If I start a tablet, will I feel better tomorrow?","response":"It usually takes time for the benefit to develop. Some side effects can occur earlier, so we should discuss what to expect from the actual medicine and arrange an early review rather than leave you to manage alone.","simple":"The benefit is not usually immediate. We will discuss side effects and review how you are getting on.","why":"Explain onset, early harms and support without promising an exact individual response date.","id":"mh-depression-talk-3"},{"cue":"When should we review after starting it?","response":"We would usually arrange the first review within two weeks. If you are aged 18 to 25, or there is particular concern about suicide risk, that is usually within one week. Any immediate safety concern needs help sooner; the review date is not a reason to wait.","simple":"Usually we review within two weeks, or one week for ages 18–25 or particular suicide concern. Urgent problems need help sooner.","why":"Use the current NG222 age/risk rule for depression, not a blanket under-30 rule borrowed from GAD guidance.","id":"mh-depression-talk-4"},{"cue":"I am ashamed to say I sometimes wish I would not wake up.","response":"Thank you for telling me. I want to understand how safe you are feeling. Have you had thoughts about ending your life? I will ask about any plans or actions and what support we need to arrange now.","simple":"Thank you for telling me. Have you thought about ending your life? Let’s check your safety and arrange the support you need.","why":"Ask directly, one question at a time, and use the answer to determine urgency. A routine treatment plan does not replace an immediate safety assessment.","id":"mh-depression-talk-5"}],"variations":[{"label":"Current suicidal intent","change":"A plan and access to tablets emerge.","action":"Move to immediate safety assessment and emergency or crisis intervention appropriate to danger; do not wait for routine treatment to work.","phrase":"I am glad you told me. We need to arrange help to keep you safe today."},{"label":"Previous overactivity","change":"They describe several days of little sleep and disinhibition.","action":"Assess possible bipolar disorder and seek specialist assessment; do not simply increase an antidepressant.","phrase":"That earlier period changes how we should assess and treat this."},{"label":"Medication declined","change":"The patient prefers psychological treatment.","action":"Explore reasons, offer appropriate therapy and active monitoring; reassess urgency and preferences.","phrase":"We can start with an appropriate talking treatment and agree when to review it."}],"links":[{"label":"NICE NG222 — recommendations","url":"https://www.nice.org.uk/guidance/ng222/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE CG185 — recommendations","url":"https://www.nice.org.uk/guidance/cg185/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not apply an under-30 review rule or diagnose severity using PHQ-9 alone."],"followUp":"Review treatment response and safety within an agreed interval. After starting an antidepressant, usual initial review is within 2 weeks, or 1 week for ages 18–25 or particular suicide concern; urgent risk needs earlier action.","reviewed":"2026-11-12","tags":["depression","first","presentation"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Move to immediate safety assessment and emergency or crisis intervention appropriate to danger; do not wait for routine treatment to work. I am glad you told me. We need to arrange help to keep you safe today.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-minority-stress","title":"Depression with rejection and minority stress","summary":"Assess depressive symptoms, function and immediate safety","presentation":"An adult feels isolated after family rejection related to sexuality and beliefs. They worry that discussing this will lead to judgement.","assessment":["Assess depressive symptoms, function and immediate safety","Ask which relationships are safe and supportive","Explore discrimination, housing, financial dependence and coercion","Ask what support the patient wants without assumptions"],"management":[{"step":"1. Validate","detail":"Acknowledge the impact of rejection without treating identity or beliefs as an illness."},{"step":"2. Treat the clinical problem","detail":"Offer depression treatment matched to severity and preference; check prior response and adverse effects."},{"step":"3. Find safe support","detail":"Explore trusted friends and inclusive support services. Family work is optional and only appropriate if wanted and safe."},{"step":"4. Maintain privacy","detail":"Agree safe contact and consent for any information sharing; assess safeguarding when relevant."}],"discussion":[{"cue":"I am worried you will judge me as well.","response":"You deserve respectful care here. I would like to understand how the rejection has affected your health and what help feels safe for you. We do not need to make assumptions about your identity, beliefs or relationships.","simple":"You deserve respectful care. Let’s discuss how this affects you and what support feels safe.","why":"Treat the person as an individual, acknowledge discrimination and assess the clinical problem without treating identity as an illness.","id":"mh-minority-stress-talk-1"},{"cue":"Please do not tell my family about this.","response":"Let’s agree who, if anyone, you want involved and how we can contact you safely. I will explain any necessary information sharing if a serious safety concern arises, as far as it is safe and possible to do so.","simple":"Who would you want involved, if anyone? Let’s agree safe contact and discuss any safety-related sharing clearly.","why":"Respect privacy and consent without promising absolute secrecy in every circumstance; do not assume family involvement is helpful.","id":"mh-minority-stress-talk-2"},{"cue":"They read my messages. Could you just text the appointment?","response":"Before sending anything, let’s check what would be safe. Is there a number, contact method or time that only you can use privately? We should record that arrangement and check whether you need help with the situation at home.","simple":"Let’s agree a genuinely safe way to contact you before sending a message.","why":"Use the answer to change contact arrangements and assess coercion or safeguarding needs; a revealing text is not neutral.","id":"mh-minority-stress-talk-3"},{"cue":"Would getting back in touch with them make the depression better?","response":"That may be something you want to explore, but it should be your choice and safe for you. We can discuss boundaries and support for that conversation alongside treatment for the mood symptoms. I cannot promise how your family will respond.","simple":"We can discuss safe, patient-led contact if you want it, alongside treatment and support.","why":"Do not prescribe reconciliation as treatment or make it a condition of receiving care.","id":"mh-minority-stress-talk-4"},{"cue":"What can we actually do after today?","response":"Let’s agree the treatment or support you want to start, who will arrange it and a review of your mood and safety. Which safe person or service could you contact between appointments? If you feel unable to stay safe, we need urgent help rather than wait for the review.","simple":"Let’s name the next treatment step, safe support, review date and earlier-help plan.","why":"Connect a validating conversation to feasible clinical and social actions with named ownership.","id":"mh-minority-stress-talk-5"}],"variations":[{"label":"Unsafe family contact","change":"Family members monitor messages.","action":"Agree safe contact and assess coercion; do not send revealing information.","phrase":"How can we contact you without putting you at risk?"},{"label":"Existing medicine ineffective","change":"Treatment has not helped.","action":"Review adherence, duration, diagnosis and comorbidity before changing treatment.","phrase":"Let us check what has and has not changed before choosing the next step."},{"label":"Support desired","change":"They want to repair a relationship.","action":"Explore patient-led support, boundaries and counselling without promising reconciliation.","phrase":"We can discuss support for that conversation if it is safe and something you want."}],"links":[{"label":"NICE NG222 — recommendations","url":"https://www.nice.org.uk/guidance/ng222/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE CG138: respectful, individual care","url":"https://www.nice.org.uk/guidance/cg138/chapter/recommendations","use":"Privacy, respect, communication and avoiding assumptions."}],"pitfalls":["Do not assume that sexuality, religion or lack of religion determines symptoms, preferences or available support."],"followUp":"Agree early review of mood, safety and access to therapy; use antidepressant-specific monitoring when medication changes.","reviewed":"2026-11-13","tags":["depression","with","rejection","and"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Agree safe contact and assess coercion; do not send revealing information. How can we contact you without putting you at risk?","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-sleep","title":"Low mood and a sleeping-tablet request","summary":"Distinguish sleep-onset and maintenance problems and duration","presentation":"A worker reports persistent insomnia, stress and declining mood. They ask for a quick prescription and operate machinery.","assessment":["Distinguish sleep-onset and maintenance problems and duration","Assess mood, suicide risk, mania, alcohol, drugs and sedating medicines","Ask about shift work, caffeine, sleep apnoea symptoms and restless legs","Explore what relief the patient hopes to gain"],"management":[{"step":"1. Identify causes","detail":"Assess depression, anxiety, substance effects and physical contributors rather than treating insomnia in isolation."},{"step":"2. Compare options","detail":"Discuss appropriate psychological treatment, including CBT-based approaches to insomnia and mood where indicated; agree manageable sleep routines."},{"step":"3. Make prescribing safe","detail":"Do not use a hypnotic as an automatic response. Check interactions, dependence, alertness, driving and work risks before any individualised medicine decision."},{"step":"4. Address stress","detail":"Offer practical support for work or caring pressures and arrange follow-up."}],"discussion":[{"cue":"Please just give me something so I can sleep tonight.","response":"I want to help you sleep, and we also need to understand what is keeping the problem going. Any medicine needs to be safe with your work, mood and anything else you take. Let’s agree an assessment and a practical first step.","simple":"Let’s help the sleep problem and check what is causing it. Any treatment must be safe with your work and other medicines.","why":"Acknowledge the request while assessing insomnia in context rather than automatically prescribing a hypnotic.","id":"mh-sleep-talk-1"},{"cue":"Does talking treatment really help a sleep problem?","response":"A treatment such as CBT for insomnia works on patterns that can keep sleep difficulties going. We can discuss whether it fits your situation, how to access it and what support you need while you wait. We should also address mood or another cause when present.","simple":"CBT for insomnia can address patterns that keep the problem going. Let’s discuss suitable access and support.","why":"Offer appropriate treatment and actual arrangements rather than a sleep-hygiene leaflet alone or implying that every sleep problem has the same cause.","id":"mh-sleep-talk-2"},{"cue":"Is a short course of sleeping tablets automatically safe for my machinery job?","response":"A short course does not remove the risk of impaired alertness. We need to check the actual medicine, your sleepiness, alcohol or other sedatives and your work duties. Do not operate machinery or drive if your alertness is impaired; we should arrange a safe practical plan.","simple":"Even short-term medicine can affect alertness. We need a safe plan for your medicine, driving and machinery work.","why":"Assess individual occupational and medicine risk; do not promise safety from the course length or invent a universal driving-notification rule.","id":"mh-sleep-talk-3"},{"cue":"I have only slept three hours, but I feel unusually energetic and do not need more.","response":"That is different from feeling exhausted and unable to sleep. I need to ask about changes in mood, energy, behaviour and judgement, and whether urgent assessment is needed. We should not assume this is an ordinary insomnia problem.","simple":"Unusually high energy with little need for sleep changes what we need to assess.","why":"Consider mania and urgency rather than prescribing a sedative without assessment.","id":"mh-sleep-talk-4"},{"cue":"Can I use alcohol with the tablet to make it work better?","response":"Alcohol and sedating medicines can be a dangerous combination. We need to check what you have taken and how you feel, and act on any immediate danger. Severe breathing difficulty or inability to wake normally needs 999. Let’s make the sleep plan safe rather than combine them.","simple":"Do not combine alcohol with sedating medicine. We need to check current use and danger; severe breathing difficulty or inability to wake needs 999.","why":"Assess current co-use, respiratory risk and alcohol dependence/withdrawal; do not replace clinical assessment with a generic warning.","id":"mh-sleep-talk-5"}],"variations":[{"label":"Heavy alcohol use","change":"Morning shaking and regular alcohol emerge.","action":"Assess dependence and withdrawal; avoid adding sedation and arrange supported care.","phrase":"Combining alcohol and sleeping tablets could be dangerous."},{"label":"Little need for sleep","change":"They feel energised after very little sleep.","action":"Assess possible mania and arrange urgent specialist review if suspected.","phrase":"Feeling unusually energised changes what we need to check."},{"label":"Safety-critical work","change":"They drive professionally.","action":"Discuss alertness and current fitness-to-drive requirements; arrange practical occupational support.","phrase":"We need a plan that also keeps you safe at work."}],"links":[{"label":"NICE NG222 — recommendations","url":"https://www.nice.org.uk/guidance/ng222/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE CG113 — recommendations","url":"https://www.nice.org.uk/guidance/cg113/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE NG215 — recommendations","url":"https://www.nice.org.uk/guidance/ng215/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NHS: insomnia","url":"https://www.nhs.uk/conditions/insomnia/","use":"Patient explanation, CBT for insomnia and safe sleep treatment."}],"pitfalls":["Do not prescribe mirtazapine while concealing that it is an antidepressant, or promise a sedative is safe because the course is short."],"followUp":"Agree a specific review of sleep, mood, functioning and adverse effects; assess urgent risk immediately.","reviewed":"2026-11-12","tags":["low","mood","and","a"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Assess dependence and withdrawal; avoid adding sedation and arrange supported care. Combining alcohol and sleeping tablets could be dangerous.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-palliative","title":"Depression and distress in advanced illness","summary":"Clarify pain, delirium, breathlessness and other distressing symptoms","presentation":"A person with advanced cancer asks for extra sedating medication and says they no longer see a point in living. Pain and loneliness may be contributing.","assessment":["Clarify pain, delirium, breathlessness and other distressing symptoms","Ask directly about suicidal intent, plans, access and any ingestion","Explore goals, understanding of illness, bereavement and support","Review actual medicines, supply, renal function and care plan"],"management":[{"step":"1. Assess safety today","detail":"A request for extra medicine with hopelessness needs direct assessment; emergency care is required for overdose or immediate danger."},{"step":"2. Relieve suffering","detail":"Coordinate symptom assessment and treatment with palliative clinicians. Do not withhold appropriate analgesia because suicide is being assessed."},{"step":"3. Coordinate support","detail":"Involve community nursing, palliative care and mental health services according to need; agree safe prescribing and storage collaboratively."},{"step":"4. Plan continuity","detail":"Address loneliness, carer burden and preferred care setting. Discuss future-care planning separately from immediate crisis management."}],"discussion":[{"cue":"I do not see the point of going on like this.","response":"I am sorry things feel so difficult. When you say you cannot go on, do you mean you wish the suffering would stop, or have you been thinking about ending your life? I want to understand, relieve the symptoms and check what support is needed now.","simple":"Could you tell me what you mean by not wanting to go on? Let’s assess your safety and treat what feels unbearable.","why":"Explore the meaning directly without assuming either active intent or an absence of risk because the person has advanced illness.","id":"mh-palliative-talk-1"},{"cue":"Please just give me extra sedating medicine.","response":"I want to relieve your distress, and I need to check what you have already taken, the pain and other symptoms, and whether you feel safe. We can involve the palliative team to agree symptom treatment and a safe prescribing plan.","simple":"Let’s check your symptoms and medicines, then agree safe relief with the palliative team.","why":"Assess overdose, interactions and clinical needs; neither an automatic extra supply nor withholding appropriate symptom relief is a complete plan.","id":"mh-palliative-talk-2"},{"cue":"Does asking about suicide mean you will stop my pain relief?","response":"Your pain still needs treatment. Checking safety helps us make the whole plan safer; it is not a reason to abandon symptom relief. Let’s agree the appropriate treatment, support and medicine arrangements with the team.","simple":"We still need to treat the pain while making a safe plan for your distress and medicines.","why":"Keep symptom care and suicide assessment connected, with appropriate coordination rather than a punitive response.","id":"mh-palliative-talk-3"},{"cue":"My family says I am suddenly confused. Is that just depression?","response":"A sudden or fluctuating change needs urgent clinical assessment for possible physical causes or medicine effects. We should contact the appropriate clinical team now and use your agreed care plan; immediate danger or serious acute illness needs emergency help.","simple":"Sudden confusion needs urgent assessment. Let’s contact the clinical team now and follow the appropriate care plan.","why":"Do not label an acute change as depression or inevitable dying; assess promptly while respecting goals of care and clinical urgency.","id":"mh-palliative-talk-4"},{"cue":"I am most frightened of being alone at night.","response":"Let’s make that part of the care plan. Who can be contacted at night, what support is actually available and what would happen if symptoms are not controlled? I will check the arrangements with the team so you have a usable plan.","simple":"Let’s confirm the real night-time support, contact number and backup plan with the team.","why":"An out-of-hours contact and named coordination address a concrete source of distress without promising unavailable care.","id":"mh-palliative-talk-5"}],"variations":[{"label":"Active plan","change":"They intend to take the available medicine.","action":"Arrange immediate emergency/crisis assessment and safe support; address means access without abandoning symptom relief.","phrase":"We need help now, and I will stay involved while it is arranged."},{"label":"New confusion","change":"The change is sudden and fluctuating.","action":"Assess possible delirium and reversible causes urgently rather than labelling it depression.","phrase":"This sudden change may have a physical cause we need to assess."},{"label":"Loneliness without intent","change":"They deny intent but feel unsupported.","action":"Assess the full picture and arrange active psychosocial and palliative follow-up; do not declare safety from denial alone.","phrase":"Let us make a practical plan for support as well as symptoms."}],"links":[{"label":"NICE NG222 — recommendations","url":"https://www.nice.org.uk/guidance/ng222/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE NG225 — recommendations","url":"https://www.nice.org.uk/guidance/ng225/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE NG142: coordinated end-of-life care","url":"https://www.nice.org.uk/guidance/ng142/chapter/recommendations","use":"Individual needs, multipractitioner care, coordination and out-of-hours arrangements."}],"pitfalls":["Do not treat a DNACPR discussion as the response to current suicidal intent."],"followUp":"Match follow-up to immediate risk and symptom severity; confirm who will contact the patient today and out of hours.","reviewed":"2026-11-13","tags":["depression","and","distress","in"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Arrange immediate emergency/crisis assessment and safe support; address means access without abandoning symptom relief. We need help now, and I will stay involved while it is arranged.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-adjustment","title":"Low mood after relationship breakdown","summary":"Assess duration, severity, function and suicide risk","presentation":"An adult has become tearful and unable to concentrate after separation. They request a letter for work.","assessment":["Assess duration, severity, function and suicide risk","Distinguish an understandable stress response from depressive illness without minimising either","Explore alcohol, sleep, housing, finances and dependants","Check domestic abuse or coercion when indicated"],"management":[{"step":"1. Validate","detail":"Acknowledge the loss and disruption, and ask what is hardest now."},{"step":"2. Formulate","detail":"Avoid diagnosing major depression solely because a stressor is present, or excluding it because there is a stressor."},{"step":"3. Support","detail":"Agree practical help, structured routine, trusted support and appropriate psychological care; consider a fit note based on functional assessment."},{"step":"4. Review","detail":"Arrange active monitoring and reassess if symptoms persist, worsen or meet criteria for depression."}],"discussion":[{"cue":"It is only a separation. I should be coping better.","response":"A relationship breakdown can affect sleep, concentration, mood and daily life. You do not have to minimise what is happening. Let’s assess the effect on you and whether there is a depression or another problem needing specific treatment.","simple":"This is affecting you and deserves help. Let’s assess the symptoms and what treatment or support fits.","why":"A life event neither proves nor excludes depressive illness; assess duration, severity, function and safety.","id":"mh-adjustment-talk-1"},{"cue":"Will a tablet take the pain of this away?","response":"Medicine is not automatically the right response to every painful event. We should discuss the assessment, the symptoms we are trying to treat and suitable options, including practical and psychological support. If medication is appropriate, I will explain why and how we would review it.","simple":"Let’s decide what needs treating and compare appropriate support and treatment, rather than assume a tablet is always the answer.","why":"Offer assessment-led treatment without dismissing distress or making an unsupported prescribing promise.","id":"mh-adjustment-talk-2"},{"cue":"Can you give me a letter saying I cannot work?","response":"Let’s look at how your health affects the tasks you need to do and whether any adjustments would be realistic. A fit note, if appropriate, can give health-based advice about work; it is not a judgement about who was at fault in the separation.","simple":"Let’s assess what you can manage at work and whether a fit note or adjustments would help.","why":"Use the functional assessment and current fit-note guidance, rather than issue a predetermined or non-medical verdict.","id":"mh-adjustment-talk-3"},{"cue":"I am scared of how my former partner will react if they find out I came.","response":"Is it safe for us to talk now? We can agree a safe contact method and discuss what has been happening and any support you need. I would not arrange a joint conversation without checking that it is wanted and safe.","simple":"Let’s check your safety and how we can contact you before arranging anything involving your former partner.","why":"A fear response changes the assessment; do not automatically recommend joint counselling where coercion or danger may be present.","id":"mh-adjustment-talk-4"},{"cue":"What if I am still feeling worse next week?","response":"We should agree a review date and how to contact us sooner if things deteriorate. If you develop thoughts of acting on self-harm or cannot stay safe, seek urgent help rather than wait. At review we will reassess the symptoms and treatment, not simply keep calling it stress.","simple":"Let’s book a review and an earlier-help route. Continuing deterioration needs reassessment.","why":"Active monitoring has an owner, timing and a contingency; it is not open-ended reassurance.","id":"mh-adjustment-talk-5"}],"variations":[{"label":"Immediate self-harm risk","change":"The patient has made preparations.","action":"Arrange urgent or emergency assessment according to danger.","phrase":"Your safety needs our attention today."},{"label":"Coercive relationship","change":"They fear a partner’s reaction.","action":"Check safe communication and safeguarding needs; avoid unsafe joint counselling.","phrase":"Is it safe for us to discuss this and contact you?"},{"label":"Symptoms persistent","change":"Function and mood continue to deteriorate.","action":"Reassess diagnosis, severity and treatment needs rather than repeatedly attributing symptoms to stress.","phrase":"The persistence means we should review the treatment plan."}],"links":[{"label":"NICE NG222 — recommendations","url":"https://www.nice.org.uk/guidance/ng222/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE NG225 — recommendations","url":"https://www.nice.org.uk/guidance/ng225/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"GOV.UK: fit-note guidance for healthcare professionals","url":"https://www.gov.uk/government/publications/fit-note-guidance-for-healthcare-professionals/getting-the-most-out-of-the-fit-note-guidance-for-healthcare-professionals","use":"Health-based functional advice, work adjustments and consent."}],"pitfalls":["Do not use a recent life event as proof that depression is absent."],"followUp":"Agree a short, explicit review interval based on function and safety; provide an earlier deterioration route.","reviewed":"2026-11-13","tags":["low","mood","after","relationship"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Arrange urgent or emergency assessment according to danger. Your safety needs our attention today.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-antenatal","title":"Depression during pregnancy","summary":"Assess mood, safety, prior severe episodes and bipolar symptoms","presentation":"A pregnant patient has stopped an effective antidepressant after discovering the pregnancy and is becoming unwell.","assessment":["Assess mood, safety, prior severe episodes and bipolar symptoms","Establish pregnancy stage, medication, dose and timing of cessation","Explore fears and previous treatment response","Assess obstetric, social and safeguarding context"],"management":[{"step":"1. Assess relapse and withdrawal","detail":"Clarify the course since stopping; significant deterioration requires prompt specialist support."},{"step":"2. Discuss balanced risks","detail":"Compare untreated illness, relapse and medication exposure using current perinatal prescribing advice; avoid blanket reassurance or blanket stopping."},{"step":"3. Coordinate","detail":"Seek specialist perinatal input where indicated and involve maternity care with consent; agree a named coordinating clinician."},{"step":"4. Offer treatment","detail":"Discuss suitable psychological and medication options according to severity, history and preferences; plan postpartum care too."}],"discussion":[{"cue":"I stopped the antidepressant because I thought any medicine would harm the baby.","response":"It is understandable to want to protect your baby. We need to consider the effects of the illness, stopping treatment and the particular medicine, rather than assume one option has no risk. Let’s review what you took, when you stopped and how you are now, using pregnancy-specific advice.","simple":"Let’s review the illness, the medicine and what changed after stopping, with pregnancy-specific advice.","why":"Acknowledge the concern and assess relapse/withdrawal; neither automatic continuation nor blanket stopping is a complete individual plan.","id":"mh-antenatal-talk-1"},{"cue":"Should I restart the same dose tonight?","response":"We need a prompt clinical review of the actual medicine, dose, time since stopping and your symptoms before deciding the next prescription. I will seek the appropriate perinatal advice and confirm who will contact you and when. If you cannot stay safe or become acutely unwell, we need urgent help now.","simple":"Let’s arrange a prompt, medicine-specific review and a clear contact plan rather than guess the dose.","why":"Do not supply a universal restart instruction; assess urgency and obtain the expertise needed for the actual treatment.","id":"mh-antenatal-talk-2"},{"cue":"Can I choose a talking treatment instead?","response":"We can discuss suitable psychological treatment and your preference. The severity, previous episodes and what has helped before affect the options. If medication or combined treatment is recommended, I will explain the benefits and risks, and we will make a supported plan rather than leave you without care.","simple":"Let’s discuss the suitable options and your preference, with support and review whatever we decide.","why":"CG192 requires support, discussion of stopping risks and appropriate psychological care when medicine is declined or stopped.","id":"mh-antenatal-talk-3"},{"cue":"Does taking treatment mean I cannot breastfeed later?","response":"That depends on the particular treatment and your baby’s circumstances. We can use medicine-specific breastfeeding advice and plan monitoring with the perinatal and maternity teams. Your feeding wishes matter, and we should support the informed choice rather than make a blanket rule.","simple":"Let’s check the specific medicine and feeding plan with the right team. It is not the same answer for every treatment.","why":"Discuss lactation separately from pregnancy exposure and include the risks of untreated illness or stopping medication; do not promise zero exposure or require breastfeeding.","id":"mh-antenatal-talk-4"},{"cue":"Who is looking after this between the GP and maternity team?","response":"Let’s name the coordinating clinician, the next review and the contact route if symptoms worsen. With appropriate agreement, we will share the relevant plan with maternity and mental-health colleagues so you receive consistent advice before and after the birth.","simple":"Let’s agree the named clinician, shared plan, review date and urgent contact route.","why":"Coordination and postpartum planning make the risk discussion actionable; a referral alone is not continuity.","id":"mh-antenatal-talk-5"}],"variations":[{"label":"Severe illness","change":"Psychosis or inability to remain safe emerges.","action":"Arrange immediate specialist or emergency help; routine referral is insufficient.","phrase":"We need urgent specialist assessment today."},{"label":"Stable on treatment","change":"The medicine is working and no acute issue is present.","action":"Review benefits and pregnancy-specific risks; do not abruptly stop solely because of pregnancy.","phrase":"We can make an informed plan rather than stop automatically."},{"label":"Breastfeeding planned","change":"They ask about feeding and treatment.","action":"Use medicine-specific lactation advice and develop a postpartum monitoring plan.","phrase":"The choice can take your feeding wishes into account."}],"links":[{"label":"NICE CG192 — recommendations","url":"https://www.nice.org.uk/guidance/cg192/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE NG222 — recommendations","url":"https://www.nice.org.uk/guidance/ng222/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not describe any antidepressant as universally safe or universally prohibited in pregnancy."],"followUp":"Agree risk-adjusted perinatal follow-up and a shared antenatal/postnatal care plan, including who monitors medication changes.","reviewed":"2026-11-13","tags":["depression","during","pregnancy"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Arrange immediate specialist or emergency help; routine referral is insufficient. We need urgent specialist assessment today.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-postnatal","title":"Postnatal depression and isolation","summary":"Assess symptoms, duration, functioning and ability to care","presentation":"A new parent has persistent low mood, guilt and poor sleep, with limited family support. They worry their baby will be removed if they disclose symptoms.","assessment":["Assess symptoms, duration, functioning and ability to care","Ask directly about self-harm, infant safety, intrusive thoughts and intent","Screen for mania, delusions, hallucinations and confusion","Assess birth trauma, feeding, support, domestic safety and physical illness"],"management":[{"step":"1. Explain","detail":"Differentiate transient early emotional changes from persistent depression requiring assessment."},{"step":"2. Treat","detail":"Offer appropriate psychological and/or medication treatment matched to severity and feeding considerations; use perinatal advice where needed."},{"step":"3. Support the family","detail":"Coordinate health visitor, maternity and perinatal services; assess practical help and the parent–infant relationship sensitively."},{"step":"4. Plan safety","detail":"Explain confidentiality honestly, identify urgent warning signs and arrange a named review."}],"discussion":[{"cue":"If I tell you about my thoughts, will my baby be taken away?","response":"Telling us helps us understand what support you and your baby need. I cannot promise the outcome before we assess the situation, but I will explain the assessment and any necessary information sharing. Could you tell me what the thoughts are like and whether you feel you might act on them?","simple":"Let’s understand the thoughts and safety needs. I will explain the assessment and any necessary sharing.","why":"Avoid a false safeguarding guarantee or automatic punitive response. Assess intrusive thoughts, intent, psychosis, function and the infant’s needs.","id":"mh-postnatal-talk-1"},{"cue":"The thoughts frighten me. I do not want them and do not want to do them.","response":"That distinction matters, and I am glad you told me. I need to ask about the thoughts, how you respond, any wish or plan to act, and how you and the baby are managing. We can then choose appropriate treatment and support.","simple":"Unwanted thoughts are not automatically an intention to act. We still need to assess the whole situation and help you.","why":"Do not equate an intrusive unwanted thought with intent, or declare safety from that distinction alone.","id":"mh-postnatal-talk-2"},{"cue":"Everyone says it is just the baby blues.","response":"Early emotional changes can happen, but persistent low mood, loss of enjoyment or difficulty functioning deserves a proper assessment. Let’s look at the duration, impact, sleep, support and safety rather than dismiss it as something you must simply put up with.","simple":"Persistent symptoms need assessment and support. Let’s check how this is affecting you and the baby.","why":"Distinguish transient changes from illness using the clinical picture; avoid making the label a reason to delay help.","id":"mh-postnatal-talk-3"},{"cue":"I cannot get to therapy because there is nobody to look after the baby.","response":"Let’s make the arrangements fit your actual situation. We can check what appointment formats and local support are available, involve the health visitor or perinatal team as appropriate, and agree who will review you while treatment is being arranged.","simple":"Let’s check accessible appointments, practical support and interim review rather than give you an unusable referral.","why":"Respond to the real access barrier without promising a service that has not been confirmed.","id":"mh-postnatal-talk-4"},{"cue":"I feel suddenly full of energy, hardly need sleep, and things are becoming confusing.","response":"That sudden change needs immediate assessment. It could be a serious postnatal mental-health or physical problem. I will contact the appropriate urgent team now; if there is immediate danger to you or the baby, we need emergency help without waiting.","simple":"This sudden change needs urgent specialist assessment now, with emergency help for immediate danger.","why":"Consider postpartum psychosis/mania and medical causes. Suspected postpartum psychosis requires immediate assessment within four hours of referral, not a routine depression review.","id":"mh-postnatal-talk-5"}],"variations":[{"label":"Psychotic symptoms","change":"Delusions, confusion or unusually elevated mood appear.","action":"Suspected postpartum psychosis needs immediate specialist assessment within 4 hours of referral; emergency help if immediate danger.","phrase":"This needs urgent specialist help now."},{"label":"Intrusive unwanted thoughts","change":"They are distressed by thoughts with no desire to act.","action":"Assess carefully rather than equating intrusive thoughts automatically with intent; arrange appropriate treatment and support.","phrase":"Help me understand what the thought means to you."},{"label":"No practical support","change":"They cannot rest or access appointments.","action":"Arrange feasible support and accessible follow-up; do not make advice depend on unavailable help.","phrase":"Let us identify support you can actually use."}],"links":[{"label":"NICE CG192 — recommendations","url":"https://www.nice.org.uk/guidance/cg192/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not assume every tired new parent has depression or that intrusive thoughts automatically mean intent to harm."],"followUp":"Agree early review matched to safety and functioning, coordinated with perinatal and health-visiting teams; escalate new psychotic symptoms immediately.","reviewed":"2026-11-13","tags":["postnatal","depression","and","isolation"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Suspected postpartum psychosis needs immediate specialist assessment within 4 hours of referral; emergency help if immediate danger. This needs urgent specialist help now.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-postpartum-psychosis","title":"Postpartum psychosis: recognising an emergency","summary":"Assess immediate danger to parent and baby","presentation":"Ten days after delivery, a parent has hardly slept, appears confused and believes the baby has special powers. A partner requests sleeping tablets.","assessment":["Assess immediate danger to parent and baby","Establish onset, sleep, mood, psychotic symptoms and capacity to engage","Check medical causes, medicines and substances without delaying referral","Confirm location, support and safe supervision"],"management":[{"step":"1. Escalate immediately","detail":"Refer for immediate specialist mental health assessment, preferably perinatal, within 4 hours of referral. If there is immediate danger, use emergency services now."},{"step":"2. Protect safely","detail":"Arrange safe support for parent and baby while help is mobilised; do not leave the family to manage an unsafe situation alone."},{"step":"3. Assess physical needs","detail":"Coordinate urgent medical assessment for confusion or possible physical illness as needed."},{"step":"4. Handover","detail":"Share clinical facts, timing, safety concerns and relevant history directly with receiving services; confirm the plan has been accepted."}],"discussion":[{"cue":"Could you just give her something to sleep?","response":"The sudden confusion, unusual beliefs and major sleep change need immediate assessment. Postpartum psychosis is one possible explanation and is treatable, but sleeping tablets alone are not the right plan. I will contact the specialist team now and arrange the appropriate urgent help.","simple":"This needs specialist assessment now, not a sleeping-tablet-only plan.","why":"Explain the emergency from observed change without diagnosing from one feature or delaying assessment with a routine prescription.","id":"mh-postpartum-psychosis-talk-1"},{"cue":"She has never had a mental-health problem before.","response":"It can happen without a previous diagnosis. What matters now is the sudden change after birth and the safety of both parent and baby. We should not wait for a routine appointment because there is no previous history.","simple":"No previous diagnosis does not make this safe to wait. The current symptoms need immediate assessment.","why":"Do not use absence of history to downgrade a possible first episode.","id":"mh-postpartum-psychosis-talk-2"},{"cue":"Does within four hours mean we should wait and see for a bit?","response":"No. I need to refer now for immediate assessment, with the guideline expectation of assessment within four hours of referral. If anyone is in immediate danger, call 999 now rather than wait for that pathway.","simple":"We act now. Four hours is not a reason to wait; immediate danger needs 999.","why":"Preserve the exact CG192 timing and distinguish it from emergency action for immediate danger.","id":"mh-postpartum-psychosis-talk-3"},{"cue":"I am frightened to leave her alone with the baby.","response":"Let’s confirm where you are and who can provide safe support while help is arranged. Do not put yourself at risk or try to manage an unsafe situation alone. I will give the receiving team the safety concerns and confirm the next steps; immediate danger needs emergency services.","simple":"Let’s confirm location and safe support while urgent help is arranged. Do not manage immediate danger alone.","why":"Turn referral into a practical handover for parent and infant rather than leave the family with an unconfirmed contact number.","id":"mh-postpartum-psychosis-talk-4"},{"cue":"She also has a fever and is becoming difficult to wake.","response":"That needs emergency medical assessment now. We must check physical causes as well as the mental-health symptoms. Call 999; do not wait for a routine psychiatric review. I will make sure the handover includes the birth history, fever and change in consciousness.","simple":"Fever with difficulty waking needs 999 now and a medical assessment alongside mental-health care.","why":"Physical instability or reduced consciousness changes the route; do not attribute all postnatal confusion to psychiatric illness.","id":"mh-postpartum-psychosis-talk-5"}],"variations":[{"label":"Immediate threat","change":"The parent threatens harm.","action":"Activate emergency help immediately; do not wait for the 4-hour maximum.","phrase":"We need emergency help at your location now."},{"label":"No previous illness","change":"There is no psychiatric history.","action":"Do not downgrade urgency; postpartum psychosis can be a first episode.","phrase":"This can happen even without previous mental illness."},{"label":"Physical instability","change":"Fever or reduced consciousness appears.","action":"Arrange emergency medical assessment alongside psychiatric care.","phrase":"We need to assess physical causes urgently as well."}],"links":[{"label":"NICE CG192 — recommendations","url":"https://www.nice.org.uk/guidance/cg192/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not call this routine postnatal depression or wait for a routine appointment."],"followUp":"Confirm immediate handover and supervision; subsequent treatment and follow-up are specialist-led with coordinated family and primary-care support.","reviewed":"2026-11-13","tags":["postpartum","psychosis","recognising","an"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Activate emergency help immediately; do not wait for the 4-hour maximum. We need emergency help at your location now.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-gad","title":"Generalised anxiety: persistent worry","summary":"Assess duration, breadth of worry and functional impairment","presentation":"An adult describes months of hard-to-control worry, tension and poor sleep affecting work. They request diazepam.","assessment":["Assess duration, breadth of worry and functional impairment","Assess depression, self-harm, substances and physical contributors","Review previous therapy and medication response","Explore barriers and preferences"],"management":[{"step":"1. Explain","detail":"Discuss the working diagnosis and the worry–avoidance cycle in plain language."},{"step":"2. Use stepped care","detail":"Begin with education and appropriate low-intensity interventions when suitable; marked impairment or inadequate response warrants high-intensity CBT, applied relaxation or medication according to preference."},{"step":"3. Prescribe safely","detail":"If using an SSRI, check contraindications, interactions, licensing, activation and withdrawal; explain monitoring."},{"step":"4. Avoid default sedation","detail":"Benzodiazepines are not routine GAD treatment; exceptional short crisis use requires specific assessment and a clear plan."}],"discussion":[{"cue":"Is there treatment for this constant worrying?","response":"The aim is to reduce the ongoing worry and help you function more comfortably. We can compare suitable therapy and medicine options, then choose a plan that fits the impact on your life and your preferences.","simple":"There are treatments for the worry. Let’s compare suitable options and agree a plan you can use.","why":"Explain the purpose of treatment and choose the level of care from impact, previous response and preference.","id":"mh-gad-talk-1"},{"cue":"Diazepam helped before. Why not just give me that?","response":"I understand why you want quick relief. Diazepam is not a routine treatment for ongoing GAD because of its risks, including dependence. Exceptional short crisis use needs its own careful assessment and plan. I would like us to agree an approach for the ongoing worry as well.","simple":"Diazepam is not the routine answer for ongoing worry. Let’s agree a safer longer-term treatment plan and assess any current crisis.","why":"CG113 restricts benzodiazepines in GAD to a short-term measure during crises; it does not support a routine repeat prescription.","id":"mh-gad-talk-2"},{"cue":"What is the difference between therapy and taking medicine?","response":"Appropriate therapy can help you change how you respond to worry and anxiety. Medicine is another option when indicated, with benefits, side effects and monitoring to discuss. Let’s look at the options that fit your situation and what you would prefer.","simple":"We can discuss suitable therapy or medicine, how each might help and the practical arrangements.","why":"Discuss stepped care rather than imply every degree of anxiety needs the same intensity or one universally best treatment.","id":"mh-gad-talk-3"},{"cue":"I am 27. Do I need an early check if I start an SSRI?","response":"Yes. In GAD, guidance recommends seeing people under 30 within one week of starting an SSRI or SNRI and checking suicidal thinking and self-harm risk weekly for the first month. We will agree who does that and how to get help sooner if your mental state worsens.","simple":"For GAD under age 30, we arrange a review within one week and weekly risk checks for the first month after starting an SSRI or SNRI.","why":"This is CG113’s GAD recommendation. It differs from the depression-specific 18–25 rule and still needs individual risk assessment and arrangements.","id":"mh-gad-talk-4"},{"cue":"I have been drinking to calm myself down.","response":"Thank you for telling me. Could we go through how much you drink, when and what happens if you do not drink? That affects what is safe to prescribe and whether you need supported help with alcohol as part of the anxiety plan.","simple":"Let’s check the drinking pattern and any withdrawal symptoms. That changes what is safe and what support you need.","why":"Assess dependence and withdrawal and avoid unsafe sedative combinations; do not give an unsupported instruction to stop abruptly if dependence is possible.","id":"mh-gad-talk-5"}],"variations":[{"label":"Marked impairment","change":"They can no longer work or manage daily tasks.","action":"Offer higher-intensity treatment and consider specialist involvement according to complexity.","phrase":"The impact means a more active treatment plan is needed."},{"label":"Alcohol coping","change":"They use alcohol to manage anxiety.","action":"Assess dependence and avoid unsafe sedative combinations; coordinate treatment.","phrase":"We need a plan that addresses both problems safely."},{"label":"First treatment fails","change":"Symptoms persist despite an adequate attempt.","action":"Review diagnosis, engagement and adverse effects, then discuss another recommended option or specialist input.","phrase":"Let us work out why the first approach did not help."}],"links":[{"label":"NICE CG113 — recommendations","url":"https://www.nice.org.uk/guidance/cg113/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not make diazepam the routine quick fix for chronic worry."],"followUp":"Review medicine efficacy and adverse effects every 2–4 weeks for the first 3 months, then every 3 months, adjusted for risk. For people under 30 starting an SSRI/SNRI for GAD, arrange review within 1 week and weekly monitoring of suicidal thinking/self-harm risk for the first month. Confirm therapy access and named follow-up ownership; acute risk needs earlier action.","reviewed":"2026-11-12","tags":["generalised","anxiety","persistent","worry"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Offer higher-intensity treatment and consider specialist involvement according to complexity. The impact means a more active treatment plan is needed.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-panic","title":"Panic attacks with physical symptoms","summary":"Assess the current episode for cardiac, respiratory and other acute causes","presentation":"An adult reports episodes of racing heart, breathlessness and fear. They believe anxiety explains a new episode of chest pain.","assessment":["Assess the current episode for cardiac, respiratory and other acute causes","Clarify triggers, onset, duration, avoidance and anticipatory anxiety","Review caffeine, substances, medicines and physical history","Assess depression and safety"],"management":[{"step":"1. Triage first","detail":"Do not use a previous anxiety diagnosis to exclude physical illness; urgent symptoms need urgent assessment."},{"step":"2. Explain after assessment","detail":"When appropriate, explain panic symptoms and the cycle of fear without dismissing the physical experience."},{"step":"3. Treat recurrent panic","detail":"Discuss CBT and appropriate antidepressant options according to the guideline and patient preference."},{"step":"4. Plan coping and review","detail":"Agree non-harmful coping methods, reduced stimulant exposure, access to therapy and a clear plan for changed symptoms."}],"discussion":[{"cue":"This new chest pain must just be another panic attack, right?","response":"Panic can cause powerful physical symptoms, but we should not assume that explains a new or different episode. I need to assess the chest pain and whether urgent physical assessment is needed before treating it as panic.","simple":"New or different chest pain needs its own assessment. A panic history does not rule out another cause.","why":"Triage the current presentation before accepting the patient’s or clinician’s previous anxiety label.","id":"mh-panic-talk-1"},{"cue":"Are you saying I am imagining the symptoms?","response":"No. The symptoms are real. Panic can produce a strong physical alarm response, but we only use that explanation after the appropriate assessment. Let’s go through what we have checked and what the plan is.","simple":"No. The symptoms are real. We need the right assessment before deciding they are panic-related.","why":"Validate the experience without false reassurance or prematurely excluding physical illness.","id":"mh-panic-talk-2"},{"cue":"Can I have diazepam for every attack?","response":"I understand wanting something that works quickly. Benzodiazepines are not recommended treatment for panic disorder. We can discuss appropriate CBT or medicine options that aim to reduce the attacks and their effect on your life.","simple":"Diazepam is not recommended for panic disorder. Let’s discuss treatment aimed at improving the attacks over time.","why":"CG113’s panic recommendation differs from the exceptional crisis role of benzodiazepines in GAD; do not treat those situations as interchangeable.","id":"mh-panic-talk-3"},{"cue":"I have stopped leaving the house because I fear another attack.","response":"That is a major effect on your life. Let’s assess the avoidance and what support would make treatment accessible, then agree a plan to work on it with appropriate therapy and review.","simple":"Let’s discuss the avoidance and arrange accessible treatment and support.","why":"Explore agoraphobia, functional impact and access instead of giving a generic reassurance or telling the person simply to go out more.","id":"mh-panic-talk-4"},{"cue":"What if chest pain comes back after we call it panic?","response":"If symptoms are new, different, persistent or otherwise concerning, they need reassessment. Ongoing chest pressure with sweating or serious illness needs emergency help: call 999. We will also agree what you can do for familiar, appropriately assessed panic symptoms.","simple":"New or concerning symptoms need reassessment. Persistent chest pressure with sweating or serious illness needs emergency help: call 999.","why":"Provide a contingency that does not label every later physical symptom as anxiety or use coping advice to delay urgent care.","id":"mh-panic-talk-5"}],"variations":[{"label":"Persistent chest pressure","change":"Sweating and ongoing chest discomfort occur.","action":"Arrange emergency assessment for a possible acute cardiac problem.","phrase":"This pattern needs emergency help now."},{"label":"Avoidance","change":"They have stopped leaving home.","action":"Assess agoraphobia and functional impact; arrange accessible CBT and treatment.","phrase":"We can make the treatment accessible while working on avoidance."},{"label":"Sedative request","change":"They request a benzodiazepine for every attack.","action":"Explain that benzodiazepines are not recommended treatment for panic disorder and offer evidence-based alternatives.","phrase":"I want an approach that improves the attacks over time."}],"links":[{"label":"NICE CG113 — recommendations","url":"https://www.nice.org.uk/guidance/cg113/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not advise paper-bag rebreathing or use benzodiazepines as standard panic treatment."],"followUp":"Agree review of attack frequency, avoidance and treatment effects; specify reassessment for new or different physical symptoms.","reviewed":"2026-11-12","tags":["panic","attacks","with","physical"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Arrange emergency assessment for a possible acute cardiac problem. This pattern needs emergency help now.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-young-person","title":"Young person with anxiety, low mood and school avoidance","summary":"Hear the young person directly and offer private discussion","presentation":"A parent requests antidepressants for a 15-year-old who is not attending school. The young person has not yet spoken privately.","assessment":["Hear the young person directly and offer private discussion","Assess self-harm, suicide, bullying, abuse and exploitation","Explore development, family, school, substances and physical health","Assess function, eating, sleep and existing supports"],"management":[{"step":"1. Engage","detail":"Explain confidentiality and its limits in age-appropriate language; include the young person in decisions."},{"step":"2. Assess needs","detail":"Distinguish anxiety, depression and other causes; assess safeguarding and immediate risk."},{"step":"3. Coordinate age-appropriate care","detail":"Use age-appropriate child mental-health pathways and psychological interventions. For antidepressant treatment of depression, NG134 requires prior assessment and diagnosis by a child and adolescent psychiatrist; do not copy adult or family prescriptions. Any treatment needs an agreed monitoring and continuity plan."},{"step":"4. Support function","detail":"Agree school and family support with consent and safety considerations; arrange active follow-up during waits."}],"discussion":[{"cue":"My parent has told you everything. Do I need to talk?","response":"I would like to hear how things feel from your point of view. I offer young people some time to talk privately, and I will explain confidentiality and when information may need to be shared for safety. We can then agree how to involve the people who can help.","simple":"I would like to hear you directly and offer private time, with a clear explanation of confidentiality.","why":"Engage the young person, assess understanding and apply the relevant consent/safeguarding framework rather than let an adult’s account replace the consultation.","id":"mh-young-person-talk-1"},{"cue":"Will you promise not to tell anyone what I say?","response":"I will respect your privacy. If I am worried that you or someone else is at serious risk, I may need to involve the right people to help. I will explain what needs to be shared and try to discuss it with you first, as far as it is safe to do so.","simple":"I respect your privacy, but serious safety concerns may mean involving help. I will explain that as clearly as I can.","why":"Explain limits before sensitive questions without promising absolute secrecy or automatic disclosure of everything to a parent.","id":"mh-young-person-talk-2"},{"cue":"Can they try my antidepressant? It worked for me.","response":"Please do not share a prescription. We need to assess what is happening for this young person and use the appropriate age-specific treatment pathway. If antidepressant treatment for depression is considered, NICE requires assessment and diagnosis by a child and adolescent psychiatrist, with a clear treatment and monitoring plan.","simple":"Please do not share medicine. The young person needs their own assessment and appropriate specialist input for antidepressant treatment.","why":"Do not copy adult prescribing, a relative’s drug or the adult review-age rule into a 15-year-old’s care.","id":"mh-young-person-talk-3"},{"cue":"School say I must be back tomorrow. I do not feel able to go.","response":"What feels hardest or unsafe about going in? Let’s understand the anxiety, mood, bullying or other concerns and agree suitable school and family support with you. We need an achievable plan and a named review, not simply an instruction to attend.","simple":"Let’s understand what makes school difficult and agree safe, achievable support and review.","why":"Use the answer to assess underlying needs, safeguarding and function; avoid treating absence as defiance or giving an unassessed return timetable.","id":"mh-young-person-talk-4"},{"cue":"The specialist waiting list is long. Who helps us meanwhile?","response":"We should agree who will review you while the referral is being arranged, what support is available and how to seek help sooner. An overdose, serious injury or immediate danger needs urgent or emergency assessment, not waiting for the routine appointment.","simple":"Let’s name the interim clinician, support and earlier-help route while the referral is tracked.","why":"An accepted referral does not remove primary-care continuity. When antidepressants are initiated, NG134 calls for specific close monitoring, for example weekly contact for the first four weeks, individualised and documented.","id":"mh-young-person-talk-5"}],"variations":[{"label":"Self-harm disclosure","change":"They have recently taken tablets.","action":"Arrange emergency medical care and age-appropriate psychosocial assessment; do not wait for routine CAMHS.","phrase":"We need to make sure you are medically safe now."},{"label":"Parent dominates","change":"The parent answers every question.","action":"Create a safe opportunity for direct and private discussion while respecting relevant consent frameworks.","phrase":"I ask all young people some questions on their own."},{"label":"Medication requested","change":"The parent wants an adult relative’s SSRI.","action":"Do not share or copy another person’s prescription; seek appropriate specialist assessment for depression treatment.","phrase":"The right treatment needs to be chosen specifically for them."}],"links":[{"label":"NICE NG134 — recommendations","url":"https://www.nice.org.uk/guidance/ng134/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE NG225 — recommendations","url":"https://www.nice.org.uk/guidance/ng225/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not let a long waiting list substitute for a safety plan and ongoing clinical review."],"followUp":"Name a clinician for interim review, referral tracking and escalation. For antidepressant treatment, NG134 recommends specific close arrangements, for example weekly contact with the young person and parents/carers as appropriate during the first 4 weeks; individualise and document the frequency. Acute danger needs earlier action.","reviewed":"2026-11-13","tags":["young","person","with","anxiety,"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Arrange emergency medical care and age-appropriate psychosocial assessment; do not wait for routine CAMHS. We need to make sure you are medically safe now.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-psychosis","title":"First-episode psychosis and a request for sleep medication","summary":"Assess command hallucinations, risk, self-neglect and vulnerability","presentation":"A young adult hears voices, suspects neighbours are watching them and has slept poorly. They ask for sleeping tablets and plan to travel.","assessment":["Assess command hallucinations, risk, self-neglect and vulnerability","Clarify symptoms, onset, insight, function and mood","Assess substances, medicines and physical causes","Identify support, location and ability to engage"],"management":[{"step":"1. Refer promptly","detail":"Refer without delay to early intervention in psychosis; use crisis or emergency services when risk or severity requires."},{"step":"2. Assess broadly","detail":"Arrange physical and mental-state assessment and targeted tests without delaying specialist involvement."},{"step":"3. Avoid unsupervised initiation","detail":"Do not start an antipsychotic for a first sustained presentation in primary care without consultation with a consultant psychiatrist."},{"step":"4. Support safely","detail":"Discuss trusted support, practical needs and travel risks; use clear, non-confrontational language and arrange direct handover."}],"discussion":[{"cue":"My neighbours are watching me. Do you believe me?","response":"I can hear that this feels very real and frightening for you. I cannot confirm what the neighbours are doing, but I do want to understand what you are experiencing and help you feel safer. Could you tell me what has been happening?","simple":"That sounds frightening. I want to understand the experiences and help you safely, without assuming the explanation.","why":"Acknowledge distress without endorsing the belief or getting into a confrontation about it.","id":"mh-psychosis-talk-1"},{"cue":"The voices tell me things. Does that matter?","response":"Yes. I need to understand what they say and how much influence they have. Have they told you to hurt yourself or someone else? We should assess what you feel you might do and arrange help according to the immediate risk.","simple":"Let’s check what the voices say, whether you might act and what help is needed now.","why":"Ask directly about command content, intent and ability to resist; do not assume every voice has the same risk.","id":"mh-psychosis-talk-2"},{"cue":"Can I just have sleeping tablets and sort the rest later?","response":"The poor sleep matters, but the voices and suspiciousness need an assessment too. I recommend involving the appropriate mental-health or early-intervention team without delay, with urgent or emergency help if the safety assessment requires it. We should also check physical and substance-related causes.","simple":"The sleep problem is part of a wider assessment. Let’s arrange appropriate help without delay.","why":"A hypnotic-only plan can miss a first psychosis or medical problem; specialist referral should not be postponed until routine tests or travel are complete.","id":"mh-psychosis-talk-3"},{"cue":"Can you start the usual antipsychotic now?","response":"The right treatment needs a specialist assessment and prescribing plan. For a first presentation of sustained psychotic symptoms, I would consult a consultant psychiatrist before starting an antipsychotic in primary care. I will contact the team and explain the next action rather than leave you without a plan.","simple":"I will seek the appropriate psychiatrist’s advice and arrange the assessment and prescribing plan.","why":"Apply CG178’s specific first-presentation primary-care rule; do not choose an unassessed drug or dose.","id":"mh-psychosis-talk-4"},{"cue":"I have a flight tomorrow. Can this wait until I return?","response":"I am concerned that delaying assessment or being away from support could make things harder or less safe. Let’s assess the current risk, discuss the travel plans and agree practical support with the receiving team. I recommend the assessment before treating this as something to leave until after the trip.","simple":"Let’s assess this now and discuss the travel risks and support rather than automatically wait until you return.","why":"Explore the actual journey, support and ability to engage; do not promise fitness to travel or a legal restriction without the necessary assessment.","id":"mh-psychosis-talk-5"}],"variations":[{"label":"Command voices","change":"Voices urge harm and the patient feels compelled.","action":"Assess immediate danger and arrange urgent crisis or emergency help.","phrase":"We need help now to keep you and others safe."},{"label":"Substance use","change":"Cannabis or stimulants are involved.","action":"Assess intoxication and physical risk; do not assume substance involvement removes the need for psychosis assessment.","phrase":"We should assess both the substance effects and these experiences."},{"label":"Travel imminent","change":"They intend to fly alone tomorrow.","action":"Discuss postponement and safe continuity; urgency is determined by current illness and risk.","phrase":"Travelling could make getting help much harder just now."}],"links":[{"label":"NICE CG178 — recommendations","url":"https://www.nice.org.uk/guidance/cg178/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not agree with delusions, argue aggressively, or treat sleep alone while delaying referral."],"followUp":"Confirm specialist acceptance, immediate safety arrangements and primary-care contact; subsequent follow-up is coordinated with the treating team.","reviewed":"2026-11-13","tags":["first-episode","psychosis","and","a"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Assess immediate danger and arrange urgent crisis or emergency help. We need help now to keep you and others safe.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-relapse","title":"Schizophrenia: stopping medication because of adverse effects","summary":"Assess relapse symptoms, risk and ability to care for self","presentation":"An adult with schizophrenia stopped treatment because of distressing side effects and is becoming suspicious again.","assessment":["Assess relapse symptoms, risk and ability to care for self","Establish medicine, last dose, reasons for stopping and previous relapse","Check substances, physical illness and adverse-effect severity","Review the crisis plan, team contacts and support"],"management":[{"step":"1. Respond to the reason","detail":"Acknowledge adverse effects and assess whether urgent medical treatment is needed."},{"step":"2. Contact the team","detail":"Use the existing crisis plan and seek prompt specialist advice for relapse; escalate according to severity."},{"step":"3. Restart safely","detail":"Do not automatically restart an old full dose. Some medicines require special restart procedures and monitoring; coordinate with the treating specialist."},{"step":"4. Plan ongoing care","detail":"Agree medicine review, physical-health monitoring, support and a reliable contact route."}],"discussion":[{"cue":"I stopped because the tablets made me feel awful. Will you just tell me off?","response":"The side effects matter, and I want to understand them. Let’s check the medicine, when you stopped, what you experienced and whether any effect needs urgent medical attention. We also need to assess the symptoms that are returning.","simple":"Let’s take the side effects seriously and assess the returning symptoms, without blame.","why":"Acknowledge the reason for stopping and assess both physical harms and relapse; do not frame the problem only as non-adherence.","id":"mh-relapse-talk-1"},{"cue":"Can I just restart my old full dose tonight?","response":"The restart plan depends on the particular medicine and how long you have been off it. Some treatments need careful reintroduction and monitoring. I will check the records and discuss it with your treating team before confirming a safe plan.","simple":"Please let us check the specific medicine and time off with your team before deciding the restart dose.","why":"Do not apply a universal restart instruction or assume a previous prescription is safe to resume unchanged.","id":"mh-relapse-talk-2"},{"cue":"The suspicious thoughts are back, but I do not want to go to hospital.","response":"Let’s talk about what has changed, how it affects you and whether you or anyone else is at risk. We can use your crisis plan and involve the team promptly. The setting depends on the assessment and what support can safely be arranged, rather than a promise that hospital will or will not be needed.","simple":"Let’s assess the change and safety, use your crisis plan and involve the team promptly.","why":"Respect the concern without promising an outcome before assessing severity, function, support and the relevant legal framework.","id":"mh-relapse-talk-3"},{"cue":"I do not want to choose between being well and putting on more weight.","response":"That is a real concern to discuss in the treatment review. We can compare the benefits and side effects of suitable options with the specialist and make sure physical-health monitoring is included. Let’s also discuss practical support for the effects you are already experiencing.","simple":"Let’s review the options and side effects with your team and include physical-health checks and support.","why":"CG178 makes metabolic and other adverse effects part of shared treatment choice, not a reason to dismiss the person’s priorities.","id":"mh-relapse-talk-4"},{"cue":"Who should I call if the voices get worse tonight?","response":"Let’s check the actual crisis contact in your plan and confirm the team knows what is happening. We should agree who is supporting you and what needs help sooner. If there is immediate danger or you feel likely to act on commands to harm someone, use emergency help rather than wait for a routine review.","simple":"Let’s confirm the real crisis contact and support tonight. Immediate danger needs emergency help.","why":"Close the loop with a named service, accepted communication and severity-matched contingency; do not give an unverified number alone.","id":"mh-relapse-talk-5"}],"variations":[{"label":"Clozapine interruption","change":"The stopped medicine is clozapine.","action":"Seek urgent specialist advice on restart and monitoring; do not resume the previous dose without instruction.","phrase":"This medicine needs a specific safe restart plan."},{"label":"Severe self-neglect","change":"They are not eating or maintaining safety.","action":"Arrange urgent crisis assessment and physical care as indicated.","phrase":"The immediate priority is getting you assessed and supported."},{"label":"Stable but unhappy","change":"There are no relapse signs yet.","action":"Arrange a collaborative specialist medication review before deterioration occurs.","phrase":"We can review the side effects while protecting your stability."}],"links":[{"label":"NICE CG178 — recommendations","url":"https://www.nice.org.uk/guidance/cg178/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not assume every antipsychotic can be restarted at its previous dose after an interruption."],"followUp":"Confirm team communication and an early review of symptoms, adverse effects and the agreed prescribing plan.","reviewed":"2026-11-13","tags":["schizophrenia","stopping","medication","because"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Seek urgent specialist advice on restart and monitoring; do not resume the previous dose without instruction. This medicine needs a specific safe restart plan.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-mania","title":"Possible mania behind reduced sleep","summary":"Assess mood elevation, disinhibition, psychosis and function","presentation":"An adult requests help for sleep but is unusually energised, spending excessively and talking rapidly after several nights with little sleep.","assessment":["Assess mood elevation, disinhibition, psychosis and function","Ask about danger, exploitation, spending, driving and dependants","Check medicines, antidepressants, substances and physical causes","Establish previous episodes and collateral history with appropriate consent"],"management":[{"step":"1. Recognise","detail":"Distinguish reduced need for sleep from exhausting insomnia; consider mania or hypomania."},{"step":"2. Escalate","detail":"Suspected mania requires urgent specialist assessment, with emergency care for immediate danger or severe physical compromise."},{"step":"3. Reduce harm","detail":"Address driving, finances, exploitation and safe support without confrontation or unsupported guarantees."},{"step":"4. Coordinate treatment","detail":"Medication changes should follow urgent specialist advice and current safety requirements; do not simply increase an antidepressant."}],"discussion":[{"cue":"I feel fantastic. Why do you think anything is wrong?","response":"I hear that you feel well. I am concerned about the change in sleep, energy, spending and behaviour together. I would like to assess how this is affecting you and arrange an urgent specialist opinion rather than assume it is ordinary insomnia.","simple":"The combination of changes concerns me, even though you feel well. I recommend urgent assessment.","why":"Explain the observed pattern without an argument or a definitive diagnosis from one symptom.","id":"mh-mania-talk-1"},{"cue":"I only need three hours of sleep. Can I just have a tablet?","response":"Needing very little sleep while feeling unusually energetic is different from being exhausted and unable to sleep. We need to assess the mood, decisions, physical health, medicines and substances as well. A sleeping-tablet-only plan would not address that.","simple":"This sleep change needs a wider assessment and urgent advice, not just a sleeping tablet.","why":"Distinguish reduced need for sleep from ordinary insomnia and consider alternative or contributing causes.","id":"mh-mania-talk-2"},{"cue":"Can I keep driving and make a big purchase today?","response":"Until this has been assessed, I am concerned about safety and major decisions. Let’s discuss a safe alternative to driving, postponing important purchases and involving a trusted person if appropriate. We will use the actual assessment and relevant guidance for the ongoing plan.","simple":"Let’s arrange safe transport and postpone major decisions while urgent assessment is organised.","why":"Address driving, spending, exploitation and practical support without implying that a vague reassurance establishes fitness or legal capacity.","id":"mh-mania-talk-3"},{"cue":"Could you increase my antidepressant to settle this?","response":"The current symptoms change what we need to review. I would not simply increase the antidepressant. We need urgent specialist advice about the diagnosis and the whole medication plan, including whether an antidepressant should be changed.","simple":"I would not simply increase it. Let’s seek urgent advice about these symptoms and the medication plan.","why":"CG185 advises urgent assessment for suspected mania and has specific treatment/antidepressant recommendations; avoid a generic self-directed stop/start or dose increase.","id":"mh-mania-talk-4"},{"cue":"What happens if I do not agree to a referral?","response":"Could you tell me what worries you about it? I will explain why I recommend it and what it involves. We still need to assess your understanding, safety and support, and arrange help under the appropriate local framework if there is serious danger.","simple":"Let’s discuss the concern, explain the recommendation and assess safety and understanding rather than leave this unresolved.","why":"Explore refusal and decision-making in context. Do not promise either forced admission or no intervention before the clinical/legal assessment.","id":"mh-mania-talk-5"}],"variations":[{"label":"Psychosis","change":"Grandiose beliefs and unsafe behaviour emerge.","action":"Increase urgency and arrange crisis or emergency assessment according to immediate danger.","phrase":"We need help today to keep things safe."},{"label":"Antidepressant started","change":"Symptoms followed a prescription change.","action":"Review urgently with specialist input; assess possible treatment-associated mania.","phrase":"That medicine change is important to the assessment."},{"label":"Past brief episodes","change":"They report earlier periods of overactivity.","action":"Arrange specialist diagnostic assessment even if currently settled, with urgency matched to risk.","phrase":"Your previous experiences help us choose safer treatment."}],"links":[{"label":"NICE CG185 — recommendations","url":"https://www.nice.org.uk/guidance/cg185/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not diagnose bipolar disorder from a questionnaire alone or treat possible mania as ordinary anxiety."],"followUp":"Arrange direct handover and confirm an immediate safety plan; ongoing monitoring and diagnosis are specialist-led.","reviewed":"2026-11-13","tags":["possible","mania","behind","reduced"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Increase urgency and arrange crisis or emergency assessment according to immediate danger. We need help today to keep things safe.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-ptsd","title":"PTSD after trauma","summary":"Ask permission and assess symptoms without requiring a detailed trauma narrative","presentation":"An adult has nightmares, avoidance and intrusive memories after an assault. They fear being forced to retell every detail at the first appointment.","assessment":["Ask permission and assess symptoms without requiring a detailed trauma narrative","Assess current safety, ongoing threat and self-harm","Explore dissociation, substances, mood and function","Consider physical injury, social needs and previous treatment"],"management":[{"step":"1. Establish safety","detail":"Address ongoing danger, urgent risk and practical instability."},{"step":"2. Explain","detail":"Describe trauma-related symptoms sensitively and let the person control the pace of discussion."},{"step":"3. Offer treatment","detail":"Offer an appropriate individual trauma-focused CBT intervention for adults presenting more than one month after trauma with PTSD or clinically important symptoms. For adult non-combat-related trauma, consider EMDR at 1–3 months if preferred and offer it after 3 months, according to NG116. Earlier presentations have their own active-monitoring/treatment recommendations. Medication can be considered for adults with diagnosed PTSD who prefer it, with regular review; do not use drugs to prevent PTSD."},{"step":"4. Enable access","detail":"Adapt the setting and communication, address barriers and arrange a follow-up route."}],"discussion":[{"cue":"Will you make me tell you every detail today?","response":"You do not have to give a detailed account today. I would like to understand the effects on you, whether you are safe now and what help you want. We can explain each step and agree a manageable pace.","simple":"We can start with the effects on you and current safety, without a detailed retelling today.","why":"Build trust and assess needs without forcing a detailed trauma narrative or a psychologically focused debriefing.","id":"mh-ptsd-talk-1"},{"cue":"What kind of treatment helps with the memories?","response":"Trauma-focused CBT and, in appropriate situations, EMDR are recommended approaches. The suitable option depends on the symptoms, timing, type of trauma and your preference. I can explain the referral and what to expect from an appropriately trained therapist.","simple":"We can discuss suitable trauma-focused treatment, how it works and how to access it.","why":"NG116 differentiates adult treatment by timing and non-combat trauma for EMDR; do not present every approach as identical for every presentation.","id":"mh-ptsd-talk-2"},{"cue":"Can I have tablets now to stop PTSD developing?","response":"There is not a recommended medicine course to prevent PTSD after trauma. We should assess what is happening now and offer appropriate support or treatment. For adults with established PTSD who prefer medication, suitable options need a separate discussion and regular review.","simple":"We do not use medicine simply to prevent PTSD after trauma. Let’s assess the symptoms and discuss appropriate support.","why":"Distinguish prevention from treatment of an established adult diagnosis; NG116 advises against preventive drug treatment, including benzodiazepines.","id":"mh-ptsd-talk-3"},{"cue":"I have been drinking to get through the night. Does that mean you cannot help me?","response":"It does not mean you should be excluded from PTSD treatment. We need to assess the drinking, any dependence or withdrawal and what makes treatment difficult, then coordinate help for both. If dependence is possible, any change in drinking needs a safe clinical plan.","simple":"We can address both. Let’s assess the drinking and agree safe, coordinated support.","why":"NG116 says not to exclude people solely for comorbid alcohol/drug misuse; manage barriers and acute risks rather than give an unsupported abrupt-stop instruction.","id":"mh-ptsd-talk-4"},{"cue":"The person who hurt me can still come to my home.","response":"Your current safety needs attention alongside treatment. Is it safe for you to speak now? Let’s understand the immediate threat and arrange the appropriate safeguarding or urgent support, using a contact method that does not put you at greater risk.","simple":"Let’s assess the current danger and arrange safe contact and appropriate support now.","why":"Ongoing threat changes the plan; a routine therapy referral alone does not address it.","id":"mh-ptsd-talk-5"}],"variations":[{"label":"Alcohol use","change":"Alcohol is used to suppress memories.","action":"Assess dependence and withdrawal and coordinate support; do not exclude PTSD treatment solely for substance misuse.","phrase":"We can address both together."},{"label":"Ongoing threat","change":"The perpetrator still has access.","action":"Prioritise safety and safeguarding alongside treatment planning.","phrase":"Your present safety comes first."},{"label":"Traumatic birth","change":"Symptoms follow a difficult delivery.","action":"Use perinatal and trauma pathways and assess parent–infant needs.","phrase":"We can arrange support that understands both the trauma and new parenthood."}],"links":[{"label":"NICE NG116 — recommendations","url":"https://www.nice.org.uk/guidance/ng116/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE CG192 — recommendations","url":"https://www.nice.org.uk/guidance/cg192/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not force detailed retelling or offer psychologically focused debriefing for prevention or treatment.","Do not conflate preventive drug treatment with medication choices for established adult PTSD, or exclude care solely because of substance misuse."],"followUp":"Agree review of safety, access to therapy and functioning; coordinate care where substance use, severe symptoms or perinatal needs complicate treatment.","reviewed":"2026-11-13","tags":["ptsd","after","trauma"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Assess dependence and withdrawal and coordinate support; do not exclude PTSD treatment solely for substance misuse. We can address both together.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-bullying","title":"Bullying, disability and deteriorating mental health","summary":"Assess mood, self-harm, sleep and function","presentation":"An adult with a long-term condition describes workplace humiliation and worsening mood. They ask whether the GP can solve the dispute.","assessment":["Assess mood, self-harm, sleep and function","Clarify specific events, current threat and desired outcome","Explore disability-related needs and workplace support","Assess financial pressure and safe social support"],"management":[{"step":"1. Treat health needs","detail":"Address the mental and physical health effects and immediate safety."},{"step":"2. Support function","detail":"Consider a fit note based on clinical function and discuss possible occupational-health input and reasonable adjustments."},{"step":"3. Explain boundaries","detail":"Provide factual medical information with consent; do not promise a legal finding or outcome."},{"step":"4. Agree practical steps","detail":"Discuss appropriate workplace, union or advice routes and psychological care according to need."}],"discussion":[{"cue":"Can you tell my employer they have broken the law?","response":"I can assess how this is affecting your health and provide relevant medical advice with appropriate consent. I cannot decide the legal dispute or guarantee what your employer will do. We can also discuss suitable advice and workplace support routes.","simple":"I can help with the health effects and relevant medical advice, but cannot promise a legal finding.","why":"Explain professional boundaries without withdrawing clinical or practical support.","id":"mh-bullying-talk-1"},{"cue":"Do I have to tell my manager everything I told you?","response":"Let’s clarify what information is needed and what you are comfortable sharing. A medical report for work should have an agreed purpose and appropriate consent; it should not automatically include your whole record.","simple":"We should agree the relevant information and consent rather than send your whole record automatically.","why":"Use proportionate, purpose-specific disclosure for a routine employer request and explain privacy arrangements.","id":"mh-bullying-talk-2"},{"cue":"Can I have a fit note saying I can never work there again?","response":"We should assess your current health and the effect on work tasks. A fit note can advise on fitness for work and potentially helpful adjustments; it cannot guarantee an employment outcome or resolve the dispute. Let’s agree what is clinically appropriate now and when to review it.","simple":"Let’s assess current function and appropriate work advice, with a review rather than a guaranteed employment outcome.","why":"Base certification on clinical function and current guidance, not a fixed legal or permanent occupational conclusion.","id":"mh-bullying-talk-3"},{"cue":"I cannot afford to be off work.","response":"That changes what is realistic. What could you manage safely, and are there adjustments or occupational-health support we can explore? We should also discuss appropriate financial or advice support while treating the health problems.","simple":"Let’s consider safe, feasible work adjustments and practical support as well as treatment.","why":"Use the actual financial barrier rather than assuming absence is possible or telling the person simply to endure harm.","id":"mh-bullying-talk-4"},{"cue":"I am so trapped that I have thought about ending my life.","response":"Thank you for telling me. I need to ask about those thoughts, any plans or preparations and whether you are safe right now. We will arrange the appropriate help; the workplace paperwork can wait while we address immediate safety.","simple":"Let’s assess your safety now and arrange the right help before dealing with the paperwork.","why":"Direct assessment and escalation follow the actual risk; a fit note or a future counselling appointment is not an immediate safety plan.","id":"mh-bullying-talk-5"}],"variations":[{"label":"Self-harm","change":"They disclose current suicidal intent.","action":"Arrange immediate safety assessment and escalation; the workplace dispute becomes secondary today.","phrase":"We need to focus on keeping you safe now."},{"label":"Employer asks for records","change":"A manager requests the whole record.","action":"Clarify consent, purpose and proportionate disclosure under professional guidance.","phrase":"We should agree exactly what information is relevant."},{"label":"Financial crisis","change":"They feel unable to take time off.","action":"Discuss feasible workplace changes and practical support rather than assume absence is possible.","phrase":"Let us make a plan you can realistically use."}],"links":[{"label":"NICE NG222 — recommendations","url":"https://www.nice.org.uk/guidance/ng222/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE NG225 — recommendations","url":"https://www.nice.org.uk/guidance/ng225/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NICE CG138: respectful, individual care","url":"https://www.nice.org.uk/guidance/cg138/chapter/recommendations","use":"Privacy, respect, communication and avoiding assumptions."},{"label":"GOV.UK: fit-note guidance for healthcare professionals","url":"https://www.gov.uk/government/publications/fit-note-guidance-for-healthcare-professionals/getting-the-most-out-of-the-fit-note-guidance-for-healthcare-professionals","use":"Health-based functional advice, work adjustments and consent."}],"pitfalls":["Do not promise that a GP letter proves discrimination or guarantees adjustments."],"followUp":"Arrange review of health, functioning, treatment and practical support; reassess risk if work circumstances worsen.","reviewed":"2026-11-13","tags":["bullying,","disability","and","deteriorating"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Arrange immediate safety assessment and escalation; the workplace dispute becomes secondary today. We need to focus on keeping you safe now.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-dependence","title":"Long-term benzodiazepine use and an early refill","summary":"Establish actual dose, last use, remaining supply and withdrawal symptoms","presentation":"An adult taking diazepam regularly has used extra tablets during stress and fears being cut off.","assessment":["Establish actual dose, last use, remaining supply and withdrawal symptoms","Assess sedation, alcohol, opioids and other medicines","Ask about overdose, self-harm and underlying anxiety","Review previous reduction attempts and prescriber records"],"management":[{"step":"1. Assess immediate danger","detail":"Severe withdrawal, seizures, respiratory depression or overdose require urgent or emergency care."},{"step":"2. Verify","detail":"Reconcile prescribing and actual use with the usual clinician and pharmacy; prevent conflicting supplies."},{"step":"3. Plan collaboratively","detail":"Avoid punitive language and abrupt discontinuation. If reducing, use an individualised gradual process adjusted to symptoms and clinical risk."},{"step":"4. Treat underlying needs","detail":"Offer appropriate anxiety or insomnia care and agree clear monitoring and prescribing responsibility."}],"discussion":[{"cue":"Are you going to cut me off because I used extra tablets?","response":"I will not leave you without a plan. First we need to check what you have taken, what is left and how you feel, then agree a safe way forward with the usual prescriber and pharmacy.","simple":"Let’s check your actual use and symptoms, then agree a safe plan with the usual team.","why":"Avoid punitive reassurance or a promise of a particular supply before assessing danger and reconciling medicines.","id":"mh-dependence-talk-1"},{"cue":"Are you calling me an addict?","response":"I am not making that judgement. The body can become physically dependent on a medicine, even when it was prescribed for a reason. We should assess what is happening for you without blame and discuss the benefits, risks and support you need.","simple":"I am not judging you. Physical dependence can happen with prescribed medicine. Let’s assess your situation and the support you need.","why":"Distinguish physical dependence from a diagnosis of addiction; an early request alone does not establish either the full history or a label.","id":"mh-dependence-talk-2"},{"cue":"Can you just issue my usual full supply now?","response":"I need to check the prescription record, actual doses, remaining tablets and other medicines first. I will explain the safe arrangements we can make and who will be responsible, so you are not left with conflicting instructions or an unexplained supply problem.","simple":"We need to verify the record and your actual use before deciding the safe supply plan.","why":"Medicine reconciliation and coordinated prescribing come before an automatic replacement or a punitive refusal.","id":"mh-dependence-talk-3"},{"cue":"Why not stop it all today and get it over with?","response":"A sudden stop can cause withdrawal and may be dangerous. Unless there is an exceptional medical reason for urgent change, reductions need an individual plan, adjusted to your symptoms and risk, with regular review. We should also treat the problem the medicine was helping with.","simple":"Please do not stop suddenly without an agreed clinical plan. We can review a gradual, individual approach and support the underlying problem.","why":"NG215 advises against abrupt cessation except in exceptional medical circumstances; avoid a universal taper schedule.","id":"mh-dependence-talk-4"},{"cue":"The last reduction made me feel much worse. Do I just have to push through?","response":"No. We should assess the symptoms and whether they could be withdrawal, a return of the original problem or something else. We can review the pace and next step together. A seizure or severe breathing difficulty needs emergency help: call 999. Serious confusion or other severe deterioration needs urgent assessment rather than waiting for a routine review.","simple":"Let’s assess what changed and review the pace. A seizure or severe breathing difficulty needs 999; other serious deterioration needs urgent assessment.","why":"Use symptoms to review the plan and urgency rather than assume failure, insist on a fixed timetable or automatically increase the dose.","id":"mh-dependence-talk-5"}],"variations":[{"label":"Seizure","change":"They have had a seizure after running out.","action":"Arrange emergency assessment; a routine taper discussion is insufficient.","phrase":"You need urgent medical assessment now."},{"label":"Alcohol co-use","change":"They drink heavily with the medicine.","action":"Assess respiratory and withdrawal risks and coordinate supported management.","phrase":"The combination changes what is safe today."},{"label":"Withdrawal symptoms","change":"Symptoms worsen after a reduction.","action":"Review whether symptoms reflect withdrawal, relapse or another illness and adapt the reduction plan.","phrase":"We can review the pace rather than push through without assessment."}],"links":[{"label":"NICE NG215 — recommendations","url":"https://www.nice.org.uk/guidance/ng215/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not give a universal seven-day taper or stop treatment as punishment for early use."],"followUp":"Agree a named prescriber, next review and a specific route for withdrawal symptoms or supply problems; monitor at each reduction.","reviewed":"2026-11-12","tags":["long-term","benzodiazepine","use","and"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Arrange emergency assessment; a routine taper discussion is insufficient. You need urgent medical assessment now.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-opioid","title":"Codeine use, persistent pain and dependence","summary":"Assess pain diagnosis, new red flags and functional goals","presentation":"An adult requests more codeine for longstanding non-cancer pain. The benefit is decreasing and they feel unwell when doses are missed.","assessment":["Assess pain diagnosis, new red flags and functional goals","Establish actual opioid use and other sedating drugs","Assess constipation, sedation, overdose and withdrawal","Explore mood, sleep, previous treatment and daily function"],"management":[{"step":"1. Reassess","detail":"Do not assume persistent pain has one cause or that increasing opioid dose is the answer."},{"step":"2. Review balance","detail":"Discuss actual benefit, harms and dependence without blame; verify medicines and prescribing history."},{"step":"3. Agree change","detail":"When reduction is appropriate, use an individualised supported plan; avoid abrupt cessation except exceptional medical circumstances requiring urgent management."},{"step":"4. Support function","detail":"Offer condition-appropriate alternatives, rehabilitation and psychological support, with specialist input where needed."}],"discussion":[{"cue":"The codeine does less now. Can I just have a stronger dose?","response":"Before increasing it, let’s review the pain, what the medicine helps you do and any harms. I also need to check the actual product and doses, other sedating medicines and whether there is a new cause for the pain. Then we can agree a useful, safer plan.","simple":"Let’s review benefit, function, harms and actual medicine use before considering more.","why":"Do not equate reduced benefit with an automatic need for opioid escalation or overlook new red flags.","id":"mh-opioid-talk-1"},{"cue":"I feel ill if I miss a dose. Does that mean the pain is worse?","response":"It could be withdrawal, a return of the original problem or another illness. We need to look at the symptoms and timing rather than guess. Physical dependence can happen with prescribed medicines; we can discuss this without blame and plan any change safely.","simple":"Let’s assess the symptoms and timing. It may be withdrawal, returning pain or something else.","why":"Distinguish dependence/withdrawal from relapse or a new illness; avoid diagnosing addiction from one symptom.","id":"mh-opioid-talk-2"},{"cue":"Could I stop all the tablets today to get this over with?","response":"A sudden stop can cause withdrawal. Unless an exceptional medical situation needs urgent change, reductions should follow an individual, supported plan that we review and adjust. We should also agree how to help the underlying pain and function.","simple":"Please do not stop suddenly without an agreed clinical plan. Let’s arrange supported changes and pain care.","why":"Use NG215’s flexible, stepwise withdrawal approach rather than a universal taper or unsupported abrupt cessation.","id":"mh-opioid-talk-3"},{"cue":"Some of the tablets contain paracetamol too. Does that matter?","response":"Yes. We need to check every ingredient and the total you have taken, including other products. Too much paracetamol can cause serious harm even before you feel unwell. If you have taken more than the recommended amount, seek advice now; breathing difficulty or severe impairment needs emergency help.","simple":"Let’s check all ingredients and doses. Too much co-codamol needs advice now even if you feel well; breathing difficulty needs 999.","why":"Recognise combination-product risk. NHS co-codamol advice uses urgent 111 advice after excess dosing even if well, with emergency action for breathing difficulty; a clinician should assess the actual ingestion.","id":"mh-opioid-talk-4"},{"cue":"If you reduce it, who will help when I have a bad day?","response":"Let’s agree the prescribing clinician, the next review and what to do if pain or withdrawal symptoms become difficult. We can discuss condition-appropriate support and revise the pace if needed, rather than leave you to manage alone or change doses without advice.","simple":"Let’s name the clinician, review and contact plan, with support for pain and any difficult symptoms.","why":"A medicine reduction needs continued care and ownership, not only a dose schedule.","id":"mh-opioid-talk-5"}],"variations":[{"label":"Overdose signs","change":"They are very drowsy with slow breathing.","action":"Activate emergency care immediately.","phrase":"This needs emergency help now."},{"label":"New neurological symptoms","change":"Back pain now includes bladder changes.","action":"Assess for a spinal emergency rather than simply increasing analgesia.","phrase":"The new symptoms need urgent assessment."},{"label":"Cancer pain","change":"Pain is due to advanced cancer.","action":"Use the appropriate cancer/palliative pathway; do not apply this chronic non-cancer withdrawal framework automatically.","phrase":"Your situation needs a pain plan specific to the cancer."}],"links":[{"label":"NICE NG215 — recommendations","url":"https://www.nice.org.uk/guidance/ng215/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"},{"label":"NHS: co-codamol dosing and excess doses","url":"https://www.nhs.uk/medicines/co-codamol-for-adults/how-and-when-to-take-co-codamol-for-adults/","use":"Combination ingredients, urgent advice after excess dosing and emergency breathing symptoms."}],"pitfalls":["Do not apply this dependence guideline as a blanket opioid withdrawal protocol for acute pain, cancer pain or end-of-life care."],"followUp":"Review function, adverse effects and the reduction plan regularly, with a clear prescribing owner and escalation route.","reviewed":"2026-11-13","tags":["codeine","use,","persistent","pain"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Activate emergency care immediately. This needs emergency help now.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-gambling","title":"Gambling-related harms and hidden suicidal risk","summary":"Ask about gambling patterns and impacts without judgement","presentation":"An adult presents with insomnia and irritability after escalating online gambling losses. They are reluctant to discuss debt.","assessment":["Ask about gambling patterns and impacts without judgement","Assess suicide directly, including acute risk after losses or disclosure","Explore debt, relationships, safeguarding and substances","Review medicines associated with impulse-control problems"],"management":[{"step":"1. Prioritise safety","detail":"Gambling harm can drive suicide risk even without another diagnosis; act on current danger."},{"step":"2. Offer treatment","detail":"Offer gambling-specific group CBT after diagnosis, with individual CBT if the person does not want a group, a group is not possible or it is unsuitable. Discuss the actual referral/access and peer support if wanted; coordinate care for other needs."},{"step":"3. Reduce harm","detail":"Discuss practical barriers to gambling, financial safeguards and support for affected others with appropriate consent."},{"step":"4. Use specialist medicines appropriately","detail":"Consider naltrexone only in the selected NG248 circumstances after an appropriate psychological course has not achieved the desired outcome or repeated relapses occur despite it. Initiation/supervision requires a suitably qualified experienced specialist, with opioid-use, kidney/liver and other prescribing checks and ongoing monitoring; it is not an automatic GP first-line prescription."}],"discussion":[{"cue":"I just need something to sleep. I would rather not talk about the losses.","response":"We can discuss the sleep, and I also want to understand how the gambling is affecting you. You do not have to justify yourself. The losses, debts and how you feel afterwards matter to choosing the right help and checking safety.","simple":"Let’s help with sleep and understand the gambling’s effect without judgement.","why":"Look beyond the presenting symptom and stigma; gambling-related harm can be a major driver of distress without another diagnosis.","id":"mh-gambling-talk-1"},{"cue":"After the last loss I thought everyone would be better off without me.","response":"Thank you for telling me. Have you had thoughts about ending your life, any plans or preparations, or done anything to harm yourself? We need to assess your safety now and arrange help that matches the risk. We should not wait for the next gambling appointment if there is immediate danger.","simple":"Let’s assess the suicidal thoughts and safety now, then arrange the right help.","why":"NG248 calls for direct assessment and notes risk can be highest immediately after a gambling episode. Do not assume a low-risk presentation because the person came about sleep.","id":"mh-gambling-talk-2"},{"cue":"I could not talk in a group. Does that mean there is no treatment for me?","response":"No. Gambling-specific CBT is recommended, and individual CBT is an option if you do not want a group, a group is not possible or it is unsuitable. Let’s check the appropriate service and a format you can engage with.","simple":"We can discuss individual gambling-specific CBT if a group does not fit. Let’s check the real referral options.","why":"Apply NG248’s group/individual recommendations and make access practical rather than turn preference into exclusion.","id":"mh-gambling-talk-3"},{"cue":"Is there anything I can do to make another bet harder today?","response":"We can discuss options such as self-exclusion, blocking tools and bank payment blocks, alongside treatment and a safety plan. If you want someone to help with money, we should choose support that is trusted and safe, with your involvement rather than assume a particular family member should take control.","simple":"Let’s discuss practical blocking options and safe support as part of the wider treatment plan.","why":"Use agreed practical safeguards while considering coercion, affected others and the limits of access barriers alone.","id":"mh-gambling-talk-4"},{"cue":"Could I have a medicine for the urges? I also take codeine.","response":"Medicines are not the automatic first step. A specialist may consider naltrexone in selected circumstances after appropriate psychological treatment has not helped enough or there are repeated relapses. Your codeine matters because opioids need specific checks before that medicine is considered. Please do not change the codeine suddenly to try it yourself.","simple":"That needs a specialist decision. Codeine is an important safety check before naltrexone; do not start it or change opioids yourself.","why":"NG248 requires specialist initiation/supervision and checks including current opioids, liver and kidney function. Do not add a gambling medicine without the full prescribing assessment.","id":"mh-gambling-talk-5"}],"variations":[{"label":"Major loss tonight","change":"They intend to harm themselves after a loss.","action":"Arrange immediate emergency or crisis help based on danger.","phrase":"Your safety needs help now."},{"label":"Partner affected","change":"Family finances and children are at risk.","action":"Assess safeguarding and practical support, involve others with consent where appropriate.","phrase":"We should also think about who else is affected."},{"label":"Impulse-control medicine","change":"The problem began after a medication change.","action":"Coordinate urgent review with the treating team; do not stop essential treatment without a safe plan.","phrase":"That timing is important and needs a medication review."}],"links":[{"label":"NICE NG248 — recommendations","url":"https://www.nice.org.uk/guidance/ng248/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not substitute an SSRI or sleeping tablet for gambling-specific assessment and treatment."],"followUp":"Arrange active follow-up for safety, treatment access and financial/social harms. Ask directly about suicidal thinking and intent; risk can be highest immediately after a gambling episode. Agree a safety plan, named support and an urgent route when indicated, and review again after relapse or disclosure.","reviewed":"2026-11-13","tags":["gambling-related","harms","and","hidden"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Arrange immediate emergency or crisis help based on danger. Your safety needs help now.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-eating","title":"Adolescent eating disorder and physical risk","summary":"Assess weight trajectory, restriction, purging, exercise and intake","presentation":"A teenager has restricted intake, lost weight quickly and feels faint. Their BMI is not in an underweight range and the family asks to wait.","assessment":["Assess weight trajectory, restriction, purging, exercise and intake","Check observations, hydration, syncope and physical symptoms promptly","Assess electrolytes, glucose and ECG need according to risk","Ask about self-harm, comorbidity, family context and safeguarding"],"management":[{"step":"1. Assess in person","detail":"Rapid weight loss and current faintness in this scenario need prompt in-person physical assessment today; do not use normal appearance or BMI to dismiss risk. Urgency and setting depend on the full current assessment; collapse or severe physical compromise needs emergency care."},{"step":"2. Escalate instability","detail":"Severe dehydration, electrolyte disturbance, malnutrition or organ compromise requires acute medical care, potentially emergency admission."},{"step":"3. Refer","detail":"If an eating disorder is suspected after initial assessment, refer immediately to a community-based age-appropriate eating-disorder service. Do not wait for a BMI threshold or let that referral delay acute medical care when physical health is compromised."},{"step":"4. Coordinate","detail":"Agree monitoring, family involvement, nutrition support and safe follow-up with specialists; refeeding risk needs appropriate expertise."}],"discussion":[{"cue":"The BMI is normal. Surely it is safe to wait?","response":"The speed of weight loss, restricted intake and faintness can matter even when BMI is not low. We need a physical assessment today and an appropriate specialist referral. We should decide urgency from the whole picture rather than one number.","simple":"A normal-range BMI does not rule out risk. The faintness and rapid weight loss need assessment today.","why":"NG69 says not to use single measures to decide treatment or an absolute BMI/weight threshold for admission.","id":"mh-eating-talk-1"},{"cue":"What will you check in the physical assessment?","response":"We need to assess how your body is coping, including the current symptoms, pulse, blood pressure, hydration and other examination findings. Blood tests and an ECG may be needed depending on risk. I will explain each step and what the findings mean for where care is safest.","simple":"We will assess symptoms and physical observations, with blood tests or ECG as needed, then decide the safest care setting.","why":"Describe an actual risk assessment, not a promise that a single normal test settles medical safety.","id":"mh-eating-talk-2"},{"cue":"I have been vomiting and taking laxatives, but only to control my weight.","response":"Thank you for telling me. These can affect body salts and the heart, so we need to assess the amount, timing, symptoms and relevant tests promptly. If there is collapse or another severe physical problem, we need emergency help now.","simple":"Vomiting and laxatives can affect salts and heart rhythm. Let’s assess the risks promptly; collapse needs emergency help.","why":"Use disclosure to change the physical assessment and urgency, without blame or a fixed unsupported threshold.","id":"mh-eating-talk-3"},{"cue":"I am terrified the service will make me eat more.","response":"I hear that this feels frightening. We should explain the assessment and treatment step by step, involve you in decisions and discuss what support would help. The fear matters, and so do the physical risks; we need specialist help rather than leave you to manage a risky situation alone.","simple":"Let’s discuss the fear and the assessment step by step, while arranging help for the health risks.","why":"Support decision-making and assess competence/capacity and safety where needed; do not equate fear with an informed, risk-free refusal.","id":"mh-eating-talk-4"},{"cue":"Can we just use a strict meal plan from the internet until the appointment?","response":"Nutrition is important, but the right plan depends on the current medical risk. If intake has been very low or health is compromised, restarting nutrition may need specialist monitoring. I will coordinate a safe plan and confirm who checks you while referral and treatment are arranged.","simple":"Let’s get an appropriate nutrition and monitoring plan based on the assessment rather than use an unassessed internet plan.","why":"Recognise refeeding and other medical risks without withholding needed care or supplying a universal unsupervised calorie regimen.","id":"mh-eating-talk-5"}],"variations":[{"label":"Collapse","change":"They collapse or have severe physical symptoms.","action":"Arrange emergency care now.","phrase":"This needs immediate medical assessment."},{"label":"Purging","change":"Vomiting and laxative misuse emerge.","action":"Assess electrolyte and cardiac risk and increase urgency according to findings.","phrase":"These behaviours can affect salts and heart rhythm."},{"label":"Referral declined","change":"The teenager fears weight restoration.","action":"Explore fears, support decision-making and assess capacity/competence and safety; seek specialist advice promptly.","phrase":"I hear the fear, and we still need to address the risks together."}],"links":[{"label":"NICE NG69 — recommendations","url":"https://www.nice.org.uk/guidance/ng69/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not decide admission using an absolute BMI threshold or treat a screening score as a complete assessment."],"followUp":"Name the clinician monitoring physical status and referral progress; frequency follows clinical risk and specialist advice, not a standard distant review.","reviewed":"2026-11-13","tags":["adolescent","eating","disorder","and"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"Arrange emergency care now. This needs immediate medical assessment.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}},{"id":"mh-alcohol","title":"Alcohol dependence, withdrawal and change","summary":"Establish quantity, strength, pattern, last drink and current withdrawal","presentation":"An adult wants to stop heavy daily alcohol use immediately. They describe morning tremor and poor nutrition.","assessment":["Establish quantity, strength, pattern, last drink and current withdrawal","Ask about past seizures, delirium, detoxification and other substances","Assess nutrition, physical illness, injury and cognition","Assess self-harm, driving, dependants and available support"],"management":[{"step":"1. Assess urgency","detail":"Severe withdrawal, seizures, confusion or suspected Wernicke encephalopathy require emergency hospital assessment."},{"step":"2. Plan supported withdrawal","detail":"Explain that sudden stopping or a large reduction may be dangerous in dependence; arrange skilled assessment for the appropriate setting."},{"step":"3. Treat nutritional risk","detail":"Assess need for oral or parenteral thiamine according to risk and presentation, using current guidance; do not delay emergency care."},{"step":"4. Continue recovery care","detail":"Coordinate alcohol treatment, psychological support, relapse prevention and physical-health monitoring with named follow-up."}],"discussion":[{"cue":"I am ready to stop completely today. That must be the safest choice.","response":"Wanting change is an important step. Because of the daily drinking and shaking, we need to assess dependence and withdrawal before a sudden stop or big reduction. Let’s arrange a safe, supported plan rather than ask you to manage a potentially dangerous withdrawal alone.","simple":"Let’s assess withdrawal risk and arrange supported change. A sudden stop can be dangerous in dependence.","why":"CG100 advises avoiding sudden reduction in dependent drinkers outside an appropriate withdrawal plan; do not confuse motivation with medical safety.","id":"mh-alcohol-talk-1"},{"cue":"What do you need to know before choosing where I detox?","response":"I need to check the amount and pattern, last drink, current symptoms, previous withdrawal seizures or confusion, physical health, nutrition and other substances. We also need to know what support is actually available at home. Those findings help decide the safest setting.","simple":"Let’s assess current withdrawal, past severe episodes, physical health and real support before choosing the setting.","why":"Use clinical risk and social vulnerability rather than a fixed community regimen for everyone.","id":"mh-alcohol-talk-2"},{"cue":"I had a seizure when I stopped before, but I feel I can do it alone this time.","response":"That history increases the concern about severe withdrawal. We need prompt skilled assessment and to consider hospital-based medically supported withdrawal rather than assume home is safe. A seizure, serious confusion or severe deterioration now needs emergency help.","simple":"A past withdrawal seizure is important. Let’s arrange skilled assessment; a seizure or severe deterioration now needs 999.","why":"CG100 recommends hospital admission for acute withdrawal with, or high risk of, seizures or delirium tremens; do not delay emergency care for severe current symptoms.","id":"mh-alcohol-talk-3"},{"cue":"Can vitamins replace the withdrawal treatment?","response":"Nutrition matters, and thiamine may be needed to protect your health, but it does not replace assessment and treatment of withdrawal. The route and treatment depend on your condition and risk. Confusion or other serious symptoms need urgent assessment, not only a vitamin tablet.","simple":"Nutrition and thiamine may be part of care, but cannot replace a safe withdrawal plan.","why":"Assess nutritional/Wernicke risk and use the appropriate oral/parenteral pathway; do not give a universal dose or let supplements delay acute care.","id":"mh-alcohol-talk-4"},{"cue":"What happens after I get through withdrawal?","response":"Withdrawal is one part of the plan. We should agree ongoing alcohol treatment, support for triggers and mental health, suitable relapse-prevention options and physical-health review. Let’s name who coordinates it and when you will next be contacted.","simple":"Let’s arrange ongoing treatment, relapse support and physical review, with a named team and next contact.","why":"Connect acute management to recovery and continuity rather than present detoxification as a complete cure.","id":"mh-alcohol-talk-5"}],"variations":[{"label":"Previous withdrawal seizure","change":"They have a history of severe withdrawal.","action":"This increases risk and may require inpatient medically assisted withdrawal; seek skilled urgent assessment.","phrase":"Your previous seizure affects where withdrawal should be managed."},{"label":"Confusion and poor balance","change":"New neurological features develop.","action":"Treat as possible serious alcohol-related complication and arrange emergency care.","phrase":"These symptoms need hospital assessment now."},{"label":"Not ready to stop","change":"They decline referral.","action":"Explore concerns, offer harm-reduction engagement and continued review; still assess immediate risks and withdrawal.","phrase":"We can keep working together without forcing a decision today."}],"links":[{"label":"NICE CG100 — recommendations","url":"https://www.nice.org.uk/guidance/cg100/chapter/recommendations","use":"Assessment, treatment and escalation for this presentation"}],"pitfalls":["Do not advise abrupt cessation in a dependent patient or provide a generic unsupervised detox regimen."],"followUp":"Confirm service handover and early follow-up matched to physical and withdrawal risk; arrange ongoing relapse-prevention and nutritional review.","reviewed":"2026-11-13","tags":["alcohol","dependence,","withdrawal","and"],"priorities":["Identify current danger and the appropriate assessment setting.","Connect the patient’s goal with a feasible clinical plan."],"safetyNet":["Suspected overdose, seizure, collapse, severe breathing difficulty or immediate danger: arrange emergency help now.","New intent to act on suicidal thoughts, rapidly worsening mental state or inability to stay safe: seek urgent same-day crisis assessment; use emergency care for immediate danger.","If the agreed referral or review cannot happen, contact the named clinical team rather than wait without a plan."],"retrieval":{"question":"How would your management change in the first variation, and how would you explain the reason?","answer":"This increases risk and may require inpatient medically assisted withdrawal; seek skilled urgent assessment. Your previous seizure affects where withdrawal should be managed.","checks":["Named the changed risk or need","Adapted management and urgency","Explained the plan without blame and checked feasibility"]}}]},{"id":"paediatrics","title":"Paediatrics","description":"Children, young people and families: urgent assessment, development, common symptoms and practical treatment plans.","icon":"02","reviewed":"2026-11-11","cases":[{"id":"pd-fever","title":"Fever in a young child: assess before reassuring","summary":"A parent phones about a 2-year-old with fever and reduced drinking.","presentation":"A parent phones about a 2-year-old with fever and reduced drinking. They want antibiotics because a relative previously had sepsis. You have not examined the child.","priorities":["Establish age, duration, current alertness, breathing, colour and rash","Assess hydration, urine output, intake and ability to keep fluids down"],"assessment":["Establish age, duration, current alertness, breathing, colour and rash","Assess hydration, urine output, intake and ability to keep fluids down","Ask about focal symptoms, medical conditions, immunisation and parental concern","Determine whether emergency or face-to-face assessment is required; do not invent normal observations"],"management":[{"step":"1. Triage first","detail":"Use age-appropriate fever and sepsis assessment. Emergency features need immediate help; arrange timely examination when remote assessment cannot establish severity."},{"step":"2. Make a reasoned decision","detail":"Antibiotics depend on the likely cause and clinical findings. Explain the working assessment and uncertainty rather than prescribe solely to reduce anxiety."},{"step":"3. Support comfort","detail":"Discuss fluids and appropriate comfort measures. If antipyretics are used, follow age/weight and product guidance; they do not prove an illness is harmless when the temperature falls."},{"step":"4. Close the loop","detail":"Give selected warning signs, a route to urgent help and a review matched to illness severity and persistence. Confirm the parent can carry out the plan."}],"discussion":[{"cue":"Last time we waited and it got worse.","response":"I can understand why that experience worries you. First I need to check how your child is now, so we choose the right assessment and treatment.","why":"Recognise the reason behind the antibiotic request.","id":"pd-fever-talk-1","simple":"I understand why you are worried. Let’s check how your child is now and choose the right care."},{"cue":"Can you promise it is only a virus?","response":"I cannot promise that by phone. I will explain what we can assess now and whether your child needs an examination.","why":"Avoid false certainty.","id":"pd-fever-talk-2","simple":"I cannot promise a cause by phone. Let’s decide what we can assess and whether an examination is needed."},{"cue":"What should I watch for?","response":"Let us go through the specific warning symptoms and exactly where to get help, rather than just say to come back if worse.","why":"Introduce, then provide the actual safety net.","id":"pd-fever-talk-3","simple":"Let’s go through the actual warning symptoms, how urgently to act and where to get help."}],"variations":[{"label":"Young infant","change":"The child is 6 weeks old with a temperature of 38°C.","action":"This is a high-risk age/temperature combination requiring urgent paediatric assessment; use emergency care if seriously unwell.","phrase":"At this age, that temperature needs urgent assessment."},{"label":"Non-blanching rash and illness","change":"A new rash does not fade under pressure and the child appears unwell.","action":"Treat as a possible serious infection and arrange emergency assessment; do not delay to complete routine questions.","phrase":"We need emergency help now."},{"label":"Persistent fever","change":"The fever reaches 5 days.","action":"Reassess and consider causes such as Kawasaki disease and other significant illness, using the clinical picture.","phrase":"The duration means we need to assess again."}],"safetyNet":["Severe breathing difficulty, markedly reduced responsiveness, blue/mottled appearance or rapid deterioration: arrange emergency help immediately.","Poor drinking, markedly fewer wet nappies or worsening parental concern: urgent reassessment according to severity.","Explain what to do if the planned assessment or review cannot be accessed."],"followUp":"Specify the reassessment interval from current risk and the expected course; do not simply wait for a fixed week if deteriorating.","pitfalls":["Do not use response to antipyretics to distinguish serious from non-serious illness.","Do not reassure on a remote impression without acknowledging missing observations."],"links":[{"label":"NICE NG143 — recommendations","url":"https://www.nice.org.uk/guidance/ng143/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["fever","in","a","young","child:"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"This is a high-risk age/temperature combination requiring urgent paediatric assessment; use emergency care if seriously unwell. At this age, that temperature needs urgent assessment.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-gastroenteritis","title":"Diarrhoea and vomiting: dehydration and home care","summary":"A toddler has diarrhoea and vomiting and is drinking less.","presentation":"A toddler has diarrhoea and vomiting and is drinking less. The parent cannot tell whether wet nappies are reduced because every nappy contains diarrhoea.","priorities":["Assess responsiveness, breathing, perfusion and dehydration","Clarify age, duration, vomiting colour, blood, pain, intake and urine"],"assessment":["Assess responsiveness, breathing, perfusion and dehydration","Clarify age, duration, vomiting colour, blood, pain, intake and urine","Consider travel, contacts, underlying illness and diagnoses other than gastroenteritis","Assess whether the family can give fluids and access help"],"management":[{"step":"1. Assess hydration","detail":"Arrange examination when hydration or severity cannot be established remotely. Shock or severe illness needs emergency transfer."},{"step":"2. Use appropriate fluids","detail":"For children suitable for oral treatment, explain oral rehydration solution in small frequent amounts according to the assessed rehydration plan. Continue breastfeeding; follow guidance on feeding during and after rehydration."},{"step":"3. Avoid unnecessary treatment","detail":"Antibiotics are not routine, and antidiarrhoeal medicines are not an appropriate default in young children. Investigations depend on clinical and epidemiological indications."},{"step":"4. Explain practical care","detail":"Discuss hygiene, avoiding fruit juice/fizzy drinks until diarrhoea stops, and the usual 48-hour exclusion after the last vomiting or diarrhoea episode, subject to specific infection/public-health advice."}],"discussion":[{"cue":"How do I know if they are dehydrated?","response":"I want to assess the drinking, urine, behaviour and physical signs together. Because the nappies are difficult to interpret, an examination may be needed.","why":"Explain why one sign is insufficient.","id":"pd-gastroenteritis-talk-1","simple":"We need to assess drinking, urine, behaviour and physical signs together. An examination may be needed."},{"cue":"Should I stop breastfeeding?","response":"Keep breastfeeding. We can discuss additional oral rehydration if needed and explain the feeding plan for your child.","why":"Give a practical answer.","id":"pd-gastroenteritis-talk-2","simple":"Keep breastfeeding. Let’s agree any extra rehydration and the feeding plan for your child."},{"cue":"Can you give something to stop it?","response":"The main treatment is replacing fluid safely. We also need to check that nothing suggests another cause.","why":"Reconnect the request with the actual need.","id":"pd-gastroenteritis-talk-3","simple":"Replacing fluid safely is the main treatment. We must also check for another cause."}],"variations":[{"label":"Bilious vomiting","change":"The vomit is green.","action":"Arrange urgent emergency assessment for possible obstruction or another serious cause; do not label routine gastroenteritis.","phrase":"Green vomiting needs urgent assessment."},{"label":"Oral treatment fails","change":"The child cannot keep oral rehydration down and is worsening.","action":"Arrange urgent reassessment; enteral or intravenous rehydration may be needed in a supervised setting.","phrase":"The home plan is not working safely now."},{"label":"Blood in stool","change":"Bloody diarrhoea develops.","action":"Reassess and use indicated stool testing and specialist advice; avoid assuming all infection needs the same antibiotic.","phrase":"This change needs a fresh assessment."}],"safetyNet":["Collapse, poor responsiveness or signs of shock: emergency help now.","Persistent vomiting preventing fluids, substantially reduced urine or increasing drowsiness: urgent assessment.","Severe localised pain, green vomiting or blood in stool: prompt escalation appropriate to severity."],"followUp":"Agree review of intake, hydration and symptoms, with earlier assessment for deterioration; confirm the family can obtain and give the recommended fluids.","pitfalls":["Do not assume diarrhoea excludes a surgical cause.","Do not offer a generic rehydration volume without weight and clinical assessment."],"links":[{"label":"NICE CG84 — recommendations","url":"https://www.nice.org.uk/guidance/cg84/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["diarrhoea","and","vomiting:","dehydration","and"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Arrange urgent emergency assessment for possible obstruction or another serious cause; do not label routine gastroenteritis. Green vomiting needs urgent assessment.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-constipation","title":"Constipation, overflow soiling and family strain","summary":"A school-aged child soils underwear and avoids the toilet because passing stool hurts.","presentation":"A school-aged child soils underwear and avoids the toilet because passing stool hurts. The parent thinks the child is doing it deliberately and has limited money for food.","priorities":["Check onset, stool pattern, pain, withholding, soiling and growth","Look for neonatal onset, delayed meconium, neurological signs, distension with vomiting or other red flags"],"assessment":["Check onset, stool pattern, pain, withholding, soiling and growth","Look for neonatal onset, delayed meconium, neurological signs, distension with vomiting or other red flags","Assess faecal impaction and examination needs","Explore toileting access, school, finances, treatment use and family distress"],"management":[{"step":"1. Explain the mechanism","detail":"Overflow soiling may occur around retained stool; it is not wilful misbehaviour. Avoid blame and explain the pain–withholding cycle."},{"step":"2. Treat appropriately","detail":"If idiopathic constipation is established, assess impaction and use age-appropriate disimpaction when indicated, commonly with a macrogol regimen checked against current prescribing guidance."},{"step":"3. Maintain improvement","detail":"Maintenance laxatives often continue beyond the first improvement, with gradual adjustment. Combine with regular supported toileting, rewards for behaviours rather than dry pants, and suitable diet/fluids."},{"step":"4. Make it feasible","detail":"Provide a written regimen and accessible toilet/school plan, address cost and supply, and review response rather than rely on dietary advice alone."}],"discussion":[{"cue":"They must be doing it on purpose.","response":"The leakage may happen because stool has built up and softer stool leaks around it. Blaming them will not solve that; we need to make passing stool comfortable again.","why":"Remove shame.","id":"pd-constipation-talk-1","simple":"Stool can build up and leak around the blockage. Let’s treat it without blaming the child."},{"cue":"Can we just change the diet?","response":"Healthy food and fluids help, but established constipation often needs medicine as well. I will explain the actual regimen and review it with you.","why":"Set realistic expectations.","id":"pd-constipation-talk-2","simple":"Food and fluids help, but medicine is often needed too. I will explain and review the actual plan."},{"cue":"Will this be fixed tomorrow?","response":"It can take time for the bowel to recover. We will check the response and adjust the plan rather than stop as soon as one stool passes.","why":"Explain continuity.","id":"pd-constipation-talk-3","simple":"Recovery can take time. We will review and adjust treatment rather than stop after one stool."}],"variations":[{"label":"Red flags","change":"Constipation began in the neonatal period with delayed meconium.","action":"Arrange specialist assessment for an underlying cause rather than label idiopathic constipation.","phrase":"The early onset changes what we need to investigate."},{"label":"Disimpaction started","change":"Soiling initially increases during treatment.","action":"Explain that this can occur, check the prescribed regimen and symptoms, and review for completion or complications.","phrase":"Some leakage can increase while retained stool clears."},{"label":"Treatment not accessible","change":"The family cannot obtain or administer the medicine.","action":"Resolve supply, formulation, language and school barriers before calling the treatment ineffective.","phrase":"Let us make the plan possible to follow."}],"safetyNet":["Vomiting with marked distension, severe pain or a very unwell child: urgent assessment.","New neurological symptoms, faltering growth or unexplained bleeding: reassess and investigate appropriately.","Contact the treating team if the prescribed regimen cannot be given or symptoms worsen."],"followUp":"During disimpaction, review within 1 week; maintenance requires planned continuing review and a supported reduction plan when appropriate.","pitfalls":["Do not blame the child or treat established constipation with diet alone.","Do not abruptly stop maintenance treatment after the first improvement."],"links":[{"label":"NICE CG99 — recommendations","url":"https://www.nice.org.uk/guidance/cg99/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["constipation,","overflow","soiling","and","family"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Arrange specialist assessment for an underlying cause rather than label idiopathic constipation. The early onset changes what we need to investigate.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-newborn-weight","title":"Newborn weight loss and feeding concerns","summary":"A newborn has lost more than 10% of birth weight.","presentation":"A newborn has lost more than 10% of birth weight. The parent is exhausted and worried that asking for help means breastfeeding has failed.","priorities":["Assess current illness, hydration, urine, stool, alertness and jaundice","Confirm weight measurements and feeding history, including observed feeding"],"assessment":["Assess current illness, hydration, urine, stool, alertness and jaundice","Confirm weight measurements and feeding history, including observed feeding","Ask about birth history, milk transfer and maternal health","Identify urgent paediatric needs and skilled feeding support"],"management":[{"step":"1. Assess promptly","detail":"Weight loss over 10% warrants clinical assessment for dehydration or illness, a detailed feeding history and observation by someone with appropriate expertise."},{"step":"2. Support feeding","detail":"Arrange skilled breastfeeding or formula-feeding support matched to the situation. Discuss supplements when clinically indicated, supporting breastmilk supply and the parent’s informed preference."},{"step":"3. Escalate when indicated","detail":"Marked loss, illness, dehydration or failure to respond to feeding support requires paediatric input; a routine reweigh alone may be unsafe."},{"step":"4. Agree monitoring","detail":"Use a coordinated feeding and weight plan, avoiding unnecessary repeated weighing and conflicting advice. Check the parent understands what to do tonight."}],"discussion":[{"cue":"Have I failed at feeding?","response":"You have done the right thing by asking for help. We need to check the baby and observe a feed so we can make a plan that works for both of you.","why":"Reduce blame while retaining assessment.","id":"pd-newborn-weight-talk-1","simple":"Asking for help is the right step. Let’s check your baby and observe a feed together."},{"cue":"Can we wait for another weight?","response":"I want to assess the baby’s hydration and feeding now. The next weight is one part of monitoring, not a replacement for that assessment.","why":"Explain urgency.","id":"pd-newborn-weight-talk-2","simple":"We need to assess hydration and feeding now. A repeat weight alone cannot replace that."},{"cue":"Will I have to stop breastfeeding?","response":"Not automatically. If extra feeds are needed, we can discuss how to give them while supporting your feeding goals and milk supply.","why":"Avoid a forced either/or choice.","id":"pd-newborn-weight-talk-3","simple":"Not automatically. Let’s discuss any extra feeds while supporting your feeding wishes and milk supply."}],"variations":[{"label":"Lethargy","change":"The baby is difficult to wake and feeding poorly.","action":"Arrange emergency or urgent paediatric care according to severity; do not wait for feeding support alone.","phrase":"The baby needs urgent medical assessment."},{"label":"Ongoing loss","change":"Weight continues to fall despite support.","action":"Seek paediatric assessment and review the actual feeding plan and possible underlying illness.","phrase":"The response tells us we need more assessment."},{"label":"Parent overwhelmed","change":"The parent cannot manage the proposed schedule.","action":"Simplify and coordinate practical support while protecting adequate intake and parental wellbeing.","phrase":"Let us agree a safe plan you can actually carry out."}],"safetyNet":["Poor responsiveness, breathing difficulty or severe illness: emergency help.","Very poor intake, reduced urine or worsening jaundice: urgent assessment.","Explain who to contact if feeding support or weight checks do not happen."],"followUp":"Set a named feeding/weight review according to clinical concern. NICE advises weighing no more frequently than daily for concern about early weight loss; urgency is determined by the baby’s condition.","pitfalls":["Do not automatically defer all assessment for 48 hours.","Do not infer adequate intake from the duration of feeds alone."],"links":[{"label":"NICE NG75 — recommendations","url":"https://www.nice.org.uk/guidance/ng75/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["newborn","weight","loss","and","feeding"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Arrange emergency or urgent paediatric care according to severity; do not wait for feeding support alone. The baby needs urgent medical assessment.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-reflux","title":"Infant reflux: reassurance, feeding and red flags","summary":"A thriving young infant brings up milk after feeds.","presentation":"A thriving young infant brings up milk after feeds. The parent asks for acid-suppressing medicine because the washing and crying are difficult.","priorities":["Distinguish effortless regurgitation from forceful or bilious vomiting","Assess feeding, growth, distress, stool, blood and systemic illness"],"assessment":["Distinguish effortless regurgitation from forceful or bilious vomiting","Assess feeding, growth, distress, stool, blood and systemic illness","Ask about choking, respiratory events and feeding technique","Explore the family’s concern and what has already been tried"],"management":[{"step":"1. Recognise physiological reflux","detail":"Explain that uncomplicated regurgitation is common and often improves with time. A thriving infant without concerning features may not need medicine."},{"step":"2. Optimise feeding","detail":"Offer skilled feeding assessment; in formula-fed infants review volumes and feeding pattern. Use a guideline-based stepped approach if regurgitation causes marked distress."},{"step":"3. Use medicines selectively","detail":"Do not offer acid suppression solely for isolated visible regurgitation. Alginate or other treatment requires the relevant indication and review; check compatibility with thickened feeds."},{"step":"4. Protect safe sleep","detail":"Keep the infant sleeping on their back on a flat, firm sleep surface. Do not advise prone sleep or raising the cot as reflux treatment."}],"discussion":[{"cue":"Is acid burning the baby?","response":"Bringing up milk does not by itself tell us there is damaging acid disease. Let us check growth, feeding and any warning signs before deciding on treatment.","why":"Explain without dismissal.","id":"pd-reflux-talk-1","simple":"Bringing up milk alone does not prove acid disease. Let’s assess feeding, growth and warning signs."},{"cue":"Could I raise the cot?","response":"For sleep, keep the baby flat on their back. We can work on feeding safely without changing that sleep advice.","why":"Give a clear safety instruction.","id":"pd-reflux-talk-2","simple":"Keep your baby flat on their back for sleep. We can work on feeding without changing that."},{"cue":"So you are doing nothing?","response":"We can assess the feeds, check growth and agree what changes would need reassessment. Medicine is only useful when it fits the problem.","why":"Describe active care.","id":"pd-reflux-talk-3","simple":"Checking feeding, growth and warning signs is active care. Medicine should fit the assessed problem."}],"variations":[{"label":"Projectile vomiting","change":"A young infant develops persistent forceful vomiting.","action":"Arrange prompt assessment for causes such as pyloric stenosis, with urgency based on hydration and illness.","phrase":"This is different from ordinary posseting."},{"label":"Green vomiting","change":"Bilious vomiting occurs.","action":"Emergency assessment is needed for possible obstruction.","phrase":"Green vomit needs urgent medical assessment."},{"label":"Poor growth","change":"Weight gain falters or feeding becomes difficult.","action":"Reassess for pathological reflux and other causes and seek indicated specialist input.","phrase":"The growth change means we need to look further."}],"safetyNet":["Green or bloody vomiting, marked distension, severe illness or poor responsiveness: urgent/emergency assessment.","Persistent projectile vomiting, dehydration or faltering growth: prompt review.","Reassess if symptoms begin late or persist beyond the usual infant course."],"followUp":"Agree review of feeding, growth and distress; any medication trial needs an explicit duration and review of benefit.","pitfalls":["Do not prescribe a PPI for simple regurgitation alone.","Do not compromise safe-sleep advice to reduce reflux."],"links":[{"label":"NICE NG1 — recommendations","url":"https://www.nice.org.uk/guidance/ng1/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["infant","reflux:","reassurance,","feeding","and"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Arrange prompt assessment for causes such as pyloric stenosis, with urgency based on hydration and illness. This is different from ordinary posseting.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-colic","title":"Crying infant and an exhausted parent","summary":"A parent describes prolonged evening crying in a young infant.","presentation":"A parent describes prolonged evening crying in a young infant. They say they are close to losing control and ask for stronger colic drops.","priorities":["Assess the baby for illness, feeding difficulty, injury and abnormal crying","Check growth, vomiting, stools and pattern between episodes"],"assessment":["Assess the baby for illness, feeding difficulty, injury and abnormal crying","Check growth, vomiting, stools and pattern between episodes","Ask directly how the parent is coping and whether the baby is safe","Explore support, sleep and parental mental health"],"management":[{"step":"1. Assess before labelling","detail":"Colic describes crying in an otherwise healthy infant; review concerning features and examine when needed."},{"step":"2. Offer practical comfort","detail":"Discuss feeding support, holding, soothing and a calm environment. Avoid promising benefit from drops, herbal remedies or routine dietary restriction."},{"step":"3. Protect both parent and baby","detail":"If overwhelmed, the parent can place the baby safely in the cot, step away briefly to calm down and obtain help. Never shake a baby."},{"step":"4. Arrange support","detail":"Identify a trusted person and health-visiting support; act on immediate safeguarding or parental mental-health risk."}],"discussion":[{"cue":"I cannot take another night.","response":"This sounds exhausting. First, are you and the baby safe right now? Let us arrange some practical support as well as check the baby.","why":"Take distress seriously.","id":"pd-colic-talk-1","simple":"Are you and the baby safe now? Let’s check the baby and arrange practical support."},{"cue":"Which drops will cure it?","response":"There is not a guaranteed medicine for colic. We should check that the baby is well and focus on safe soothing and support.","why":"Avoid an unsupported cure.","id":"pd-colic-talk-2","simple":"There is no guaranteed colic medicine. Let’s check the baby and discuss safe soothing and support."},{"cue":"I feel angry when the crying starts.","response":"Thank you for telling me. Put the baby safely in the cot if you need a short break, and let us work out who can help you now.","why":"Respond without shame and with action.","id":"pd-colic-talk-3","simple":"Put the baby safely in the cot for a short break, and let’s arrange help now."}],"variations":[{"label":"Unwell baby","change":"Fever, poor feeding or a weak unusual cry appears.","action":"Reassess urgently rather than assume colic.","phrase":"This change needs a medical check."},{"label":"Immediate safety concern","change":"The parent fears they may hurt the baby.","action":"Arrange immediate safe support and safeguarding/emergency help appropriate to danger.","phrase":"We need someone to help keep you both safe now."},{"label":"Persistent symptoms","change":"Crying remains atypical or growth is affected.","action":"Reassess the diagnosis and feeding and arrange further assessment.","phrase":"We should review what is causing this rather than keep changing drops."}],"safetyNet":["An infant who is difficult to wake, struggling to breathe or seriously unwell needs emergency help.","Fever in a young infant, poor feeding or a changed cry needs urgent assessment.","Immediate fear of harm to the baby requires urgent safety support."],"followUp":"Agree health visitor/GP follow-up and a clear plan for the next difficult period; earlier review for illness or worsening parental coping.","pitfalls":["Do not assume all crying is benign.","Do not leave a parent describing loss of control with only a leaflet."],"links":[{"label":"Official clinical and patient guidance","url":"https://www.nhs.uk/conditions/colic/","use":"Relevant clinical safety and patient information"},{"label":"Official clinical and patient guidance","url":"https://www.nhs.uk/baby/caring-for-a-newborn/soothing-a-crying-baby/","use":"Relevant clinical safety and patient information"}],"reviewed":"2026-11-11","tags":["crying","infant","and","an","exhausted"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Reassess urgently rather than assume colic. This change needs a medical check.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-autism","title":"Developmental differences and possible autism","summary":"A parent is concerned about their toddler’s communication and play.","presentation":"A parent is concerned about their toddler’s communication and play. They fear that an assessment will label the child and limit schooling.","priorities":["Explore developmental profile, communication, play, sensory needs and repetitive patterns","Ask about loss of acquired skills, hearing, vision and other health concerns"],"assessment":["Explore developmental profile, communication, play, sensory needs and repetitive patterns","Ask about loss of acquired skills, hearing, vision and other health concerns","Gather information across home and nursery, including strengths and support needs","Explore family priorities, access barriers and the child’s own communication"],"management":[{"step":"1. Listen and explain","detail":"Describe a possible neurodevelopmental difference without diagnosing from a brief checklist or making predictions about an individual child’s future."},{"step":"2. Refer appropriately","detail":"Use the local autism diagnostic pathway when indicated. Loss of language or social skills under age 3 warrants referral to the autism team; other regression patterns may need paediatric/neurological assessment."},{"step":"3. Support now","detail":"Offer appropriate hearing/developmental assessment and speech, education or family support according to need; support should not wait solely for a diagnostic label."},{"step":"4. Coordinate","detail":"Agree consent for sharing relevant nursery/school information and name who will follow the referral and current needs."}],"discussion":[{"cue":"Will this ruin their future?","response":"An assessment is about understanding their needs and strengths so we can offer useful support. It cannot predict their whole future.","why":"Avoid deficit-only or falsely certain language.","id":"pd-autism-talk-1","simple":"The assessment helps us understand strengths and support needs. It cannot predict their whole future."},{"cue":"Must we wait for a diagnosis?","response":"We can look at communication, hearing and practical support while the assessment is arranged.","why":"Offer action now.","id":"pd-autism-talk-2","simple":"We can start addressing communication, hearing and practical needs while assessment is arranged."},{"cue":"They make eye contact, so it cannot be autism?","response":"One behaviour cannot confirm or rule it out. We need to understand the whole developmental pattern.","why":"Correct a common misconception.","id":"pd-autism-talk-3","simple":"Eye contact alone cannot rule autism in or out. We need the wider developmental assessment."}],"variations":[{"label":"Regression","change":"A 2-year-old loses words and social skills.","action":"Refer to the autism team and assess wider developmental/medical needs promptly.","phrase":"Losing skills changes the assessment we need."},{"label":"Motor regression","change":"Previously acquired motor skills are lost.","action":"Arrange paediatric/neurological assessment rather than assume autism explains it.","phrase":"This needs a broader medical assessment."},{"label":"Family reluctant","change":"The parent declines referral.","action":"Explore the fear, explain benefits and limits and arrange review of support and development.","phrase":"We can discuss your concerns and keep the support needs under review."}],"safetyNet":["Loss of skills, seizures or new neurological symptoms needs prompt medical review; acute severe symptoms require emergency care.","Family exhaustion or unsafe behaviour warrants additional support and risk assessment.","Provide a contact route if the referral is not progressing."],"followUp":"Agree a named follow-up for referral progress and the child’s functioning, with earlier reassessment for regression or new concerns.","pitfalls":["Do not rule out autism from eye contact, affection or apparently good skills in one area.","Do not promise that all children will develop in the same way."],"links":[{"label":"NICE CG128 — recommendations","url":"https://www.nice.org.uk/guidance/cg128/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["developmental","differences","and","possible","autism"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Refer to the autism team and assess wider developmental/medical needs promptly. Losing skills changes the assessment we need.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-adhd","title":"Attention and activity differences: possible ADHD","summary":"A parent requests ADHD medication for a child who struggles with concentration.","presentation":"A parent requests ADHD medication for a child who struggles with concentration. School reports are incomplete, and home life is under strain.","priorities":["Assess attention, impulsivity, activity, duration and impairment across settings","Explore sleep, learning, anxiety, trauma, hearing and other explanations"],"assessment":["Assess attention, impulsivity, activity, duration and impairment across settings","Explore sleep, learning, anxiety, trauma, hearing and other explanations","Hear the child’s perspective and gather school information appropriately","Assess severity, safety, family needs and existing support"],"management":[{"step":"1. Assess context","detail":"Describe the observed difficulties without calling the child naughty or attention-seeking. Academic success does not by itself exclude difficulties."},{"step":"2. Match referral to severity","detail":"Refer directly for specialist assessment when impairment is severe. In other presentations, provide appropriate support and review/referral; questionnaires assist but do not independently diagnose."},{"step":"3. Support function","detail":"Discuss environmental adjustments, predictable routines and appropriate parenting/education support without blaming parents."},{"step":"4. Use specialist prescribing","detail":"Initial ADHD medication decisions require relevant specialist expertise. Baseline physical assessment is needed; an ECG is not universal and depends on cardiac features/risks."}],"discussion":[{"cue":"Are they just being naughty?","response":"There may be several reasons why attention or behaviour is difficult. I would like to understand what is happening in different settings before judging the cause.","why":"Avoid labels.","id":"pd-adhd-talk-1","simple":"Let’s understand the difficulties across settings before labelling the cause."},{"cue":"Can you start tablets today?","response":"Medication needs a specialist assessment and safety checks. We can start addressing the difficulties and arrange the right pathway now.","why":"Explain action and boundaries.","id":"pd-adhd-talk-2","simple":"Medicine needs the right specialist assessment and checks. We can arrange the pathway and support now."},{"cue":"School says the grades are fine.","response":"Good grades are useful information, but we also need to know about effort, distress, attention and daily functioning.","why":"Look beyond one measure.","id":"pd-adhd-talk-3","simple":"Grades are one part. Let’s also ask about effort, distress, attention and daily life."}],"variations":[{"label":"Severe impairment","change":"The child is at substantial risk of exclusion and daily functioning is severely affected.","action":"Refer directly for specialist assessment rather than impose a routine observation delay.","phrase":"The level of difficulty warrants specialist assessment now."},{"label":"Cardiac history","change":"Syncope or relevant family cardiac history emerges before proposed medication.","action":"Follow specialist baseline assessment and indicated cardiology advice; do not rely on a routine ECG alone.","phrase":"This history changes the safety checks needed."},{"label":"Symptoms in one setting","change":"Only home difficulties are currently reported.","action":"Explore contextual and alternative explanations and gather fuller information; do not declare a diagnosis or dismiss distress.","phrase":"We need more information to understand the pattern."}],"safetyNet":["Unsafe impulsivity, self-harm or severe mental-health deterioration needs urgent assessment.","New neurological or physical symptoms require appropriate medical review.","Give a route for escalating support if school or family function deteriorates."],"followUp":"Agree review of functioning and support while awaiting assessment. Specialist medication follow-up should include the recommended growth, pulse/BP and adverse-effect monitoring for the medicine and age.","pitfalls":["Do not delay severe impairment until questionnaires are complete.","Do not state that every child needs an ECG before ADHD medication."],"links":[{"label":"NICE NG87 — recommendations","url":"https://www.nice.org.uk/guidance/ng87/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["attention","and","activity","differences:","possible"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Refer directly for specialist assessment rather than impose a routine observation delay. The level of difficulty warrants specialist assessment now.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-preschool-wheeze","title":"Preschool wheeze and suspected asthma","summary":"A 3-year-old has recurrent wheeze and interval night symptoms.","presentation":"A 3-year-old has recurrent wheeze and interval night symptoms. The parent wants a diagnosis and is worried about inhaled steroids.","priorities":["Assess current breathing and attack severity before chronic management","Clarify recurrent episodes, interval symptoms, atopy and previous severe attacks"],"assessment":["Assess current breathing and attack severity before chronic management","Clarify recurrent episodes, interval symptoms, atopy and previous severe attacks","Review existing inhalers, spacer technique, adherence and smoke exposure","Consider alternative causes and whether symptoms fit the under-5 pathway"],"management":[{"step":"1. Address acute illness","detail":"Use acute assessment and escalation if an attack is present; the chronic pathway is not an emergency treatment protocol."},{"step":"2. Explain diagnostic uncertainty","detail":"Asthma may be difficult to confirm objectively at this age. Explain the role of a planned treatment trial and review."},{"step":"3. Use the age-specific pathway","detail":"For appropriate suspected asthma under 5, consider an 8–12-week trial of twice-daily paediatric low-dose ICS with SABA reliever, following current prescribing guidance and clinical criteria."},{"step":"4. Teach and review","detail":"Demonstrate device/spacer technique, check the parent can use it and provide a written action plan. Review response and diagnosis rather than continue indefinitely without assessment."}],"discussion":[{"cue":"Does a steroid inhaler mean severe asthma?","response":"It treats inflammation in the airways. The choice and dose depend on your child’s symptoms, and we will review whether it helps.","why":"Explain purpose without minimising harms.","id":"pd-preschool-wheeze-talk-1","simple":"The inhaler treats airway inflammation. We choose and review it according to your child’s symptoms."},{"cue":"Why not just the blue inhaler?","response":"Relief of tightness is only part of the plan. We also need to consider treatment for the inflammation and how often symptoms occur.","why":"Avoid reliever-only thinking.","id":"pd-preschool-wheeze-talk-2","simple":"Relief is one part. We also need to assess inflammation treatment and symptom frequency."},{"cue":"How will we know it works?","response":"We will agree which symptoms to track and when to review the trial, including technique and any side effects.","why":"Make the trial assessable.","id":"pd-preschool-wheeze-talk-3","simple":"Let’s agree the symptoms to track, correct technique, side effects and a review date."}],"variations":[{"label":"Acute distress","change":"The child is struggling to breathe or reliever treatment is not helping.","action":"Arrange urgent or emergency care according to severity; do not wait for the trial to work.","phrase":"We need to deal with the breathing difficulty now."},{"label":"No response","change":"Symptoms persist despite the trial.","action":"Check technique, adherence, environment and alternative diagnoses, then seek specialist assessment as indicated.","phrase":"We should review why it has not helped before adding more treatment."},{"label":"Symptoms resolve","change":"The trial resolves symptoms.","action":"Consider guideline-based stopping/reassessment and ongoing review rather than assume permanent treatment is automatically needed.","phrase":"We can review whether the treatment is still needed."}],"safetyNet":["Severe breathing difficulty, exhaustion, blue colour or reduced responsiveness: emergency help.","Worsening wheeze or poor response to the agreed action plan: urgent reassessment.","Give device-specific reliever instructions and contacts in the written plan, not a generic instruction to double inhalers."],"followUp":"Review the trial at 8–12 weeks and sooner for deterioration or adverse effects; confirm the ongoing or stopping plan.","pitfalls":["Do not copy the adult AIR/MART pathway into every preschool case.","Do not let chronic management delay acute attack treatment."],"links":[{"label":"NICE NG245 — recommendations","url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["preschool","wheeze","and","suspected","asthma"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Arrange urgent or emergency care according to severity; do not wait for the trial to work. We need to deal with the breathing difficulty now.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-uti","title":"Childhood UTI and recurrent infection","summary":"A child has painful urination and a previous urinary infection.","presentation":"A child has painful urination and a previous urinary infection. The parent asks for the same antibiotic and an automatic preventive prescription.","priorities":["Establish age, systemic illness, fever, loin pain, vomiting and hydration","Obtain appropriate urine information and prior culture results"],"assessment":["Establish age, systemic illness, fever, loin pain, vomiting and hydration","Obtain appropriate urine information and prior culture results","Ask about recurrence, constipation, voiding and structural history","Assess sample collection and the need for urgent specialist care"],"management":[{"step":"1. Triage by age and illness","detail":"A suspected UTI in an infant under 3 months needs immediate paediatric specialist referral; seriously unwell children need urgent/emergency care."},{"step":"2. Collect a useful sample","detail":"Use age-appropriate collection and testing, ideally before antibiotics, without delaying needed treatment for a seriously ill child."},{"step":"3. Treat according to presentation","detail":"Choose treatment using the lower/upper UTI pathway, age, allergy and culture history. Do not simply repeat a previous antibiotic without review."},{"step":"4. Plan recurrence care","detail":"Use the age- and episode-specific imaging tables. Recurrent or atypical infection may need specialist referral and imaging; prophylaxis is a selected specialist decision, not routine after a first infection."}],"discussion":[{"cue":"Why do we need another urine sample?","response":"The sample helps us check whether this is an infection and which treatment is likely to work. We also need to assess how unwell your child is.","why":"Connect testing with decisions.","id":"pd-uti-talk-1","simple":"The sample helps confirm infection and choose treatment. We also need to assess how unwell your child is."},{"cue":"Will every child need a scan?","response":"Not every child. The need and timing depend on age, the type of infection, the response and whether infections recur.","why":"Avoid a universal scan rule.","id":"pd-uti-talk-2","simple":"Scans depend on age, the infection, response and recurrence. They are not needed for every child."},{"cue":"Can daily antibiotics prevent this?","response":"Sometimes a specialist may consider prevention, but first we need to review the infections and possible contributing problems.","why":"Keep prevention individualised.","id":"pd-uti-talk-3","simple":"Prevention needs an individual review and sometimes specialist advice, not an automatic daily antibiotic."}],"variations":[{"label":"Under 3 months","change":"The patient is a 7-week-old baby.","action":"Refer immediately to paediatrics for assessment and treatment; do not use a routine community oral-antibiotic plan.","phrase":"At this age, suspected infection needs specialist assessment."},{"label":"Systemically unwell","change":"Fever, vomiting and poor hydration appear.","action":"Assess upper UTI/sepsis and escalate according to illness and ability to take treatment.","phrase":"These features mean we need a more urgent assessment."},{"label":"Recurrent infection","change":"Further confirmed episodes occur.","action":"Review cultures, bladder/bowel factors and the imaging/referral pathway for recurrence.","phrase":"We should look at the pattern, not just treat another episode."}],"safetyNet":["Severe illness, poor responsiveness or circulatory/respiratory compromise: emergency help.","Persistent vomiting, worsening fever, poor urine output or failure to improve on treatment: prompt reassessment.","Explain who reviews the culture and will contact the family if treatment needs changing."],"followUp":"Track culture results and clinical response; reassess promptly for failure to improve, with imaging/referral follow-up based on the actual age and infection pattern.","pitfalls":["Do not treat every child with upper UTI as the same admission scenario regardless of assessment.","Do not automatically prescribe long-term prophylaxis or image every first infection."],"links":[{"label":"NICE NG224 — recommendations","url":"https://www.nice.org.uk/guidance/ng224/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["childhood","uti","and","recurrent","infection"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Refer immediately to paediatrics for assessment and treatment; do not use a routine community oral-antibiotic plan. At this age, suspected infection needs specialist assessment.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-bedwetting","title":"Bedwetting, embarrassment and a school trip","summary":"An 8-year-old wets at night and is anxious about a residential school visit.","presentation":"An 8-year-old wets at night and is anxious about a residential school visit. The parent has been limiting drinks all day.","priorities":["Clarify primary/secondary wetting, daytime symptoms, constipation and fluid/toilet pattern","Ask about thirst, polyuria, weight loss, illness and new stressors"],"assessment":["Clarify primary/secondary wetting, daytime symptoms, constipation and fluid/toilet pattern","Ask about thirst, polyuria, weight loss, illness and new stressors","Explore the child’s goals, privacy and family response","Assess whether an alarm or medication plan would be feasible"],"management":[{"step":"1. Normalise without dismissing","detail":"Explain that bedwetting is not deliberate and avoid punishment. Reward agreed behaviours rather than dry nights alone."},{"step":"2. Address contributors","detail":"Treat constipation and assess relevant urinary or medical causes. Support adequate daytime fluid intake and regular toileting."},{"step":"3. Choose treatment","detail":"An alarm is often the initial treatment after appropriate advice when acceptable and feasible. Desmopressin may suit a need for rapid/short-term improvement or when alarm use is unsuitable, following age/suitability guidance."},{"step":"4. Explain safety","detail":"If desmopressin is prescribed, give clear fluid-restriction instructions and when to withhold it; check understanding and use current product guidance."}],"discussion":[{"cue":"Should we stop drinks all day?","response":"No. Adequate daytime drinking matters. If medicine is used, there are specific night-time fluid rules which I will explain separately.","why":"Separate general hydration from medicine safety.","id":"pd-bedwetting-talk-1","simple":"Keep adequate daytime drinking. I will explain any medicine-specific rules about fluids at night separately."},{"cue":"They are being lazy.","response":"This is not something to punish. We can help them with a practical plan and protect their privacy.","why":"Remove shame.","id":"pd-bedwetting-talk-2","simple":"Please do not punish them. Let’s make a practical plan and protect their privacy."},{"cue":"Can the trip still happen?","response":"Let us discuss options for the trip, including a discreet plan and whether short-term treatment is suitable.","why":"Use the child’s meaningful goal.","id":"pd-bedwetting-talk-3","simple":"Let’s plan discreet support for the trip and discuss whether suitable short-term treatment would help."}],"variations":[{"label":"Diabetes symptoms","change":"New thirst, weight loss and frequent urination develop.","action":"Arrange urgent assessment for diabetes; do not treat as uncomplicated enuresis.","phrase":"These symptoms need checking promptly."},{"label":"Constipation","change":"Painful infrequent stools and soiling coexist.","action":"Treat bowel dysfunction alongside the wetting plan.","phrase":"The bowel problem can contribute to wetting."},{"label":"Cannot follow fluid rules","change":"The child cannot safely comply with night-time fluid restriction.","action":"Do not use desmopressin without a safe plan; consider alternatives and specialist advice.","phrase":"The medicine is only suitable if its safety instructions can be followed."}],"safetyNet":["New illness, significant thirst/weight loss or urinary pain needs medical assessment.","For desmopressin, explain warning symptoms such as significant headache, vomiting or confusion and the urgent action required.","Give a contact route for treatment difficulties or family distress."],"followUp":"Review alarm engagement and progress early according to the recommended pathway; desmopressin needs review of response and safety rather than unsupervised indefinite use.","pitfalls":["Do not punish wetting or impose dehydration throughout the day.","Do not prescribe desmopressin without discussing safe fluid intake."],"links":[{"label":"NICE CG111 — recommendations","url":"https://www.nice.org.uk/guidance/cg111/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["bedwetting,","embarrassment","and","a","school"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Arrange urgent assessment for diabetes; do not treat as uncomplicated enuresis. These symptoms need checking promptly.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-eczema","title":"Childhood eczema and fear of topical steroids","summary":"A child scratches through the night.","presentation":"A child scratches through the night. The parent stopped the prescribed cream after reading that steroids always damage skin.","priorities":["Assess severity, extent, sites, infection signs and effect on sleep/growth","Clarify what products and potencies have actually been used"],"assessment":["Assess severity, extent, sites, infection signs and effect on sleep/growth","Clarify what products and potencies have actually been used","Check quantity, technique, adherence barriers and skin irritation","Assess painful rapidly worsening eczema or eye involvement"],"management":[{"step":"1. Explain the condition","detail":"Describe inflammation and skin-barrier problems. Regular emollients support the barrier; flares may need anti-inflammatory treatment."},{"step":"2. Treat proportionately","detail":"Match topical corticosteroid potency to severity, body site and age, following the actual prescription and current guidance. Explain where, how much and how long."},{"step":"3. Teach practically","detail":"Demonstrate application, suitable washing and a written flare plan. Explain emollient residue fire risk and appropriate precautions."},{"step":"4. Escalate complications","detail":"Suspected eczema herpeticum needs immediate treatment and same-day specialist advice; eye involvement needs ophthalmological as well as dermatological advice."}],"discussion":[{"cue":"Will the cream thin their skin?","response":"Using the right strength in the right place for the prescribed time has a different risk from using a strong cream everywhere indefinitely. Let me show you the plan for your child.","why":"Address the specific fear.","id":"pd-eczema-talk-1","simple":"The strength, area and duration matter. Let me show you the exact plan for your child."},{"cue":"Should we stop all treatment if the skin weeps?","response":"We need to assess whether there is infection and choose treatment accordingly. Do not assume every flare needs antibiotics or stop all eczema care without advice.","why":"Avoid an automatic rule.","id":"pd-eczema-talk-2","simple":"We need to assess infection. Do not automatically stop all eczema care or assume every flare needs antibiotics."},{"cue":"How much should I put on?","response":"I will show you the amount for each area and write down which product goes where.","why":"Make instructions usable.","id":"pd-eczema-talk-3","simple":"I’ll show the amount for each area and write down where each product goes."}],"variations":[{"label":"Painful punched-out lesions","change":"The eczema becomes rapidly painful with uniform blisters/erosions and illness.","action":"Consider eczema herpeticum, start indicated systemic treatment and arrange same-day specialist advice.","phrase":"This may need urgent treatment beyond the usual eczema creams."},{"label":"Eye area affected","change":"Suspected herpetic lesions involve skin near the eyes.","action":"Arrange same-day ophthalmological and dermatological advice.","phrase":"The eye area makes urgent specialist assessment important."},{"label":"Treatment ineffective","change":"Symptoms persist despite the plan.","action":"Review diagnosis, actual technique, potency, infection and adherence, and refer if indicated.","phrase":"Let us check why the plan is not controlling the symptoms."}],"safetyNet":["Rapidly worsening painful eczema, blisters or fever: urgent same-day assessment.","Eye symptoms or involvement in suspected eczema herpeticum: same-day specialist care.","Seek advice for significant treatment adverse effects, poor growth or uncontrolled sleep disturbance."],"followUp":"Set an explicit flare review and ongoing skin-care plan; review sooner for worsening, infection concerns or poor response.","pitfalls":["Do not call all topical steroids dangerous or harmless regardless of use.","Do not treat every weeping flare with antibiotics without assessment."],"links":[{"label":"NICE CG57 — recommendations","url":"https://www.nice.org.uk/guidance/cg57/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["childhood","eczema","and","fear","of"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Consider eczema herpeticum, start indicated systemic treatment and arrange same-day specialist advice. This may need urgent treatment beyond the usual eczema creams.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-not-brought","title":"Child not brought: access barriers and safeguarding","summary":"A child has missed essential follow-up twice.","presentation":"A child has missed essential follow-up twice. A parent says they could not understand the messages and had no transport.","priorities":["Establish the child’s current health and consequences of delay","Review the pattern of missed care and other safeguarding information"],"assessment":["Establish the child’s current health and consequences of delay","Review the pattern of missed care and other safeguarding information","Clarify language, transport, disability, finances and communication needs","Listen without assuming either neglect or no risk"],"management":[{"step":"1. Assess current need","detail":"Determine whether delay creates urgent clinical harm and arrange appropriate assessment."},{"step":"2. Remove barriers","detail":"Use professional interpretation, accessible communication and feasible appointment arrangements; confirm the parent understands the reason for care."},{"step":"3. Assess safeguarding","detail":"Repeated failure to bring a child to essential follow-up can raise neglect concerns. Consider the whole pattern, seek safeguarding advice and act proportionately."},{"step":"4. Close the loop","detail":"Name who will track the appointment and the agreed action if it is missed or contact fails; document facts and reasoning."}],"discussion":[{"cue":"We did not understand the letter.","response":"Thank you for telling me. Let us explain the appointment in your preferred language and check what is needed for your child now.","why":"Repair communication.","id":"pd-not-brought-talk-1","simple":"Let’s explain the appointment in your preferred language and check the care your child needs now."},{"cue":"Are you saying I am a bad parent?","response":"I want to understand what prevented the care and make sure your child gets what they need. I also have a duty to consider their safety.","why":"Combine empathy and responsibility.","id":"pd-not-brought-talk-2","simple":"I want to understand the barrier and arrange care, while checking your child’s safety."},{"cue":"What happens if transport fails again?","response":"Let us agree a backup contact and who will help arrange the next step, rather than leave the appointment untracked.","why":"Make a reliable plan.","id":"pd-not-brought-talk-3","simple":"Let’s name who will arrange the next step and agree a backup contact if transport fails."}],"variations":[{"label":"Acute clinical risk","change":"The missed treatment has left the child unwell.","action":"Arrange urgent assessment now and safeguarding action if indicated.","phrase":"The child needs care today."},{"label":"Persistent missed essential care","change":"Missed appointments continue despite support and safety concerns rise.","action":"Use safeguarding advice and local multi-agency pathways; do not endlessly rebook without review.","phrase":"We need additional help to protect your child’s health."},{"label":"Communication solved","change":"An interpreter reveals a genuine misunderstanding.","action":"Correct access and understanding, but still assess the actual clinical consequences and wider information.","phrase":"We can fix the communication and check the health needs."}],"safetyNet":["An acutely unwell child needs urgent/emergency care according to symptoms.","No response to attempts at contact must trigger the agreed clinical and safeguarding escalation.","Explain how the family can contact the team if arrangements fail."],"followUp":"Document a named appointment/results owner and contact-back deadline based on the child’s clinical risk; verify essential care happens.","pitfalls":["Do not label non-attendance as informed refusal by the child.","Do not declare no safeguarding concern solely because one practical barrier is identified."],"links":[{"label":"NICE CG89 — recommendations","url":"https://www.nice.org.uk/guidance/cg89/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"},{"label":"NICE NG76 — recommendations","url":"https://www.nice.org.uk/guidance/ng76/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["child","not","brought:","access","barriers"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Arrange urgent assessment now and safeguarding action if indicated. The child needs care today.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-neonatal-eye","title":"A red sticky eye in a newborn","summary":"A 12-day-old has a red sticky eye.","presentation":"A 12-day-old has a red sticky eye. The parent requests ordinary conjunctivitis drops from the pharmacy.","priorities":["Establish age, redness, discharge, swelling and ability to open the eye","Ask about fever, feeding, responsiveness and other illness"],"assessment":["Establish age, redness, discharge, swelling and ability to open the eye","Ask about fever, feeding, responsiveness and other illness","Review onset and relevant birth/maternal history sensitively","Assess urgency and access to paediatric/ophthalmic care"],"management":[{"step":"1. Recognise neonatal risk","detail":"A red sticky eye in a newborn requires urgent assessment rather than routine treatment as older-child conjunctivitis."},{"step":"2. Assess complications","detail":"Examine for significant infection or eye involvement and arrange appropriate sampling and specialist advice."},{"step":"3. Treat the cause","detail":"Some neonatal infections need systemic treatment and assessment of mother/partners, guided by specialists; topical drops alone may be insufficient."},{"step":"4. Communicate sensitively","detail":"Explain urgency without blame or assumptions about infection source. Agree prompt attendance and follow-up."}],"discussion":[{"cue":"Can I just buy eye drops?","response":"Because your baby is so young, we need an urgent assessment before treating this like ordinary conjunctivitis.","why":"Give the reason for urgency.","id":"pd-neonatal-eye-talk-1","simple":"A newborn’s red, sticky eye needs urgent assessment before ordinary eye treatment."},{"cue":"Is this my fault?","response":"Our priority is to assess and treat the baby. We will explain any tests and any care needed for you without making assumptions.","why":"Reduce blame.","id":"pd-neonatal-eye-talk-2","simple":"Let’s focus on assessing and treating the baby, explaining tests and any care you need without blame."},{"cue":"Can it wait until next week?","response":"No, a newborn’s red sticky eye should be checked urgently.","why":"Use clear timing.","id":"pd-neonatal-eye-talk-3","simple":"A newborn’s red, sticky eye needs urgent assessment."}],"variations":[{"label":"Systemic illness","change":"The baby has fever, poor feeding or lethargy.","action":"Arrange urgent/emergency paediatric assessment according to severity.","phrase":"The baby needs medical assessment now."},{"label":"Marked swelling","change":"The eye cannot open or swelling is significant.","action":"Escalate urgent eye/paediatric assessment for serious infection.","phrase":"This needs urgent specialist review."},{"label":"Discharge without redness","change":"A well infant has mild stickiness without a red eye.","action":"Assess whether tear-duct obstruction is likely, but retain a low threshold for review and clear red-eye/illness advice.","phrase":"We need to distinguish simple stickiness from infection."}],"safetyNet":["Newborn redness with discharge: urgent assessment.","Fever, poor feeding, reduced responsiveness or significant swelling: urgent/emergency care.","Explain who follows samples and specialist treatment."],"followUp":"Confirm urgent assessment and appropriate specialist/result follow-up; do not provide only a distant routine review.","pitfalls":["Do not use the older-child conjunctivitis pathway without considering age.","Do not assume topical drops alone treat all neonatal eye infections."],"links":[{"label":"Official clinical and patient guidance","url":"https://www.nhs.uk/symptoms/red-eye/","use":"Relevant clinical safety and patient information"},{"label":"Official clinical and patient guidance","url":"https://www.moorfields.nhs.uk/for-health-professionals/childrens-eye-conditions-management/infective-conjunctivitis","use":"Relevant clinical safety and patient information"}],"reviewed":"2026-11-11","tags":["a","red","sticky","eye","in"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Arrange urgent/emergency paediatric assessment according to severity. The baby needs medical assessment now.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"pd-head-lice","title":"Head lice, recurrent treatment and school anxiety","summary":"A parent finds nits and wants the whole household treated with an old insecticide shampoo.","presentation":"A parent finds nits and wants the whole household treated with an old insecticide shampoo. They worry the child must miss school.","priorities":["Confirm live lice rather than eggs alone","Review prior treatment, timing, technique and close contacts"],"assessment":["Confirm live lice rather than eggs alone","Review prior treatment, timing, technique and close contacts","Check age, pregnancy/asthma considerations for product suitability","Assess scalp injury or secondary infection"],"management":[{"step":"1. Confirm infestation","detail":"Treatment is based on live lice. Lice are not proof of poor hygiene."},{"step":"2. Choose an effective approach","detail":"Explain wet combing on days 1, 5, 9 and 13, then check on day 17. If unsuitable or unsuccessful, discuss a suitable recommended lotion/spray with the pharmacist and follow its instructions."},{"step":"3. Treat affected contacts","detail":"Check close contacts and treat those with live lice on the same day; do not automatically treat everyone or use prevention insecticides."},{"step":"4. Avoid unnecessary exclusion","detail":"Children do not need to stay off school solely for head lice. Explain practical checking and adherence without excessive household cleaning demands."}],"discussion":[{"cue":"Does this mean their hair is dirty?","response":"No. Head lice spread through close head contact and are not a sign of poor hygiene.","why":"Remove stigma.","id":"pd-head-lice-talk-1","simple":"No. Head lice are not a sign of dirty hair or poor hygiene."},{"cue":"Should everyone use the shampoo?","response":"Check everyone, then treat the people who have live lice on the same day.","why":"Make the advice specific.","id":"pd-head-lice-talk-2","simple":"Check everyone, and treat those with live lice on the same day."},{"cue":"Can they go to school?","response":"They do not need to miss school just because of head lice. Let us make sure the treatment plan is followed properly.","why":"Prevent unnecessary disruption.","id":"pd-head-lice-talk-3","simple":"Head lice alone do not mean missing school. Let’s follow the right treatment plan."}],"variations":[{"label":"Eggs only","change":"No live lice are found.","action":"Recheck carefully rather than automatically use treatment.","phrase":"We treat live infestation, not every remaining egg case."},{"label":"Treatment failure","change":"Live lice persist after an apparently complete course.","action":"Check technique, correct repeat timing, reinfestation and product suitability; seek pharmacist/clinical advice.","phrase":"Let us work out why it has not cleared before repeating the same product."},{"label":"Scalp infection","change":"Painful crusting or spreading redness develops.","action":"Assess and treat the skin complication as indicated.","phrase":"The scalp symptoms need a separate assessment."}],"safetyNet":["Spreading redness, swelling, significant pain or systemic illness needs medical review.","Persistent live lice despite correctly completed treatment needs reassessment of technique and choice.","Avoid applying more product than directed or using incompatible products together."],"followUp":"Use the complete combing schedule and day-17 check, or the actual product’s repeat/check schedule.","pitfalls":["Do not recommend permethrin as a routine current UK head-lice treatment.","Do not diagnose active infestation from nits alone or require school exclusion."],"links":[{"label":"Official clinical and patient guidance","url":"https://www.nhs.uk/conditions/head-lice-and-nits/","use":"Relevant clinical safety and patient information"}],"reviewed":"2026-11-11","tags":["head","lice,","recurrent","treatment","and"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Recheck carefully rather than automatically use treatment. We treat live infestation, not every remaining egg case.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}}]},{"id":"older-palliative","title":"Older-person & palliative care","description":"Cognition, falls, symptom relief, support and planning care around the person’s wishes.","icon":"03","reviewed":"2026-11-11","cases":[{"id":"op-delirium","title":"Sudden confusion: delirium until assessed","summary":"A care worker reports that an older person has become muddled over a day.","presentation":"A care worker reports that an older person has become muddled over a day. The person is quieter than usual, takes several medicines and lives alone. The caller asks for antibiotics for a urine infection.","priorities":["Assess responsiveness, breathing, circulation, focal neurological signs and immediate safety","Establish acute onset, fluctuation and baseline cognition/function"],"assessment":["Assess responsiveness, breathing, circulation, focal neurological signs and immediate safety","Establish acute onset, fluctuation and baseline cognition/function","Check physical illness, pain, hydration, constipation, retention, medicines and glucose when relevant","Obtain collateral information and determine whether safe urgent community assessment is achievable"],"management":[{"step":"1. Assess urgently","detail":"New confusion needs prompt clinical assessment for potentially serious causes; emergency features require emergency care. Quiet withdrawal can be hypoactive delirium, not reassuring calmness."},{"step":"2. Search for causes","detail":"Assess observations, examination and targeted tests. A 4AT can support delirium assessment in relevant settings; no score replaces assessment of the cause."},{"step":"3. Avoid diagnostic shortcuts","detail":"In older adults, do not use urine dipsticks to diagnose UTI or treat asymptomatic bacteriuria. Consider urinary symptoms and the overall clinical picture; do not assume confusion equals UTI."},{"step":"4. Support and coordinate","detail":"Provide reassurance, orientation, sensory aids and familiar support. Arrange safe supervision and a definite review; community care is appropriate only if the assessment and support can meet the need."}],"discussion":[{"cue":"It must be a urine infection.","response":"An infection is one possibility, but dehydration, medicines, constipation and other illnesses can also cause sudden confusion. We need to assess the person rather than choose treatment from a urine dipstick.","why":"Broaden the differential.","id":"op-delirium-talk-1","simple":"Infection is one possibility, but a urine test alone is not enough. We need to assess the person and other causes."},{"cue":"They are just sleepy, not agitated.","response":"A sudden quieter or sleepier state can still be important. It needs the same attention to possible causes.","why":"Recognise hypoactive delirium.","id":"op-delirium-talk-2","simple":"A sudden quiet or sleepy change can be important too and needs assessment."},{"cue":"Can they stay at home?","response":"That depends on the illness and whether safe assessment, treatment and support can be provided. We need a plan for today, not simply leave them alone.","why":"Connect setting to actual support.","id":"op-delirium-talk-3","simple":"Let’s decide where safe assessment, treatment and support can happen today. They should not be left without a plan."}],"variations":[{"label":"Stroke signs","change":"New weakness or speech change appears.","action":"Activate the acute stroke/emergency pathway immediately.","phrase":"These new symptoms need emergency help."},{"label":"Medicine error","change":"An accidental extra dose or sedating medicine is identified.","action":"Assess toxicity and seek urgent medicines/toxicology advice or emergency care according to effects.","phrase":"We need to check the dose and effects urgently."},{"label":"Home unsafe","change":"The person cannot safely be left without supervision.","action":"Arrange an appropriate urgent care setting or reliable support; do not promise an unavailable home package.","phrase":"We need a safe arrangement while this is assessed."}],"safetyNet":["Reduced consciousness, severe illness, stroke signs, respiratory compromise or suspected serious overdose: emergency help.","Worsening confusion or inability to maintain intake/safety: urgent reassessment.","Give carers an actual same-day contact and backup route."],"followUp":"Confirm same-day assessment and handover, with close reassessment according to cause and response; do not defer review of unresolved delirium for a routine week.","pitfalls":["Do not diagnose UTI in an older adult from a positive dipstick alone.","Do not equate quietness with recovery or presume a new dementia diagnosis during acute confusion."],"links":[{"label":"NICE CG103 — recommendations","url":"https://www.nice.org.uk/guidance/cg103/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"},{"label":"Official clinical and patient guidance","url":"https://www.gov.uk/government/publications/urinary-tract-infection-diagnosis/diagnosis-of-urinary-tract-infections-quick-reference-tools-for-primary-care","use":"Relevant clinical safety and patient information"}],"reviewed":"2026-11-11","tags":["sudden","confusion:","delirium","until","assessed"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Activate the acute stroke/emergency pathway immediately. These new symptoms need emergency help.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"op-memory","title":"Progressive memory difficulties and possible dementia","summary":"An adult and their partner describe gradually worsening memory over months.","presentation":"An adult and their partner describe gradually worsening memory over months. The person fears losing independence and asks for an immediate diagnosis.","priorities":["Distinguish gradual decline from acute delirium","Assess cognition, daily function, mood, sensory impairment and medicines"],"assessment":["Distinguish gradual decline from acute delirium","Assess cognition, daily function, mood, sensory impairment and medicines","Hear the patient directly and obtain relevant collateral information with appropriate consent","Assess driving, work, home safety and support needs"],"management":[{"step":"1. Assess broadly","detail":"Evaluate the cognitive and functional pattern and potentially reversible contributors using examination and appropriate tests. Use an appropriate cognitive instrument with attention to language, education and sensory needs."},{"step":"2. Refer when indicated","detail":"Arrange specialist dementia assessment after appropriate initial evaluation. A normal brief score does not alone exclude dementia; do not diagnose subtype from one score."},{"step":"3. Support independence","detail":"Agree practical memory aids and support, medicine safety and meaningful goals. Discuss family involvement according to the patient’s wishes."},{"step":"4. Discuss responsibilities","detail":"Address driving and other safety concerns, including notification duties after diagnosis using the relevant licensing authority. Future planning is supported and decision-specific."}],"discussion":[{"cue":"Does this mean I have dementia?","response":"There are several possible explanations for memory difficulties. We need to assess the pattern, check contributing causes and arrange specialist assessment if needed.","why":"Explain uncertainty.","id":"op-memory-talk-1","simple":"Memory problems have several possible causes. Let’s assess the pattern and arrange the right tests or referral."},{"cue":"Will everyone else make decisions for me?","response":"A diagnosis does not automatically take away your ability to decide. We will support you with each decision and involve people you choose where appropriate.","why":"Protect autonomy.","id":"op-memory-talk-2","simple":"A diagnosis does not automatically remove your ability to decide. We will support you with each decision."},{"cue":"Can tablets cure it?","response":"Treatments may help some symptoms in particular types of dementia, but they are not a cure. The specialist assessment helps identify suitable options.","why":"Avoid an exaggerated promise.","id":"op-memory-talk-3","simple":"Some treatments help symptoms in certain types of dementia, but are not a cure. Let’s assess suitable options."}],"variations":[{"label":"Sudden worsening","change":"Confusion develops over hours or days.","action":"Assess delirium and urgent causes rather than label progression.","phrase":"The sudden change needs assessment now."},{"label":"Unsafe driving","change":"A credible report describes dangerous driving.","action":"Assess promptly, advise against unsafe driving and follow professional duties and licensing guidance if concerns persist.","phrase":"We must address the driving risk directly."},{"label":"Brief test normal","change":"A screening score is normal despite concerning functional decline.","action":"Do not dismiss the history; consider further assessment and referral.","phrase":"The score is one piece of the assessment."}],"safetyNet":["Acute confusion, new neurological symptoms or major loss of function needs urgent assessment.","Immediate hazards at home or inability to meet basic needs require a timely safety plan.","Provide a contact for referral delays and carer difficulties."],"followUp":"Name who tracks tests/referral and reviews support needs; cognitive and functional review should be tailored to risk and specialist advice.","pitfalls":["Do not assume incapacity from a diagnosis or score.","Do not promise a drug will stop disease progression or use an acute delirium score to diagnose dementia."],"links":[{"label":"NICE NG97 — recommendations","url":"https://www.nice.org.uk/guidance/ng97/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["progressive","memory","difficulties","and","possible"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Assess delirium and urgent causes rather than label progression. The sudden change needs assessment now.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"op-dementia-distress","title":"Distress and aggression in dementia","summary":"A family asks for medication because a person with dementia shouts during personal care.","presentation":"A family asks for medication because a person with dementia shouts during personal care. The pattern has recently changed, and carers are exhausted.","priorities":["Assess immediate danger and whether symptoms are new or fluctuating","Look for pain, delirium, constipation, retention, infection, sensory problems and medicine effects"],"assessment":["Assess immediate danger and whether symptoms are new or fluctuating","Look for pain, delirium, constipation, retention, infection, sensory problems and medicine effects","Ask what happens before and during distress and how care is provided","Assess the person’s preferences, communication and carer safety"],"management":[{"step":"1. Identify the need","detail":"Use a structured assessment of clinical and environmental causes before treating distress. Do not assume aggression is simply inevitable dementia."},{"step":"2. Adapt care","detail":"Use calm communication, familiar routines, reduced overstimulation, appropriate pain relief and person-centred activities. Avoid coercive or humiliating approaches."},{"step":"3. Use medicines selectively","detail":"Antipsychotics require an appropriate indication such as risk of harm or severe distress, a benefit–harm discussion, lowest effective dose and shortest duration. Follow relevant prescribing and specialist advice."},{"step":"4. Review and support","detail":"Address carer needs and a safe care plan. If an antipsychotic is used, reassess at least every 6 weeks and stop if there is no clear continuing benefit, with appropriate clinical planning."}],"discussion":[{"cue":"Can you give something to calm them?","response":"I understand how difficult this is. First we need to check whether pain, illness or the way care is happening is causing distress.","why":"Explain why assessment precedes sedation.","id":"op-dementia-distress-talk-1","simple":"Let’s first check pain, illness and care needs before choosing something to calm the distress."},{"cue":"They will not cooperate.","response":"Their behaviour may be telling us something is frightening or uncomfortable. Let us look at what triggers it and how we can change the care.","why":"Use non-blaming interpretation.","id":"op-dementia-distress-talk-2","simple":"Let’s look for what feels frightening or uncomfortable and how care could help."},{"cue":"Are the medicines harmless?","response":"They can sometimes help, but they also carry important risks. We need a specific reason to use them and a clear review plan.","why":"Be honest about harms.","id":"op-dementia-distress-talk-3","simple":"There are important risks as well as possible benefits. Medicine needs a clear reason and review."}],"variations":[{"label":"Lewy body dementia","change":"There is Lewy body or Parkinson’s disease dementia.","action":"Antipsychotic sensitivity and worsening motor symptoms are important risks; obtain appropriate specialist advice.","phrase":"This type of dementia changes the medicine risks."},{"label":"New pain","change":"Distress occurs during movement or care.","action":"Assess and treat pain, adapting handling and communication.","phrase":"Relieving pain may be more useful than sedation."},{"label":"Immediate violence","change":"Someone faces immediate serious harm.","action":"Arrange emergency help and a safe response without expecting carers to physically manage danger alone.","phrase":"We need help to keep everyone safe now."}],"safetyNet":["Immediate serious danger needs emergency help.","Acute confusion, fever, new pain or marked deterioration needs urgent assessment.","Give a route for carers who cannot safely provide care or if medicine adverse effects appear."],"followUp":"Arrange an early review of the care changes; if antipsychotics are prescribed, review effectiveness and need at least every 6 weeks, sooner for adverse effects.","pitfalls":["Do not prescribe sedation for convenience.","Do not overlook severe antipsychotic sensitivity in Lewy body/Parkinson’s disease dementia."],"links":[{"label":"NICE NG97 — recommendations","url":"https://www.nice.org.uk/guidance/ng97/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"},{"label":"NICE CG103 — recommendations","url":"https://www.nice.org.uk/guidance/cg103/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["distress","and","aggression","in","dementia"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Antipsychotic sensitivity and worsening motor symptoms are important risks; obtain appropriate specialist advice. This type of dementia changes the medicine risks.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"op-falls","title":"Falls, dizziness and a recent medicine change","summary":"An older adult has fallen twice after a treatment change.","presentation":"An older adult has fallen twice after a treatment change. They are frightened of losing independence and want to stop every medicine.","priorities":["Assess injury, head trauma, loss of consciousness and acute illness","Ask about dizziness, posture, heart symptoms and neurological symptoms"],"assessment":["Assess injury, head trauma, loss of consciousness and acute illness","Ask about dizziness, posture, heart symptoms and neurological symptoms","Review actual medicines, vision, gait, balance, footwear and home hazards","Explore function, confidence, osteoporosis/fracture risk and support"],"management":[{"step":"1. Address immediate harm","detail":"Arrange urgent injury or acute-cause assessment when indicated; do not label every fall mechanical."},{"step":"2. Assess comprehensively","detail":"Use a falls assessment matched to history and risk, including relevant examination, lying/standing BP, gait/balance and medication review."},{"step":"3. Make targeted changes","detail":"Reconcile recent changes and drug-related risks. Adjust according to findings rather than stop all medicines or prescribe a general tonic."},{"step":"4. Restore confidence","detail":"Discuss appropriate strength/balance interventions, home hazard work, vision care and support. Agree a meaningful mobility goal and ownership across services."}],"discussion":[{"cue":"Does this mean I must stop living alone?","response":"Not automatically. We need to understand the falls and what would make your home and movement safer.","why":"Avoid a premature loss-of-independence conclusion.","id":"op-falls-talk-1","simple":"Not automatically. Let’s assess the falls and what support could make home and movement safer."},{"cue":"I will stop all the tablets.","response":"Some may contribute, but stopping everything could also cause harm. Let us check what you take and make a targeted plan.","why":"Support a safe review.","id":"op-falls-talk-2","simple":"Please do not stop everything. Let’s check the actual medicines and agree targeted changes."},{"cue":"I am afraid to walk now.","response":"That fear matters. We can plan safe support and rehabilitation while we address the causes.","why":"Connect reassurance to action.","id":"op-falls-talk-3","simple":"Let’s address the causes and arrange safe support and rehabilitation for walking."}],"variations":[{"label":"Head injury","change":"The fall included a head strike and anticoagulant use.","action":"Use the current head-injury pathway for urgent assessment rather than routine falls follow-up.","phrase":"The head injury and medicine change the urgency."},{"label":"Blackout","change":"There was transient loss of consciousness.","action":"Assess a blackout/cardiac cause through the appropriate pathway.","phrase":"We need to understand why consciousness was lost."},{"label":"Multiple falls and frailty","change":"There are recurrent falls with impaired gait.","action":"Arrange comprehensive assessment and individualised intervention rather than a single leaflet.","phrase":"Several factors may be interacting, so the plan needs to address them together."}],"safetyNet":["Head injury with concerning symptoms, new neurological signs, collapse or severe injury: urgent/emergency assessment.","Recurrent falls, inability to mobilise safely or worsening dizziness require timely review.","Specify the backup plan if home support or rehabilitation cannot be arranged."],"followUp":"Arrange follow-up based on injury/acute risk and the interventions, including who reviews medicine changes and whether mobility is improving.","pitfalls":["Do not use a prediction score as a substitute for assessing individual risks.","Do not treat falls with blanket medicine stopping."],"links":[{"label":"NICE NG249 — recommendations","url":"https://www.nice.org.uk/guidance/ng249/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["falls,","dizziness","and","a","recent"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Use the current head-injury pathway for urgent assessment rather than routine falls follow-up. The head injury and medicine change the urgency.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"op-opioid-constipation","title":"Opioid-related constipation in a frail adult","summary":"A care-home resident taking an opioid for painful arthritis has constipation and increasing distress.","presentation":"A care-home resident taking an opioid for painful arthritis has constipation and increasing distress. A laxative is already prescribed, but actual use is unclear.","priorities":["Check obstruction features, pain, vomiting, distension and passage of flatus","Assess stool pattern, overflow, impaction, intake and mobility"],"assessment":["Check obstruction features, pain, vomiting, distension and passage of flatus","Assess stool pattern, overflow, impaction, intake and mobility","Review opioid dose, actual laxative administration and other constipating medicines","Assess new confusion, urinary retention and safe care needs"],"management":[{"step":"1. Assess before escalating laxatives","detail":"Obstruction, severe illness or marked impaction needs appropriate examination and urgent management rather than remote dose escalation."},{"step":"2. Review the regimen","detail":"Verify what is actually administered and why the opioid is used. Maintain adequate pain care while considering the medicine’s benefits and harms."},{"step":"3. Treat appropriately","detail":"Choose a suitable bowel regimen using current prescribing guidance; opioid constipation often needs regular laxative treatment and may require an osmotic/stimulant approach. Avoid inappropriate bulk loading or rectal treatment without assessment."},{"step":"4. Make care practical","detail":"Agree a bowel chart, fluids and mobility as appropriate to clinical status, who can administer treatment and when response will be reviewed."}],"discussion":[{"cue":"Can we stop the painkiller?","response":"We should review whether it is still the best treatment, but I also want to keep the pain controlled. Let us assess the constipation and balance both needs.","why":"Avoid replacing one untreated problem with another.","id":"op-opioid-constipation-talk-1","simple":"Let’s assess the constipation and review the medicine while keeping a safe pain-relief plan."},{"cue":"Should we give extra fibre?","response":"That depends on the situation. We first need to check for retained stool or obstruction and choose a suitable treatment.","why":"Avoid generic advice.","id":"op-opioid-constipation-talk-2","simple":"We need to check for built-up stool or a blockage before choosing treatment or adding fibre."},{"cue":"They are more agitated.","response":"Pain, constipation, retention or delirium may contribute. The change needs assessment rather than just a stronger sedative.","why":"Recognise interacting problems.","id":"op-opioid-constipation-talk-3","simple":"The change needs assessment for pain, constipation, retention or delirium, not simply more sedation."}],"variations":[{"label":"Obstruction signs","change":"Vomiting, marked distension and no flatus develop.","action":"Arrange urgent assessment rather than add oral laxatives without review.","phrase":"These symptoms need an urgent medical assessment."},{"label":"Overflow","change":"Loose leakage occurs around retained stool.","action":"Assess impaction; do not assume laxative-induced diarrhoea or stop all treatment automatically.","phrase":"Leakage can occur despite constipation."},{"label":"Renal impairment","change":"Significant kidney impairment limits treatment choices.","action":"Check laxative and opioid suitability and seek specialist/pharmacy advice as needed.","phrase":"The kidney function changes what is safest."}],"safetyNet":["Severe pain, vomiting, distension, inability to pass wind or significant bleeding: urgent assessment.","New confusion, poor intake or rapid deterioration: reassess promptly.","Give a route for non-response or inability to administer the actual regimen."],"followUp":"Set a definite short-interval bowel and symptom review, commonly within 24–48 hours when symptomatic, sooner for warning signs; reassess unresolved symptoms and suspected impaction.","pitfalls":["Do not assume leakage excludes impaction.","Do not give a generic laxative escalation or enema without checking obstruction, frailty and renal considerations."],"links":[{"label":"NICE CG140 — recommendations","url":"https://www.nice.org.uk/guidance/cg140/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["opioid-related","constipation","in","a","frail"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Arrange urgent assessment rather than add oral laxatives without review. These symptoms need an urgent medical assessment.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"op-palliative-pain","title":"Palliative pain and an opioid patch problem","summary":"A person with advanced cancer has worsening pain and says the opioid patch keeps coming loose.","presentation":"A person with advanced cancer has worsening pain and says the opioid patch keeps coming loose. A relative asks for a direct conversion to tablets over the phone.","priorities":["Assess pain severity, pattern, breakthrough use and urgent causes","Establish exact drug, strength, timing, patch number, adhesion and removal"],"assessment":["Assess pain severity, pattern, breakthrough use and urgent causes","Establish exact drug, strength, timing, patch number, adhesion and removal","Assess sedation, breathing, cognition, renal/hepatic function and other medicines","Ask about swallowing, goals, available support and specialist plan"],"management":[{"step":"1. Check immediate risks","detail":"Assess possible toxicity as well as undertreatment. New neurological deficit or suspected cancer emergency needs urgent escalation consistent with the person’s care plan."},{"step":"2. Review delivery","detail":"Check the product and application instructions, skin and adhesion, heat exposure and accidental transfer. Do not cut patches or improvise extra patches."},{"step":"3. Change safely","detail":"Opioid conversions are not a single universal ratio. Seek specialist/pharmacist advice for switching, residual absorption, incomplete cross-tolerance, organ impairment and breakthrough treatment."},{"step":"4. Coordinate","detail":"Provide the actual written prescription/administration plan, bowel and nausea care, monitoring, safe storage/disposal and a named contact."}],"discussion":[{"cue":"Can we just replace it with morphine?","response":"We may be able to change treatment, but the dose and timing need checking carefully because medicine effects can persist after the patch has been removed.","why":"Explain why conversion needs care.","id":"op-palliative-pain-talk-1","simple":"Medicine effects can persist after patch removal. Switching needs careful dose and timing checks."},{"cue":"Will this mean stopping pain relief?","response":"No. We need a safe pain-relief plan, including what to do while any change is arranged.","why":"Avoid abandonment.","id":"op-palliative-pain-talk-2","simple":"We need safe pain relief and a clear plan while any change is arranged."},{"cue":"Can a hot-water bottle help over the patch?","response":"Do not put heat over or near the patch. Heat can increase absorption and cause harm.","why":"Use a clear safety boundary.","id":"op-palliative-pain-talk-3","simple":"Keep heat away from the patch. Too much medicine could enter your body."}],"variations":[{"label":"Toxicity","change":"The person is difficult to wake with slow breathing.","action":"Arrange emergency care and follow opioid-toxicity guidance; patch removal does not end the need for assessment/monitoring.","phrase":"This needs emergency help now."},{"label":"Renal impairment","change":"Kidney function has significantly deteriorated.","action":"Seek specialist advice on opioid choice/dose and assess accumulation.","phrase":"The kidney change affects how the medicine is handled."},{"label":"Spinal symptoms","change":"New weakness or bladder/bowel changes appear with spinal pain.","action":"Arrange urgent assessment for possible cord/cauda equina compression rather than simply increase opioid.","phrase":"The new nerve symptoms change the urgency."}],"safetyNet":["Very slow breathing, unresponsiveness or suspected overdose: emergency help.","New neurological symptoms or severe rapidly worsening pain: urgent assessment.","Clarify who to call for uncontrolled pain, confusion or accidental patch exposure."],"followUp":"Agree prompt review after a change, with observation frequency matched to risk and opioid kinetics; confirm specialist/community team handover and access to breakthrough care.","pitfalls":["Do not use a universal opioid conversion or fixed start time without patient-specific checking.","Do not assume a removed patch has immediately stopped working."],"links":[{"label":"NICE CG140 — recommendations","url":"https://www.nice.org.uk/guidance/cg140/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"},{"label":"Official clinical and patient guidance","url":"https://www.nhs.uk/medicines/fentanyl/how-and-when-to-use-fentanyl/","use":"Relevant clinical safety and patient information"},{"label":"MHRA: fentanyl patch safety","url":"https://www.gov.uk/drug-safety-update/transdermal-fentanyl-patches-life-threatening-and-fatal-opioid-toxicity-from-accidental-exposure-particularly-in-children","use":"Heat, accidental exposure, overdose and persistent risk after removal; check the actual patch product."}],"reviewed":"2026-11-13","tags":["palliative","pain","and","an","opioid"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Arrange emergency care and follow opioid-toxicity guidance; patch removal does not end the need for assessment/monitoring. This needs emergency help now.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"op-palliative-nausea","title":"Nausea and vomiting after an opioid change","summary":"A patient receiving palliative care develops nausea after an opioid increase.","presentation":"A patient receiving palliative care develops nausea after an opioid increase. The family assumes the opioid must be stopped, but constipation and other causes have not been checked.","priorities":["Assess hydration, vomiting frequency, intake and medicine retention","Check constipation/obstruction, metabolic causes, infection and intracranial symptoms"],"assessment":["Assess hydration, vomiting frequency, intake and medicine retention","Check constipation/obstruction, metabolic causes, infection and intracranial symptoms","Review all medicines, timing, organ function and prior antiemetic response","Clarify route needs, symptom goals and home support"],"management":[{"step":"1. Assess cause","detail":"Do not assume the opioid is the only explanation. Obstruction, dehydration or other urgent pathology may change management."},{"step":"2. Treat symptoms","detail":"When opioid-related nausea is likely, explain that it can occur and may improve; prescribe and optimise a suitable antiemetic when indicated, checking interactions and contraindications."},{"step":"3. Preserve pain care","detail":"Review the balance of analgesia and adverse effects. Persistent symptoms despite appropriate antiemetic treatment may require a specialist opioid/route review."},{"step":"4. Coordinate review","detail":"Arrange a route the patient can use, a hydration/symptom plan consistent with goals and clear contact for ongoing vomiting."}],"discussion":[{"cue":"Must we stop the pain medicine?","response":"Not automatically. We need to check the cause of the sickness and treat it while keeping the pain under control.","why":"Balance competing needs.","id":"op-palliative-nausea-talk-1","simple":"Let’s assess and treat the sickness while keeping pain controlled, rather than automatically stop the pain medicine."},{"cue":"Can I take any anti-sickness tablet?","response":"The best choice depends on the cause, other medicines and whether you can keep tablets down.","why":"Explain individualisation.","id":"op-palliative-nausea-talk-2","simple":"The cause, other medicines and whether tablets stay down affect the right choice."},{"cue":"What if the medicine comes back up?","response":"Let us agree what to do if you cannot retain it and whether another route is needed. Do not keep repeating doses without advice.","why":"Prevent accidental extra dosing.","id":"op-palliative-nausea-talk-3","simple":"Let’s agree what to do if the medicine will not stay down. Do not repeat doses without advice."}],"variations":[{"label":"Obstruction suspected","change":"Vomiting occurs with colic, distension and no flatus.","action":"Seek urgent/specialist assessment and an obstruction-specific plan; avoid prokinetics in complete obstruction.","phrase":"This pattern needs a different assessment and treatment."},{"label":"Cannot swallow","change":"Oral medicines cannot be taken.","action":"Review formulation and route with the team; do not crush modified-release preparations or assume every drug can be given through a tube.","phrase":"We need a route that is safe and effective."},{"label":"New severe headache","change":"Vomiting accompanies new neurological symptoms.","action":"Assess an urgent intracranial or other acute cause, in line with the clinical situation and care goals.","phrase":"The new symptoms need urgent review."}],"safetyNet":["Blood in vomit, severe pain/distension, marked dehydration or new neurological signs: urgent assessment.","Persistent inability to retain fluids/medicines or worsening confusion: prompt clinical review.","Explain the day/night contact and what to do if the antiemetic does not help."],"followUp":"Arrange early review of response, hydration and medicine retention, sooner for deterioration; persistent symptoms need a revised cause/route assessment.","pitfalls":["Do not attribute every vomiting episode to opioids.","Do not give a cause-blind antiemetic or repeat vomited doses without a plan."],"links":[{"label":"NICE CG140 — recommendations","url":"https://www.nice.org.uk/guidance/cg140/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"},{"label":"NICE NG31 — recommendations","url":"https://www.nice.org.uk/guidance/ng31/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["nausea","and","vomiting","after","an"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Seek urgent/specialist assessment and an obstruction-specific plan; avoid prokinetics in complete obstruction. This pattern needs a different assessment and treatment.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"op-breathlessness","title":"Breathlessness in advanced illness: physical causes and anxiety","summary":"A person with advanced cancer becomes breathless when dressing and is afraid to leave home.","presentation":"A person with advanced cancer becomes breathless when dressing and is afraid to leave home. A recent assessment was reassuring, but today’s symptoms must still be clarified.","priorities":["Assess current severity, onset, change and emergency features","Consider pulmonary, cardiac, thromboembolic, infective and medication causes"],"assessment":["Assess current severity, onset, change and emergency features","Consider pulmonary, cardiac, thromboembolic, infective and medication causes","Explore panic, activity limitation and the patient’s goals","Review baseline condition, prescribed symptom plan and available support"],"management":[{"step":"1. Reassess change","detail":"A previous normal assessment does not exclude new illness. Arrange examination/investigation or escalation according to current symptoms and care goals."},{"step":"2. Offer practical relief","detail":"Positioning, a handheld fan if suitable, calm support and paced activity may help. Avoid exhausting instructions to breathe deeply repeatedly."},{"step":"3. Individualise medicines","detail":"Persistent distress may need a palliative symptom plan with specialist support and attention to opioids, sedatives, organ function and toxicity. Do not use a blanket sedative for presumed anxiety."},{"step":"4. Coordinate","detail":"Clarify expected response, review and out-of-hours help. Oxygen is not a universal treatment for breathlessness; in the last days of life, use it when symptomatic hypoxaemia is known or suspected."}],"discussion":[{"cue":"They checked me last week, so it must be anxiety.","response":"Anxiety may contribute, but I need to assess what is happening today before assuming there is no physical cause.","why":"Avoid diagnostic overshadowing.","id":"op-breathlessness-talk-1","simple":"We need to assess today’s breathlessness. Anxiety or last week’s check does not rule out a physical cause."},{"cue":"Can I have oxygen?","response":"We need to assess whether oxygen would help your situation. There are other ways to ease breathlessness too.","why":"Avoid promising a treatment without indication.","id":"op-breathlessness-talk-2","simple":"Let’s check whether oxygen would help and discuss other suitable ways to ease the breathlessness."},{"cue":"I just want to get outside.","response":"That goal matters. Let us first check safety, then build a symptom and activity plan that supports it.","why":"Connect care to function.","id":"op-breathlessness-talk-3","simple":"Let’s check safety and make the symptom and activity plan support that goal."}],"variations":[{"label":"Acute chest pain","change":"New sudden breathlessness and chest pain occur.","action":"Assess for a possible emergency such as PE or cardiac illness, with urgent action appropriate to findings/goals.","phrase":"This new pattern needs urgent assessment."},{"label":"Last days of life","change":"The person is recognised as dying and is distressed.","action":"Use an individualised end-of-life symptom plan, checking reversible causes and preferences; do not apply a chronic rehabilitation plan mechanically.","phrase":"We will focus on relief that fits your wishes."},{"label":"Medicine sedation","change":"Extra sedating doses have been taken.","action":"Assess respiratory depression/toxicity urgently and review the prescribed plan.","phrase":"We need to check whether medicine is contributing."}],"safetyNet":["Severe new breathlessness, chest pain, collapse, blue colour or reduced responsiveness: emergency/urgent care appropriate to the agreed plan and clinical assessment.","Worsening despite the symptom plan needs prompt contact with the treating team.","Give a usable day/night route rather than vague advice to wait for a nurse."],"followUp":"Agree prompt review of current symptoms and any medicine changes; reassess physical causes when the pattern changes.","pitfalls":["Do not conclude there is no physical cause from a remote account or old normal observations.","Do not prescribe oxygen or a benzodiazepine automatically for all breathlessness."],"links":[{"label":"NICE NG31 — recommendations","url":"https://www.nice.org.uk/guidance/ng31/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["breathlessness","in","advanced","illness:","physical"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Assess for a possible emergency such as PE or cardiac illness, with urgent action appropriate to findings/goals. This new pattern needs urgent assessment.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"op-mnd","title":"MND, swallowing difficulties and carer exhaustion","summary":"A person with MND uses a gastrostomy and communicates with an aid.","presentation":"A person with MND uses a gastrostomy and communicates with an aid. Their partner asks about anticipatory medicines and says care at home is becoming unsafe.","priorities":["Hear the patient using suitable communication support","Assess current respiratory, swallowing, nutrition and symptom needs"],"assessment":["Hear the patient using suitable communication support","Assess current respiratory, swallowing, nutrition and symptom needs","Review tube problems, medicines, care plan and what carers can actually provide","Clarify wishes, decision-specific capacity and any valid legal authority"],"management":[{"step":"1. Support communication","detail":"Allow time and communication aids. Speech difficulty does not imply impaired understanding or capacity."},{"step":"2. Coordinate specialist care","detail":"Use the MND multidisciplinary team, dietetics, speech and language therapy, respiratory and palliative services according to need."},{"step":"3. Make medicines/routes safe","detail":"Check each medicine’s formulation and suitability for tube or other route with pharmacy/nursing input. Do not crush modified-release medicines or give every liquid through a tube without checking."},{"step":"4. Plan care realistically","detail":"Discuss carer assessment, respite, equipment, hospice/community options and who will respond today. Revisit preferences as needs change; a past wish for home care does not require unsafe care."}],"discussion":[{"cue":"Does a syringe pump mean death is being caused?","response":"It is a way of giving prescribed medicines steadily when that route is needed. We should explain which symptoms each medicine treats and how we monitor its effects.","why":"Explain purpose rather than guarantee an outcome.","id":"op-mnd-talk-1","simple":"A syringe pump gives prescribed medicine steadily when needed. We will explain the purpose and monitor the effects."},{"cue":"I cannot manage another night.","response":"Thank you for saying that. We need a safe plan for tonight as well as longer-term support.","why":"Act on the immediate burden.","id":"op-mnd-talk-2","simple":"Let’s arrange a safe plan and practical help for tonight as well as longer-term support."},{"cue":"Can I decide everything because I am next of kin?","response":"We need to involve them as fully as possible and check any actual legal authority for decisions they cannot make.","why":"Avoid assumed proxy authority.","id":"op-mnd-talk-3","simple":"We should support their own decisions and check actual legal authority if they cannot make a particular decision."}],"variations":[{"label":"Tube problem","change":"The gastrostomy leaks, blocks or is displaced.","action":"Use the relevant urgent tube-care pathway and specialist advice; do not force feeds or medicines through an unsafe tube.","phrase":"We need to check the tube before using it."},{"label":"Respiratory deterioration","change":"New distress or signs of ventilatory failure develop.","action":"Arrange urgent respiratory/palliative assessment and escalation in line with the agreed plan.","phrase":"The breathing change needs help now."},{"label":"Placement requested","change":"The partner requests a hospice or care setting.","action":"Explore the patient’s current wishes and feasible support, and follow the appropriate decision process if capacity is lacking.","phrase":"Let us discuss the safest achievable setting with the person and team."}],"safetyNet":["Acute respiratory distress, choking, reduced responsiveness or tube displacement needs urgent help through the relevant pathway.","Uncontrolled symptoms or inability to provide safe care tonight requires an urgent practical response.","Give named day/night contacts and a backup if the usual team cannot respond."],"followUp":"Confirm who will assess current needs and when; coordinate ongoing MDT review and explicit follow-up of carer support and symptom/route changes.","pitfalls":["Do not infer incapacity from communication impairment.","Do not promise instant hospice admission or send carers away with an unconfirmed referral."],"links":[{"label":"NICE NG42 — recommendations","url":"https://www.nice.org.uk/guidance/ng42/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"},{"label":"NICE NG31 — recommendations","url":"https://www.nice.org.uk/guidance/ng31/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["mnd,","swallowing","difficulties","and","carer"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Use the relevant urgent tube-care pathway and specialist advice; do not force feeds or medicines through an unsafe tube. We need to check the tube before using it.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}},{"id":"op-advance-care","title":"Advance care, CPR and treatment preferences","summary":"A patient with advanced disease wants to plan future care.","presentation":"A patient with advanced disease wants to plan future care. A family member believes a DNACPR recommendation means all treatment will stop.","priorities":["Check current symptoms and whether a decision is needed now","Explore understanding, values, fears and desired involvement"],"assessment":["Check current symptoms and whether a decision is needed now","Explore understanding, values, fears and desired involvement","Support communication and assess capacity for each relevant decision when indicated","Check existing documents, legal authority and the UK nation’s framework"],"management":[{"step":"1. Start with the person","detail":"Ask permission to discuss future care and what matters most. Avoid imposing a decision based solely on age, disability or diagnosis."},{"step":"2. Separate decisions","detail":"Explain that CPR recommendations concern CPR, while other treatments and escalation require their own discussion. A DNACPR recommendation is distinct from a valid applicable advance refusal of treatment."},{"step":"3. Plan practically","detail":"Discuss preferred care, likely scenarios, benefits/burdens and who will coordinate. Explain uncertainty and when the plan should be reviewed."},{"step":"4. Record and share","detail":"Document agreed preferences/decisions and share with appropriate teams, including out-of-hours services, respecting confidentiality and the applicable legal framework."}],"discussion":[{"cue":"Does DNACPR mean no antibiotics?","response":"No. It concerns CPR if the heart or breathing stops. Other appropriate treatments need their own plan.","why":"Correct the central misunderstanding.","id":"op-advance-care-talk-1","simple":"DNACPR concerns CPR. Other appropriate treatments, including antibiotics, need their own plan."},{"cue":"Can I change my mind?","response":"We can review preferences and the plan as your wishes or circumstances change. The exact effect depends on the type of decision or document.","why":"Avoid conflating documents.","id":"op-advance-care-talk-2","simple":"We can review your wishes and plan. The effect depends on the decision or document involved."},{"cue":"Will you make my family decide everything?","response":"We should involve you as fully as possible. Family views can help, but we need to check any actual legal authority if you cannot make a particular decision.","why":"Explain roles.","id":"op-advance-care-talk-3","simple":"Your involvement matters. Family views help, but any decision-making authority must be checked."}],"variations":[{"label":"Currently capable refusal","change":"The patient makes an informed refusal of a treatment.","action":"Respect the decision within the applicable law, explain consequences and record clearly; do not equate disagreement with incapacity.","phrase":"I want to make sure you understand the options and that we record your wishes accurately."},{"label":"Capacity uncertain","change":"The person cannot engage because of acute confusion.","action":"Assess/treat the acute cause, support decision-making and follow the relevant legal process for decisions that cannot wait.","phrase":"We need to support the decision and check what can safely wait."},{"label":"Valid prior refusal","change":"An advance refusal may apply to the current treatment.","action":"Check validity, applicability and legal requirements; seek timely advice if uncertain rather than assume a CPR form settles it.","phrase":"We need to check exactly what this document covers."}],"safetyNet":["Acute deterioration still needs assessment and treatment consistent with valid applicable decisions and the clinical situation.","Clarify which service to contact for a crisis and how the care plan will be available.","Explain how to request a review when wishes or circumstances change."],"followUp":"Name the coordinating clinician and triggers for review, such as deterioration, admission, changed preferences or a change in decision-making ability.","pitfalls":["Do not equate DNACPR with comfort-only care or automatic refusal of all treatment.","Do not assume next of kin has unrestricted authority or apply one UK nation’s legal rules universally."],"links":[{"label":"Official clinical and patient guidance","url":"https://www.gmc-uk.org/professional-standards/the-professional-standards/treatment-and-care-towards-the-end-of-life/cardiopulmonary-resuscitation-cpr","use":"Relevant clinical safety and patient information"},{"label":"NICE NG31 — recommendations","url":"https://www.nice.org.uk/guidance/ng31/chapter/recommendations","use":"Assessment, treatment or referral recommendations relevant to this case"}],"reviewed":"2026-11-11","tags":["advance","care,","cpr","and","treatment"],"retrieval":{"question":"What changes in the first permutation, and what action would you explain to the patient or family?","answer":"Respect the decision within the applicable law, explain consequences and record clearly; do not equate disagreement with incapacity. I want to make sure you understand the options and that we record your wishes accurately.","checks":["Identified the change in risk or need","Specified action, urgency and ownership","Used clear language and checked practical understanding"]}}]},{"id":"cardiovascular","title":"Cardiovascular","description":"Raised blood pressure, atrial fibrillation and acute chest-pain triage, each with management discussion and three changed circumstances.","icon":"04","reviewed":"2026-11-12","cases":[{"id":"cv-hypertension","title":"Raised blood pressure: confirmation, risk and a shared plan","summary":"Confirm the pattern, assess urgency and discuss prevention in terms the person can use.","presentation":"A 52-year-old has repeat clinic readings around 158/96 mmHg at a health check. They feel well and ask whether tablets are really necessary. There are no supplied symptoms of acute target-organ injury; these must still be assessed.","assessment":["Repeat and interpret measurements using an appropriate validated device, cuff and technique; check pulse regularity and relevant postural symptoms.","Ask about chest pain, breathlessness, confusion, neurological or visual symptoms and other findings that change urgency.","Review previous readings, current medicines and substances, kidney or cardiovascular disease, diabetes, pregnancy possibility where relevant, family history and cardiovascular risk.","Assess for target-organ damage and relevant baseline investigations using NG136; explore daily routines, beliefs, treatment burden and what the patient wants to understand."],"priorities":["Separate a routine confirmation pathway from severe hypertension with acute symptoms or signs.","Explain why a person who feels well may still benefit from assessment and prevention."],"management":[{"step":"1. Establish the appropriate urgency","detail":"Suspected acute organ injury or other time-critical illness requires immediate/same-day specialist assessment according to the clinical picture. Severe clinic BP of 180/120 mmHg or higher needs the specific NG136 pathway, not an automatic long wait for home readings."},{"step":"2. Confirm rather than label from one reading","detail":"For clinic BP in the non-severe diagnostic range, offer ABPM; use HBPM if ABPM is unsuitable or not tolerated. Hypertension is confirmed with clinic BP at least 140/90 and an ABPM daytime or HBPM average at least 135/85 mmHg. Use the correct monitoring protocol."},{"step":"3. Assess the wider risk","detail":"Check for target-organ damage and calculate cardiovascular risk using the appropriate current tool. Explain the findings and any relevant kidney, diabetic or cardiovascular conditions that affect the plan."},{"step":"4. Discuss prevention and treatment","detail":"Offer practical lifestyle support. Discuss antihypertensive treatment according to confirmed stage, age, risk, organ damage and comorbidities. Do not imply that lifestyle change and indicated medication are mutually exclusive."},{"step":"5. Choose and monitor treatment safely","detail":"If prescribing, use the current NICE step algorithm and prescribing reference, considering age, relevant comorbidities, contraindications, interactions, pregnancy potential and monitoring. Agree an individual BP target; frailty and postural symptoms may change the approach."},{"step":"6. Make monitoring workable","detail":"Demonstrate home technique if used, check access to an appropriate monitor and agree who reviews the readings. Set a definite confirmation/result discussion and earlier checks after any medicine change as appropriate to the drug and patient."}],"discussion":[{"cue":"I feel fine. Why should we do anything?","response":"High blood pressure often has no symptoms. We check it carefully because, over time, it can increase the chance of a stroke, heart or kidney problems. Our next step is to confirm the pattern and discuss what would help you.","why":"Link prevention to a clear first action without using fear or diagnosing from one value.","id":"cv-hypertension-talk-1","simple":"Blood pressure can be high without symptoms. Let’s confirm it and discuss how to reduce the longer-term risks."},{"cue":"Is it just because I get nervous here?","response":"That can affect a reading. A monitor during your usual day, or a properly recorded set of home readings, helps us see whether the pressure is also raised outside the surgery.","why":"Explain why the confirmation process changes the decision.","id":"cv-hypertension-talk-2","simple":"Anxiety can affect the reading. Monitoring outside the surgery helps us check the usual pattern."},{"cue":"I don’t want to be on tablets forever.","response":"Could you tell me what concerns you most about taking them? We can discuss the likely benefit, possible side effects, what changes you want to make and how we would review the plan.","why":"Explore the reason for reluctance and keep indicated treatment open for discussion.","id":"cv-hypertension-talk-3","simple":"What worries you most about tablets? Let’s discuss benefits, side effects and a review plan."},{"cue":"Which number am I aiming for?","response":"We will agree a target that fits your age, overall health and any dizziness on standing. Home and surgery targets are different, so I will write down the one we want you to use.","why":"Make the target explicit for the individual rather than apply one number to every setting.","id":"cv-hypertension-talk-4","simple":"Let’s write down your individual target. Home and surgery targets are different."},{"cue":"I can’t afford a home machine.","response":"Let’s check whether ambulatory monitoring or another available practice arrangement would work. We need a plan you can actually use, rather than asking you to buy something you cannot afford.","why":"Identify access barriers and confirm actual service availability.","id":"cv-hypertension-talk-5","simple":"Let’s check an available monitoring arrangement you can use without buying an unaffordable machine."}],"variations":[{"label":"Severe BP with acute symptoms","change":"The reading is 192/124 mmHg and new chest pain or confusion is present.","action":"Arrange emergency/same-day acute specialist assessment according to the suspected condition. Do not wait for routine monitoring or attempt an unsupported rapid outpatient reduction.","phrase":"The new symptoms change the urgency. I’m concerned this needs emergency assessment now, and I will help arrange it."},{"label":"Clinic and out-of-office readings differ","change":"The daytime ABPM average is below the diagnostic threshold despite raised clinic readings.","action":"Review the quality of readings and the whole clinical picture. Do not automatically label sustained hypertension; consider a white-coat effect and agree risk management and subsequent monitoring.","phrase":"The readings outside the surgery are different. Let’s check what that means for your risk and agree how we will keep an eye on it."},{"label":"Frailty and postural symptoms","change":"An older frail person reports dizziness and falls after a recent treatment change.","action":"Check lying/standing BP, actual medicines, falls and other causes. Individualise targets and treatment burden, using standing measurements where indicated and arranging clinically appropriate review.","phrase":"We want to reduce future risk while keeping you steady and safe now. Let’s review the standing readings and the medicines together."}],"pitfalls":["Do not diagnose sustained hypertension from a single clinic value or dismiss a severely raised reading without assessment.","Do not automatically send every asymptomatic severe reading through the same pathway as severe BP with acute organ injury; follow the defined NG136 severe-hypertension pathway.","Do not use one universal target or medication regimen for pregnancy, CKD, frailty and all other adults."],"safetyNet":["New chest pain, severe breathlessness, focal neurological symptoms, confusion or severe acute illness needs urgent/emergency assessment according to severity.","With BP at least 180/120 and no same-day-referral features, assess for target-organ damage promptly and follow NG136: if no target-organ damage is found, ensure repeat/confirmatory assessment and clinical review within 7 days.","If monitoring, tests or the review cannot be arranged, contact the named team promptly rather than leave the confirmation process open."],"followUp":"Book a definite review of confirmation and baseline results, then drug-specific safety/response checks if treatment starts. Provide at least annual hypertension review thereafter, with earlier review for symptoms, poor control or treatment problems.","reviewed":"2026-11-12","tags":["blood pressure","hypertension","ABPM","HBPM","prevention","adherence"],"links":[{"label":"NICE NG136: hypertension","url":"https://www.nice.org.uk/guidance/ng136","use":"Measurement, confirmation, severe-hypertension pathways, targets and treatment."},{"label":"NHS: high blood pressure","url":"https://www.nhs.uk/conditions/high-blood-pressure/","use":"Plain-language explanation and patient information."}],"retrieval":{"question":"How would you explain the need for out-of-office confirmation, and how does 192/124 with new chest pain change the plan?","answer":"Explain that out-of-office readings help establish whether pressure remains raised outside the surgery. New chest pain with severe BP changes the priority to acute specialist/emergency assessment; do not wait for routine confirmation.","checks":["Explained confirmation and what it changes","Recognised acute symptoms and severe BP","Specified an actual assessment and follow-up owner"]}},{"id":"cv-atrial-fibrillation","title":"New atrial fibrillation: symptoms, stroke prevention and bleeding concerns","summary":"Separate stability, rhythm-related symptoms and prevention of stroke, then make an individual plan.","presentation":"A clinically stable 72-year-old man with hypertension has AF confirmed on a 12-lead ECG after palpitations. He asks whether an irregular heartbeat means an immediate stroke and is worried about bleeding if a new medicine is offered.","assessment":["Check haemodynamic stability, chest pain, breathlessness, syncope, acute heart failure and neurological symptoms; instability or suspected stroke changes urgency.","Clarify onset, duration, symptom burden, previous episodes, comorbidities, current medicines and possible contributors; arrange appropriate examination and investigations.","Assess stroke risk with CHA₂DS₂-VASc and bleeding risk with ORBIT using verified clinical information. Review renal function, interactions, previous bleeding, valve disease and other factors that affect safe treatment.","Explore the patient’s goals, understanding, actual medicine use, falls, alcohol and ability to follow a monitoring and treatment plan."],"priorities":["Treat acute instability or suspected stroke as urgent/emergency care.","Explain that symptom control and prevention of stroke are related but separate decisions."],"management":[{"step":"1. Establish and document the diagnosis","detail":"Use the actual ECG and assessment. If episodes are intermittent and a resting ECG does not capture AF, arrange appropriate ambulatory ECG monitoring; a normal tracing between episodes does not exclude paroxysmal AF."},{"step":"2. Agree symptom-management assessment","detail":"Review rate/rhythm needs and possible causes with the patient. Select treatment and referral through current guidance, considering heart failure, duration, symptoms, comorbidities and suitability rather than giving one regimen to every patient."},{"step":"3. Assess stroke and bleeding risk explicitly","detail":"In this supplied example, age 65–74 and hypertension each contribute to the stroke-risk assessment. Calculate the actual score and use ORBIT to identify bleeding risk and modifiable factors. Explain the estimates and their limits."},{"step":"4. Discuss appropriate anticoagulation","detail":"NICE offers a DOAC for AF with CHA₂DS₂-VASc at least 2 and considers it for men with a score of 1, taking bleeding risk into account. Check the specific agent’s indication, renal function, interactions, dose criteria and contraindications; some valve conditions need a different pathway."},{"step":"5. Reduce avoidable harm","detail":"Address uncontrolled BP, interacting medicines such as inappropriate NSAIDs, alcohol and treatable causes of anaemia where relevant. Do not withhold anticoagulation solely because of age or falls, and do not use aspirin alone as AF stroke prevention."},{"step":"6. Close the practical plan","detail":"Give clear medicine and missed-dose advice for the actual agent, accessible written information, monitoring arrangements and an agreed review. Record a shared decision and reassess if anticoagulation is declined, unsuitable or later reconsidered."}],"discussion":[{"cue":"Does this mean I am having a stroke?","response":"An irregular rhythm can increase the risk of a clot forming over time, but it does not mean you are having a stroke now. New stroke symptoms need emergency help. Let’s discuss both the rhythm symptoms and how we can reduce future risk.","why":"Distinguish current symptoms from longer-term risk without ignoring an acute neurological presentation.","id":"cv-atrial-fibrillation-talk-1","simple":"An irregular heart rhythm can increase future stroke risk. It does not by itself mean a stroke is happening now. New stroke symptoms need emergency help."},{"cue":"Why are there two parts to the treatment?","response":"One part of the plan helps control the heart rhythm or rate and how you feel. Another considers reducing the chance of a clot causing a stroke. We should discuss each clearly.","why":"Avoid implying that symptom improvement removes the need to assess stroke prevention.","id":"cv-atrial-fibrillation-talk-2","simple":"We need to discuss symptom control and stroke prevention separately. Feeling better does not settle both questions."},{"cue":"A blood thinner sounds dangerous.","response":"Bleeding is an important risk to discuss. We can look at your stroke risk, the bleeding risk and what we can change to make treatment safer, then explain why a particular option is recommended for you.","why":"Balance benefit and harm using the person’s actual risk and preferences.","id":"cv-atrial-fibrillation-talk-3","simple":"Let’s balance your stroke and bleeding risks and discuss how to make suitable treatment safer."},{"cue":"I have fallen before. Does that rule it out?","response":"The falls matter and we should assess why they happen. A history of falls alone does not automatically rule out stroke-prevention treatment. Let’s review the risks and practical ways to make the plan safer.","why":"Address falls without treating them as a blanket contraindication.","id":"cv-atrial-fibrillation-talk-4","simple":"Falls need assessment, but do not automatically rule out stroke-prevention treatment."},{"cue":"What if I miss a dose?","response":"The advice depends on the medicine and timing. I will give you the instructions for your actual prescription, including missed doses, bleeding warnings and who to contact. Please check rather than guess or double a dose.","why":"Make medicine instructions specific to the selected agent.","id":"cv-atrial-fibrillation-talk-5","simple":"Let’s use your actual medicine’s missed-dose instructions. Please ask if uncertain rather than change the dose yourself."}],"variations":[{"label":"New instability","change":"The person develops collapse, ongoing chest pain, severe breathlessness or other signs of haemodynamic compromise.","action":"Arrange immediate emergency assessment and handover. Do not delay for a routine stroke score or outpatient rate-control discussion.","phrase":"The symptoms now need emergency care. I will arrange help and pass on the ECG and what has changed."},{"label":"Anticoagulation declined because of falls","change":"The patient fears that a single fall would inevitably cause a fatal bleed.","action":"Explore the fear, assess the falls and actual bleeding risks, explain benefit/harm and address modifiable factors. Avoid withholding solely on falls; document the shared decision and agree reassessment.","phrase":"Let’s look at what has caused the falls and what your individual treatment risks are, rather than assume that one fact decides everything."},{"label":"Symptoms not captured on today’s ECG","change":"Episodes are intermittent and the resting ECG is normal.","action":"Do not label the symptoms harmless from that tracing. Arrange monitoring of suitable duration to capture suspected paroxysmal AF, guided by episode frequency and the relevant pathway; assess other causes and current urgency.","phrase":"The tracing shows what the heart was doing at that moment. A monitor can help us find out what happens during an episode."}],"pitfalls":["Do not confuse anticoagulation with symptom treatment or assume a normal resting ECG excludes intermittent AF.","Do not make a universal DOAC choice or dose without checking valve disease, renal function, interactions and the indication.","Do not prescribe aspirin alone for AF stroke prevention or withhold anticoagulation solely for age/falls."],"safetyNet":["New facial weakness, arm weakness, speech difficulty or other sudden neurological symptoms needs emergency assessment.","Collapse, severe chest pain or severe breathlessness needs emergency help rather than waiting for routine AF review.","For prescribed anticoagulation, provide agent-specific advice about significant/recurrent bleeding and emergency features; ensure a named route for questions and monitoring problems."],"followUp":"Arrange timely review of symptoms, treatment choice, safety tests and ability to follow the plan. Reassess stroke/bleeding risk when circumstances change and at guideline-recommended intervals; actively review if treatment is declined or stopped.","reviewed":"2026-11-12","tags":["AF","atrial fibrillation","palpitations","anticoagulation","stroke prevention","ORBIT"],"links":[{"label":"NICE NG196: atrial fibrillation","url":"https://www.nice.org.uk/guidance/ng196","use":"Diagnosis, risk assessment, anticoagulation and rate/rhythm management."},{"label":"NHS: atrial fibrillation","url":"https://www.nhs.uk/conditions/atrial-fibrillation/","use":"Patient explanation and urgent symptom advice."},{"label":"NHS: anticoagulant adverse effects","url":"https://www.nhs.uk/medicines/anticoagulants/side-effects/","use":"Bleeding and other medicine safety information."}],"retrieval":{"question":"How would you explain the separate goals of AF treatment to someone worried about bleeding, and what does a history of falls change?","answer":"Distinguish symptom control from stroke prevention. Review verified stroke and bleeding risks, explain relevant benefits/harms and address falls and other modifiable factors. Falls alone should not determine withholding anticoagulation.","checks":["Separated current urgency, symptoms and prevention","Used individual stroke/bleeding assessment","Addressed the concern and monitoring plan without a blanket rule"]}},{"id":"cv-chest-pain","title":"Chest pain by telephone: recognise possible ACS and arrange help","summary":"Use a brief focused assessment to choose urgency, then communicate and hand over clearly.","presentation":"A 58-year-old describes twenty minutes of central chest heaviness with sweating and discomfort into the arm. The pain is still present during a telephone call. They ask whether it could simply be indigestion and do not want to leave a dependent partner alone.","assessment":["Establish exact location, a callback number and whether the person is alone; arrange emergency help without delay when the supplied symptoms suggest ACS.","Clarify current pain, onset, duration, radiation, breathlessness, sweating, nausea, collapse and relevant history and medicines without allowing questions to delay escalation.","Consider other time-critical causes of chest pain and clinical instability. Do not use a normal resting ECG or response to indigestion treatment/GTN to rule out ACS.","Assess the practical barrier to emergency care, the person’s understanding and decision-making ability if there is a concern; identify safe arrangements for the dependent partner."],"priorities":["The supplied current symptoms need emergency hospital assessment, not routine outpatient testing.","Make the next action explicit and confirm an accepted handover and practical support."],"management":[{"step":"1. State the concern and arrange emergency care","detail":"For suspected ACS with current pain, arrange emergency hospital referral/ambulance through the local pathway. Confirm location and contact details and do not ask the person to drive themselves."},{"step":"2. Keep initial care proportionate","detail":"Follow the acute chest-pain/ACS pathway while help is arranged. An ECG, if available, must not delay transfer. NICE recommends a single 300 mg aspirin loading dose as soon as possible unless there is clear aspirin allergy; check prior dosing and relevant clinical circumstances and communicate any treatment to the receiving team."},{"step":"3. Avoid false exclusion","detail":"Do not rule out ACS because pain resolves, an ECG is normal, the person is younger than expected or a previous episode was attributed to reflux. Referral urgency depends on current symptoms, timing and the relevant ECG/clinical findings."},{"step":"4. Address refusal and the actual barrier","detail":"Acknowledge the concern about the partner, explain the risk and recommended urgency, and seek a feasible support arrangement. If the person continues to decline, assess understanding and any capacity concern, seek appropriate senior/emergency advice and document the discussion and plan under the relevant framework."},{"step":"5. Make and document the handover","detail":"Pass the symptom history and timing, observations/ECG if obtained, treatment given, allergies and relevant risks. Confirm that the receiving service has accepted the handover; keep contact as appropriate while assistance is arranged."}],"discussion":[{"cue":"Could it just be indigestion?","response":"It could have more than one cause, but the pressure, sweating and arm discomfort make me concerned about a heart-related emergency. I recommend emergency assessment now. I will help arrange the ambulance.","why":"Explain the reason for urgency without claiming a confirmed diagnosis.","id":"cv-chest-pain-talk-1","simple":"These symptoms could be a heart emergency. I recommend emergency assessment now and will help arrange it."},{"cue":"Can I drive myself in?","response":"Please do not drive yourself. Your symptoms could worsen on the way. Let’s confirm where you are and arrange the safest emergency help.","why":"Link the recommendation to practical transport rather than only giving a destination.","id":"cv-chest-pain-talk-2","simple":"Please do not drive yourself. Let’s confirm your location and arrange emergency help."},{"cue":"I cannot leave my partner alone.","response":"I hear that you are worried about your partner. Your symptoms still need emergency assessment. Let’s work out who can support them while the ambulance is arranged, rather than leave you both without help.","why":"Acknowledge the barrier while retaining the urgent recommendation.","id":"cv-chest-pain-talk-3","simple":"You still need emergency assessment. Let’s arrange support for your partner while help comes."},{"cue":"The pain has eased. Do I still need to go?","response":"The improvement is useful to know, but it does not by itself rule out a heart problem. Because of what has happened and how recently it occurred, we need to keep the urgent assessment plan.","why":"Do not use symptom resolution as a standalone safety test.","id":"cv-chest-pain-talk-4","simple":"Pain improving does not rule out a heart problem. We need to keep the urgent plan for this episode."},{"cue":"What if this turns out to be nothing serious?","response":"That would be reassuring. The safest way to find out is the appropriate emergency assessment, because waiting could be harmful if this is a heart problem.","why":"Support the action without promising the outcome.","id":"cv-chest-pain-talk-5","simple":"Emergency assessment is the safest way to check this. Waiting could be harmful if it is a heart problem."}],"variations":[{"label":"Pain stops during the call","change":"The same recent concerning episode has resolved but no ECG is available.","action":"Do not cancel escalation solely because symptoms stop. Follow CG95’s recent-pain pathway; suspected ACS with pain in the last 12 hours and no available ECG still requires emergency referral.","phrase":"I’m glad the pain has eased, but that alone does not make it safe to wait. We still need the emergency assessment."},{"label":"Patient continues to decline hospital","change":"The person understands the recommendation but fears leaving a dependent partner.","action":"Explore the barrier, offer practical arrangements, explain the risk and options and assess capacity if there is a concern. Respect the relevant decision-making framework, seek appropriate advice and record a concrete safety plan; disagreement alone is not incapacity.","phrase":"Could you tell me what you understand about the risk of waiting? I want to work with you on the safest plan and the help your partner needs."},{"label":"A different stable exertional pattern","change":"In a separate scenario, a completed assessment identifies predictable exertional discomfort without acute or recent ACS features.","action":"Use the stable chest-pain diagnostic pathway, with appropriate timely assessment and CT coronary angiography when indicated. Give clear advice for prolonged, rest or changing pain. Do not relabel the original current-pain case as stable just to avoid referral.","phrase":"This pattern needs a different assessment pathway. Let’s arrange it and agree what change would mean you should seek emergency help."}],"pitfalls":["Do not delay an emergency referral while completing a full routine history, arranging outpatient troponin or waiting for an ECG.","Do not exclude ACS from a normal ECG or improved pain alone.","Do not treat a care barrier as an informed refusal without exploring it, and do not assume disagreement automatically means incapacity."],"safetyNet":["For the supplied ongoing possible-ACS presentation, the immediate action is emergency care now; safety-net wording is not a substitute for escalation.","Confirm who is calling/arranging emergency help and what happens if the call disconnects; avoid an ambiguous assumption that someone else has acted.","In a genuinely stable outpatient scenario, new persistent/rest pain, collapse, severe breathlessness or other acute change requires emergency reassessment."],"followUp":"Confirm the actual emergency handover and document action. After discharge, reconcile the diagnosis, treatment and follow-up arrangements, including rehabilitation and secondary prevention if indicated; an emergency referral should not disappear from continuity of care.","reviewed":"2026-11-12","tags":["chest pain","ACS","heart attack","urgent triage","refusal","carer"],"links":[{"label":"NICE CG95: recent-onset suspected cardiac chest pain","url":"https://www.nice.org.uk/guidance/cg95","use":"Current and recent suspected-ACS referral pathways and diagnostic assessment."},{"label":"NICE NG185: acute coronary syndromes","url":"https://www.nice.org.uk/guidance/ng185","use":"Acute treatment and subsequent management."},{"label":"NHS: heart attack","url":"https://www.nhs.uk/conditions/heart-attack/","use":"Patient-facing emergency advice."}],"retrieval":{"question":"What would you say when the pain eases but the patient still does not want hospital because of a dependent partner?","answer":"Acknowledge the improvement and the care barrier, retain the appropriate recent-ACS emergency pathway, explain why symptom relief does not exclude danger and arrange practical support and an accepted handover.","checks":["Kept urgency linked to the clinical history and timing","Addressed the barrier without blame or false reassurance","Named an actual action, transport and handover owner"]}}]},{"id":"respiratory","title":"Respiratory","description":"Adult asthma and COPD: diagnosis and control, inhaler discussion, breathlessness and exacerbation decisions, each with three changed circumstances.","icon":"05","reviewed":"2026-11-12","cases":[{"id":"rs-adult-asthma","title":"Adult asthma: increasing reliever use and night symptoms","summary":"Assess current severity, actual inhaler use and technique, then agree an anti-inflammatory treatment plan.","presentation":"A 30-year-old with confirmed asthma requests another blue reliever inhaler. They report needing it most days and waking with symptoms. They are comfortable speaking now but stopped the preventer because of fears about steroids.","assessment":["Assess current symptoms and severity, including ability to speak, breathlessness at rest, exhaustion, response to reliever and relevant objective measures when feasible; do not delay emergency action to obtain a reading.","Explore day/night symptoms, activity limitation, reliever use, previous attacks/admissions, risk factors and actual treatment use.","Check the recorded basis for diagnosis and reconsider alternatives if uncertain. Objective testing follows the appropriate pathway; previous ICS treatment can affect test results.","Watch inhaler technique using the actual device, review adherence without blame, triggers, smoking/exposures and comorbidities, and explore the patient’s concerns and functional goals."],"priorities":["Separate an acute attack from a chronic-control review.","Address the reason for poor control before automatically increasing doses."],"management":[{"step":"1. Act on acute severity","detail":"Arrange emergency or urgent assessment when indicated by the current symptoms and local acute-asthma pathway. Do not wait for routine spirometry or a control-review appointment during a serious attack."},{"step":"2. Identify what is happening in real use","detail":"Check reliever frequency, anti-inflammatory treatment use, device technique, supply and barriers. Demonstrate technique and ask the patient to show it back. Review contributory exposures and comorbidities."},{"step":"3. Use the current age-appropriate pathway","detail":"For people aged 12 and over with newly diagnosed asthma, NG245 offers low-dose ICS/formoterol as-needed AIR therapy. Existing uncontrolled asthma may need an appropriate MART or other pathway step after review. Use the correct formulation, dose and licence; not every ICS/LABA combination is a reliever."},{"step":"4. Avoid SABA-only management in asthma","detail":"Do not prescribe a SABA without an accompanying ICS prescription. Discuss the role of anti-inflammatory treatment, relevant benefits/harms and the patient’s concerns rather than repeatedly issuing a reliever alone."},{"step":"5. Agree an achievable written action plan","detail":"Explain the actual regimen, routine/reliever roles, maximum use and deterioration actions for the selected device. Check understanding and access; plans for SABA and AIR/MART regimens are not interchangeable."},{"step":"6. Review response and safety","detail":"After starting or adjusting asthma medicines, review response in 8–12 weeks, or earlier for clinical need, side effects or deterioration. An attack needs early follow-up; NHS advice is GP review within 2 days even after improvement. Maintain ongoing control and risk review."}],"discussion":[{"cue":"Why is using the blue inhaler a problem if it works?","response":"It is useful that you get relief, but needing it frequently and waking at night suggest the asthma is not well controlled. We need to review the inflammation treatment and how the inhalers fit together.","why":"Acknowledge relief while explaining why frequency matters.","id":"rs-adult-asthma-talk-1","simple":"Needing relief often and waking at night means we should review how your asthma is being treated."},{"cue":"I’m scared of steroids.","response":"What have you heard that worries you most? The inhaled treatment aims to reduce airway inflammation and the chance of attacks. We can discuss the risks of the actual product and dose and how to use it safely.","why":"Explore a specific concern instead of dismissing it or claiming there are no harms.","id":"rs-adult-asthma-talk-2","simple":"What worries you about steroids? Let’s discuss the actual inhaled treatment, benefits, risks and safe use."},{"cue":"Are you saying I use it wrongly?","response":"I check technique with everyone because the devices can be tricky and instructions are not always clear. Could you show me how you usually use yours, then we can work through it together?","why":"Make the review routine and collaborative, not a criticism.","id":"rs-adult-asthma-talk-3","simple":"I check technique with everyone. Could you show me your usual method so we can work through it together?"},{"cue":"Does this inhaler do both jobs?","response":"Some specific inhalers are used in a plan that covers both anti-inflammatory treatment and relief. We will make sure you know exactly which device you have and how your written plan says to use it.","why":"Avoid transferring AIR/MART instructions to a different device or combination.","id":"rs-adult-asthma-talk-4","simple":"Only specific inhalers and regimens do both jobs. Let’s confirm your exact device and written instructions."},{"cue":"I cannot remember extra doses during shifts.","response":"Let’s look at your actual routine and choose a suitable regimen you can follow. We can practise the device, write down the instructions and agree what to do if you miss a dose or need more relief.","why":"Address the barrier while keeping advice product-specific.","id":"rs-adult-asthma-talk-5","simple":"Let’s choose a suitable plan that fits your shifts and write down the exact instructions."}],"variations":[{"label":"Attack not responding to reliever","change":"The patient is worsening, struggling to speak or not improving with their reliever.","action":"Arrange emergency help and follow the acute-asthma action pathway. Confirm location, actual reliever/regimen and handover; do not continue a routine chronic review.","phrase":"Your breathing needs emergency help now. Let’s confirm where you are and arrange it, while following the emergency instructions for your actual inhaler."},{"label":"New diagnosis after objective assessment","change":"A symptomatic adult has asthma newly confirmed and no acute attack requiring a different pathway.","action":"Use NG245’s age-appropriate initial pharmacological pathway, including as-needed low-dose ICS/formoterol AIR therapy for ages 12 and over; check the actual product, licensing and instructions, teach technique and provide an action plan.","phrase":"We can choose a suitable treatment that includes anti-inflammatory medicine and relief, and I will show you exactly how your prescribed device should be used."},{"label":"Regimen seems ineffective despite reported use","change":"Control remains poor after a change, but the patient is using the device incorrectly or cannot obtain it reliably.","action":"Watch actual technique and establish access and use before reflex escalation. Correct barriers, reassess diagnosis and risks, and arrange a definite review or specialist advice if control remains inadequate.","phrase":"Before adding more medicine, let’s make sure this device and plan are actually working for you in day-to-day use."}],"pitfalls":["Do not use normal speech at one moment or a single reassuring measurement to dismiss a concerning attack history.","Do not continue SABA-only management for asthma or assume all ICS/LABA inhalers can be used as relievers.","Do not automatically apply adult/12-and-over pathways to younger children or delay acute treatment for diagnostic testing."],"safetyNet":["An attack with worsening symptoms, poor reliever response, severe breathing difficulty, exhaustion or altered consciousness requires emergency help through the actual action plan.","More frequent relief, night waking, reduced activity or concern about treatment needs prompt clinical review; do not wait for a planned routine date if worsening.","Give written device-specific instructions and a contact route if the inhaler cannot be obtained, instructions are unclear or the plan is not working."],"followUp":"Agree a named review and assess symptoms, function, reliever use, attacks, technique, actual use and adverse effects. Usual medication-response review is 8–12 weeks, with earlier action when needed; review promptly after an attack and continue scheduled asthma reviews.","reviewed":"2026-11-12","tags":["adult asthma","AIR","MART","ICS","reliever","inhaler technique"],"links":[{"label":"NICE NG245: BTS/NICE/SIGN asthma guidance","url":"https://www.nice.org.uk/guidance/ng245","use":"Objective assessment, age-specific treatment, monitoring and action plans."},{"label":"NHS: asthma","url":"https://www.nhs.uk/conditions/asthma/","use":"Patient explanation, attacks and early review."}],"retrieval":{"question":"What would you say to a patient who gets relief from frequent SABA use but stopped anti-inflammatory treatment because of fear?","answer":"Acknowledge relief, explain that frequency and night symptoms suggest poor control, explore the specific treatment concern and review technique/actual use. Agree an appropriate ICS-containing plan, device-specific instructions and review; escalate any current attack.","checks":["Assessed current severity","Explored the barrier and actual use","Recommended an appropriate anti-inflammatory plan and clear follow-up"]}},{"id":"rs-copd","title":"COPD: breathlessness, inhaler review and a request for oxygen","summary":"Confirm the diagnosis and current stability, address function and use an individual management plan.","presentation":"A 67-year-old with previously confirmed COPD reports gradually limiting breathlessness and asks for home oxygen. They use inhalers inconsistently and have had several courses from rescue packs. There is no supplied acute deterioration; assess this rather than assume stability.","assessment":["Check whether breathlessness is new or acutely worse, including chest pain, fever, haemoptysis, severe hypoxia, confusion or other findings suggesting urgent illness or another diagnosis.","Review the basis for COPD diagnosis, symptoms and exposures; use quality post-bronchodilator spirometry in the appropriate clinical context rather than a smoking history alone.","Assess functional limitation, exacerbations/admissions, sputum pattern, oxygen saturation where appropriate, weight/nutrition, comorbidities and possible asthma/steroid-responsive features.","Watch device technique, establish actual medicines and rescue-pack use, smoking status and support needs, and ask what the patient most wants to be able to do."],"priorities":["Separate stable limitation from an acute exacerbation or a different serious cause.","Treat breathlessness and prevention needs rather than prescribe oxygen from symptoms alone."],"management":[{"step":"1. Confirm the clinical picture","detail":"Review the diagnostic evidence and current assessment. Consider alternative or additional causes of breathlessness and investigate/refer when the pattern, examination or warning features require it."},{"step":"2. Optimise practical treatment","detail":"Check device suitability, technique, actual use and benefit before changing inhalers. Select bronchodilator/other maintenance treatment using NG115, accounting for asthma/steroid-responsive features, exacerbations, symptoms, adverse effects and patient preferences."},{"step":"3. Offer broader support","detail":"Offer smoking-cessation treatment and support where relevant, appropriate vaccinations, activity/nutrition advice and pulmonary rehabilitation when breathlessness limits function and the person is suitable. Address anxiety, social needs and access."},{"step":"4. Assess oxygen properly","detail":"Home oxygen requires assessment against clinical hypoxaemia criteria and a formal safety/risk process; breathlessness alone is not an indication. Smoking and household risks must be addressed through the appropriate specialist pathway."},{"step":"5. Make an exacerbation plan specific","detail":"Explain how to recognise a sustained change from the usual state and when to seek help. Rescue medicines are for appropriate patients who understand their use, with reporting and review; repeated courses need reassessment."},{"step":"6. Treat an actual exacerbation when indicated","detail":"Assess severity, differential diagnosis and setting. For appropriate COPD exacerbations requiring oral corticosteroids, NICE recommends oral prednisolone 30 mg daily for 5 days, with suitability and existing therapy checked. Consider antibiotics using NG114, including sputum colour/volume/thickness changes, severity, complications and previous cultures; not every exacerbation needs them."},{"step":"7. Agree response and continuity checks","detail":"Confirm the actual inhaler and self-management instructions, arrange review of any change and consider specialist input for persistent symptoms, diagnostic uncertainty or complex oxygen/exacerbation needs. Give an annual or clinically appropriate more frequent review plan."}],"discussion":[{"cue":"Would oxygen make walking easier?","response":"We should check why you are breathless and whether your blood oxygen is low. Oxygen helps in particular circumstances and needs a proper assessment and safety plan. We can also look at treatments and rehabilitation that may help your day-to-day activity.","why":"Validate the goal while explaining why oxygen is not prescribed from the symptom alone.","id":"rs-copd-talk-1","simple":"We need to check the cause of breathlessness and your oxygen level before deciding on oxygen. Let’s discuss suitable treatment and rehabilitation too."},{"cue":"There are too many inhalers.","response":"Could you show me what you actually use on a usual day? Let’s check what each one is for, whether the device suits you and how we can make a safe plan you can follow.","why":"Explore treatment burden and actual use before changing doses or devices.","id":"rs-copd-talk-2","simple":"Please show me what you use. Let’s check each inhaler and make the plan manageable."},{"cue":"I’ve used another rescue pack. Can I have a replacement?","response":"Let’s review what changed, what you took and whether you improved. Repeated courses can mean we need to reassess the cause and the prevention plan rather than only replace the pack.","why":"Make rescue-pack use visible and clinically reviewed.","id":"rs-copd-talk-3","simple":"Let’s review the flare, treatment and response before simply replacing another rescue pack."},{"cue":"Are you just going to tell me to stop smoking?","response":"Stopping can make an important difference, and we can offer practical treatment and support if you would like it. We will also assess and treat the breathing problems and discuss what matters to you now.","why":"Offer help without blame or making all other care conditional on cessation.","id":"rs-copd-talk-4","simple":"We can offer support to stop smoking if you would like it, and we will also assess and treat your breathing problems."},{"cue":"Exercise feels impossible.","response":"That is exactly the sort of difficulty a suitable rehabilitation programme can help us work on. Let’s discuss what it involves, whether it is appropriate for you and how you could attend.","why":"Describe structured rehabilitation rather than simply telling the person to exercise more.","id":"rs-copd-talk-5","simple":"A suitable rehabilitation programme can help with that difficulty. Let’s discuss the programme and how you could attend."}],"variations":[{"label":"Severe acute deterioration","change":"The person is now very breathless at rest, confused, cyanosed or otherwise seriously unwell.","action":"Arrange emergency assessment and appropriate acute treatment/oxygen management through the clinical pathway. Do not assume a routine COPD flare or issue only a rescue pack.","phrase":"The change in your breathing needs emergency assessment now. I will help arrange it and pass on your usual treatment and what has changed."},{"label":"Repeated antibiotics without a clear review","change":"Several packs have been used for any increase in cough, without documenting sputum change, response or complications.","action":"Reassess the episode and diagnosis, antibiotic indication, cultures where appropriate and prevention. Check for other causes and harms of repeated treatment, and agree when/how to use future rescue medicines.","phrase":"Let’s go through what happened with each course and make the instructions clearer, so treatment matches the change in your symptoms."},{"label":"Breathlessness with acceptable oxygen levels","change":"The person is stable and oxygen assessment does not show an indication for home oxygen.","action":"Explain the result and address other treatable contributors, inhalers, rehabilitation, anxiety/function and specialist needs. Do not give oxygen solely because the person remains breathless.","phrase":"The oxygen result helps us choose the treatment. Let’s focus on the other things that can improve your breathing and daily activity."}],"pitfalls":["Do not diagnose COPD from smoking alone or attribute new chest pain, haemoptysis, weight loss or sudden breathlessness to established COPD without assessment.","Do not assume asthma and COPD use identical inhaler pathways or that every person with COPD needs an inhaled steroid.","Do not prescribe home oxygen for breathlessness alone or use repeated oral steroids/antibiotics as routine stable management without reviewing indications and harms."],"safetyNet":["Severe or rapidly worsening breathlessness, difficulty speaking, confusion, blue/grey colour, collapse or other serious acute symptoms require emergency help.","For a sustained increase in usual symptoms, follow the individual action plan and seek clinical advice according to severity; do not wait through deterioration because a rescue pack has been started.","Report rescue-pack courses and any treatment failure, significant adverse effect or inability to use the prescribed device through the named clinical team."],"followUp":"Arrange an early clinically appropriate review after exacerbation or treatment change, checking recovery and prevention needs. In stable care review symptoms, function, attacks, technique, actual use, smoking support and comorbidities at least annually, or more often when clinically indicated.","reviewed":"2026-11-12","tags":["COPD","breathlessness","oxygen","rescue pack","pulmonary rehabilitation","inhalers"],"links":[{"label":"NICE NG115: COPD diagnosis and management","url":"https://www.nice.org.uk/guidance/ng115","use":"Assessment, stable management, oxygen, rehabilitation and exacerbations."},{"label":"NICE NG114: antibiotics for COPD exacerbations","url":"https://www.nice.org.uk/guidance/ng114","use":"Antibiotic decision-making and current prescribing tables."},{"label":"NHS: COPD","url":"https://www.nhs.uk/conditions/chronic-obstructive-pulmonary-disease-copd/","use":"Patient explanation and treatment overview."}],"retrieval":{"question":"How would you respond to a request for oxygen and another rescue pack without making either the automatic answer to breathlessness?","answer":"Assess current severity and possible alternative causes, review actual inhalers and recent courses, and explain that oxygen needs formal hypoxaemia/safety assessment. Agree appropriate treatment, prevention, rehabilitation and a clear exacerbation/review plan.","checks":["Assessed stability and possible additional diagnoses","Explained oxygen and rescue-treatment decisions accurately","Addressed the person’s goal, practical use and follow-up"]}}]},{"id":"endocrine-metabolic","title":"Endocrine & metabolic","description":"Current type 2 diabetes treatment discussions, underactive-thyroid care and possible type 1/DKA recognition, each with three changed circumstances.","icon":"06","reviewed":"2026-11-12","cases":[{"id":"em-type2-diabetes","title":"New type 2 diabetes: explain the diagnosis and current treatment choices","summary":"Connect confirmation, the 2026 medicine pathway, self-management and ongoing checks in a practical plan.","presentation":"A 57-year-old has diabetes confirmed after repeat testing and appropriate clinical assessment. There are no acute hyperglycaemic symptoms and no relevant cardiovascular/renal comorbidity or significant frailty identified in this example. The person feels blamed and asks whether one tablet is the whole treatment.","assessment":["Confirm the diagnostic evidence and clinical classification; review symptoms, speed of onset, weight change and possible type 1 or secondary diabetes rather than decide type from age or BMI alone.","Assess current illness and features of ketosis/DKA or marked symptomatic hyperglycaemia; an acute picture changes treatment and urgency.","Assess cardiovascular and renal status, frailty, current medicines, interactions, weight/nutrition, symptoms of complications and other comorbidities before selecting a treatment pathway.","Explore the person’s understanding, concerns, daily routine, health literacy, access and goals; establish baseline checks and structured education/support needs."],"priorities":["Separate a stable confirmed type 2 diagnosis from an insulin-deficient or acutely unwell presentation.","Use current NG28 and an individual plan, including the 2026 medicine changes and comorbidity-specific pathways."],"management":[{"step":"1. Explain the diagnosis without blame","detail":"Use the actual test/clinical findings, acknowledge the effect of the diagnosis and explain the plan for glucose, broader health and prevention. Offer structured diabetes education and appropriate ongoing support."},{"step":"2. Select the correct current pathway","detail":"The current NG28 summary recommends modified-release metformin and an SGLT-2 inhibitor for adults with no relevant comorbidities, with different details for other groups. Assess renal/cardiovascular disease, obesity, early-onset disease and frailty and use the appropriate current table, licensing and local implementation."},{"step":"3. Introduce medicines safely","detail":"The current visual summary advises starting medicines sequentially, not simultaneously, and moving through treatment after confirming the maximum tolerable current dose. Choose the actual agent/dose with renal function, contraindications, interactions and patient preferences checked; do not interpret a combination recommendation as an automatic same-day double prescription."},{"step":"4. Explain benefits and harms clearly","detail":"Discuss what each medicine aims to achieve, relevant adverse effects and what to do if problems occur. With SGLT-2 inhibitors discuss dehydration/genital-infection concerns, ketoacidosis risk, appropriate sick-day guidance and when to seek help; risks and suitability are individual."},{"step":"5. Agree achievable self-management and targets","detail":"Discuss food, activity, weight goals and support in the person’s circumstances. Agree an individual glycaemic target and monitoring plan rather than a universal target or a promise of rapid normalisation. Include BP, lipid, kidney, foot and eye assessment through the relevant pathways."},{"step":"6. Make monitoring and sick-day advice concrete","detail":"Write down the introduction/titration plan, safety checks, who reviews results and when to seek help. Use an individual sick-day plan: acute illness, dehydration or surgery can change medicines and monitoring. Suspected DKA on an SGLT-2 inhibitor needs urgent assessment even without very high glucose."}],"discussion":[{"cue":"Have I caused this?","response":"This result is not a judgement about you. Several factors can contribute. Let’s focus on what the results mean for your health and the steps we can take together.","why":"Reduce shame and make the next actions understandable.","id":"em-type2-diabetes-talk-1","simple":"This is not a judgement about you. Let’s focus on what the result means and the next helpful steps."},{"cue":"Is the treatment just one tablet?","response":"We will choose the plan that fits your health and the current guidance. It often includes more than one medicine working in different ways, alongside practical support and checks. We introduce treatment carefully and review how you are getting on.","why":"Explain the current individual plan without using an outdated universal sequence or promising a fixed regimen.","id":"em-type2-diabetes-talk-2","simple":"Treatment may include more than one medicine. We will choose and introduce the plan carefully for your health."},{"cue":"Why start medicines one at a time?","response":"Introducing them in sequence helps us check how you manage each one, adjust the dose safely and understand any side effects. I will write down when the next step and review should happen.","why":"Turn the sequencing instruction into a practical schedule with ownership.","id":"em-type2-diabetes-talk-3","simple":"Starting in sequence helps us check each medicine and side effect. Let’s agree the actual schedule and review."},{"cue":"How will I know whether a side effect is serious?","response":"We will go through the warnings for the actual medicines. If you develop vomiting, abdominal pain, unusual sleepiness or deep breathing, seek urgent emergency assessment rather than assume it is a normal tablet side effect.","why":"Name relevant urgent symptoms and avoid false reassurance about DKA.","id":"em-type2-diabetes-talk-4","simple":"We will discuss your actual medicine warnings. Vomiting, abdominal pain, deep breathing or unusual sleepiness needs emergency assessment."},{"cue":"I work shifts and eat at different times.","response":"Let’s look at a typical working day and choose instructions you can follow safely. We can also discuss support with meals, activity and attending checks, rather than give you a plan that does not fit your life.","why":"Link treatment to the person’s circumstances and feasible support.","id":"em-type2-diabetes-talk-5","simple":"Let’s make the treatment and checks fit your actual shifts, meals and support needs."},{"cue":"Do two medicines mean I have failed?","response":"The choice considers your health and what each medicine can help with, not a judgement about your effort. We will explain why the recommended plan fits you and introduce it with the right support and checks.","why":"Address shame and explain the reason for the actual individual recommendation.","id":"em-type2-diabetes-talk-6","simple":"The number of medicines is not a judgement about effort. Let’s explain why the plan fits your health."}],"variations":[{"label":"Rapid symptoms or possible insulin deficiency","change":"The person has rapid weight loss, thirst, frequent urination and becomes unwell or ketotic.","action":"Reassess classification and urgency; possible type 1/insulin deficiency and DKA need appropriate same-day specialist or emergency assessment. Do not simply add routine type 2 tablets or wait for HbA1c/antibody confirmation.","phrase":"The speed of this change means we need a different assessment today. If you are unwell or have ketones, we need urgent hospital help."},{"label":"Kidney disease changes eligibility","change":"Renal assessment shows significant CKD, including a level where metformin is contraindicated.","action":"Use NG28’s current eGFR-specific pathway and the actual agent’s licence/dose criteria; the no-comorbidity plan cannot simply be copied. Seek appropriate renal/diabetes input where needed.","phrase":"Your kidney result changes which medicines and doses are suitable. Let’s choose the plan using that information."},{"label":"Frailty, dizziness and treatment burden","change":"A frail person has postural symptoms, multiple medicines and risk of adverse events.","action":"Use the frailty pathway, individualise targets and minimise burden. An SGLT-2 inhibitor is not automatic if frailty places the person at adverse-event risk; check the current alternatives and shared priorities.","phrase":"We need a plan that helps you while keeping you steady and making the medicine routine manageable."}],"pitfalls":["Do not use an old universal “metformin alone first for everyone” rule without checking the current NG28 pathway.","Do not assume all age/BMI patterns imply type 2 disease or delay assessment of ketosis, weight loss or acute illness.","Do not start medicines simultaneously merely because both appear in the initial recommendation, or ignore renal function, frailty and sick-day education."],"safetyNet":["Vomiting, abdominal pain, deep breathing, drowsiness or confusion with possible diabetes requires urgent assessment; severe illness or suspected DKA needs emergency hospital care.","SGLT-2-associated DKA may occur with near-normal glucose. If DKA is suspected, stop the SGLT-2 inhibitor and obtain urgent medical assessment. After DKA, do not restart an SGLT-2 inhibitor unless another cause has been identified and resolved and appropriate clinical review supports restarting.","Agree whom to contact for intolerance, dehydration, inability to eat/drink or a missed monitoring/review arrangement; provide clear medicine-specific advice."],"followUp":"Book medicine-introduction/tolerance and safety reviews and a named review of glycaemic and broader health targets. Continue structured diabetes reviews, education and complication checks, with earlier reassessment if symptoms, risks or treatment suitability change.","reviewed":"2026-11-12","tags":["type 2 diabetes","metformin","SGLT2","2026 guidance","shared decisions","sick day rules"],"links":[{"label":"NICE NG28: type 2 diabetes management","url":"https://www.nice.org.uk/guidance/ng28","use":"Current treatment, individualisation and review recommendations."},{"label":"NICE: current diabetes medicine visual summary","url":"https://www.nice.org.uk/guidance/ng28/resources/visual-summary-choosing-reviewing-and-changing-medicines-pdf-10956472093","use":"Current initial and further medicine pathways, including the September 2026 clarification."},{"label":"MHRA: SGLT2 inhibitors and ketoacidosis","url":"https://www.gov.uk/drug-safety-update/sglt2-inhibitors-updated-advice-on-the-risk-of-diabetic-ketoacidosis","use":"Recognising DKA, including cases without marked hyperglycaemia."},{"label":"NHS: type 2 diabetes","url":"https://www.nhs.uk/conditions/type-2-diabetes/","use":"Plain-language diagnosis and ongoing care information."}],"retrieval":{"question":"How would you explain the current initial plan and why CKD, frailty or acute symptoms could change it?","answer":"Use the current NG28 subgroup pathway, explain the role of the medicines and sequential introduction, and agree support and monitoring. Renal disease and frailty change suitability; possible insulin deficiency or DKA changes urgency and may replace routine oral treatment with an urgent specialist/emergency pathway.","checks":["Used the current subgroup pathway","Explained sequencing and patient-specific safety","Recognised an acute or classification-changing presentation"]}},{"id":"em-hypothyroidism","title":"Underactive thyroid: treatment, taking the tablet and follow-up","summary":"Distinguish overt from subclinical disease and agree replacement treatment and monitoring that fits the person.","presentation":"An adult reports fatigue, cold intolerance and constipation. Thyroid tests show raised TSH with FT4 below the laboratory reference range, and the clinical assessment supports primary hypothyroidism. They ask whether they need lifelong treatment and how the tablet fits with other medicines.","assessment":["Interpret TSH and FT4 in the clinical context, including medicines, supplements/biotin, recent illness and possible pituitary disease when relevant.","Assess symptom severity, other causes of fatigue, age, body weight, cardiovascular history and current medicines before choosing a starting dose.","Ask about pregnancy or plans for pregnancy where relevant, and consider autoimmune context and other appropriate investigations.","Explore the person’s expectations, usual meal/medicine routine, practical barriers and concerns about long-term treatment."],"priorities":["Confirm the actual biochemical and clinical pattern instead of treating fatigue alone or a single mildly raised TSH as overt disease.","Choose replacement and monitoring safely, with a different approach for older people, cardiovascular disease and pregnancy."],"management":[{"step":"1. Explain and agree treatment","detail":"Levothyroxine is the usual first-line replacement for primary hypothyroidism. Explain what it replaces and expected gradual improvement. Do not routinely offer liothyronine or natural thyroid extract as a superior standard option."},{"step":"2. Choose a clinically appropriate initial dose","detail":"NG145 considers 1.6 micrograms/kg/day, rounded to the nearest 25 micrograms, for adults under 65 with no cardiovascular disease. For adults 65 or over, or with cardiovascular disease, consider 25–50 micrograms/day with titration. Check the actual prescription, product and patient circumstances; these are not universal doses."},{"step":"3. Teach the actual administration routine","detail":"Use the prescribed product instructions. Current NHS advice describes taking it on an empty stomach 30–60 minutes before the first meal, caffeine or other medicine. Check interacting medicines/supplements and required separation with the pharmacist, and agree a sustainable consistent routine."},{"step":"4. Arrange monitoring rather than guess from symptoms alone","detail":"NICE considers TSH every 3 months until stable (two similar in-range results 3 months apart), then annually. Arrange appropriate checks after changes and consider FT4 if needed for persistent symptoms; avoid excessive replacement or repeated premature adjustments."},{"step":"5. Reassess context and continuing symptoms","detail":"If symptoms persist, review actual use, interactions, results and alternative causes rather than automatically increase the dose. Pregnancy/planning pregnancy needs its own timely review and monitoring pathway."},{"step":"6. Close prescription and results ownership","detail":"Confirm the daily dose in micrograms, repeat-prescription arrangements, test/review dates, who reviews results and what to do for adverse symptoms or practical problems."}],"discussion":[{"cue":"What does an underactive thyroid mean?","response":"The thyroid is making less hormone than your body needs. Levothyroxine replaces that hormone. We use your symptoms and blood tests to find a suitable dose.","why":"Explain replacement before giving a medicine name alone.","id":"em-hypothyroidism-talk-1","simple":"Levothyroxine replaces thyroid hormone that is lacking. Symptoms and blood tests guide the dose."},{"cue":"Will I feel normal tomorrow?","response":"Improvement is usually gradual, and we need follow-up to check the dose and how you are feeling. If symptoms continue, we will review the results, how the medicine is taken and other possible causes.","why":"Set a realistic expectation without promising a fixed recovery time.","id":"em-hypothyroidism-talk-2","simple":"Improvement takes time. We will review symptoms, results, medicine use and other causes if problems continue."},{"cue":"Can I take it with breakfast and my other tablets?","response":"Let’s go through your usual morning. It is taken on an empty stomach before food or caffeine, and some other medicines need separation. I will give you the instructions for your actual prescription and check the other tablets with you.","why":"Make administration workable and avoid an unreviewed instruction to take every medicine together.","id":"em-hypothyroidism-talk-3","simple":"Take it on an empty stomach, following your prescription instructions. Let’s check how it fits with food, coffee and your other tablets."},{"cue":"Would a higher dose give me more energy?","response":"Too much replacement can cause problems such as palpitations. We should adjust it using the assessment and blood results, rather than keep increasing it whenever you feel tired.","why":"Explain why monitoring matters without dismissing ongoing symptoms.","id":"em-hypothyroidism-talk-4","simple":"Too much replacement can cause harm. We should review the results and symptoms rather than simply increase it for tiredness."},{"cue":"What if I become pregnant?","response":"Please contact us promptly so we can review the dose and arrange the right blood-test and pregnancy support plan. Thyroid treatment and monitoring often need to change in pregnancy.","why":"Make the need for early review explicit without giving a generic pregnancy dose.","id":"em-hypothyroidism-talk-5","simple":"Please contact us promptly in pregnancy so we can review the dose, blood tests and support."},{"cue":"Will I need it for life?","response":"That depends on the cause. Many people need long-term replacement, and we will explain what is likely in your case and review the blood results and treatment. Please discuss any wish to change or stop it with us so we can make a safe plan.","why":"Answer the original long-term-treatment concern without promising a fixed duration.","id":"em-hypothyroidism-talk-6","simple":"Many people need long-term replacement, but the cause matters. Let’s discuss your plan before changing or stopping it."}],"variations":[{"label":"Subclinical rather than overt disease","change":"TSH is mildly raised but FT4 is normal.","action":"Do not copy the overt-hypothyroidism plan automatically. Follow NG145’s repeat-testing and treatment-consideration criteria, including age, symptoms and persistence; discuss uncertainty and an appropriate review.","phrase":"This is a different blood-test pattern. Let’s confirm how persistent it is and discuss whether treatment or monitoring is the right next step."},{"label":"Pregnancy or pregnancy planning","change":"The person becomes pregnant or is planning pregnancy.","action":"Arrange timely thyroid/pregnancy review, dose assessment and closer monitoring through the appropriate pathway. Do not leave the usual annual review unchanged or stop prescribed replacement without clinical advice.","phrase":"This changes the monitoring and may change the dose. Let’s arrange the appropriate review promptly."},{"label":"Palpitations after a dose change","change":"The person develops palpitations or other possible over-replacement symptoms.","action":"Assess severity, dose/actual use, interactions and thyroid/cardiac findings. Acute chest pain, collapse or serious illness needs urgent/emergency assessment; do not assume every symptom is a harmless adjustment effect.","phrase":"We should check the new symptoms and the actual dose rather than assume they are expected. If there are serious symptoms, we need urgent assessment."}],"pitfalls":["Do not confuse micrograms and milligrams, or use the young/no-cardiovascular-disease dose in every older/cardiac patient.","Do not ignore interactions, administration routine, biotin/assay context or other causes of continuing symptoms.","Do not treat pregnancy, possible central thyroid disease or severe illness as a routine unchanged primary-hypothyroidism follow-up."],"safetyNet":["Acute chest pain, collapse, severe breathlessness or serious new illness needs urgent/emergency assessment, including when it follows a medicine change.","Report persistent palpitations, marked tremor, treatment intolerance or inability to follow the prescription for clinician review.","Contact the team promptly for pregnancy/planning pregnancy, an unresolved prescription or missed monitoring so the plan can be adjusted."],"followUp":"Confirm the actual initial and titration prescription and review arrangements. Use appropriate TSH monitoring until stable, then at least annual review, with earlier reassessment for symptoms, dose changes, interactions or pregnancy.","reviewed":"2026-11-12","tags":["hypothyroidism","thyroid","levothyroxine","TSH","FT4","medicine timing"],"links":[{"label":"NICE NG145: thyroid disease","url":"https://www.nice.org.uk/guidance/ng145","use":"Testing, primary/subclinical hypothyroidism, replacement and monitoring."},{"label":"NHS: underactive thyroid","url":"https://www.nhs.uk/conditions/underactive-thyroid-hypothyroidism/","use":"Patient explanation and pregnancy considerations."},{"label":"NHS: levothyroxine","url":"https://www.nhs.uk/medicines/levothyroxine/","use":"Current administration instructions and medicine information."}],"retrieval":{"question":"How would you explain the tablet routine and why an older person with heart disease needs a different starting approach?","answer":"Explain hormone replacement, verify the exact dose/product and agree a consistent empty-stomach routine with interactions checked. Older age/cardiovascular disease changes starting-dose and titration considerations; blood results and clinical review guide adjustment.","checks":["Explained replacement and practical administration","Recognised the patient-specific starting approach","Specified monitoring and earlier-review triggers"]}},{"id":"em-new-type1","title":"Thirst, weight loss and vomiting: possible type 1 diabetes or DKA","summary":"Recognise insulin deficiency and acute danger, explain urgency and arrange a real same-day/emergency handover.","presentation":"A 28-year-old reports several weeks of thirst, frequent urination and weight loss, followed by vomiting, abdominal pain and deep breathing. They have not been diagnosed with diabetes. The current symptoms raise concern for an acute metabolic emergency.","assessment":["Assess immediate illness, responsiveness, breathing, circulation/dehydration and other acute symptoms. Confirm location and a callback route for a remote consultation.","Obtain appropriate immediate glucose and ketone assessment if feasible without delaying emergency care; hospital assessment establishes the biochemical diagnosis and treatment needs.","Clarify the symptom course, weight change, current/previous diabetes treatment, medicines including SGLT-2 inhibitors, intercurrent illness and relevant history while arranging the appropriate help.","Consider insulin deficiency regardless of age or BMI, other causes of hyperglycaemia/illness and the person’s ability to access urgent care safely."],"priorities":["The supplied vomiting, abdominal pain and deep breathing with diabetic symptoms needs emergency hospital assessment.","Do not wait for routine fasting tests, HbA1c, autoantibodies or an outpatient review before acting."],"management":[{"step":"1. Arrange emergency care for suspected DKA","detail":"Use the emergency pathway for the current unwell presentation. Confirm location, safe transport and an accepted handover. DKA is potentially life-threatening and requires urgent hospital treatment and monitoring."},{"step":"2. Use immediate tests without creating delay","detail":"Check glucose/ketones when available and appropriate, but do not delay escalation for testing. A less striking glucose result does not exclude DKA in relevant settings, including SGLT-2 inhibitor use."},{"step":"3. Avoid a routine type 2 prescription pathway","detail":"Do not rely on age/body size to exclude type 1 diabetes or start a routine oral-treatment trial in place of assessing insulin deficiency. Classification and specialist treatment should be coordinated through the urgent diabetes pathway."},{"step":"4. Match a stable suspected-type-1 scenario to urgent specialist care","detail":"If a person is clinically well without acute-DKA features but type 1 diabetes is suspected, arrange urgent specialist assessment, usually the same day under the relevant service. Confirm the actual arrangement and a safe alternative if that route cannot respond."},{"step":"5. Explain what will happen and address barriers","detail":"Explain that urgent care is needed to assess glucose/ketones, fluid balance and treatment. Resolve transport, caring responsibilities and communication support where possible; do not leave the person waiting alone with an unconfirmed referral."},{"step":"6. Reconnect after the acute episode","detail":"Check the confirmed diagnosis, treatment and discharge plan. Coordinate specialist diabetes education, insulin/monitoring support when relevant, sick-day advice, supply, follow-up and the person’s concerns."}],"discussion":[{"cue":"Can I just do the blood test tomorrow?","response":"The thirst and weight loss, together with vomiting and deep breathing, make me concerned about a diabetes emergency. I recommend hospital assessment now rather than waiting for tomorrow’s test. I will help arrange it.","why":"Connect symptoms with the action without pretending a remote assessment confirms the full diagnosis.","id":"em-new-type1-talk-1","simple":"This could be a diabetes emergency. We need hospital assessment now, not tomorrow’s test."},{"cue":"Why would this make me sick?","response":"If the body does not have enough insulin, chemicals called ketones can build up and make someone seriously unwell. We need urgent tests and treatment to check what is happening and correct it safely.","why":"Use a simple mechanism to support the urgency, not a long biochemical lecture.","id":"em-new-type1-talk-2","simple":"Without enough insulin, ketones can build up and cause serious illness. We need urgent tests and treatment."},{"cue":"I’m too old for type 1, aren’t I?","response":"Type 1 diabetes can develop in adults. Age alone does not tell us which type this is. Your current symptoms and assessment are what determine the next step.","why":"Correct a common misconception without diagnosing solely from age or symptoms.","id":"em-new-type1-talk-3","simple":"Type 1 can develop in adults. The current symptoms and assessment determine what we do next."},{"cue":"The glucose number is not as high as I expected.","response":"The number is only part of the picture. Some diabetes emergencies can occur without a very high glucose reading, especially with certain medicines. We need to assess the symptoms and ketones appropriately.","why":"Avoid reassurance from one measurement when the clinical picture is concerning.","id":"em-new-type1-talk-4","simple":"A glucose number alone does not rule out an emergency. We need the symptoms and appropriate ketone assessment."},{"cue":"I’m frightened of what happens after hospital.","response":"That is understandable. First we need to make you safe and establish the diagnosis. Then the diabetes team and your practice can explain treatment, show you how to use it and agree support and follow-up.","why":"Acknowledge fear and sequence immediate care and longer-term learning.","id":"em-new-type1-talk-5","simple":"First we need to make you safe and establish the diagnosis. Then we will arrange treatment teaching and follow-up support."}],"variations":[{"label":"Clinically well but suspected type 1","change":"The person has new diabetic symptoms but no vomiting, deep breathing or other acute illness after assessment.","action":"Arrange urgent specialist assessment, usually the same day, through the appropriate diabetes pathway. Do not defer to a routine later appointment or await all classification tests before arranging care.","phrase":"You do not have the emergency features we checked for now, but this still needs urgent diabetes assessment today. Let’s confirm that arrangement."},{"label":"SGLT-2 inhibitor and modest glucose","change":"An adult taking an SGLT-2 inhibitor is unwell with DKA symptoms despite a glucose reading that is not markedly high.","action":"Assess for DKA urgently, including blood ketones where appropriate, and obtain emergency care when indicated. Stop the SGLT-2 inhibitor if DKA is suspected and follow MHRA/specialist guidance on subsequent treatment; do not simply restart after symptoms settle.","phrase":"This medicine can be associated with ketoacidosis even without very high glucose. We need urgent assessment rather than reassurance from that number."},{"label":"Different scenario: known type 1 during illness","change":"Someone already treated with insulin stops taking it because they are vomiting and not eating.","action":"Assess glucose, ketones, hydration and current danger urgently. Use the individual sick-day/diabetes-team plan; do not advise unsupported cessation of basal insulin. DKA symptoms or significant clinical deterioration require emergency care.","phrase":"Illness can change how much insulin and monitoring you need. Let’s get urgent advice and assess for ketones rather than stop the usual plan without support."}],"pitfalls":["Do not exclude type 1 diabetes from age or BMI, or attribute weight loss and thirst to lifestyle without assessing diabetes.","Do not delay emergency care while waiting for HbA1c or reassure from a near-normal glucose result in someone with possible DKA.","Do not issue a generic insulin correction dose or advise stopping insulin from an incomplete remote assessment."],"safetyNet":["For the supplied acutely unwell presentation, act now through emergency care; a future warning list is not a substitute for escalation.","If a clinically well person is awaiting the confirmed same-day specialist arrangement, vomiting, abdominal pain, deep breathing, drowsiness, confusion or deterioration requires immediate reassessment/emergency help.","Give a clear callback/contact plan if the call disconnects or the receiving service cannot respond; make sure a handover is accepted."],"followUp":"Confirm arrival/acceptance through the appropriate handover process. After acute care, reconcile the diagnosis and medicine/monitoring plan, ensure access to supplies and structured education and agree practice/specialist follow-up.","reviewed":"2026-11-12","tags":["type 1 diabetes","DKA","ketones","thirst","weight loss","urgent referral"],"links":[{"label":"NICE NG17: type 1 diabetes in adults","url":"https://www.nice.org.uk/guidance/ng17","use":"Assessment, classification and ongoing specialist diabetes care."},{"label":"NHS: type 1 symptoms and diagnosis","url":"https://www.nhs.uk/conditions/type-1-diabetes/symptoms/","use":"Urgent assessment and usual same-day specialist care."},{"label":"NHS: diabetic ketoacidosis","url":"https://www.nhs.uk/conditions/diabetic-ketoacidosis/","use":"Symptoms and emergency action."},{"label":"MHRA: SGLT2 and ketoacidosis","url":"https://www.gov.uk/drug-safety-update/sglt2-inhibitors-updated-advice-on-the-risk-of-diabetic-ketoacidosis","use":"Important near-normal-glucose presentations and medicine safety."}],"retrieval":{"question":"How does the plan differ between a clinically well person with suspected type 1 and someone with vomiting and deep breathing?","answer":"Suspected type 1 still needs urgent specialist assessment, usually the same day, with an actual confirmed route. Vomiting/deep breathing and possible DKA require emergency hospital assessment now. Testing and classification must not delay the appropriate care.","checks":["Matched setting/urgency to the current illness","Avoided waiting for routine or classification tests","Explained the reason and confirmed an accepted handover"]}}]},{"id":"gastrointestinal","title":"Gastrointestinal","description":"IBS-pattern symptoms, rectal bleeding/FIT and dyspepsia: assessment, test discussions and changed-risk pathways, each with three variations.","icon":"07","reviewed":"2026-11-12","cases":[{"id":"gi-ibs","title":"IBS-pattern symptoms: a positive explanation and an individual plan","summary":"Recognise the pattern, assess warning features and offer practical symptom-led care without dismissing the patient.","presentation":"A 29-year-old has eight months of intermittent abdominal pain associated with changes in stool pattern and bloating. Symptoms affect work and social life. Appropriate assessment and initial tests have not identified warning features or another cause in this ordinary scenario.","assessment":["Clarify the pain–stool relationship, duration, stool form/frequency, bloating, triggers, effect on life and the person’s explanation and concerns.","Assess for warning features and alternative diagnoses, including bleeding, weight loss, anaemia, inflammatory symptoms, masses and relevant family history. A new or changed pattern needs reassessment.","Use the appropriate examination and initial tests, including blood count, inflammatory markers and coeliac serology according to CG61. Interpret tests in the clinical context; coeliac testing needs an adequate gluten-containing diet during the diagnostic process.","When IBD versus IBS remains a relevant differential and specialist assessment is being considered, faecal calprotectin can support assessment if cancer is not suspected and a locally agreed pathway is in place (HTG320). Interpret it in context; it is not a test to exclude bowel cancer.","Review medicines, actual diet and any exclusions, nutrition, mental health/context and constipation/diarrhoea predominance without attributing all symptoms to stress."],"priorities":["Make an assessment-led positive explanation rather than label unexplained symptoms automatically as IBS.","Keep warning symptoms visible and avoid restrictive advice or unnecessary testing that does not answer the clinical question."],"management":[{"step":"1. Explain the working diagnosis","detail":"Relate the typical symptom pattern and assessed findings to IBS. Explain that symptoms are real and that gut sensitivity/function can contribute; do not imply the person is imagining them or guarantee that future symptoms need no assessment."},{"step":"2. Agree a small practical starting plan","detail":"Discuss regular meals, suitable fluids, activity and symptom/food patterns. Review fibre type and tolerance rather than simply advise unlimited bran. Identify what is most disruptive and agree a feasible first step."},{"step":"3. Tailor symptom treatment","detail":"Consider appropriate antispasmodic and constipation/diarrhoea options according to the pattern, contraindications and preferences. Avoid one drug for every phenotype; use the current prescribing reference and CG61."},{"step":"4. Use dietary expertise appropriately","detail":"If general advice is insufficient, consider further dietary management, including low-FODMAP/exclusion approaches, with a suitably trained professional. Avoid broad indefinite food restriction or starting a gluten-free diet before adequate coeliac assessment."},{"step":"5. Review persistent symptoms and next options","detail":"Check response, diagnosis, actual use and harms. For persistent symptoms consider the appropriate further treatment or specialist input; low-dose neuromodulator/psychological options require an explanation of purpose, suitability and review rather than imply the symptoms are psychiatric."},{"step":"6. Set a definite review and change plan","detail":"Agree what improvement would look like, a review date and specific earlier-help triggers. New warning features require investigation/referral rather than simply another IBS prescription."}],"discussion":[{"cue":"Are you saying it is all in my head?","response":"No. The pain and bowel changes are real. In IBS, the way the gut works and senses signals can contribute to symptoms. We can discuss treatments aimed at the symptoms that are affecting you most.","why":"Validate the experience and explain a mechanism without a false mind/body split.","simple":"No. The symptoms are real. We can discuss treatments for the pain and bowel changes that affect you most.","id":"gi-ibs-talk-1"},{"cue":"How can you diagnose it if there is no single test?","response":"We use the pattern of symptoms, examination and appropriate tests to check for other important causes. Your assessment fits the working diagnosis today, and we will review it if the pattern changes or new warning signs appear.","why":"Explain a positive clinical assessment and the limits of certainty.","simple":"The symptom pattern, examination and appropriate tests support the working diagnosis. We will review it if the pattern changes.","id":"gi-ibs-talk-2"},{"cue":"Should I stop eating lots of different foods?","response":"Let’s first look at what you eat and what seems to affect symptoms. If a more detailed dietary approach is needed, we can arrange appropriate advice so your diet stays balanced and the changes have a clear purpose.","why":"Avoid a poorly supported restrictive diet.","simple":"Let’s review your diet first. If detailed changes are needed, we can arrange suitable advice to keep your diet balanced.","id":"gi-ibs-talk-3"},{"cue":"Why would a medicine used for mood help bowel pain?","response":"Some medicines can affect how pain signals are processed and may be used at a low dose for that purpose. If we consider one, I will explain why, the possible side effects and how we would review it.","why":"Explain a possible treatment honestly without assuming the person has depression.","simple":"Some medicines affect pain signals and can help bowel pain at a low dose. We would discuss suitability, side effects and review.","id":"gi-ibs-talk-4"},{"cue":"What is the first thing I should change?","response":"Of the pain, bloating and bowel changes, which is getting in the way most? Let’s choose one practical treatment step, agree what you will try and review the effect before changing several things together.","why":"Reduce cognitive burden and make response to the plan interpretable.","simple":"Which symptom gets in the way most? Let’s choose one manageable step and review what it changes.","id":"gi-ibs-talk-5"}],"variations":[{"label":"New warning features","change":"Rectal bleeding, unexplained weight loss, anaemia or another concerning change develops.","action":"Reassess the diagnosis and follow the appropriate investigation/referral pathway. Do not attribute new warning findings to the previous IBS label.","phrase":"The new symptoms change what we need to check. We should reassess rather than assume this is the same problem."},{"label":"Diet becomes very restricted","change":"The person has removed multiple foods and is losing weight or struggling to eat adequately.","action":"Assess nutrition, weight change and the reason for restriction; reconsider other causes and arrange appropriate dietetic/clinical support. Avoid adding more exclusions without a safe plan.","phrase":"I’m concerned the current restrictions may be making it harder to stay well. Let’s review the symptoms and rebuild a safe, balanced plan with the right support."},{"label":"New IBS-type symptoms after age 50","change":"A person with female reproductive organs develops new IBS-type symptoms within the last 12 months at age 50 or over.","action":"Follow NG12’s appropriate ovarian-cancer assessment/testing pathway alongside the wider differential rather than assume a new functional-bowel diagnosis. Use the current age-/symptom-specific recommendations.","phrase":"The new pattern and your circumstances mean we should check other possible causes, including the relevant pelvic/ovarian pathway, rather than assume this is IBS."}],"pitfalls":["Do not dismiss symptoms as stress or diagnose IBS without considering warning features and appropriate initial assessment.","Do not use a previous IBS label or a single reassuring test to explain every new symptom.","Do not recommend a broadly restrictive or gluten-free diet without considering nutrition and the effect on coeliac testing."],"safetyNet":["New significant bleeding, black stools, persistent vomiting, severe/worsening pain, collapse or serious illness needs prompt urgent/emergency assessment according to severity.","New weight loss, anaemia, masses or an unexplained changed pattern requires reassessment and appropriate investigation/referral.","Agree when and who to contact if the trial fails or treatment causes problems; do not leave follow-up only as a vague “if worse”."],"followUp":"Review the specific symptom/function goals and treatment trial after an agreed interval. Further medicine options have their own safety/response reviews; new warning features prompt earlier investigation.","reviewed":"2026-11-12","tags":["IBS","abdominal pain","bloating","bowel change","diet","coeliac"],"links":[{"label":"NICE CG61: IBS in adults","url":"https://www.nice.org.uk/guidance/cg61","use":"Assessment, initial tests, diet and symptom-directed treatment."},{"label":"NICE NG20: coeliac disease","url":"https://www.nice.org.uk/guidance/ng20","use":"Appropriate testing and the effect of gluten exclusion."},{"label":"NHS: IBS","url":"https://www.nhs.uk/conditions/irritable-bowel-syndrome-ibs/","use":"Patient explanations and self-management information."},{"label":"NICE NG12: new and concerning symptom pathways","url":"https://www.nice.org.uk/guidance/ng12","use":"GI warning findings and the appropriate ovarian assessment for new IBS-type symptoms."},{"label":"NICE HTG320: faecal calprotectin","url":"https://www.nice.org.uk/guidance/htg320","use":"Conditional use to support the IBD/IBS differential when cancer is not suspected and an appropriate local pathway is in place."}],"retrieval":{"question":"How would you explain IBS as a real, assessment-led diagnosis and still make room for new warning symptoms?","answer":"Explain the typical pattern and assessed findings, validate the symptoms and choose a focused practical trial. Explicitly reassess bleeding, weight loss or a changed pattern rather than assume all future symptoms are IBS.","checks":["Used a positive, respectful explanation","Matched treatment to the person and symptom pattern","Specified new-warning and planned-review actions"]}},{"id":"gi-rectal-bleeding","title":"Rectal bleeding and bowel change: explain FIT and close the referral loop","summary":"Assess urgency, use the current symptomatic pathway and explain a test result without false reassurance.","presentation":"A 56-year-old reports several weeks of rectal bleeding and a changed bowel habit. They assume it is piles and mention a previous negative screening test. They are currently stable in this scenario but need appropriate assessment and the symptomatic investigation/referral pathway.","assessment":["Assess current bleeding volume, haemodynamic symptoms, severe pain or other acute illness; significant ongoing bleeding, collapse or instability changes urgency.","Clarify duration, bowel pattern, pain, weight loss, anaemia symptoms, family/personal history and relevant medicines, including anticoagulants.","Offer an appropriate abdominal and anorectal assessment, explaining purpose, consent, dignity and chaperone arrangements; a mass or other concerning finding changes the pathway.","Distinguish symptomatic FIT from previous screening and explore the person’s fears, sample-collection barriers and ability to attend investigations."],"priorities":["Do not diagnose the cause as haemorrhoids from a brief account or a history of piles alone.","Make investigation, results review, referral and non-returned samples explicit and owned."],"management":[{"step":"1. Choose the right urgency","detail":"Manage significant acute bleeding or instability through the urgent/emergency pathway. For stable persistent symptoms, use current NG12 and local symptomatic lower-GI guidance."},{"step":"2. Arrange appropriate examination and tests","detail":"Assess the actual findings and relevant blood tests. Offer quantitative FIT when indicated by the symptomatic pathway, even if screening was previously negative. A rectal mass, unexplained anal mass or anal ulceration does not need FIT before referral is considered."},{"step":"3. Act on the FIT in context","detail":"NICE recommends suspected-cancer-pathway referral for adults with FIT at least 10 micrograms haemoglobin per gram of faeces. A result below that threshold is not an automatic dismissal of ongoing unexplained symptoms or strong clinical concern."},{"step":"4. Explain the purpose and next steps","detail":"Explain that FIT detects small amounts of blood, not the cause by itself. Discuss why further assessment/referral is recommended and how uncertainty will be resolved; do not announce a cancer diagnosis from FIT alone."},{"step":"5. Support completion and ownership","detail":"Check sample instructions, practical/cultural/privacy needs and return arrangements. Name who checks the result and acts on it; follow up non-returned samples or unresolved concerns rather than assume lack of interest."},{"step":"6. Confirm the referral and review plan","detail":"Check the referral is sent/received and provide an agreed contact/backup plan if an appointment or result is not received. Persistent concern may require referral despite a low/absent FIT; safety netting does not replace that decision."}],"discussion":[{"cue":"It is probably just piles, isn’t it?","response":"That is one possible cause, but the bleeding and changed bowel habit need a proper assessment. I do not want to assume the explanation before we have checked the relevant findings and tests.","why":"Acknowledge a possibility without prematurely closing the diagnosis.","simple":"Piles are one possibility, but we need to assess the bleeding and bowel change rather than assume the cause.","id":"gi-rectal-bleeding-talk-1"},{"cue":"My screening test was negative. Why repeat it?","response":"Screening looked at risk when that sample was taken. New symptoms need their own assessment. The test and examination we arrange now help us decide what should happen next.","why":"Distinguish screening from the current symptomatic pathway.","simple":"New symptoms need their own assessment, even after a previous negative screening test.","id":"gi-rectal-bleeding-talk-2"},{"cue":"Does a positive FIT mean cancer?","response":"It means the test found blood at or above the level used for further investigation. It does not tell us the cause by itself. We should explain the result and arrange the appropriate next assessment.","why":"Explain “positive” without treating it as either good news or a confirmed diagnosis.","simple":"The test found blood at or above the investigation threshold. It does not tell us the cause; we need the next assessment.","id":"gi-rectal-bleeding-talk-3"},{"cue":"If the result is low, can I forget about the symptoms?","response":"A low result can be helpful, but it does not answer every question. If symptoms continue, change or remain concerning, we still need to review the whole picture and decide on further assessment.","why":"Avoid false reassurance and retain clinician responsibility.","simple":"A low result helps, but continuing or concerning symptoms still need review and possibly further assessment.","id":"gi-rectal-bleeding-talk-4"},{"cue":"I find collecting the sample embarrassing.","response":"Many people find it awkward. Could you tell me which part feels difficult? We can go through the practical steps and check what would make it manageable for you.","why":"Address the actual barrier without shame or assumptions.","simple":"Which part of collecting the sample is difficult? Let’s go through what would make it manageable.","id":"gi-rectal-bleeding-talk-5"}],"variations":[{"label":"FIT is at least 10","change":"The quantitative symptomatic FIT reaches the referral threshold.","action":"Arrange the suspected-cancer pathway, explain what the result does and does not establish, and confirm referral ownership and the contact plan.","phrase":"The result means we should arrange further assessment through the urgent pathway. It does not by itself tell us the diagnosis."},{"label":"FIT is low but concern persists","change":"Symptoms continue, or examination/history raises strong concern despite a result below threshold.","action":"Reassess and do not delay appropriate secondary-care referral when clinical concern remains. A low result does not negate a mass, persistent unexplained symptoms or another important finding.","phrase":"The test is one part of the assessment. Your continuing symptoms mean we still need to act on the wider picture."},{"label":"The sample is not returned","change":"The patient has not completed FIT because of unclear instructions, disability, language or embarrassment.","action":"Contact and clarify the barrier, support completion and assess ongoing urgency. If concern is strong, do not let the missing sample delay an appropriate referral.","phrase":"It sounds as though the test arrangements were difficult. Let’s work out what would help and make sure your symptoms are still being assessed safely."}],"pitfalls":["Do not treat a previous screening result, a low symptomatic FIT or an anticoagulant prescription as a complete explanation for persistent bleeding.","Do not wait for FIT before considering referral for a rectal/unexplained anal mass or ulceration.","Do not send a test or referral without named follow-up and a plan for non-return or missed communication."],"safetyNet":["Heavy ongoing bleeding, collapse, marked faintness, severe pain or serious acute illness needs urgent/emergency assessment.","Persistent or worsening unexplained symptoms need review even after a low FIT; do not simply close the case because the result is below threshold.","Agree when results and referral information should be available and how to contact the team if not; the practice remains responsible for checking significant unresolved findings."],"followUp":"Track sample completion, result review and referral/action. Confirm how the patient will receive information and what to do for deterioration or missed contact. Continue assessment of persistent concern until a clinically appropriate explanation and plan are established.","reviewed":"2026-11-12","tags":["rectal bleeding","FIT","bowel change","colorectal referral","results ownership"],"links":[{"label":"NICE NG12: suspected cancer","url":"https://www.nice.org.uk/guidance/ng12","use":"Current symptomatic lower-GI investigation and referral recommendations."},{"label":"NICE HTG690: FIT in primary care","url":"https://www.nice.org.uk/guidance/htg690","use":"Thresholds, referral and safety-netting principles."},{"label":"NHS: bleeding from the bottom","url":"https://www.nhs.uk/symptoms/bleeding-from-the-bottom-rectal-bleeding/","use":"Patient explanation and urgent symptom advice."}],"retrieval":{"question":"What would you say after a low FIT if symptoms or examination remain concerning?","answer":"Explain that the result is one part of the assessment, review the continuing findings and arrange the appropriate referral/investigation when concern remains. Do not let a low or unreturned FIT delay action on strong clinical concern.","checks":["Interpreted the result in the clinical context","Specified actual referral or reassessment","Retained results/referral ownership and a contingency"]}},{"id":"gi-dyspepsia","title":"Dyspepsia: explain testing, a treatment trial and changed symptoms","summary":"Assess warning features, choose a proportionate test/treatment sequence and give a review plan.","presentation":"A 36-year-old describes recurrent upper abdominal discomfort and reflux symptoms. Appropriate assessment has not identified alarm features in this ordinary scenario. They buy acid-suppressing medicine intermittently and ask whether they need a scope or antibiotics.","assessment":["Clarify the symptom pattern, duration, swallowing difficulty, vomiting, weight loss, bleeding/black stools, anaemia symptoms and other concerning findings; examine as appropriate.","Consider cardiac, biliary and other causes rather than label every upper abdominal/chest symptom as acid reflux.","Review medicines, including NSAIDs/aspirin and acid suppression, prior H pylori testing/treatment, allergies, previous antibiotics, alcohol/smoking and other relevant context.","Explore what the person thinks is causing symptoms, their concern about cancer/testing and the effect on eating, sleep and daily activities."],"priorities":["Separate uncomplicated dyspepsia from bleeding, obstruction, possible ACS or a suspected-cancer pathway.","Make the test/treatment sequence, result ownership and reassessment triggers clear."],"management":[{"step":"1. Choose urgency from the actual assessment","detail":"Acute serious illness, suspected GI bleeding or possible ACS needs appropriate urgent/emergency care. Use current NG12 criteria for concerning swallowing/weight-loss and other findings rather than a routine empirical trial when referral is indicated."},{"step":"2. Agree a proportionate initial strategy","detail":"For uncomplicated dyspepsia, discuss H pylori test-and-treat and/or an appropriate empirical full-dose PPI trial (CG184 describes 4 weeks), selecting the sequence based on the clinical context and previous treatment."},{"step":"3. Prepare testing correctly","detail":"For a breath or stool antigen H pylori test, leave the recommended 2-week PPI washout when safe and clinically appropriate. Check recent antibiotics and the actual laboratory/test preparation requirements. Agree symptom support and timing rather than give an unsupported stop instruction."},{"step":"4. Act on a positive result using an appropriate regimen","detail":"If eradication is indicated, choose the current appropriate regimen considering allergy, previous antibiotic exposure, interactions and local resistance/prescribing guidance. Explain the actual course, adherence, harms and what to do if treatment is not tolerated."},{"step":"5. Review response and ongoing need","detail":"Review after the planned trial/result. Check actual use and reconsider diagnosis if symptoms persist or change. If ongoing acid suppression is appropriate, agree the lowest effective/appropriate regimen and review its indication, including any required gastroprotection."},{"step":"6. Close tests, referral and safety loops","detail":"Name who reviews the test, when the person should hear and what happens if symptoms continue. Retesting/further assessment depends on the indication, response and guideline pathway; do not leave treatment repeating indefinitely without review."}],"discussion":[{"cue":"Does this mean I need an endoscopy?","response":"That depends on the symptoms, examination and any warning findings. Your assessment today allows us to discuss an initial test or treatment plan, but a change such as difficulty swallowing or concerning weight loss would change what we arrange.","why":"Explain why the decision is assessment-led and what would change it.","simple":"It depends on the assessment. New warning symptoms can change whether and how quickly further investigation is needed.","id":"gi-dyspepsia-talk-1"},{"cue":"What is the H pylori test looking for?","response":"It looks for a bacterium that can contribute to some stomach problems, including ulcers. A positive result helps us decide whether eradication treatment is appropriate; it is not a cancer diagnosis.","why":"Explain purpose and limits without overclaiming the cause of every symptom.","simple":"It looks for a bacterium linked to some stomach problems. A positive result is not a cancer diagnosis.","id":"gi-dyspepsia-talk-2"},{"cue":"Why do I need to pause the acid medicine for a test?","response":"It can affect how accurate the test is. We need the correct preparation period and a plan to manage symptoms safely while you prepare. Let’s check the instructions for the actual test and your other medicines.","why":"Make preparation practical and preserve clinical safety.","simple":"The medicine can affect the test. Let’s check the preparation and agree safe symptom support while you prepare.","id":"gi-dyspepsia-talk-3"},{"cue":"Can you give antibiotics now to be safe?","response":"Antibiotics help when there is an appropriate infection-related reason and the right regimen is selected. Let’s confirm the test and assessment plan rather than give a course that may not help and can cause side effects.","why":"Retain a clinically grounded decision while answering the request.","simple":"Antibiotics help for the right reason and with the right regimen. Let’s agree the assessment and test plan first.","id":"gi-dyspepsia-talk-4"},{"cue":"Will I be taking acid tablets forever?","response":"We’ll review how the planned course works and whether you still need treatment. Some people need ongoing medicine for a clear reason, and some can reduce it. We will decide from your response, risks and other medicines.","why":"Avoid promising either indefinite treatment or automatic stopping.","simple":"We will review the response and whether treatment is still needed. Any longer-term plan needs a clear reason.","id":"gi-dyspepsia-talk-5"}],"variations":[{"label":"Alarm features develop","change":"The person develops dysphagia, concerning weight loss, bleeding or another significant change.","action":"Reassess urgency and use the appropriate NG12/acute pathway. Do not simply increase the PPI or repeat antibiotics while delaying needed investigation.","phrase":"The new symptom changes what we need to check. We should arrange the appropriate assessment rather than only adjust the acid medicine."},{"label":"Test performed without adequate preparation","change":"A breath/stool test was taken during PPI use or too soon after a medicine that can affect the result.","action":"Interpret the result with the actual test conditions and arrange the correct preparation/retest plan when needed, keeping clinical warning features and urgency separate.","phrase":"The medicine can affect this result. Let’s check how the sample was taken and agree the correct next step."},{"label":"Symptoms persist after a reasonable initial trial","change":"There is incomplete response despite appropriate actual use and no new emergency feature.","action":"Review the diagnosis, treatment use, previous H pylori pathway and other causes; consider further investigation/referral according to guidance. Do not continue indefinite empirical escalation without reassessment.","phrase":"Let’s review what changed during the trial and whether we need a different explanation or investigation."}],"pitfalls":["Do not use an empirical PPI trial to delay action on dysphagia, bleeding, concerning weight loss or possible cardiac symptoms.","Do not interpret H pylori testing without the relevant medicine preparation or prescribe a universal eradication regimen regardless of allergy/exposure.","Do not stop a clinically needed protective medicine or continue long-term acid suppression without reviewing the actual indication."],"safetyNet":["Vomiting blood, black/tarry stools with illness, collapse, severe/worsening pain or possible cardiac symptoms needs appropriate urgent/emergency assessment.","New swallowing difficulty, unintentional weight loss, persistent vomiting or another significant change requires prompt reassessment and the relevant investigation/referral pathway.","Agree a definite result/treatment review and how to contact the team for intolerance, preparation problems or treatment failure."],"followUp":"Book review of the initial treatment/test and confirm ownership of results. Reassess persistent or changed symptoms and the ongoing medicine indication; arrange retesting/investigation/referral where indicated rather than leave open-ended repeats.","reviewed":"2026-11-12","tags":["dyspepsia","reflux","H pylori","PPI","endoscopy","test preparation"],"links":[{"label":"NICE CG184: dyspepsia and reflux","url":"https://www.nice.org.uk/guidance/cg184","use":"Initial strategies, H pylori testing/treatment and review."},{"label":"NICE NG12: suspected cancer","url":"https://www.nice.org.uk/guidance/ng12","use":"Current upper-GI alarm/referral criteria."},{"label":"NHS: indigestion","url":"https://www.nhs.uk/conditions/indigestion/","use":"Patient explanation and concerning symptoms."}],"retrieval":{"question":"How would you explain the H pylori test and PPI preparation while making it clear that warning symptoms change the plan?","answer":"Explain the bacterium/test purpose, check current medicines and arrange safe preparation with symptom support. Assess warning features separately and act through the appropriate acute/cancer pathway rather than wait for a routine test or empirical treatment response.","checks":["Explained test purpose and preparation","Kept urgent/referral findings separate","Named results/treatment review and a contingency"]}}]},{"id":"musculoskeletal","title":"Musculoskeletal","description":"Back pain/sciatica, gout and knee osteoarthritis: risk assessment, treatment explanations, function and changed circumstances, each with three variations.","icon":"08","reviewed":"2026-11-12","cases":[{"id":"msk-back-pain","title":"Low back pain: assess risk and build an active plan","summary":"Explain a positive plan without routine imaging or unsupported medicines, and recognise symptoms that change urgency.","presentation":"A 42-year-old has two weeks of low back pain after lifting. They are worried that movement will cause damage and ask for an MRI and stronger tablets. Appropriate history and examination have not identified a serious specific cause or neurological deficit in this ordinary scenario.","assessment":["Clarify onset, trauma, pain distribution, leg symptoms, neurological function and progression, previous episodes and the impact on movement, sleep, work and caring.","Assess for serious causes, including cauda equina/cord compression, infection, cancer, fracture and inflammatory disease. New or changed findings need reconsideration rather than automatic reuse of a previous mechanical label.","Ask clearly about bladder/bowel changes, altered saddle/genital sensation, sexual-function changes and leg weakness/numbness where relevant, and perform the appropriate examination. A remote account does not replace needed in-person assessment.","Review medical and medicine risks, actual analgesic use, fear of movement, expectations about scans and the practical support needed to keep active safely."],"priorities":["Choose the urgency before discussing routine back-pain care.","Offer a clear explanation, achievable activity and a review plan rather than a scan or prescription alone."],"management":[{"step":"1. Act on concerning findings","detail":"Arrange the appropriate urgent/emergency pathway when a serious cause is suspected. New bladder/bowel dysfunction, saddle/genital sensory loss, relevant new sexual-function changes or significant bilateral neurological symptoms need immediate assessment; do not wait for routine imaging or physiotherapy."},{"step":"2. Explain the working assessment","detail":"Relate the actual findings to the current working diagnosis and acknowledge the pain. Do not say that pain proves damage, or guarantee that every future symptom is harmless. Explain why the current assessment supports a non-emergency plan."},{"step":"3. Agree activity and support","detail":"Encourage continued normal activities as appropriate, avoiding prolonged bed rest. Agree manageable movement and return-to-work/daily-activity goals; tailor exercise support to needs, preferences and capabilities. If manual therapy is considered, it should be part of a package including exercise."},{"step":"4. Explain imaging appropriately","detail":"Do not routinely offer imaging in non-specialist care for low back pain with or without sciatica. Specialist imaging is considered when it is likely to change management. A patient request deserves an explanation and a positive plan, not a dismissive refusal."},{"step":"5. Choose medicines by indication and risk","detail":"If an oral NSAID is appropriate for low back pain, check gastrointestinal, renal, liver and cardiovascular risks, interactions and gastroprotection/monitoring needs; use the lowest effective dose for the shortest period. Do not offer paracetamol alone for low back pain or routine opioids; chronic low back pain should not be treated with opioids. Do not offer gabapentinoids for low back pain."},{"step":"6. Keep sciatica and existing medicine use distinct","detail":"For sciatica, NG59 advises against gabapentinoids/other antiepileptics, oral corticosteroids and benzodiazepines, and against opioids for chronic sciatica. Do not abruptly stop an existing dependence-forming medicine; review indication, risks and a suitable withdrawal plan separately."},{"step":"7. Agree review and earlier-help triggers","detail":"Set a review according to severity, function and the treatment trial. Reassess persistent or changed symptoms, barriers and the diagnosis. Make clear how to get urgent help and who reviews any medicine or referral."}],"discussion":[{"cue":"Can I have an MRI to make sure nothing is damaged?","response":"A scan is useful when it is likely to change what we do. Based on the assessment today, a routine scan is not the next helpful step. Let’s go through the treatment and review plan, and the changes that would mean we need a different assessment.","why":"Explain the reason and offer an active plan instead of only refusing a request.","simple":"A scan helps when it changes what we do. Let’s discuss the treatment and review plan, and what would change the assessment.","id":"msk-back-pain-talk-1"},{"cue":"Should I stay in bed until the pain is completely gone?","response":"Long periods in bed can make it harder to get moving again. Let’s choose manageable activities and build up in a way that fits your symptoms and the assessment. We will also agree what would need review sooner.","why":"Support function without telling the person to push through every symptom.","simple":"Long periods in bed can make movement harder. Let’s agree manageable activity and when to seek review.","id":"msk-back-pain-talk-2"},{"cue":"Does pain mean I am damaging my back?","response":"Pain can be very real and limiting without telling us exactly how much tissue damage there is. We use the history and examination to assess what needs checking and which activities are appropriate.","why":"Avoid both catastrophic language and unsupported reassurance.","simple":"Pain is real, but it does not measure tissue damage by itself. The assessment helps us choose safe next steps.","id":"msk-back-pain-talk-3"},{"cue":"My friend was given pregabalin for sciatica. Why not me?","response":"I understand why you ask. Current guidance does not recommend pregabalin for sciatica because the expected benefit does not outweigh the harms. I would rather agree a treatment and support plan that is appropriate for your assessment.","why":"Explain an evidence-led recommendation and a constructive alternative.","simple":"Current guidance does not recommend pregabalin for sciatica because benefit does not outweigh harm. Let’s agree appropriate support.","id":"msk-back-pain-talk-4"},{"cue":"I cannot go straight back to lifting at work.","response":"Let’s look at what your job involves and what you can manage safely now. We can discuss suitable temporary adjustments and a review rather than assume the only choices are full lifting or complete rest.","why":"Turn return to activity into a feasible individual arrangement.","simple":"What can you manage safely at work now? Let’s discuss temporary adjustments and a review.","id":"msk-back-pain-talk-5"}],"variations":[{"label":"New bladder or saddle symptoms","change":"Back/leg symptoms are joined by new difficulty passing urine, loss of bladder/bowel control, altered genital/saddle sensation or significant bilateral neurological symptoms.","action":"Arrange immediate emergency assessment through the appropriate pathway for possible serious neurological compression. Do not wait for routine MRI, a GP follow-up slot or physiotherapy.","phrase":"The new symptoms change the urgency. You need emergency assessment now rather than waiting for the routine back-pain plan."},{"label":"NSAID risk is high","change":"The person has CKD, previous GI bleeding, anticoagulation or another important medicine risk.","action":"Review the individual risks and actual medicines before prescribing. Do not automatically add an oral NSAID; use an appropriate alternative/support plan and seek prescribing advice when needed.","phrase":"Before we choose pain medicine, I need to check what is safe with your kidneys, other conditions and current treatment."},{"label":"Already taking long-term opioids or gabapentinoids","change":"The patient is using a dependence-forming medicine long term with little benefit and asks whether to stop today.","action":"Review the indication, benefit, harm and dependence/withdrawal risk. Explain the current recommendation and agree an individual review/withdrawal plan rather than abrupt unsupervised stopping.","phrase":"Let’s review what the medicine is doing for you and how to make any change safely. Please do not make a sudden change without an agreed plan."}],"pitfalls":["Do not use a previous mechanical diagnosis or a routine scan request to distract from new neurological or systemic warning findings.","Do not equate a positive plan with bed rest, escalating opioids or gabapentinoids.","Do not promise imaging or a specific recovery deadline without the actual clinical reason; do not abruptly stop dependence-forming medicines."],"safetyNet":["New bladder/bowel or genital/saddle sensory changes, serious bilateral leg neurological symptoms or other suspected compression needs immediate emergency assessment; do not drive yourself if emergency transfer is needed.","Serious trauma, acute systemic illness or suspected cancer/infection/fracture needs the appropriate urgent pathway.","Persistent deterioration, new weakness or a changed pattern needs reassessment; agree a contact route and review instead of only “if worse”."],"followUp":"Agree a review based on function, severity and any medicine trial, including adverse-effect checks. If not improving, revisit the diagnosis, examination and support rather than automatically repeat the same prescription. Track any referral and maintain an earlier-help plan.","reviewed":"2026-11-12","tags":["back pain","sciatica","MRI","activity","cauda equina","NSAID","medicine review"],"links":[{"label":"NICE NG59: low back pain and sciatica","url":"https://www.nice.org.uk/guidance/ng59","use":"Current assessment, imaging, activity and medicine recommendations, including the 2026 amendments."},{"label":"NHS: back pain","url":"https://www.nhs.uk/conditions/back-pain/","use":"Patient explanations, activity and emergency warning symptoms."},{"label":"NICE NG215: dependence and withdrawal","url":"https://www.nice.org.uk/guidance/ng215","use":"Safe individual review of existing dependence-forming medicines."}],"retrieval":{"question":"How would you explain why a routine MRI is not the next step while still offering a clear, safe back-pain plan?","answer":"Connect the actual assessment to the recommendation, explain that imaging is useful when it changes management, agree activity/support and appropriate medicine checks, and name review and warning symptoms. A new neurological or systemic warning finding changes the pathway immediately.","checks":["Linked the recommendation to assessment rather than dismissal","Offered practical activity/support and medicine-risk checks","Specified review ownership and emergency changes"]}},{"id":"msk-gout","title":"Gout: treat the flare and explain long-term prevention","summary":"Separate acute relief from urate lowering, consider comorbidity and make treat-to-target follow-up understandable.","presentation":"A 58-year-old has recurrent clinically assessed gout affecting the big toe. The current presentation has been assessed without evidence of joint infection in this fictional ordinary scenario. They want rapid relief and ask whether preventive tablets can be stopped once the pain settles.","assessment":["Assess the red, swollen joint and overall illness; consider septic arthritis, CPPD and other inflammatory causes rather than assume every hot joint is gout. Suspected septic arthritis requires immediate referral via the local pathway.","Clarify the pattern, number and severity of flares, tophi, kidney disease/stones, medicines including diuretics, cardiovascular disease, previous treatment and functional impact.","Use serum urate in the clinical context. If below 360 micromol/litre during a flare but gout remains strongly suspected, repeat at least two weeks after the flare settles; consider aspiration or appropriate imaging when diagnosis remains uncertain.","Check renal function, co-prescriptions, allergy and other treatment risks before choosing flare or urate-lowering medicines. Explore beliefs, barriers and what the person means by “prevention”."],"priorities":["Exclude a hot-joint emergency before routine gout treatment.","Explain the different jobs of flare treatment and long-term urate lowering, with a monitored plan for each."],"management":[{"step":"1. Confirm urgency and the diagnostic basis","detail":"Assess for joint infection and other important causes. Arrange immediate referral if septic arthritis is suspected; do not delay for routine urate testing or treat presumed gout while infection remains unaddressed."},{"step":"2. Treat the assessed flare appropriately","detail":"Choose an NSAID, colchicine or a short course of oral corticosteroid according to comorbidities, co-prescriptions and preference. Check the actual dose/product, renal function, contraindications and interactions; consider gastroprotection when indicated. Do not offer the same regimen to everyone."},{"step":"3. Explain and offer prevention when indicated","detail":"Offer treat-to-target urate-lowering therapy for multiple/troublesome flares, CKD stages 3–5, diuretic therapy, tophi or chronic gouty arthritis. Discuss the option after other first/subsequent flares too. Explain that ULT is usually continued after the target is reached and is typically lifelong."},{"step":"4. Choose the start and medicine safely","detail":"NG219 recommends starting ULT at least 2–4 weeks after a flare has settled; it can start during a flare when flares are more frequent, with appropriate prevention discussion. Allopurinol or febuxostat can be first-line depending on context; use allopurinol first-line for major cardiovascular disease. Check the full prescribing reference and patient-specific risks."},{"step":"5. Titrate to a measured target","detail":"Start ULT at a low dose and use monthly serum urate to guide tolerated increases until target. Aim below 360 micromol/litre; consider below 300 for tophi/chronic gouty arthritis or continuing frequent flares despite reaching below 360. Explain that the blood test guides dose rather than pain alone."},{"step":"6. Discuss flare prevention during titration","detail":"Discuss benefits/harms of flare prophylaxis. If chosen, offer colchicine while reaching target, with suitable alternatives when contraindicated, not tolerated or ineffective. Check interactions and renal safety; do not mistake prophylaxis for the long-term urate-lowering medicine itself."},{"step":"7. Review after the flare and maintain follow-up","detail":"Review response, serum urate when appropriate, lifestyle and comorbidity, medicines and the ULT decision. Consider annual urate monitoring once target is reached on ongoing ULT, with earlier assessment for problems. Advice should support health without blaming the person or promising diet alone will prevent every flare."}],"discussion":[{"cue":"Why take another tablet when the pain has gone?","response":"The flare medicine treats the current inflammation and pain. Urate-lowering treatment has a different job: reducing urate over time to lower the chance of future attacks and joint problems. We adjust it using blood tests, not just whether today’s toe hurts.","why":"Separate acute relief from the preventive treatment purpose.","simple":"Flare medicine treats today’s inflammation. Urate-lowering medicine reduces the risk of future problems, with blood tests guiding the dose.","id":"msk-gout-talk-1"},{"cue":"Can I stop the preventive medicine once the blood result is normal?","response":"Reaching the target tells us the treatment is doing its job. It usually needs to continue to keep urate down. Let’s discuss the long-term plan, monitoring and any concerns before making a change.","why":"Explain why a good result is not an automatic stop signal.","simple":"A target result usually means the medicine is working and needs to continue. Let’s review the plan before changing it.","id":"msk-gout-talk-2"},{"cue":"Could the preventive tablet make attacks happen at first?","response":"Flares can occur while urate-lowering treatment is being started or adjusted. We should discuss whether suitable temporary flare-prevention treatment would help, what side effects to watch for and how to contact us.","why":"Prepare the person for a recognised barrier to adherence without promising a flare-free start.","simple":"Flares can happen when prevention is started or adjusted. We can discuss suitable temporary protection and a contact plan.","id":"msk-gout-talk-3"},{"cue":"Is this all my fault because of food?","response":"Gout has several contributing factors, including how the body handles urate and other health conditions. We can discuss helpful lifestyle changes without blaming you, and decide whether medicine is needed to prevent further problems.","why":"Reduce shame and avoid claiming that a restrictive diet alone replaces indicated treatment.","simple":"You have not failed. Several factors contribute to gout. Let’s discuss helpful changes and whether preventive medicine is needed.","id":"msk-gout-talk-4"},{"cue":"I have kidney problems. Can I take the usual tablets?","response":"That affects what is safe and how we prescribe it. I need to check your kidney function, other medicines and the specific treatment before agreeing the dose and monitoring.","why":"Make comorbidity part of the actual prescribing decision.","simple":"Your kidney function affects the treatment and dose. I need to check it alongside your other medicines.","id":"msk-gout-talk-5"}],"variations":[{"label":"Hot joint with possible infection","change":"The presentation includes a rapidly worsening hot swollen joint and systemic illness, or infection remains a meaningful concern.","action":"Refer immediately through the local septic-arthritis pathway. Do not use a gout history, raised urate or a presumed flare response to rule infection out.","phrase":"A joint infection is one of the important possibilities here. We need urgent specialist assessment now rather than assume this is another gout flare."},{"label":"Urate is low during an apparent flare","change":"The serum urate is below 360 micromol/litre during the acute episode but the clinical suspicion remains strong.","action":"Keep the differential open. Repeat serum urate at least two weeks after the flare settles; use aspiration or appropriate further assessment if the diagnosis is uncertain.","phrase":"This result during an attack does not settle the question on its own. We should review the whole picture and arrange the right repeat or further test."},{"label":"CKD and major cardiovascular disease","change":"Recurrent gout occurs with kidney disease and a history of myocardial infarction.","action":"Individualise flare medicines, ULT starting dose/titration and prophylaxis. NG219 recommends allopurinol first-line when starting ULT in major cardiovascular disease. Monitor to target and check the full prescribing guidance rather than reuse a standard regimen.","phrase":"Your kidney and heart history affect which treatment is suitable. We can choose a careful starting plan and use monitoring to adjust it safely."}],"pitfalls":["Do not assume every hot joint is gout or wait for routine blood results if infection is suspected.","Do not confuse flare treatment, flare prophylaxis and urate lowering, or prescribe without renal/interaction checks.","Do not stop preventive treatment just because pain settles or target urate is reached; review with the person."],"safetyNet":["A worsening hot swollen joint, systemic illness or suspected infection needs immediate reassessment/referral according to severity.","Discuss the actual medicine’s important adverse effects and the action/contact route, including urgent help for serious reactions.","Agree what to do for continuing pain, treatment intolerance or a flare during titration; do not leave the person to abandon or change medicines without advice."],"followUp":"Review after the flare and agree prevention. When starting/titrating ULT, use monthly urate-guided dose review until target, with safety checks and suitable flare prophylaxis discussion. Consider annual serum urate once target is reached on continuing ULT; review earlier when clinically needed.","reviewed":"2026-11-12","tags":["gout","hot joint","urate","allopurinol","CKD","flare","septic arthritis"],"links":[{"label":"NICE NG219: gout diagnosis and management","url":"https://www.nice.org.uk/guidance/ng219","use":"Flare assessment, treatment choices, ULT indications, targets and monitoring."},{"label":"NHS: gout","url":"https://www.nhs.uk/conditions/gout/","use":"Patient explanations and help-seeking advice."},{"label":"NHS: septic arthritis","url":"https://www.nhs.uk/conditions/septic-arthritis/","use":"The importance of urgent assessment of possible joint infection."}],"retrieval":{"question":"How would you explain the three different roles of flare treatment, temporary flare prevention and long-term urate lowering?","answer":"Treat the assessed flare with a suitable anti-inflammatory option. Discuss temporary prophylaxis while starting/titrating ULT when chosen. Explain that long-term ULT lowers urate to a measured target and usually continues after symptoms and blood results improve. Check the diagnostic basis, comorbidity and monitoring.","checks":["Distinguished the three medicine purposes","Included infection, renal and interaction checks","Explained target-guided titration and ongoing review"]}},{"id":"msk-knee-oa","title":"Knee osteoarthritis: movement, pain support and referral","summary":"Make a clinical diagnosis where appropriate, explain exercise and medicine choices, and consider referral from symptoms and function.","presentation":"A 67-year-old describes gradual activity-related knee pain, brief morning stiffness and difficulty walking to the shops. The assessment fits knee osteoarthritis without atypical or acute inflammatory features in this ordinary scenario. They fear that exercise will wear the knee out faster and ask whether their BMI rules out referral.","assessment":["Clarify pain pattern, duration, morning stiffness, swelling, injury, locking/instability and the effect on walking, sleep, work and valued activities. Examine appropriately.","Consider alternatives when symptoms or examination are atypical, including a hot swollen joint, marked/prolonged morning stiffness, rapid deterioration, trauma or systemic illness. Do not force every older person’s knee pain into an OA label.","NG226 supports clinical diagnosis without imaging in people aged at least 45 with activity-related pain and no morning stiffness or stiffness lasting no longer than 30 minutes. Routine imaging is not needed unless atypical findings suggest another/additional diagnosis.","Review previous exercise/support, treatment actually used, medical/medicine risks, weight-management needs if relevant and the person’s goals and beliefs about movement and surgery."],"priorities":["Base treatment on symptoms, function and preference, not an X-ray grade or a dismissive “wear and tear” label.","Offer practical therapeutic exercise and support, then appropriate medicine/referral choices with review."],"management":[{"step":"1. Explain the assessment and goals","detail":"Describe OA in accessible language, acknowledge pain and variable symptoms, and agree a meaningful function goal. Routine imaging does not improve a typical clinical diagnosis; atypical features need a different assessment."},{"step":"2. Offer tailored therapeutic exercise","detail":"Offer suitable local strengthening and general aerobic activity; consider supervised sessions. Explain that some initial discomfort can occur and regular, consistent exercise can improve pain/function. Tailor the starting level and support; a new hot joint or major change requires reassessment rather than “push through”."},{"step":"3. Discuss weight support when appropriate","detail":"If overweight/obesity is relevant, explain how supported weight management may improve symptoms and health and agree a respectful, feasible plan. Avoid blame or make weight loss a prerequisite for all care."},{"step":"4. Choose pain support alongside exercise","detail":"Offer a topical NSAID for knee OA when pharmacological treatment is needed, checking suitability. If ineffective or unsuitable, consider an oral NSAID only after GI, renal, liver, cardiovascular and co-prescription risk checks; offer gastroprotection with an oral NSAID. Use the lowest effective dose for the shortest time."},{"step":"5. Explain limits of other medicines and injections","detail":"Do not routinely offer paracetamol or weak opioids; NG226 limits their use to infrequent short-term situations when other pharmacological options are unsuitable/ineffective. Do not offer strong opioids or glucosamine. Consider an intra-articular corticosteroid when other medicines are ineffective/unsuitable or to support exercise, explaining short-term relief of about 2–10 weeks."},{"step":"6. Consider referral from the clinical picture","detail":"Consider joint-replacement referral when pain, stiffness, reduced function or deformity substantially affects quality of life and non-surgical care is ineffective or unsuitable. Do not exclude referral solely because of age, sex/gender, smoking, comorbidity or BMI; discuss how individual risks affect surgical decisions."},{"step":"7. Agree review that fits the need","detail":"Patient-initiated follow-up suits many people, while a planned review may be needed for treatment monitoring, severe limitation, support needs or preference. Name what improvement should look like, adverse-effect checks and how to return if the plan is insufficient."}],"discussion":[{"cue":"Isn’t exercise wearing the knee out even more?","response":"It is understandable to worry about that. Appropriate exercise can help the muscles support the joint and improve function. We can choose a manageable starting level and build it up, with advice about what discomfort to expect and what would need review.","why":"Challenge the damage assumption without denying pain or ignoring a changed presentation.","simple":"Appropriate exercise can improve support and function. Let’s choose a manageable starting level and agree what needs review.","id":"msk-knee-oa-talk-1"},{"cue":"If you do not X-ray it, how can you know?","response":"A typical pattern of symptoms and examination can be enough to make the diagnosis. We use imaging when the findings are unusual or it would help answer a different question, rather than order it routinely for everyone.","why":"Explain the clinical basis and when the imaging decision changes.","simple":"A typical symptom pattern and examination can establish the diagnosis. Unusual findings may need further tests.","id":"msk-knee-oa-talk-2"},{"cue":"Could an injection fix it permanently?","response":"A steroid injection may give short-term relief in an appropriate situation, sometimes to help you engage with exercise. It does not permanently repair the joint, so we should discuss its purpose, risks and what comes afterwards.","why":"Avoid promising a cure and place the intervention in the overall plan.","simple":"An injection may give temporary relief; it does not permanently repair the joint. Let’s discuss its purpose and risks.","id":"msk-knee-oa-talk-3"},{"cue":"I was told my weight means I can never be referred.","response":"Weight can affect symptoms and surgical risks, and we can offer support. It should not by itself rule out referral. We should consider how much the knee affects your life and whether suitable non-surgical care has helped, then discuss the options and individual risks.","why":"Separate risk discussion from an automatic access barrier.","simple":"Weight can affect symptoms and risk, but should not by itself rule out referral. We should assess the whole picture.","id":"msk-knee-oa-talk-4"},{"cue":"What is a realistic first goal?","response":"What activity would you most like to do more comfortably? Let’s choose one goal, agree the exercise and pain-support plan, and decide how we will judge whether it is helping.","why":"Use the patient’s valued function rather than an abstract pain score alone.","simple":"What activity matters most to you? Let’s agree a practical goal and review whether the plan helps.","id":"msk-knee-oa-talk-5"}],"variations":[{"label":"The knee becomes hot and acutely swollen","change":"New marked warmth/swelling, severe restriction or systemic illness appears.","action":"Reassess urgently for infection and other acute/inflammatory causes. Suspected septic arthritis needs immediate referral; do not treat this as an ordinary OA flare or inject before infection is addressed.","phrase":"This new swelling changes the assessment. We need to check for an acute cause rather than assume it is the same osteoarthritis pain."},{"label":"Comorbidity makes oral NSAIDs risky","change":"There is CKD, anticoagulation, previous GI bleeding or significant cardiovascular risk.","action":"Review suitability of all treatments and the actual co-prescriptions. Do not add an oral NSAID automatically or assume topical medicines have no precautions; optimise appropriate non-drug/topical support and consider further options/referral.","phrase":"We need pain support that fits safely with your other treatment. Let’s check the risks before adding another medicine."},{"label":"Quality of life remains substantially affected","change":"Suitable non-surgical options are ineffective or unsuitable and walking, sleep or daily life remains severely limited.","action":"Discuss joint-replacement referral using clinical assessment and shared decisions. Do not apply an automatic age/BMI/comorbidity exclusion; explain individual risks and what the specialist assessment involves.","phrase":"The knee is still having a major effect on your life despite the care we have tried. It is reasonable to discuss a specialist opinion about the next options."}],"pitfalls":["Do not dismiss pain as inevitable ageing or use a scan grade as the whole management decision.","Do not prescribe escalating opioids, routine paracetamol or glucosamine instead of evidence-based support.","Do not promise permanent benefit from a steroid injection or deny referral solely because of BMI, age or another listed factor."],"safetyNet":["An acutely hot swollen knee, systemic illness or suspected infection needs urgent assessment, with immediate referral for suspected septic arthritis.","New trauma, rapid deterioration or atypical features requires reassessment rather than automatic repeat OA care.","Explain adverse effects and contact arrangements for the actual medicine/injection; review an ineffective or intolerable plan."],"followUp":"Agree patient-initiated or planned review according to individual needs, treatment monitoring and preference. Review function goals, exercise access, pain support, adverse effects and whether referral is now appropriate. Track any referral and agree a contact plan.","reviewed":"2026-11-12","tags":["osteoarthritis","knee pain","exercise","NSAID","joint replacement","BMI","steroid injection"],"links":[{"label":"NICE NG226: osteoarthritis","url":"https://www.nice.org.uk/guidance/ng226","use":"Clinical diagnosis, therapeutic exercise, medicines, injections and referral criteria."},{"label":"NHS: osteoarthritis","url":"https://www.nhs.uk/conditions/osteoarthritis/","use":"Accessible patient information about symptoms and treatment."},{"label":"NHS: septic arthritis","url":"https://www.nhs.uk/conditions/septic-arthritis/","use":"Urgent assessment of a possible joint infection."}],"retrieval":{"question":"How would you explain an exercise-led knee OA plan while answering concerns about imaging, pain relief and possible referral?","answer":"Link the typical assessed pattern to a clinical diagnosis, offer tailored therapeutic exercise and appropriate support, choose medicines after risk checks and explain their limits. Use symptoms/function and response to suitable non-surgical care to discuss referral, without an automatic BMI/age exclusion. Reassess an acutely hot joint.","checks":["Explained diagnosis and a practical exercise/function goal","Included medicine risk and realistic intervention benefit","Specified review, changed symptoms and fair referral discussion"]}}]},{"id":"neurology","title":"Neurology and headache","description":"Migraine, medication-overuse headache and suspected TIA: assessment, medicine safety, urgent changes and clear explanations, each with three variations.","icon":"09","reviewed":"2026-11-13","cases":[{"id":"neuro-migraine","title":"Migraine: a clear explanation and an individual treatment plan","summary":"Recognise the assessed pattern, explain acute versus preventive care and make medicine/pregnancy checks explicit.","presentation":"A 32-year-old has recurrent disabling headaches with nausea and light sensitivity over eight months, affecting about four days each month. Appropriate history and examination support migraine without aura and have not identified warning features in this ordinary scenario. They ask for a brain scan and a medicine that will stop attacks happening.","assessment":["Clarify onset, frequency, duration, headache characteristics, associated symptoms, aura or other neurological features, triggers and change from the established pattern. Ask about the effect on work and daily life.","Assess for secondary causes and warning features, including sudden maximal severe onset, new neurological deficit, fever/meningism, altered consciousness, concerning injury or a substantial changed pattern. Do not assume a previous migraine diagnosis explains every new headache.","Review all acute/preventive and over-the-counter treatment, days of use each month, response and adverse effects. A headache diary can help clarify frequency, triggers and medicine exposure.","Check pregnancy/pregnancy plans, contraception where relevant, comorbidities such as asthma or depression, cardiovascular risk, interactions and the person’s priorities before selecting medicines."],"priorities":["Choose urgency and the diagnostic basis before reassurance or routine migraine treatment.","Separate treatment of an attack from prevention, and agree a plan that fits the person’s risks and preferences."],"management":[{"step":"1. Explain the assessment-led diagnosis","detail":"Relate the actual pattern and examined findings to the working diagnosis. Acknowledge the disability without implying the pain is imagined. New warning symptoms require reassessment rather than automatic reuse of the label."},{"step":"2. Discuss imaging in context","detail":"Do not refer for imaging solely for reassurance when an appropriate assessment has established a primary headache diagnosis. Explain the reason and what would change the decision; atypical or concerning findings may need investigation/referral."},{"step":"3. Agree acute treatment safely","detail":"CG150 recommends an oral triptan with an NSAID or paracetamol for acute migraine, with suitable alternatives according to preference, comorbidity and adverse-effect risk. Check the actual product, contraindications, interactions and relevant pregnancy advice. Do not offer opioids or ergots for acute migraine."},{"step":"4. Discuss whether prevention is appropriate","detail":"Use frequency, disability, preference and treatment response to discuss preventive care. Consider the suitable CG150 options only after their individual benefits/risks are explained. Propranolol needs relevant comorbidity and overdose-risk checks; do not choose it automatically in someone with asthma or significant self-harm concern."},{"step":"5. Apply current topiramate restrictions","detail":"Topiramate must not be used for migraine prevention in pregnancy. In women of childbearing potential it must not be used unless the Pregnancy Prevention Programme conditions are met, including highly effective contraception. Use current MHRA/product requirements and an appropriate prescribing review rather than a generic reassurance."},{"step":"6. Keep aura and contraception visible","detail":"If migraine with aura is established, do not routinely offer combined hormonal contraception under CG150; arrange a prompt individual contraception/risk review and suitable options. New or atypical neurological symptoms must first be assessed for urgent causes rather than simply called aura."},{"step":"7. Review effect, actual use and safety","detail":"Agree headache/function goals, a diary if useful, and review the actual acute/preventive treatment, adverse effects and frequency of acute medicines. Monitor possible medication overuse. Further treatment/referral follows current eligibility and clinical need, not an automatic prescription escalation."}],"discussion":[{"cue":"Why not scan my brain to be sure?","response":"A scan is useful when the assessment suggests a question it can answer. The pattern and examination today support migraine without warning features, so a scan just for reassurance is not the next recommended step. Let’s agree treatment, review and the changes that would need a different assessment.","simple":"The assessment supports migraine today. Let’s discuss treatment and what would change the need for investigation.","why":"Explain the clinical basis and a positive plan rather than dismissing a scan request or guaranteeing permanent safety.","id":"neuro-migraine-talk-1"},{"cue":"Is it just a bad headache I should put up with?","response":"Migraine can be very disabling. We can discuss treatment for attacks and whether prevention would help with the effect on your life. Which activity is most important for you to get back to?","simple":"Migraine deserves treatment. Let’s choose a goal and discuss attack treatment and prevention.","why":"Validate the burden and use a patient-defined function goal rather than minimise the condition.","id":"neuro-migraine-talk-2"},{"cue":"Does prevention mean taking more painkillers every day?","response":"Preventive treatment has a different job: reducing how often or how severely attacks happen. It is not simply taking acute pain medicine more often. We would choose a suitable option, discuss side effects and review whether it is helping.","simple":"Prevention aims to reduce attacks. It is different from taking more acute pain medicine.","why":"Distinguish the treatment purposes and the risk of frequent acute medicine use.","id":"neuro-migraine-talk-3"},{"cue":"My friend takes propranolol. I have asthma; can I have the same?","response":"Your asthma can make propranolol unsuitable, so I would not simply copy that prescription. We need to choose an appropriate preventive option after checking your health, other medicines and preferences.","simple":"Asthma affects whether propranolol is suitable. Let’s review an appropriate alternative rather than copy that prescription.","why":"Use comorbidity in the prescribing decision; do not imply one preventive drug is appropriate for every migraine patient.","id":"neuro-migraine-talk-4"},{"cue":"Could I use topiramate if I might become pregnant?","response":"Topiramate has important pregnancy restrictions and is not used for migraine prevention in pregnancy. For anyone who could become pregnant, the current pregnancy-prevention requirements must be met before it is considered. Let’s review your plans and appropriate alternatives with the prescriber.","simple":"This needs a pregnancy-specific prescribing review. Topiramate has strict restrictions and cannot be used for migraine prevention in pregnancy.","why":"Explain current MHRA requirements without a universal contraceptive instruction, reassurance of zero risk or unsupervised medication change.","id":"neuro-migraine-talk-5"}],"variations":[{"label":"A sudden, extremely painful new headache","change":"A headache becomes maximally severe suddenly, or there are new focal neurological symptoms, confusion or other serious warning findings.","action":"Arrange the appropriate emergency assessment now. Do not treat the episode as routine migraine or wait for a diary/preventive review.","phrase":"This new pattern changes the urgency. You need emergency assessment now rather than the usual migraine plan."},{"label":"Pregnancy or a pregnancy plan","change":"The person is pregnant, might be pregnant or wants to conceive while prevention is being considered or used.","action":"Review the actual medicines promptly using pregnancy-specific advice. Topiramate is contraindicated for migraine prevention in pregnancy; follow current MHRA requirements and safe alternatives. Avoid applying the ordinary non-pregnant regimen automatically.","phrase":"We need to review the actual treatment with pregnancy-specific advice and agree a safe next step promptly."},{"label":"Established aura and combined hormonal contraception","change":"After appropriate assessment, the person has migraine with aura and uses or requests combined hormonal contraception.","action":"Arrange an individual contraception and risk review; CG150 advises against routinely offering combined hormonal contraception in migraine with aura. First assess any new/atypical neurological symptoms for urgent causes and avoid leaving an unplanned contraception gap.","phrase":"The aura history affects which contraception is appropriate. Let’s review suitable options and make the change safely if needed."}],"pitfalls":["Do not let a migraine label or a request for reassurance replace assessment of a sudden or changed neurological presentation.","Do not confuse prevention with increasing days of acute medicine use, or use opioids as routine acute migraine care.","Do not copy a preventive medicine without comorbidity, self-harm, pregnancy and interaction checks."],"safetyNet":["A sudden extremely severe headache, new weakness/speech or major visual problems, confusion, seizure or serious acute illness needs emergency help; do not drive yourself.","A substantial changed pattern, new pregnancy-related concern or treatment intolerance needs prompt reassessment rather than automatic repeats.","Agree who reviews the medicine trial and what to do if it is ineffective, adverse effects occur or acute medicine use becomes frequent."],"followUp":"Agree a real review for the selected regimen and headache/function goals. Check actual use and harms, whether prevention is still needed and whether the diagnosis or pathway should change. New warning symptoms prompt earlier assessment.","reviewed":"2026-11-13","tags":["migraine","headache","prevention","aura","topiramate","pregnancy","asthma"],"links":[{"label":"NICE CG150: headache diagnosis and management","url":"https://www.nice.org.uk/guidance/cg150","use":"Assessment, imaging, acute/preventive treatment, aura and pregnancy."},{"label":"NHS: migraine","url":"https://www.nhs.uk/conditions/migraine/","use":"Patient explanation and emergency warning symptoms."},{"label":"MHRA: topiramate Pregnancy Prevention Programme","url":"https://www.gov.uk/drug-safety-update/topiramate-topamax-introduction-of-new-safety-measures-including-a-pregnancy-prevention-programme","use":"Current safety restrictions and prescribing requirements."},{"label":"NHS: propranolol suitability","url":"https://www.nhs.uk/medicines/propranolol/who-can-and-cannot-take-propranolol/","use":"Asthma/lung disease and other checks before treatment."}],"retrieval":{"question":"How would you explain acute versus preventive migraine care while making the choice safe for this person?","answer":"Explain the different purposes, connect prevention to burden and preference, check actual acute medicine days and choose any regimen after comorbidity/pregnancy/interaction checks. A changed or sudden neurological presentation needs reassessment, not a routine preventive prescription.","checks":["Explained the two treatment purposes","Applied person-specific medicine and pregnancy checks","Agreed review and urgent changes"]}},{"id":"neuro-medication-overuse","title":"Medication-overuse headache: explain a supported withdrawal plan","summary":"Recognise frequent acute treatment, distinguish a selected simple-analgesic plan from dependence risk and arrange review.","presentation":"A 40-year-old with an established primary headache disorder has developed headaches on many days while using ibuprofen for headache on most days for more than four months. Assessment has not identified another cause or warning feature in this ordinary scenario. There is no opioid, benzodiazepine or other dependence-forming medicine use, and no separate indication requiring the ibuprofen.","assessment":["Clarify the original and current headache pattern, frequency, duration, change and any secondary-headache warning findings. A medication-use history is not a substitute for assessment of a new serious cause.","List every acute headache product and ingredient, including over-the-counter or combination medicines, and count days used per month for at least the relevant preceding months. Ask about preventive treatment separately.","CG150 advises being alert when headaches develop/worsen during at least three months of triptan/opioid/ergot/combination analgesic use on at least 10 days per month, or paracetamol/aspirin/NSAID use on at least 15 days per month. Apply this to the wider clinical picture, not as a stand-alone diagnosis.","Check other medicine indications, physical dependence/withdrawal risks, comorbidity, prior withdrawal attempts, pregnancy where relevant and practical capacity to manage a supported plan."],"priorities":["Explain the treatment cycle without blame and exclude a changed urgent cause.","Make the withdrawal plan specific to the actual overused acute headache medicines and the person’s risks."],"management":[{"step":"1. Explain the working assessment","detail":"Connect the changing headache pattern and frequent acute medicine use to possible medication-overuse headache. Explain that short-term relief can coexist with a pattern that keeps headaches going; do not call the person an addict or dismiss the underlying primary headache."},{"step":"2. Verify that the ordinary withdrawal plan applies","detail":"Confirm the exact products, doses, use days and other indications. In this ordinary scenario the overused medicine is ibuprofen for headache only, without dependence-forming drugs or another prescribing reason requiring a different plan."},{"step":"3. Agree the assessed withdrawal approach","detail":"CG150 advises stopping the overused acute headache medicines abruptly rather than gradually for at least one month. Apply this only after the relevant assessment; it is not an instruction to stop all medicines, indicated preventive treatment or drugs for other conditions."},{"step":"4. Anticipate the difficult early period","detail":"Explain that symptoms are likely to worsen temporarily before improvement and withdrawal symptoms can occur. Agree close support, a feasible start and what to do if the plan is unmanageable or the symptoms differ from the expected pattern."},{"step":"5. Treat the underlying headache appropriately","detail":"Consider suitable prevention for the underlying primary headache alongside withdrawal, using its own suitability checks. Avoid simply replacing one frequently used acute medicine with another daily acute medicine without a coherent plan."},{"step":"6. Recognise a different-risk pathway","detail":"Strong opioids, relevant comorbidity or repeated unsuccessful withdrawal attempts may need specialist referral and/or inpatient withdrawal under CG150. Where dependence-forming medicines are involved, use the appropriate individual NG215 assessment rather than copy this simple-NSAID stopping instruction."},{"step":"7. Review diagnosis and response","detail":"Arrange close support according to need and review the diagnosis and further management 4–8 weeks after withdrawal starts. Track headache/function, actual medicine use and relapse prevention; new warning symptoms need earlier action."}],"discussion":[{"cue":"How can the tablets be part of the problem when they help for a few hours?","response":"They can give short-term relief, yet frequent use can contribute to a pattern of more headaches in some people. Your history fits that possibility, so I recommend an assessed, supported plan to break the cycle while treating the underlying headache too.","simple":"Short-term relief and medication-overuse headache can occur together. Let’s agree a supported plan for both.","why":"Explain the apparent contradiction without blame or pretending medicine history alone proves the diagnosis.","id":"neuro-medication-overuse-talk-1"},{"cue":"Are you calling me addicted?","response":"No. Medication-overuse headache is not the same as saying someone has an addiction. We still need to check exactly what you use and whether any medicine has dependence or withdrawal risks, because that changes the safe plan.","simple":"I am not labelling you. Let’s check the actual medicines and any withdrawal risks.","why":"Separate a headache pattern from a diagnosis of addiction while keeping real physical dependence risks visible.","id":"neuro-medication-overuse-talk-2"},{"cue":"Do I stop every medicine I take?","response":"No. We need to be precise about the overused acute headache medicine and any other reason you take it. The ordinary plan we have discussed applies to that assessed medicine, not automatically to your other treatment. I will confirm the actual instructions and support.","simple":"We should name exactly which medicine changes. Do not apply the plan to all your treatment.","why":"Avoid an unsafe blanket stop instruction, particularly when another indication or preventive medicine exists.","id":"neuro-medication-overuse-talk-3"},{"cue":"What if the headache gets worse when I stop?","response":"It can get worse for a short time before improving, so we should plan support and a contact route. A sudden very severe headache, new neurological symptoms or serious illness needs urgent assessment rather than assume it is expected withdrawal.","simple":"Let’s plan support for temporary worsening, but reassess a new warning pattern urgently.","why":"Prepare realistically without normalising every deterioration or leaving the person to cope alone.","id":"neuro-medication-overuse-talk-4"},{"cue":"When will you check whether this is working?","response":"We will agree the early support you need and review the diagnosis and plan four to eight weeks after starting withdrawal. Let’s confirm who you contact sooner if it is not manageable, and use a diary to see how headache days and medicine use change.","simple":"Let’s arrange early support and a four-to-eight-week review, with a contact route for problems sooner.","why":"Use CG150’s review window while retaining individual closer support and clinical ownership.","id":"neuro-medication-overuse-talk-5"}],"variations":[{"label":"Codeine or another dependence-forming drug is involved","change":"The full review reveals regular codeine/combination analgesics with withdrawal symptoms or other dependence risks.","action":"Reassess before any home stopping instruction. Coordinate an individual medicine/withdrawal plan and relevant specialist advice; do not copy the ordinary ibuprofen-only abrupt-stop example.","phrase":"The medicine history changes what is safe. Let’s work out an individual supported plan rather than make a sudden unassessed change."},{"label":"Withdrawal has repeatedly failed or comorbidity complicates care","change":"There are repeated unsuccessful attempts, strong opioid use or relevant medical/mental-health complexity.","action":"Consider specialist referral and/or inpatient withdrawal as appropriate under CG150, with coordinated support and treatment of the underlying headache.","phrase":"This has been difficult to manage, so we should add the right expertise and support rather than repeat the same unsupported plan."},{"label":"The headache becomes suddenly different","change":"A new sudden severe headache, focal deficit, confusion or another warning feature appears.","action":"Arrange the appropriate urgent/emergency assessment. Do not attribute a new warning pattern to medication overuse or withdrawal without assessment.","phrase":"This change needs a new assessment now. We should not assume it is the expected effect of changing the medicine."}],"pitfalls":["Do not diagnose from a medicine-day count alone or overlook a secondary headache.","Do not turn the CG150 acute-headache withdrawal advice into a rule to stop all medicines or an unassessed opioid/benzodiazepine withdrawal plan.","Do not leave the person without support or simply substitute another daily acute medicine."],"safetyNet":["Sudden extremely severe pain, new weakness/speech/vision problems, confusion, seizure or serious acute illness needs emergency assessment.","Contact the named team for an unmanageable withdrawal plan, unexpected symptoms, new medicine information or adverse effects.","Arrange active reassessment if the pattern persists or the diagnosis remains uncertain; do not assume every future headache has the same cause."],"followUp":"Provide close support according to needs and review the diagnosis/further management 4–8 weeks after starting withdrawal. Check the actual medicines, headache days, function, prevention plan and any recurrence of frequent acute use. Escalate earlier for changed risk.","reviewed":"2026-11-13","tags":["headache","medication overuse","ibuprofen","triptan","withdrawal","codeine","acute medicine days"],"links":[{"label":"NICE CG150: medication-overuse headache","url":"https://www.nice.org.uk/guidance/cg150","use":"Recognition, selected withdrawal, support, specialist indications and 4–8 week review."},{"label":"NICE NG215: dependence and withdrawal","url":"https://www.nice.org.uk/guidance/ng215","use":"Individual safe assessment when dependence-forming medicine use changes the plan."},{"label":"NHS: headaches","url":"https://www.nhs.uk/symptoms/headaches/","use":"Changed patterns and urgent warning symptoms."}],"retrieval":{"question":"How would you explain the ordinary ibuprofen-only withdrawal plan and the medicine history that would make it unsafe to copy?","answer":"Name the assessed overused acute headache medicine, explain the supported stopping plan, temporary worsening and review. Verify other indications and all products. Codeine, other dependence-forming drugs, strong opioids, comorbidity or failed attempts may need an individual/specialist pathway rather than the simple example.","checks":["Named the actual medicine and its indication","Anticipated support and withdrawal complexity","Specified review and urgent changed symptoms"]}},{"id":"neuro-suspected-tia","title":"Resolved focal symptoms: act on a possible TIA","summary":"Treat resolved symptoms as time-sensitive, distinguish current stroke symptoms and close the urgent referral loop.","presentation":"A 68-year-old reports sudden right-arm weakness and difficulty speaking that lasted ten minutes two hours ago. They say they feel completely back to normal now. In the ordinary path the clinician confirms no current deficit or instability, assesses relevant mimics and medicine risks, and has strong concern for a suspected TIA. This is not a confirmed diagnosis from a phone description alone.","assessment":["Establish exact onset/last-known-well time, symptom progression, duration, resolution and any current or recurrent focal symptoms. Ongoing or recurrent stroke symptoms need emergency stroke assessment now.","Assess the focal symptoms and relevant alternatives, including hypoglycaemia, seizure and migraine, with appropriate examination and tests without delaying the urgent pathway.","Review vascular/AF history, bleeding history, allergy, current antiplatelet/anticoagulant use, actual recent doses and other prescribing risks before the immediate medicine decision.","Confirm location, safe support/transport, understanding and ability to attend urgent assessment. Ask about driving and safety-critical work."],"priorities":["Do not treat resolution as reassurance that action can wait.","Make the referral immediate, with the assessment target measured from symptom onset, not a new clock starting after the GP call."],"management":[{"step":"1. Separate the emergency stroke route","detail":"If symptoms are ongoing or recur, arrange emergency stroke assessment now (999), with onset information and safe transfer. Do not use a routine TIA booking or an unassessed aspirin instruction as a substitute."},{"step":"2. Arrange immediate suspected-TIA referral","detail":"For the resolved suspected TIA in this ordinary scenario, NG128 recommends immediate referral for specialist assessment/investigation to be seen within 24 hours of symptom onset. If that window is already near or missed, arrange urgent assessment now rather than grant another 24 hours or wait for routine tests."},{"step":"3. Offer the indicated immediate antiplatelet safely","detail":"NG128 recommends aspirin 300 mg daily, started immediately for suspected TIA unless contraindicated. Check allergy, bleeding, existing antiplatelet/anticoagulant treatment and actual doses. Existing anticoagulation or another concern needs urgent patient-specific advice rather than automatic extra aspirin or delay of assessment."},{"step":"4. Avoid a score-driven delay","detail":"Do not use ABCD2 or another risk score to set referral urgency in suspected/confirmed TIA. A low score, normal current examination or a previously reassuring test is not a reason to defer the pathway."},{"step":"5. Leave investigations and secondary prevention connected","detail":"Specialists select appropriate investigations and confirm the diagnosis. NG128 does not recommend routine CT brain imaging for suspected TIA unless an alternative diagnosis detectable by CT is suspected. Arrange confirmed-TIA secondary prevention according to findings and the specialist plan, rather than an unsupported long-term aspirin/anticoagulant regimen."},{"step":"6. Confirm handover, driving and follow-up","detail":"Communicate onset, symptoms, current findings, medicines/actions and safety concerns directly, confirm acceptance and actual attendance/transport arrangements, and give a backup contact. Advise not to drive and check the relevant driver group/jurisdiction rules; GB DVLA advice is an official reference, with separate requirements elsewhere. Confirm who reviews the outcome and medicine plan."}],"discussion":[{"cue":"I am fine now. Can we just leave it?","response":"I am glad the symptoms have settled, but sudden weakness and speech difficulty can be a warning of a serious circulation problem. We need urgent specialist assessment even when you feel normal again. I will arrange the appropriate pathway now.","simple":"Resolved symptoms can still be important. I recommend urgent assessment now.","why":"Explain time-sensitive uncertainty without either confirming a TIA from the history alone or treating resolution as safety.","id":"neuro-suspected-tia-talk-1"},{"cue":"Does this mean you are certain I had a mini-stroke?","response":"It is one important possibility, and there are other causes to assess. We should act on the concern promptly while the specialist team checks the diagnosis. Waiting for certainty before arranging the referral would not be the safe approach.","simple":"It is suspected, not confirmed. We need urgent assessment to find out and reduce risk.","why":"Separate suspicion from confirmation while keeping the required action clear.","id":"neuro-suspected-tia-talk-2"},{"cue":"Why are you discussing aspirin if the symptoms have gone?","response":"In a suspected TIA, aspirin is recommended immediately when it is suitable to reduce early stroke risk. I need to check your allergy, bleeding history, current medicines and any dose already taken before confirming the actual plan.","simple":"Aspirin can reduce early risk when suitable, but we must check your medicines and contraindications first.","why":"NG128 specifies 300 mg daily for suspected TIA unless contraindicated; do not turn that into a universal self-dose instruction for active stroke or every anticoagulated patient.","id":"neuro-suspected-tia-talk-3"},{"cue":"Could I wait for my routine blood tests and scan?","response":"The specialist assessment should be arranged now and take place within twenty-four hours of when the symptoms started. Routine tests should not delay it. I will confirm the service and how you will get there; if symptoms return, call 999 immediately.","simple":"The referral is immediate, with assessment within 24 hours of onset. Do not wait for routine tests; recurrent symptoms need 999.","why":"Use onset timing and actual pathway ownership rather than a fresh 24-hour delay after referral.","id":"neuro-suspected-tia-talk-4"},{"cue":"Can I drive myself to the appointment?","response":"Please do not drive. Let’s arrange safe transport and confirm the assessment. We also need to go through the relevant driving rules for your licence and location; the advice is different for some driver groups, so I will not give a blanket return-to-driving date.","simple":"Do not drive. Let’s arrange safe transport and check the correct licence rules.","why":"Address immediate transport and subsequent licensing advice without an unsupported universal timeline.","id":"neuro-suspected-tia-talk-5"}],"variations":[{"label":"Symptoms recur during the call","change":"Weakness, facial droop or speech difficulty is present again.","action":"Arrange 999/emergency stroke assessment now, establish the current onset information and location and make the handover. Do not leave the patient in a routine TIA pathway.","phrase":"The symptoms have returned. We need emergency stroke help now; do not drive yourself."},{"label":"The patient already takes an anticoagulant","change":"There is current apixaban/warfarin or another antithrombotic issue, bleeding concern or uncertain prior doses.","action":"Do not automatically add or duplicate aspirin. Obtain urgent individual prescribing/pathway advice while maintaining immediate specialist assessment and checking the actual medicines.","phrase":"Your current treatment changes the medicine decision. I will check the urgent plan rather than simply add another blood-thinning medicine."},{"label":"A low score or late presentation is used to justify waiting","change":"The symptoms resolved, a risk score looks low or the patient presents after the first 24 hours.","action":"Do not use ABCD2 to delay referral or treat the missed target as permission for another routine wait. Arrange urgent specialist assessment now with exact onset/history and a clear safety/transport plan.","phrase":"The resolved symptoms and timing still need urgent action. We should arrange assessment now rather than rely on a score or wait for a routine slot."}],"pitfalls":["Do not call current or recurrent stroke symptoms a routine resolved TIA or wait for a score, ECG or scan before emergency action.","Do not measure the 24-hour target from referral or downgrade it using ABCD2.","Do not add unassessed aspirin to existing treatment, promise a diagnosis from the phone account or give a universal driving-return date."],"safetyNet":["Any recurrent or new FAST-type symptom needs 999 immediately, even if a previous episode resolved. Do not drive yourself.","If the urgent appointment/transfer is not confirmed or cannot happen, contact the responsible urgent team immediately; the practice must not leave the referral unowned.","Use the actual medicine plan and seek advice for bleeding or another serious adverse event; specialist confirmation determines the ongoing prevention and review plan."],"followUp":"Confirm immediate referral acceptance and actual safe assessment arrangements. Review the specialist outcome, diagnosis and secondary-prevention/medicine plan, ensure the patient understands driving advice and recurrence action, and retain named responsibility for unresolved results or referrals.","reviewed":"2026-11-13","tags":["TIA","stroke","FAST","aspirin","ABCD2","24 hours","driving","transient weakness"],"links":[{"label":"NICE NG128: stroke and TIA","url":"https://www.nice.org.uk/guidance/ng128","use":"Immediate aspirin/referral, onset-based timing, scores and investigations."},{"label":"NHS: TIA","url":"https://www.nhs.uk/conditions/transient-ischaemic-attack-tia/","use":"Patient explanation and emergency FAST advice."},{"label":"GOV.UK: TIA and driving (GB DVLA)","url":"https://www.gov.uk/transient-ischaemic-attacks-and-driving","use":"Current licence-group restrictions and notification advice for Great Britain; check the relevant jurisdiction."}],"retrieval":{"question":"How does the plan differ when focal symptoms have resolved completely versus when they recur now?","answer":"For a suspected resolved TIA, refer immediately for specialist assessment within 24 hours of onset and offer suitable immediate aspirin after checks. Current/recurrent stroke symptoms need emergency stroke assessment now. Do not use ABCD2, symptom resolution, routine tests or a missed target to justify delay.","checks":["Distinguished current stroke from resolved suspected TIA","Used onset timing and checked immediate treatment suitability","Confirmed urgent handover, transport and recurrence action"]}}]},{"id":"hearing-eyes-balance","title":"Hearing, eyes and balance","description":"Sudden hearing loss, red eye and brief positional vertigo: communication, safe treatment and urgent changes, each with three variations.","icon":"10","reviewed":"2026-11-13","cases":[{"id":"sense-sudden-hearing-loss","title":"Sudden hearing loss: explain why assessment cannot wait","summary":"Distinguish unexplained sudden loss from a routine hearing-aid or wax pathway and confirm urgent arrangements.","presentation":"A 57-year-old noticed a major reduction in hearing in one ear yesterday, with tinnitus. Appropriate assessment has not found an external or middle-ear explanation in this ordinary scenario. There is no current focal neurological deficit or acute instability. They ask for drops and a routine hearing test.","assessment":["Clarify the exact onset and speed, one/both ears, previous baseline, tinnitus, vertigo, ear pain/discharge, trauma, noise and medicine exposures. Ask about the effect on communication and function.","Assess the ear and hearing appropriately, including otoscopy and tests within competence; do not assume a wax or middle-ear cause from the word “blocked”. Do not wait for a routine audiogram if urgent referral is indicated.","Check new neurological symptoms, facial weakness/sensory change, severe vertigo/unsteadiness and systemic illness. A suspected stroke or other acute danger changes the route immediately.","Review comorbidity and medicine risks, communication needs, transport/support and how the patient can receive urgent instructions when hearing is impaired."],"priorities":["Use the onset pattern and current findings to select the pathway now.","Make referral, communication and attendance real rather than give a routine test request alone."],"management":[{"step":"1. Identify the time-sensitive presentation","detail":"NG98 recommends immediate referral for unexplained sudden hearing loss developing over three days or less within the past thirty days, to be seen within twenty-four hours by ENT or an emergency department. This ordinary scenario meets that urgent pattern."},{"step":"2. Assess associated danger","detail":"New focal neurological signs or suspected stroke require the local emergency stroke pathway rather than waiting for routine ENT. Assess serious infection or other acute illness as appropriate."},{"step":"3. Explain without a premature diagnosis","detail":"Explain that there are several causes and the current examination does not establish a simple external/middle-ear explanation. Some inner-ear causes need time-sensitive assessment/treatment; do not promise recovery or diagnose the exact cause without the necessary assessment."},{"step":"4. Confirm the receiving service and safe access","detail":"Contact the appropriate urgent ENT/emergency pathway, communicate onset and findings and confirm what happens next. Check accessible instructions, a safe contact method and transport; do not let a routine audiology waiting list delay the indicated assessment."},{"step":"5. Leave treatment linked to assessment","detail":"NG98 says to consider a steroid for idiopathic sudden sensorineural hearing loss in adults. The actual diagnosis, suitability, route/dose and monitoring require the appropriate clinician’s decision; do not prescribe a universal course or delay referral while trying drops or waiting for a steroid response."},{"step":"6. Use the correct later-presentation pathways","detail":"Unexplained sudden loss beginning more than thirty days ago, or rapid worsening over four to ninety days, needs urgent referral to be seen within two weeks under NG98. Additional symptoms can justify more immediate action; do not apply that longer route to this acute ordinary scenario."}],"discussion":[{"cue":"It feels blocked. Can we try wax drops for a week?","response":"A blocked feeling does not always mean wax. The assessment has not shown a simple explanation, and the sudden change means we should arrange urgent specialist assessment rather than wait to see what drops do.","simple":"The sudden change needs urgent assessment; we should not assume wax or wait a week.","why":"Connect the recommendation to the onset and assessed findings rather than a symptom label.","id":"sense-sudden-hearing-loss-talk-1"},{"cue":"Why is this urgent if I do not have pain?","response":"The speed of the hearing change matters even without pain. Some causes need treatment quickly, so I recommend the urgent ENT pathway, with assessment within twenty-four hours. I will confirm the arrangements now.","simple":"Sudden hearing loss can need quick treatment even without pain. Let’s arrange urgent assessment.","why":"Explain the time-sensitive pattern without promising a particular diagnosis or recovery.","id":"sense-sudden-hearing-loss-talk-2"},{"cue":"Should I book a hearing aid test first?","response":"A hearing test may be part of the assessment, but the routine hearing-aid route should not delay this. I will use the appropriate urgent service and explain the onset and examination findings to them.","simple":"We should use the urgent service rather than wait for a routine hearing-aid appointment.","why":"Distinguish chronic rehabilitation from the immediate unexplained sudden-loss pathway.","id":"sense-sudden-hearing-loss-talk-3"},{"cue":"Will steroids definitely bring the hearing back?","response":"I cannot promise that. A specialist needs to assess the cause and whether steroid treatment is appropriate. We should discuss expected benefit, possible harms and your other health conditions, while keeping the assessment prompt.","simple":"We cannot guarantee recovery. The team will assess whether treatment is suitable and explain benefits and risks.","why":"Keep uncertainty honest and avoid a universal steroid regimen.","id":"sense-sudden-hearing-loss-talk-4"},{"cue":"I may not hear the appointment details on the phone.","response":"What is the safest way for you to receive them? We can use an accessible written arrangement or a trusted supporter with your agreement, and confirm you know where to go, when and who to contact if the plan does not happen.","simple":"Let’s confirm accessible instructions, the appointment and a backup contact you can use.","why":"Use communication needs to change the arrangement; an unheard telephone message is not an adequate handover.","id":"sense-sudden-hearing-loss-talk-5"}],"variations":[{"label":"New facial or other neurological symptoms","change":"There is new facial droop/sensory change or another focal sign, especially with acute vertigo or unsteadiness.","action":"Reassess immediately for stroke and other urgent causes. Use the emergency stroke pathway when suspected rather than wait for routine ENT or audiology.","phrase":"The new neurological symptoms change the urgency. We need emergency assessment now."},{"label":"Sudden loss began more than thirty days ago","change":"The change was sudden but occurred more than thirty days ago, with no new immediate danger.","action":"NG98 recommends urgent ENT/audiovestibular referral to be seen within two weeks when the loss is not explained by external/middle-ear causes. Reassess if additional warning symptoms are present.","phrase":"The timing affects the referral route, but this still needs an urgent specialist assessment rather than an indefinite routine wait."},{"label":"Treatment risks need extra planning","change":"The person has diabetes or another condition/medicine risk relevant to a possible steroid course.","action":"Keep urgent referral active and communicate the comorbidity. The treating clinician must individualise suitability and monitoring rather than use an unassessed standard prescription.","phrase":"Your other treatment matters to what is safe. I will include it in the urgent handover so the medicine plan and monitoring are appropriate."}],"pitfalls":["Do not assume wax from a blocked sensation or use absence of pain to dismiss sudden loss.","Do not let a routine audiogram, drops trial or unconfirmed referral delay the indicated urgent assessment.","Do not promise recovery or a universal steroid dose; use the actual diagnosis and medicine-risk checks."],"safetyNet":["New stroke-type symptoms, severe acute neurological change or serious illness needs emergency help; do not drive yourself if emergency transfer is needed.","If urgent assessment or contact is not confirmed, contact the responsible urgent service immediately rather than wait without a plan.","Check that instructions and safety advice are accessible to the person and confirm any supporter involvement with appropriate agreement."],"followUp":"Confirm urgent assessment has been accepted and can be attended. Track the outcome and treatment plan, then coordinate any ongoing hearing/communication support. Reassess new symptoms or failed contact immediately.","reviewed":"2026-11-13","tags":["sudden hearing loss","tinnitus","ENT","24 hours","steroid","communication"],"links":[{"label":"NICE NG98: adult hearing loss","url":"https://www.nice.org.uk/guidance/ng98","use":"Sudden/rapid-loss referral criteria, associated signs and treatment considerations."},{"label":"NHS: hearing loss","url":"https://www.nhs.uk/conditions/hearing-loss/","use":"Patient information and urgent help-seeking."}],"retrieval":{"question":"What makes unexplained sudden hearing loss different from a routine hearing-aid referral?","answer":"Establish onset and findings, exclude an external/middle-ear explanation and assess associated neurological danger. Sudden loss over three days or less within the past thirty days needs immediate referral to be seen within twenty-four hours. Confirm accessible attendance and handover rather than wait for routine testing.","checks":["Used the actual onset and assessed findings","Recognised associated emergency signs","Confirmed timely accessible referral ownership"]}},{"id":"sense-red-eye","title":"Red eye: safe assessment before calling it conjunctivitis","summary":"Explain a proportionate plan for an assessed mild presentation and recognise vision-threatening changes.","presentation":"A 29-year-old has two days of bilateral gritty, watery red eyes after a cold. An appropriate assessment finds no significant pain, photophobia, vision change, injury or contact-lens use, and supports uncomplicated conjunctivitis in this ordinary scenario. They request antibiotic drops and a work-exclusion letter.","assessment":["Clarify one/both eyes, onset, pain, photophobia, vision changes, discharge/itching, trauma/chemical exposure, contact lenses, systemic symptoms and relevant history. Assess vision and examine appropriately.","Painful red eye, vision change, marked light sensitivity, severe headache/nausea, pupil change or injury needs a different urgent/emergency assessment. Do not diagnose conjunctivitis from redness alone or a remote photo without the necessary checks.","A red eye in a contact-lens wearer needs urgent assessment for a possible infection; do not apply the ordinary no-contact-lens scenario automatically.","Consider infectious, allergic and other causes, exposure and patient priorities. Persistent or atypical symptoms, relevant sexual history or a vulnerable patient may change investigation and treatment."],"priorities":["Protect vision by establishing whether this is an urgent eye problem first.","Offer a cause-appropriate plan and specific review rather than automatic antibiotic drops or reassurance."],"management":[{"step":"1. Select the urgency from the eye assessment","detail":"Arrange urgent ophthalmic/emergency assessment for concerning pain, photophobia, reduced/changed vision, serious injury or other red flags, using the actual local pathway. Do not delay while trying routine conjunctivitis treatment."},{"step":"2. Explain the ordinary working diagnosis","detail":"In this assessed mild scenario, explain conjunctival irritation/inflammation and the likely cause without guaranteeing every red eye is harmless. Reassess if the symptoms change."},{"step":"3. Offer suitable self-care and symptom support","detail":"Discuss avoiding rubbing, hand hygiene, separate towels/pillows and appropriate comfort/cleaning advice. Do not wear contact lenses while eyes are affected; a new red/contact-lens presentation needs urgent review."},{"step":"4. Choose treatment by likely cause","detail":"Antibiotics may be used for an appropriate bacterial cause but do not treat viral or allergic conjunctivitis. Check actual suitability, allergy and the diagnosis rather than prescribe for every red eye. Do not use unassessed steroid eye drops or someone else’s treatment."},{"step":"5. Give realistic work and contact advice","detail":"NHS advice does not require routine school/work absence for conjunctivitis unless the person is very unwell. Explain hygiene and check any relevant occupational/infection-control requirements rather than issue a universal exclusion period."},{"step":"6. Agree reassessment","detail":"Seek review if symptoms have not cleared within seven days, as in NHS advice, or sooner for worsening/changed features. New pain, photophobia or vision change should not wait for that review date."}],"discussion":[{"cue":"Can you just give antibiotic drops to be safe?","response":"The treatment depends on the cause. Antibiotics can help an appropriate bacterial infection, but not a virus or allergy. Your assessment today allows us to discuss a proportionate plan, with clear advice about what would need another assessment.","simple":"Antibiotics do not help every cause. Let’s choose treatment from the assessment and agree when to review.","why":"Answer the request with a positive plan and the reason rather than use antibiotics as generic reassurance.","id":"sense-red-eye-talk-1"},{"cue":"How do you know it is not something dangerous?","response":"I have checked the symptoms and findings that would change the urgency, including pain, light sensitivity and vision. Those checks support today’s working plan, but new symptoms would need reassessment rather than assume the diagnosis can never change.","simple":"The assessment supports today’s plan. New pain, light sensitivity or vision change needs reassessment.","why":"Explain the basis and limits of reassurance, not a guarantee from a single appearance.","id":"sense-red-eye-talk-2"},{"cue":"Can I use the steroid drops a relative has?","response":"Please do not use someone else’s eye medicine. The correct treatment depends on the actual cause, and some drops need a specialist diagnosis and monitoring. We should agree what is suitable for you.","simple":"Please do not share eye drops. Let’s choose treatment for your actual assessment.","why":"Avoid an unassessed steroid or borrowed prescription that could worsen or mask another eye condition.","id":"sense-red-eye-talk-3"},{"cue":"Do I need to stay away from work until every bit of redness has gone?","response":"For ordinary conjunctivitis, routine absence is not usually required unless you are very unwell. Hand hygiene and not sharing towels matter. We should check any specific workplace rules if your role has particular infection-control needs.","simple":"Routine absence is not usually needed if you are well, but use good hygiene and check relevant work requirements.","why":"Use current NHS advice while keeping occupational context visible; do not promise a universal clearance date.","id":"sense-red-eye-talk-4"},{"cue":"When should I ask for help again?","response":"If it has not cleared within seven days, arrange a review. Do not wait if you develop pain, sensitivity to light, a change in vision or another worrying change; that needs a prompt urgent eye assessment.","simple":"Review if not cleared in seven days; new pain, light sensitivity or vision change needs urgent help sooner.","why":"Give a specific review and changed-symptom route instead of only “if worse”.","id":"sense-red-eye-talk-5"}],"variations":[{"label":"Contact lens use with pain or light sensitivity","change":"A contact-lens wearer develops a red eye with pain, photophobia or reduced vision.","action":"Arrange urgent/emergency eye assessment for a potentially serious corneal/other cause. Do not treat as routine conjunctivitis or wait to see whether simple drops work.","phrase":"The contact lenses and new symptoms change the assessment. We need urgent eye care rather than routine drops."},{"label":"Strong chemical exposure","change":"A cleaning chemical such as bleach has entered the eye.","action":"Start immediate copious irrigation with clean water, keep rinsing for at least twenty minutes with a gentle flow, and arrange emergency assessment while doing so. Do not delay irrigation for a routine history or travel; follow the emergency service advice.","phrase":"Start rinsing the eye with plenty of clean water now and keep going while we arrange emergency help."},{"label":"Vision change or a painful light-sensitive eye","change":"New visual disturbance, severe headache/nausea, abnormal pupil or significant pain/photophobia appears.","action":"Use the urgent eye/emergency pathway now rather than repeat the old conjunctivitis label. Establish safe transport and handover.","phrase":"The change in vision or pain needs a new urgent assessment. Please do not wait for the routine review or drive yourself if your vision is affected."}],"pitfalls":["Do not label every red eye conjunctivitis or miss contact-lens, injury and vision-risk questions.","Do not use antibiotics for every cause or recommend unassessed steroid/borrowed eye drops.","Do not give a routine wait-and-see plan for new vision changes, light sensitivity, significant pain or chemical injury."],"safetyNet":["New vision change, painful light sensitivity, severe headache/nausea, pupil abnormality or serious injury requires urgent/emergency eye assessment.","For strong chemical exposure, begin immediate irrigation and arrange emergency help; do not wait for a routine appointment.","If an assessed uncomplicated case does not clear within seven days, seek review; worsening or warning symptoms need earlier assessment."],"followUp":"Agree the actual symptom/treatment plan and review if not cleared within seven days, earlier when symptoms change. Check correct use and any treatment harms; track any urgent eye referral and safe attendance.","reviewed":"2026-11-13","tags":["red eye","conjunctivitis","contact lenses","photophobia","vision","chemical injury","antibiotic drops"],"links":[{"label":"NHS: red eye","url":"https://www.nhs.uk/symptoms/red-eye/","use":"Assessment warning features and urgent/emergency advice."},{"label":"NHS: conjunctivitis","url":"https://www.nhs.uk/conditions/conjunctivitis/","use":"Treatment by cause, self-care, work and review advice."},{"label":"NHS: eye injuries","url":"https://www.nhs.uk/conditions/eye-injuries/","use":"Chemical injury, immediate irrigation and emergency care."},{"label":"NHS: dexamethasone eye drops","url":"https://www.nhs.uk/medicines/dexamethasone-eye-drops/","use":"Prescription use, suitability checks and potential pressure/other adverse effects."}],"retrieval":{"question":"What must you establish before offering a routine conjunctivitis plan, and what changes would make that plan unsafe?","answer":"Assess vision, pain, photophobia, contact lenses, injury/chemicals and the other relevant findings. An uncomplicated assessed presentation can use cause-appropriate care and review. New vision/pain/light-sensitivity findings or a contact-lens complication changes urgency; chemical injury needs immediate irrigation and emergency care.","checks":["Checked the vision-threatening features and context","Matched treatment to the assessed cause","Specified early-help, injury action and review"]}},{"id":"sense-positional-vertigo","title":"Brief positional vertigo: explain BPPV without missing a changed syndrome","summary":"Use the pattern and trained assessment, discuss a suitable repositioning manoeuvre and recognise acute vestibular danger.","presentation":"A 61-year-old has brief spinning attacks triggered by rolling in bed, lasting seconds and settling between attacks. A trained clinician has assessed the presentation and a Hallpike manoeuvre supports BPPV in this ordinary scenario. There is no new hearing loss, focal neurological feature, persistent severe vertigo or unstable cervical spine disease.","assessment":["Clarify timing, triggers, duration and whether symptoms fully settle; distinguish vertigo, faintness and imbalance. Ask about new hearing symptoms, headache, injury, medicines and falls.","Assess gait and neurological findings as appropriate. Sudden persistent vertigo/nausea with unsteadiness, new focal symptoms or new deafness needs assessment for a different and potentially urgent cause.","For transient rotational vertigo on head movement, NG127 recommends Hallpike testing by a trained professional, or referral when that expertise is unavailable. Do not diagnose BPPV merely because moving the head worsens dizziness.","Check neck/cervical safety, ability to tolerate an appropriate manoeuvre, falls risk, daily tasks, driving/occupation and the practical support available."],"priorities":["Confirm the appropriate assessed syndrome instead of applying a BPPV label to all dizziness.","Offer the indicated trained treatment and clear advice about symptoms that would change the plan."],"management":[{"step":"1. Recognise a changed emergency presentation","detail":"Sudden acute vestibular syndrome or focal/serious neurological findings requires assessment for posterior-circulation stroke and other acute causes. A previous BPPV diagnosis does not explain every new episode."},{"step":"2. Use diagnostic tests within competence","detail":"Hallpike is for the relevant transient positional presentation and should be performed by a trained professional. HINTS is a different assessment for acute vestibular syndrome and requires specific training and experience; it is not a home screen or a substitute for the correct pathway."},{"step":"3. Explain the ordinary BPPV assessment","detail":"Describe a position-triggered inner-ear balance problem using the actual pattern and findings. Explain that the diagnosis comes from assessment, not simply from the fact that movement causes symptoms."},{"step":"4. Offer suitable repositioning treatment","detail":"When BPPV is diagnosed, offer a canalith repositioning manoeuvre such as Epley if a trained professional is available and there is no unstable cervical spine disease. If expertise is unavailable or cervical instability is present, use the appropriate referral pathway rather than attempt an unsafe manoeuvre."},{"step":"5. Make daily safety practical","detail":"Discuss falls prevention, support during attacks and safe daily activity. Avoid driving, machinery or other dangerous tasks while dizzy or unsteady; check relevant occupational/licensing advice for the actual situation. Do not make a blanket fitness-to-drive promise."},{"step":"6. Review response and reconsider persistent symptoms","detail":"Confirm how to return if treatment does not help or symptoms recur. Reassess the pattern, diagnosis and risks rather than indefinitely repeat vestibular-suppressant prescriptions or assume every episode is BPPV."}],"discussion":[{"cue":"If turning my head triggers it, does that prove it is harmless?","response":"No. The timing, examination and other symptoms matter too. Your assessment supports BPPV today, but a new pattern, persistent severe symptoms or neurological changes would need a different assessment.","simple":"Movement alone does not prove the cause. The assessment supports today’s plan, and new features change it.","why":"Avoid an unsafe positional-equals-benign rule.","id":"sense-positional-vertigo-talk-1"},{"cue":"What is actually causing the spinning in BPPV?","response":"In BPPV, small particles in the inner ear can move into a position that triggers the balance system when the head moves. An appropriate repositioning manoeuvre aims to move them, which is why a trained treatment may help.","simple":"BPPV is an inner-ear balance problem that can respond to an appropriate repositioning manoeuvre.","why":"Explain the proposed treatment’s purpose in plain language without claiming every dizzy episode has this mechanism.","id":"sense-positional-vertigo-talk-2"},{"cue":"Can I just do an internet Epley manoeuvre even with my neck problems?","response":"We should check the diagnosis and whether the manoeuvre is safe for your neck first. It should be performed or advised by someone with the right training. With unstable cervical spine disease or another concern, we need the appropriate alternative referral.","simple":"Let’s check the diagnosis and neck safety with a trained professional before trying it.","why":"Apply NG127’s competence and cervical-spine requirements rather than a universal self-treatment instruction.","id":"sense-positional-vertigo-talk-3"},{"cue":"Would tablets fix it more reliably?","response":"The appropriate repositioning treatment addresses the BPPV mechanism. Medicines do not replace the need for the correct assessment and manoeuvre. We should review any symptom treatment individually rather than leave you on repeated tablets without checking what is happening.","simple":"The right manoeuvre can treat BPPV. Tablets should not replace diagnosis, suitable treatment and review.","why":"Offer a positive cause-appropriate plan instead of an indefinite sedating prescription.","id":"sense-positional-vertigo-talk-4"},{"cue":"What should make me seek help rather than wait for the exercises?","response":"New trouble speaking, double or lost vision, limb weakness or severe new imbalance needs emergency help. New hearing loss with sudden vertigo, or a sudden persistent different pattern, also needs immediate assessment. Do not assume those are the usual short BPPV attacks.","simple":"New neurological symptoms, hearing loss with sudden vertigo or a sudden persistent different pattern needs immediate assessment, not just another exercise.","why":"Distinguish a familiar assessed brief trigger from a changed acute vestibular/neurological syndrome and give the correct route.","id":"sense-positional-vertigo-talk-5"}],"variations":[{"label":"Sudden persistent vertigo and severe unsteadiness","change":"The spinning no longer settles and is accompanied by vomiting, marked gait difficulty or new neurological symptoms.","action":"Assess for acute vestibular syndrome/posterior stroke. NG127 recommends immediate stroke-pathway referral when BPPV/postural hypotension does not explain it and suitably trained HINTS expertise is unavailable; stroke-indicating HINTS requires immediate imaging. Do not use an untrained test to reassure.","phrase":"This is a different pattern from the brief attacks. We need urgent assessment now rather than assume it is BPPV."},{"label":"Unstable cervical spine disease or no trained practitioner","change":"The person cannot safely undergo a repositioning manoeuvre, or the required training is not available.","action":"Do not attempt an unassessed manoeuvre. Refer through the appropriate local pathway for safe assessment/treatment.","phrase":"The manoeuvre needs the right training and must be safe for your neck. Let’s arrange the appropriate service."},{"label":"Episodes last longer and there is recurrent migraine","change":"Dizziness lasts minutes to hours with a recurrent headache history, rather than the ordinary brief positional pattern.","action":"Reassess the differential, including vestibular migraine, while checking for urgent neurological features. Do not automatically repeat BPPV treatment or assume migraine explains new danger signs.","phrase":"The duration and headache history change what we should consider. Let’s reassess the pattern before choosing the next treatment."}],"pitfalls":["Do not diagnose BPPV only because head movement makes dizziness worse or because there was a previous episode.","Do not use HINTS without the required training or for the wrong syndrome.","Do not attempt a manoeuvre with unstable cervical disease or continue repeated medicines without reassessing persistent symptoms."],"safetyNet":["New speech, visual or limb neurological symptoms, severe new gait disturbance or another suspected stroke presentation needs emergency assessment; do not drive yourself.","Acute vertigo with new hearing loss or a sudden persistent different pattern needs immediate assessment through the appropriate acute medical/stroke pathway; do not wait for routine manoeuvre review.","Return if the manoeuvre fails, attacks recur, falls occur or the pattern changes; agree a named review/contact rather than only “try the exercises again”."],"followUp":"Agree review of symptom response and daily function after the actual intervention, with earlier help for changed features. Reassess persistent/recurrent symptoms, neck safety, falls and the diagnosis, and track any specialist referral.","reviewed":"2026-11-13","tags":["vertigo","BPPV","Hallpike","Epley","HINTS","balance","stroke","cervical spine"],"links":[{"label":"NICE NG127: adult dizziness and vertigo","url":"https://www.nice.org.uk/guidance/ng127/chapter/recommendations-for-adults-aged-over-16","use":"Trained assessment, BPPV manoeuvres, cervical safety and acute vestibular/stroke pathways."},{"label":"NHS: vertigo","url":"https://www.nhs.uk/conditions/vertigo/","use":"Patient explanation, activity safety and emergency features."}],"retrieval":{"question":"How does a brief, assessed BPPV presentation differ from acute persistent vertigo with severe new unsteadiness?","answer":"Use the timing, triggers and examination. Appropriate BPPV can have trained Hallpike assessment and suitable repositioning if cervical safety allows. Acute vestibular/neurological change needs the appropriate urgent stroke/medical pathway; HINTS requires trained expertise in the correct syndrome and is not a general reassurance test.","checks":["Distinguished the syndromes using assessment","Applied competence and cervical-safety checks","Named urgent changes and review ownership"]}}]},{"id":"renal-urinary","title":"Kidney and urinary health","description":"Kidney results, uncomplicated lower UTI and visible haematuria: assessment, medicine decisions, urgent changes and clear follow-up, each with three variations.","icon":"11","reviewed":"2026-11-14","cases":[{"id":"renal-reduced-egfr","title":"A first reduced eGFR: confirm the pattern before labelling CKD","summary":"Explain the result, check acute danger, arrange repeat blood/urine assessment and retain follow-up ownership.","presentation":"A 55-year-old’s first available kidney blood result gives an eGFR of 52 ml/min/1.73 m². They feel well and are frightened by an online result labelled “low”. Appropriate review finds no acute illness, reduced urine output or other urgent laboratory alert in this ordinary scenario. Prior results and urine ACR are not yet available.","assessment":["Review the whole result and clinical state, not eGFR alone: current illness, urine output, dehydration, obstruction symptoms, other laboratory abnormalities, blood pressure and relevant examination. Suspected acute kidney injury or serious illness needs the appropriate urgent pathway.","Look for earlier results and the time course. One low result does not establish chronicity, stage progression or the person’s long-term risk. Consider factors affecting the estimate and the clinical context.","Review diabetes, hypertension, cardiovascular disease, urinary findings, family history and other causes/risk factors. Arrange urine ACR and appropriate urine/blood assessment rather than use a dipstick alone to quantify albumin.","Reconcile actual prescribed and over-the-counter medicines, including NSAIDs, recent changes and intercurrent illness. Explore what the person thinks the result means and what would make testing or review difficult."],"priorities":["Distinguish an acute concern from the stable first-result scenario before offering reassurance or a routine repeat.","Make the confirmation tests, result ownership and next review explicit; do not diagnose lifelong CKD or predict dialysis from one number."],"management":[{"step":"1. Assess the current urgency","detail":"Check symptoms, the whole renal profile, prior results and relevant findings. Acute illness, oliguria, obstruction or serious biochemical disturbance needs prompt urgent/emergency assessment according to severity. The ordinary asymptomatic result is not a substitute for these checks."},{"step":"2. Explain what the estimate does and does not show","detail":"Describe eGFR as an estimate of the kidneys’ filtering function. Explain that this result needs follow-up, but one value does not establish a chronic diagnosis or mean the person needs dialysis. Avoid interpreting it as an exact percentage of kidneys working."},{"step":"3. Confirm the new reduction promptly","detail":"NG203 recommends repeating a first eGFR below 60 within two weeks, to confirm it and help exclude an acute deterioration. Use earlier assessment when the clinical picture requires it. Search for prior results; CKD involves abnormalities persisting for more than three months, not a label from one blood test."},{"step":"4. Assess urine albumin and the wider pattern","detail":"Use urine ACR. An ACR from 3 to below 70 mg/mmol needs confirmation in a subsequent early-morning sample; an initial ACR at least 70 does not need that repeat to establish the finding. Assess blood in urine and other relevant causes. Confirmed ACR at least 3 is clinically important under NG203."},{"step":"5. Review medicines and modifiable risk safely","detail":"Check NSAIDs and other potential contributors, blood pressure, diabetes and cardiovascular needs. Do not tell the person to stop every medicine or make a permanent prescribing change from eGFR alone. If renin–angiotensin system treatment is indicated/started in confirmed CKD, check potassium/eGFR before it and again 1–2 weeks after starting and each dose increase, with individual suitability checks."},{"step":"6. Discuss classification, risk and referral when supported by the findings","detail":"If CKD is established, use eGFR and ACR together, trends and the appropriate four-variable Kidney Failure Risk Equation to explain risk in plain language. Use the current NG203 referral criteria; examples include five-year renal-replacement risk greater than 5%, ACR over 30 with haematuria, or sustained concerning decline. Do not use an unstable acute result to invent a reassuring long-term risk."},{"step":"7. Close the test and review loop","detail":"Book the actual repeat and urine arrangements, name who reviews them and how/when results are communicated. Confirm what the patient does if contact fails and how to seek earlier assessment. Subsequent monitoring and treatment depend on the confirmed pattern and risk, not a universal annual repeat for everyone."}],"discussion":[{"cue":"Does this mean my kidneys are failing?","response":"It shows a lower estimate of filtering function that needs checking. It does not tell us the whole story from one test or mean that dialysis is needed. I want to check the context, repeat the blood test and look at the urine result before we make a longer-term plan.","simple":"One low result needs follow-up, but does not by itself establish chronic kidney disease or a need for dialysis.","why":"Acknowledge the concern without either dismissing the result or attaching a chronic/end-stage label prematurely.","id":"renal-reduced-egfr-talk-1"},{"cue":"Why repeat it if you already have a number?","response":"Kidney results can change with illness, medicines and normal variation. Because this is a new low result, we should repeat it within two weeks in this stable situation, sooner if you become unwell. That helps us decide what is persistent and what needs another pathway.","simple":"A prompt repeat helps confirm the pattern and check for an acute change. We should not wait if you become unwell.","why":"Connect NG203’s confirmation window to actual urgency rather than make every patient wait two weeks.","id":"renal-reduced-egfr-talk-2"},{"cue":"Why do you want a urine test as well?","response":"The blood estimate and urine albumin tell us different things. Albumin in the urine can help us understand kidney damage and risk, so the two results together are more useful for choosing the next steps.","simple":"The urine and blood results give different information. We need both to understand the pattern and risk.","why":"Explain the purpose of ACR rather than order an unexplained sample or imply the eGFR alone gives a complete stage/risk assessment.","id":"renal-reduced-egfr-talk-3"},{"cue":"Should I stop all my blood-pressure and pain tablets?","response":"Please do not stop everything. Let’s check exactly what you take, including medicines you buy, and whether any recent change or illness matters. We can then make targeted changes and arrange the appropriate blood checks rather than guess.","simple":"Let’s review the actual medicines and make targeted changes with monitoring, rather than stop everything.","why":"Balance potential nephrotoxicity, beneficial treatment and monitoring; do not apply a blanket medicine stop rule.","id":"renal-reduced-egfr-talk-4"},{"cue":"Who will tell me what the next results mean?","response":"The practice will review the repeat blood and urine results and contact you by the date we agree. We will explain whether more tests, monitoring or specialist advice is needed. If you have not heard, contact us as a backup; we remain responsible for checking the results.","simple":"We will review and contact you by the agreed date, then explain the next step. Call if contact is missed; we still need to follow it up.","why":"Retain clinical ownership and a real communication plan rather than transfer responsibility to an online result or patient chasing alone.","id":"renal-reduced-egfr-talk-5"}],"variations":[{"label":"Acute illness or reduced urine output","change":"Vomiting/diarrhoea, dehydration, reduced urine, obstruction symptoms or a serious laboratory abnormality appears.","action":"Reassess urgently for acute kidney injury, obstruction or other serious illness. Do not wait for the routine two-week repeat or give an unassessed fixed fluid/medicine plan.","phrase":"The new symptoms change the urgency. We need to assess this now rather than wait for the planned repeat."},{"label":"Albumin and blood change the risk","change":"Further assessment shows marked albuminuria, haematuria or a sustained concerning decline.","action":"Use the full NG203 and relevant urinary/cancer assessment pathways, with specialist advice/referral when indicated. Examples include ACR over 30 with haematuria or other referral criteria; assess urgency and do not assume routine annual monitoring is enough.","phrase":"These findings change what we need to investigate and who should be involved. Let’s arrange the appropriate next assessment."},{"label":"A recent medicine change may contribute","change":"The review identifies a new NSAID, a recent kidney/BP medicine change or another potential contributor.","action":"Review timing, the actual drug and indication, potassium and creatinine/eGFR trends. Make an individual prescribing/monitoring plan; do not automatically stop every beneficial medicine or ignore an acute deterioration.","phrase":"The medicine history matters. Let’s check the actual treatment and blood results before deciding what should change."}],"pitfalls":["Do not diagnose chronicity, a fixed progression rate or a dialysis need from one eGFR.","Do not use the two-week confirmation window to delay assessment of acute illness, obstruction or a serious biochemical finding.","Do not prescribe from eGFR alone, ignore urine albumin or leave significant results without named follow-up."],"safetyNet":["Reduced urine, significant acute illness, dehydration, obstruction symptoms or serious deterioration needs prompt urgent assessment; severe illness needs emergency help.","Do not wait for the routine repeat if new concerning symptoms or an urgent result appears.","If tests cannot be completed or the agreed contact is missed, contact the practice; the clinical team must track unresolved significant results."],"followUp":"Arrange the repeat blood result within two weeks in the supplied stable first-result scenario, with appropriate urine ACR and review. Communicate findings and the next plan using a named clinician/team; tailor later monitoring/referral to the confirmed pattern and risk. Acute concerns need earlier action.","reviewed":"2026-11-13","tags":["eGFR","CKD","kidney function","ACR","repeat blood test","medicine review","results ownership"],"links":[{"label":"NICE NG203: chronic kidney disease","url":"https://www.nice.org.uk/guidance/ng203","use":"Confirmation, ACR, chronicity, risk/referral and medicine monitoring."},{"label":"NHS: kidney disease diagnosis","url":"https://www.nhs.uk/conditions/kidney-disease/diagnosis/","use":"Patient explanation of blood and urine assessment."},{"label":"NICE NG12: urinary cancer warning pathways","url":"https://www.nice.org.uk/guidance/ng12","use":"Use the relevant pathway when haematuria or other findings raise concern."}],"retrieval":{"question":"What would you say and arrange after a first eGFR of 52 in a stable person, and what would make you act sooner?","answer":"Explain the estimate and uncertainty, check the full result/context and prior records, arrange repeat blood within two weeks and urine ACR, review medicines and name result ownership. New acute illness, reduced urine, obstruction or serious laboratory findings changes urgency; do not wait or label chronic kidney disease from one result.","checks":["Distinguished the stable first result from acute danger","Arranged confirmation and urine/medicine assessment","Named results review, contingency and possible next steps"]}},{"id":"renal-lower-uti","title":"Lower UTI: a treatment choice that fits the actual patient","summary":"Distinguish uncomplicated lower symptoms from pregnancy, upper infection and prescribing risks; agree clear action and review.","presentation":"A 26-year-old woman who is not pregnant has two days of dysuria and urinary frequency affecting daily activities. Appropriate assessment supports an uncomplicated lower UTI, without fever, flank pain, vomiting, vaginal symptoms or systemic illness in this ordinary scenario. Prescribing suitability, including renal considerations, is reviewed before choosing treatment.","assessment":["Clarify dysuria, frequency/urgency, duration, haematuria, lower abdominal discomfort and the effect on daily life. Consider vaginal/urethral and other causes, including relevant sexual-health needs, rather than diagnose from urine appearance alone.","Ask about fever/shivering, flank/back pain, vomiting, serious illness and ability to drink; these may indicate upper infection or a complication. Assess for sepsis or acute danger when appropriate.","Establish pregnancy possibility, age, relevant urinary abnormalities, recurrence, immunosuppression, diabetes, kidney function when relevant, allergy, actual medicines, recent antibiotics and previous culture results.","Use the appropriate current urine-testing strategy for the population and presentation. If sending culture, explain the collection and who checks it. Pregnancy and men require a pre-antibiotic midstream sample for culture under NG109; do not copy this ordinary non-pregnant case into those pathways."],"priorities":["Choose the actual population, severity and urgency before applying an antibiotic regimen.","Make immediate versus back-up treatment, the actual prescription and earlier-help triggers understandable."],"management":[{"step":"1. Select the correct pathway","detail":"The ordinary scenario has lower symptoms without pregnancy or systemic/upper-UTI features. Suspected pyelonephritis, sepsis, pregnancy or another complicated context needs its own assessment and treatment, not an automatic three-day lower-UTI prescription."},{"step":"2. Discuss a clear antibiotic strategy","detail":"For non-pregnant women with lower UTI, NG109 supports an immediate or back-up prescription, chosen using severity, complication risk, previous results/antibiotics and preference. A back-up is used if symptoms do not start improving within 48 hours or worsen, with separate earlier-help advice for significant deterioration/systemic illness."},{"step":"3. Check the actual medicine and course","detail":"Use current NG109/local guidance and the actual contraindications, renal/pregnancy considerations, interactions and resistance history. As a specific guideline example only for suitable non-pregnant adult women with lower UTI and eGFR at least 45 ml/minute, nitrofurantoin modified-release 100 mg twice daily for 3 days is a first-choice option. This is not the regimen for every UTI or every renal function."},{"step":"4. Explain use and appropriate self-care","detail":"Give the exact prescription directions and relevant adverse-effect advice, and discuss suitable analgesia and enough fluids to avoid dehydration. Do not promise that cranberry products or urinary alkalinising agents treat the acute infection, or prescribe an unassessed universal fluid volume."},{"step":"5. Review culture and response together","detail":"If culture was sent, review the result and action. In non-pregnant women, NG109 advises changing according to susceptibility if bacteria are resistant and symptoms are not already improving, using a narrow-spectrum option when possible. Pregnancy has different result-action recommendations. Do not ignore a significant result or automatically extend treatment without the context."},{"step":"6. Specify reassessment","detail":"Reassess if symptoms worsen rapidly/significantly, do not start improving within 48 hours of taking the antibiotic, or the person becomes systemically very unwell. Confirm who reviews results and what to do for failed contact, intolerance or recurrent/persistent symptoms."}],"discussion":[{"cue":"Do I need antibiotics immediately?","response":"That depends on how severe this is, your risk of complications and what you prefer after we discuss the options. In an appropriate non-pregnant lower-UTI situation, we can use an immediate or a back-up prescription. I will explain which I recommend for you and exactly when to use it.","simple":"Let’s choose immediate or back-up treatment from your symptoms, risks and preference, with clear instructions.","why":"Make a recommendation for the assessed context rather than present the two strategies as suitable for every patient.","id":"renal-lower-uti-talk-1"},{"cue":"Can I use the same short course as a friend?","response":"Please do not share antibiotics. The right medicine and length depend on pregnancy, kidney function, other medicines and the type of infection. We should agree your actual prescription after those checks.","simple":"The medicine and course must fit your assessment. Please do not copy or share a prescription.","why":"Prevent transfer of the ordinary non-pregnant regimen to pregnancy, renal impairment, men or upper infection.","id":"renal-lower-uti-talk-2"},{"cue":"If I get a fever, should I just start the back-up and wait?","response":"A fever, pain in the side or back, vomiting or feeling significantly unwell can change the assessment. Please seek advice promptly rather than assume the same lower-UTI plan is still enough. Severe illness or signs of sepsis need emergency help.","simple":"New fever, flank pain, vomiting or serious illness needs reassessment, not simply waiting on the old plan.","why":"Explain that a significant clinical change can override the back-up timing and need a different treatment/setting.","id":"renal-lower-uti-talk-3"},{"cue":"What if the laboratory says the antibiotic is resistant but I am improving?","response":"We should review the result and how you are doing together. The right action depends on your situation, including pregnancy and any remaining symptoms. I will explain whether a change is needed rather than leave you to interpret the report alone.","simple":"Let’s review the culture and your response together before deciding whether treatment changes.","why":"Use population-specific NG109 culture advice; do not automatically ignore resistance or switch every improving non-pregnant patient.","id":"renal-lower-uti-talk-4"},{"cue":"When should I contact you if it is not helping?","response":"Contact us if symptoms worsen significantly at any time, you feel generally very unwell, or they have not started improving within forty-eight hours of taking the antibiotic. We will also agree how any urine result is checked and how you will hear about a change.","simple":"Seek review for worsening, serious illness or no improvement within 48 hours of antibiotics; we will check any culture result.","why":"Give a clear reassessment route and result ownership rather than an open-ended prescription.","id":"renal-lower-uti-talk-5"}],"variations":[{"label":"Pregnancy is possible or confirmed","change":"The patient is pregnant or pregnancy is newly identified.","action":"Use the pregnancy lower-UTI pathway: immediate appropriate antibiotic and pre-treatment midstream culture, with prompt review of results and medicine/course suitability. Do not reuse the ordinary three-day example or delay care for an unreturned sample when clinically urgent.","phrase":"Pregnancy changes the testing and treatment plan. Let’s choose the right prescription and arrange the sample and review promptly."},{"label":"Fever, flank pain or systemic illness","change":"The person develops upper-UTI symptoms or becomes significantly unwell.","action":"Reassess for pyelonephritis/sepsis and use the appropriate antimicrobial and referral pathway. NG111 recommends hospital referral for signs of serious illness/sepsis, and consideration of referral/specialist advice for dehydration, inability to take oral treatment, pregnancy or higher complication risk.","phrase":"These new symptoms need a fresh assessment today. The simple lower-UTI prescription may not be the right treatment."},{"label":"Renal, allergy or resistance history changes suitability","change":"There is reduced renal function, relevant allergy, recent antibiotic exposure or a resistant previous organism.","action":"Recheck actual agent eligibility, current guidance and the need for culture/alternative treatment. Do not copy a standard nitrofurantoin regimen without the renal and other checks.","phrase":"Your kidney function and medicine history affect the choice. Let’s use a treatment that is suitable for you."}],"pitfalls":["Do not treat every dysuria presentation as an uncomplicated bacterial lower UTI or miss pregnancy/systemic illness.","Do not transfer the three-day example to every patient, share antibiotics or ignore the actual product/renal checks.","Do not give a back-up plan without clear timing, deterioration advice and result ownership."],"safetyNet":["New fever, flank pain, vomiting or significant deterioration needs prompt reassessment for a changed pathway; serious illness/sepsis needs emergency care.","Seek review for symptoms not starting to improve within 48 hours of antibiotic treatment or for relevant adverse effects; follow the actual medicine’s emergency warnings.","Persistent or recurrent visible blood, recurring symptoms or failed contact needs assessment and the appropriate pathway rather than repeated automatic antibiotics."],"followUp":"Agree the actual prescription/strategy and symptom-review triggers, including no improvement within 48 hours of antibiotics. Track any culture and communicate the population-appropriate action. Reassess recurrence, persistent blood and new systemic symptoms rather than repeat the same plan.","reviewed":"2026-11-14","tags":["UTI","dysuria","nitrofurantoin","back-up prescription","pregnancy","renal function","urine culture"],"links":[{"label":"NICE NG109: lower UTI antimicrobial prescribing","url":"https://www.nice.org.uk/guidance/ng109","use":"Immediate/back-up strategies, population-specific courses, culture and review."},{"label":"NICE NG111: acute pyelonephritis","url":"https://www.nice.org.uk/guidance/ng111","use":"Changed upper/systemic symptoms, antibiotic and referral pathways."},{"label":"NHS: urinary tract infections","url":"https://www.nhs.uk/conditions/urinary-tract-infections-utis/","use":"Patient symptoms, help-seeking and treatment information."},{"label":"NHS: nitrofurantoin","url":"https://www.nhs.uk/medicines/nitrofurantoin/","use":"Actual medicine use and adverse-effect/emergency advice."}],"retrieval":{"question":"What makes an immediate/back-up uncomplicated lower-UTI plan unsuitable to copy into a different patient?","answer":"Check pregnancy, sex/age, upper or systemic symptoms, complications, renal function, allergy/resistance and actual medicines. Choose the appropriate pathway and prescription, explain the back-up/review timing and track culture action. New severe symptoms need reassessment rather than waiting for the old plan.","checks":["Defined the actual population and urgency","Checked agent/course suitability","Explained review and culture ownership"]}},{"id":"renal-visible-haematuria","title":"Visible blood in urine: explain investigation without premature reassurance","summary":"Act on unexplained visible haematuria, separate infection and anticoagulation questions and retain referral ownership.","presentation":"A 58-year-old man reports one episode of clearly visible blood in the urine. Appropriate assessment has not identified a UTI or another explanation in this ordinary scenario. He is stable, can pass urine and has no ongoing heavy bleeding. He feels reassured because there was no pain and the urine looks normal again.","assessment":["Clarify true urinary bleeding rather than another source or a colour change: onset, duration, clots, pain, urinary symptoms, ability to pass urine and any recurrence. Assess acute bleeding/retention and clinical stability first.","Review infection symptoms and appropriate urine assessment, stone/renal symptoms, previous urinary history, smoking/occupational risks, relevant examination and blood/renal tests as indicated.","Check anticoagulants/antiplatelets, actual doses, renal function and other medicines. Medication-related bleeding risk does not by itself establish the cause or remove the need to investigate.","Explore cancer worry, beliefs about pain/resolution, practical barriers and the person’s understanding of a suspected-cancer pathway."],"priorities":["Do not dismiss unexplained visible haematuria because it was painless, brief or has stopped.","Choose acute care when needed and arrange/track the appropriate diagnostic referral rather than a reassurance-only repeat urine test."],"management":[{"step":"1. Identify an acute problem first","detail":"Heavy bleeding, instability or inability to pass urine with suspected retention needs urgent/emergency care. Do not leave acute retention waiting for a future cancer appointment; arrange appropriate immediate assessment and drainage by trained clinicians under the local pathway."},{"step":"2. Apply the actual referral criteria","detail":"NG12 recommends suspected-cancer-pathway referral for people aged 45 and over with unexplained visible haematuria without UTI, or visible haematuria that persists or recurs after successful UTI treatment, for bladder/renal cancer assessment. This ordinary 58-year-old meets the unexplained visible-haematuria criterion."},{"step":"3. Explain concern versus confirmation","detail":"Explain that several causes are possible and the pathway is to investigate promptly, not a cancer diagnosis from the symptom alone. Resolution and absence of pain do not cancel the indication in this scenario."},{"step":"4. Keep infection and medicine issues separate","detail":"Treat an actual infection using the correct population-specific guidance and confirm follow-up of blood. Do not give antibiotics simply to postpone investigation. Assess antithrombotic-related bleeding and any medicine changes individually; do not automatically stop all treatment or assume it explains the haematuria."},{"step":"5. Make investigation and referral usable","detail":"Arrange the appropriate tests without delaying indicated referral, check the actual urgent service and explain likely next steps without promising a particular procedure. Confirm the referral is sent/received and give realistic contact expectations using the local pathway."},{"step":"6. Confirm ownership and a deterioration plan","detail":"Name who reviews results and referral outcome, when/how the person hears and what to do if contact is missed. Specify earlier action for retention, heavy bleeding or serious illness; persistent concerns remain the clinical team’s responsibility."}],"discussion":[{"cue":"It only happened once and did not hurt. Can I ignore it?","response":"Even one painless episode can need investigation. Because the visible blood is unexplained in your situation, I recommend the urgent referral pathway rather than assume it is harmless because it stopped.","simple":"One painless episode can still matter. I recommend investigation through the appropriate urgent pathway.","why":"Connect the recommendation to the age and assessed unexplained visible bleeding, not a guarantee about every urinary colour change.","id":"renal-visible-haematuria-talk-1"},{"cue":"Does an urgent cancer referral mean you think I definitely have cancer?","response":"No. It means we should investigate promptly for an important possible cause. Other explanations are possible, and the assessment is how we find out. I will explain the referral and make sure the follow-up is clear.","simple":"The referral checks an important possibility; it does not confirm cancer. Let’s arrange and track the assessment.","why":"Avoid both a confirmed diagnosis and falsely reassuring language that undermines the referral.","id":"renal-visible-haematuria-talk-2"},{"cue":"Could we try antibiotics first just in case?","response":"Antibiotics help when there is an appropriate infection to treat. We have not found that explanation here, so I do not want an unnecessary course to delay the investigation. If infection is identified, we still need to check that the blood resolves and use the right referral advice.","simple":"We should treat an actual infection, not use antibiotics to delay unexplained bleeding assessment.","why":"Apply the distinction between no UTI and persistent/recurrent blood after successful treatment.","id":"renal-visible-haematuria-talk-3"},{"cue":"My blood thinner must be the whole explanation, surely?","response":"It can affect bleeding, but it does not tell us why the blood appeared or remove the need to assess it. We should check the actual medicine, bleeding severity and your other risks before deciding on any medicine change. Please do not stop it without an agreed clinical plan.","simple":"The medicine may affect bleeding, but we still need the cause checked and an individual treatment plan.","why":"Avoid diagnostic closure or a universal instruction to continue/stop anticoagulation regardless of severity.","id":"renal-visible-haematuria-talk-4"},{"cue":"Who will tell me if I have an appointment, and what if it does not come?","response":"I will arrange the referral and the practice will track the response. Let’s agree when and how you should hear, based on the actual service. If you have not heard by then, contact us as a backup; we remain responsible for following it up. Seek urgent help sooner if you cannot pass urine or bleeding becomes heavy.","simple":"We will track the referral and agree a contact date. Call if contact fails; retention or heavy bleeding needs help sooner.","why":"Combine practical ownership with a severity-matched contingency rather than shift the referral to patient chasing alone.","id":"renal-visible-haematuria-talk-5"}],"variations":[{"label":"An actual UTI is identified","change":"The assessment supports infection and an appropriate treatment course is completed.","action":"Treat using the correct population-specific pathway, review culture when indicated and confirm whether visible blood clears. At age 45 or over, persistence/recurrence after successful UTI treatment meets NG12 suspected-cancer criteria.","phrase":"We should treat the infection properly and check the blood has resolved. If it persists or comes back, further urgent assessment is needed."},{"label":"Clots and inability to pass urine","change":"The person develops painful retention or cannot pass urine, with clots or significant bleeding.","action":"Arrange immediate acute urological/emergency assessment rather than wait for the diagnostic referral. CG97 recommends immediate catheterisation for acute retention in men, using the appropriate trained/local pathway.","phrase":"Not being able to pass urine changes the urgency. You need immediate assessment now, not to wait for the referral appointment."},{"label":"Anticoagulation or renal findings complicate care","change":"There is anticoagulant use, significant albuminuria/renal impairment or another finding affecting the differential and treatment.","action":"Assess bleeding/drug risks and renal/urological causes together, using appropriate specialist advice and the relevant pathways. Do not automatically add/stop medicines or cancel the indicated haematuria assessment.","phrase":"These findings affect the investigation and medicine decisions. We need a coordinated plan rather than assume one explanation settles everything."}],"pitfalls":["Do not dismiss visible blood because it is painless, transient or occurs during anticoagulation.","Do not use an unindicated antibiotic course or repeated tests to delay an indicated suspected-cancer referral.","Do not leave retention/heavy bleeding on a routine pathway or make a blanket antithrombotic instruction without assessing risks."],"safetyNet":["Inability to pass urine, painful retention, heavy bleeding or serious deterioration needs urgent/emergency assessment according to severity.","Do not wait for the planned investigation if a new acute problem develops.","If the expected appointment/result contact is missed, contact the practice; the team must track unresolved significant findings and the referral."],"followUp":"Confirm referral receipt and actual contact arrangements, and review significant tests and the specialist outcome. If infection is treated, confirm whether visible blood resolves and act on persistence/recurrence. Keep a named clinician/team responsible for the diagnostic loop and earlier-help advice.","reviewed":"2026-11-14","tags":["haematuria","blood in urine","visible blood","suspected cancer","UTI","anticoagulant","retention"],"links":[{"label":"NICE NG12: bladder and renal warning pathways","url":"https://www.nice.org.uk/guidance/ng12","use":"Age/infection-specific suspected-cancer referral criteria."},{"label":"NHS: blood in urine","url":"https://www.nhs.uk/symptoms/blood-in-urine/","use":"Patient explanation and help-seeking even after a small/first episode."},{"label":"NICE CG97: urinary retention in men","url":"https://www.nice.org.uk/guidance/cg97","use":"Acute retention and appropriate immediate care."},{"label":"NICE NG203: kidney/urinary findings","url":"https://www.nice.org.uk/guidance/ng203","use":"Albuminuria, haematuria and renal assessment/referral context."}],"retrieval":{"question":"How would you explain the need for referral after a single painless episode of visible blood, and what would change the urgency?","answer":"Link the actual age and unexplained visible bleeding to NG12 referral, explain suspicion versus diagnosis, arrange and track the pathway. Actual UTI requires treatment and blood follow-up; anticoagulation is not a complete explanation. Retention, heavy bleeding or illness needs an acute route rather than waiting.","checks":["Used the actual visible-haematuria criteria","Avoided premature reassurance and an unindicated delay","Named referral ownership and acute changes"]}}]},{"id":"reproductive-health","title":"Reproductive and menstrual health","description":"Menopause, heavy periods and early-pregnancy pain/bleeding: individual treatment choices, fertility priorities, uncertainty and changed urgency.","icon":"12","reviewed":"2026-11-14","cases":[{"id":"rh-menopause","title":"Menopause symptoms: choose treatment through an individual risk discussion","summary":"Explain a clinical diagnosis, weigh symptom relief and individual risks, and agree a usable treatment and review plan.","presentation":"A 49-year-old woman has new hot flushes, night sweats and changing periods that disturb sleep and work. She has a uterus, has not started HRT and is worried by conflicting reports about cancer. Appropriate assessment in this ordinary scenario finds no unexplained concerning bleeding or other urgent cause. She wants to understand her choices rather than be given a prescription without discussion.","assessment":["Clarify cycle changes, vasomotor symptoms, sleep, mood, genitourinary symptoms and the impact on daily life. Ask which symptoms matter most and what the person hopes treatment will achieve; consider alternative/coexisting causes when indicated.","Establish age, pregnancy possibility, contraception and actual hormone use, uterus/hysterectomy history, bleeding pattern and any unexplained/postmenopausal bleeding. Do not treat concerning bleeding as a routine menopause symptom.","Review personal and family cancer history, thromboembolism, cardiovascular/stroke history, liver disease, migraine, blood pressure and relevant comorbidity/medicines. Use the actual product contraindications and seek specialist advice when appropriate.","Explore treatment beliefs, preferences, practical use and understanding. Use inclusive language that fits the person rather than assume identity, relationship, fertility goals or sexual concerns."],"priorities":["Link a clinical diagnosis and actual symptom burden to shared treatment choices, not a universal hormone test or HRT regimen.","Give balanced, individual benefits/risks and clear arrangements for use, bleeding advice and review."],"management":[{"step":"1. Explain how the diagnosis is made","detail":"NG23 identifies perimenopause clinically, without laboratory tests, in otherwise healthy people aged 45 or over with recently started vasomotor symptoms and menstrual-cycle changes. Menopause in this group is 12 months without a period when not using hormonal contraception. Hormonal treatment can obscure the pattern; younger or atypical presentations need their own assessment."},{"step":"2. Offer symptom-matched options","detail":"Offer HRT for menopause-associated vasomotor symptoms after suitability and informed discussion. Menopause-specific CBT can be added, or considered when HRT is contraindicated or not preferred. Discuss relevant wellbeing measures and treat other conditions separately; do not routinely use SSRIs/SNRIs or clonidine as first-line treatment for vasomotor symptoms alone."},{"step":"3. Choose formulation and route individually","detail":"For a person with a uterus choosing systemic HRT, offer combined HRT; after total hysterectomy offer oestrogen-only HRT, considering conditions needing specialist advice. Use the lowest effective dose and choose sequential/continuous regimen, route and product for the actual menstrual and clinical context. Consider transdermal rather than oral HRT when VTE risk is increased, including BMI over 30; high VTE risk may need specialist assessment."},{"step":"4. Discuss risks without absolutes","detail":"Use the current NICE discussion aid and individual baseline risks to explain expected symptom benefits and relevant breast/endometrial, clot and cardiovascular considerations. Combined and oestrogen-only HRT have different risk profiles. Do not describe every formulation as identical, risk-free or necessarily unsuitable because of a relative’s history. Review personal cancer, cardiovascular or clot history with appropriate expertise."},{"step":"5. Address other symptoms and newer options correctly","detail":"Vaginal oestrogen is an option for genitourinary symptoms, including alongside systemic HRT; a personal history of breast cancer needs the specific NG23 pathway and appropriate specialist involvement. TA1143 (2026) includes fezolinetant for moderate/severe vasomotor symptoms when HRT is unsuitable. This requires actual eligibility/interactions and MHRA liver-safety checks, not an automatic substitute for anyone declining hormones: liver tests before, monthly for the first three months and periodically thereafter according to clinical judgement; avoid known/high-risk liver disease."},{"step":"6. Explain actual use and ongoing contraception","detail":"Give product-specific instructions, relevant adverse-effect advice and a feasible supply/administration plan. HRT is not contraception; discuss an appropriate contraception plan if needed. Do not invent one standard dose, switch rule or stopping date for all people."},{"step":"7. Review and make bleeding advice current","detail":"Review each treatment at three months, then annually, or earlier for problems. NG23 (2026) explains common bleeding in people with a uterus during the first six months of systemic HRT or within three months of a dose/preparation change, and prompt medical help for unscheduled bleeding beyond these windows. New, heavy, concerning or otherwise unexplained bleeding still needs clinical assessment; do not use a time window to dismiss risk. Use current NG12/local pathways as indicated."}],"discussion":[{"cue":"Do I need a hormone blood test to prove it?","response":"In an otherwise healthy person of your age with these symptoms and changing periods, we can usually identify perimenopause from the history. A routine hormone test may not help. I will still check whether anything suggests a different problem or needs a separate test.","simple":"Your age, symptoms and changing periods usually guide the diagnosis. We should test for other problems if the assessment suggests them.","why":"Give the age/context-specific NG23 approach without implying that all symptoms or younger presentations need no investigation.","id":"rh-menopause-talk-1"},{"cue":"Does HRT always cause cancer?","response":"The risks are not the same for every person or every type of HRT. We should look at your own history, the expected symptom benefit and the risks of the suitable options. I can use the NICE discussion aid to make the size of those risks clearer, then we can decide together.","simple":"Let’s compare the likely benefits and risks for you, using the suitable types and the NICE discussion aid.","why":"Avoid blanket reassurance, alarm or unsupported numerical comparisons; distinguish personal baseline and treatment type.","id":"rh-menopause-talk-2"},{"cue":"Could I just have oestrogen without the other hormone?","response":"Because you have a uterus, systemic oestrogen normally needs a progestogen as part of combined HRT to protect the womb lining. We can discuss suitable ways to provide that and choose a regimen that fits your periods, health and preferences.","simple":"With a uterus, systemic HRT normally includes progestogen to protect the womb lining. Let’s choose a suitable combined option.","why":"Explain the rationale and actual systemic context; do not transfer this statement indiscriminately to local vaginal treatment.","id":"rh-menopause-talk-3"},{"cue":"I cannot use HRT. Am I stuck with the symptoms?","response":"There are other approaches. Menopause-specific CBT can help, and we should discuss options that fit your symptoms and medical history. For moderate to severe hot flushes when HRT is unsuitable, fezolinetant may be an option under current NICE guidance, but it needs medicine checks and liver monitoring.","simple":"We can discuss CBT and other suitable options. Fezolinetant may fit some people who cannot use HRT, with liver-safety checks.","why":"Include the current 2026 option without portraying it as universally suitable or monitoring-free.","id":"rh-menopause-talk-4"},{"cue":"Will HRT stop me becoming pregnant?","response":"No, HRT is not contraception. If pregnancy is possible, let’s discuss reliable contraception alongside the symptom treatment and check that the choices work safely together.","simple":"HRT does not prevent pregnancy. We should agree contraception separately if needed.","why":"Separate symptom treatment from pregnancy prevention and check the actual combined plan.","id":"rh-menopause-talk-5"},{"cue":"If I start treatment, when do we check it and what about bleeding?","response":"We will review it at about three months, then yearly if it is working well, and sooner for problems. I will explain the bleeding pattern expected with your actual regimen and when to contact us promptly. New heavy or concerning bleeding should be assessed rather than simply waiting for the routine review.","simple":"We review at three months, then yearly, or sooner for problems. Let’s agree your regimen’s bleeding and urgent-help advice.","why":"Complete this with the actual regimen, current bleeding windows, concerning features and local contact route; a generic review date is not safety-netting.","id":"rh-menopause-talk-6"}],"variations":[{"label":"Aged under 40 or an atypical presentation","change":"The person is younger, the pattern is unclear or symptoms suggest an alternative cause.","action":"Assess possible premature ovarian insufficiency/other causes using the relevant NG23 pathway, appropriate tests and specialist support. Do not apply the ordinary over-45 clinical-diagnosis rule to everyone.","phrase":"Your age and symptom pattern mean we should investigate this differently rather than assume the same explanation."},{"label":"Personal cancer history or high clot/cardiovascular risk","change":"Past breast cancer, high VTE risk or other important history changes the choice.","action":"Use the specific NG23 risk pathway, actual product information and appropriate specialist advice. Distinguish local vaginal treatment from systemic treatment; do not make a blanket choice from the ordinary scenario.","phrase":"Your previous condition affects which options are appropriate. I will seek the right advice so we can discuss a suitable plan."},{"label":"Unscheduled bleeding or poor response on treatment","change":"Bleeding occurs outside expected windows, is heavy/concerning, or symptoms/side effects persist.","action":"Assess the actual bleeding pattern, regimen and risk factors, using current NG23/NG12 and local pathways. Seek earlier clinical review, and menopause expertise when symptoms or side effects do not improve; do not automatically increase the dose or reassure by time alone.","phrase":"This change needs a review of the bleeding and your treatment. Let’s assess it rather than wait for the annual check."}],"pitfalls":["Do not reduce a whole consultation to a hormone result or one standard HRT prescription.","Do not say HRT is contraception, describe all formulations as having the same risks or overlook protection of the uterus.","Do not teach the old blanket three-month bleeding rule or dismiss heavy/unexplained bleeding because treatment is recent.","Do not offer newer non-hormonal treatment without eligibility, interaction and liver monitoring checks."],"safetyNet":["Assess new heavy, concerning or unexplained bleeding and use the appropriate urgency/pathway; promptly report unscheduled bleeding beyond the current regimen windows.","Explain actual medicine-specific emergency symptoms, including possible clot/stroke or severe adverse reactions, and the appropriate urgent action.","If using fezolinetant, explain liver monitoring and immediate medical attention for possible liver injury such as jaundice/dark urine, itching, unusual fatigue, abdominal pain or nausea; use current MHRA/product advice."],"followUp":"Agree actual treatment, product instructions, contraception if relevant, written bleeding/adverse-effect advice and contact route. Review at three months then annually or sooner for problems, documenting symptoms that matter, tolerability and individual ongoing benefits/risks. Assign responsibility for required tests and specialist advice.","reviewed":"2026-11-14","tags":["menopause","perimenopause","HRT","hot flushes","shared decision","bleeding","fezolinetant","contraception"],"links":[{"label":"NICE NG23: menopause","url":"https://www.nice.org.uk/guidance/ng23","use":"Clinical diagnosis, individual treatment, 2026 bleeding advice and review."},{"label":"NICE TA1143: fezolinetant","url":"https://www.nice.org.uk/guidance/ta1143","use":"2026 recommendation for moderate/severe vasomotor symptoms when HRT is unsuitable."},{"label":"MHRA: fezolinetant liver safety","url":"https://www.gov.uk/drug-safety-update/fezolinetantv-veoza-risk-of-liver-injury-new-recommendations-to-minimise-risk","use":"Eligibility, liver tests and liver-injury warnings."},{"label":"NHS: HRT","url":"https://www.nhs.uk/medicines/hormone-replacement-therapy-hrt/","use":"Patient explanations, types, practical use and adverse effects."},{"label":"NICE NG12: suspected cancer","url":"https://www.nice.org.uk/guidance/ng12","use":"Current assessment/referral context for concerning bleeding."}],"retrieval":{"question":"How would you turn a request for HRT into a clear individual decision and follow-up plan?","answer":"Assess symptoms/alternative causes, age and bleeding, pregnancy/contraception, uterus and individual risks. Explain suitable benefits/options, choose actual regimen/route with appropriate expertise, include progestogen for systemic HRT with a uterus, and agree product use, current bleeding advice, tests and three-month/annual review. Newer options still need safety checks.","checks":["Connected the diagnosis and symptom goals to the actual person","Explained a suitable treatment and individual risks","Owned medicine use, bleeding advice, monitoring and review"]}},{"id":"rh-heavy-periods","title":"Heavy periods: agree treatment around impact, cause and fertility","summary":"Assess anaemia and bleeding pattern, select appropriate investigation and offer options that respect pregnancy and treatment preferences.","presentation":"A 38-year-old woman reports regular but increasingly heavy periods that disrupt work and exercise. She is stable, has no intermenstrual or postcoital bleeding and no features suggesting pregnancy in the assessed ordinary scenario. She wants symptom relief but is uncertain about an intrauterine system. History suggests a low risk of uterine-cavity or other significant pathology; this must be reassessed if the story changes.","assessment":["Ask about bleeding pattern, flooding/clots, duration, cycle regularity and impact on daily life. Clarify pain/pressure, intermenstrual or postcoital bleeding and any other concerning change. Assess acute heavy loss, faintness, breathlessness and other symptoms suggesting significant anaemia or instability.","Establish pregnancy possibility, contraception, fertility plans, medicines including anticoagulants, relevant comorbidity and previous treatment. Do not assume a person who does not want pregnancy now never wants future fertility.","Arrange full blood count in parallel with treatment for HMB. Consider coagulation-disorder testing when heavy bleeding has been present since periods began and personal/family history suggests a disorder. Do not routinely order female hormone tests, or thyroid tests without other thyroid features.","Use history and appropriate consented examination to judge pathology risk and investigation. Explain choices, pain/trauma concerns, chaperone and the right to pause/decline; a treatment involving LNG-IUS requires examination before insertion."],"priorities":["Take quality-of-life impact seriously, assess severity/anaemia and avoid a one-size-fits-all scan or medicine.","Choose treatment and investigation using pathology risk, contraindications, preference and fertility goals."],"management":[{"step":"1. Treat urgent bleeding differently","detail":"Acute severe bleeding, collapse, instability or serious anaemia symptoms needs urgent/emergency assessment. The ordinary stable HMB pathway does not justify waiting through deterioration."},{"step":"2. Assess and investigate proportionately","detail":"NG88 allows pharmacological treatment without investigating the cause first when history/examination suggests low risk of fibroids, cavity/histological abnormality or adenomyosis. Full blood count remains part of care. Use history and examination to choose hysteroscopy or ultrasound rather than give every person the same investigation."},{"step":"3. Choose the right test when the story suggests pathology","detail":"Persistent intermenstrual bleeding or endometrial-risk features can warrant outpatient hysteroscopy. Suspected mass/larger fibroids or difficult examination can warrant pelvic ultrasound; suspected adenomyosis has its own ultrasound recommendation. Consider endometrial biopsy at hysteroscopy for high-risk contexts; NG88 advises against blind biopsy for HMB. Suspected cancer uses NG12."},{"step":"4. Discuss an LNG-IUS without pressure","detail":"Consider an LNG-IUS as first treatment when there is no identified pathology, fibroids under 3 cm without cavity distortion, or suspected/diagnosed adenomyosis, if suitable and acceptable. Explain insertion, contraception, bleeding-pattern changes and that at least six cycles may be needed to see the benefits. Do not use that expectation to dismiss significant deterioration or new red flags."},{"step":"5. Offer suitable alternatives","detail":"If the LNG-IUS is declined or unsuitable, consider tranexamic acid, NSAIDs, combined hormonal contraception or cyclical oral progestogens as appropriate. Check the actual agent’s risks, interactions, renal/other suitability and fertility/pregnancy context before prescribing. Do not force hormonal treatment or describe all options as equally suitable."},{"step":"6. Plan response and further care","detail":"Agree a review based on symptoms, treatment and blood results; diagnose/manage anaemia appropriately. Persistent severe symptoms, failed/declined treatment or significant pathology may need specialist assessment and additional options. Explain effects on fertility before procedures; endometrial ablation is not contraception and future pregnancy should be avoided with effective contraception after it."}],"discussion":[{"cue":"Is this just something I have to put up with?","response":"No. If the bleeding is disrupting your life, it deserves assessment and a discussion about treatment. I would like to understand the pattern, check for anaemia and any features that need investigation, then choose an option that fits your priorities.","simple":"The impact on your life matters. Let’s assess it, check for anaemia and discuss treatment that fits you.","why":"Validate impact without normalising untreated symptoms or promising one cause.","id":"rh-heavy-periods-talk-1"},{"cue":"Will I need every hormone test and a scan?","response":"Not necessarily. We should do a full blood count, and choose other tests from the history and assessment. Some bleeding patterns need a scan or a camera test of the womb; others can start suitable treatment without all those investigations first.","simple":"We need a blood count. Other tests depend on the bleeding pattern and assessment, rather than a standard list for everyone.","why":"Distinguish universal FBC from risk-directed investigation; avoid routine hormone/thyroid panels without indication.","id":"rh-heavy-periods-talk-2"},{"cue":"I do not want the hormonal coil. Will you still help?","response":"Yes. It is one option, not something you have to accept. We can talk through suitable alternatives, including non-hormonal medicines, and weigh their benefits and downsides against your health and pregnancy plans.","simple":"You do not have to choose it. Let’s compare the suitable alternatives and what matters to you.","why":"Respect informed refusal while providing an actual alternative recommendation after suitability checks.","id":"rh-heavy-periods-talk-3"},{"cue":"If I choose the system, will the bleeding stop straight away?","response":"The bleeding pattern can change at first and it may take at least six cycles to see the benefit. I will explain what is expected with the actual device and when you should contact us earlier, so you are not left coping with a worrying change alone.","simple":"It may take six cycles to see the benefit. We will explain expected changes and when to seek review sooner.","why":"Set realistic LNG-IUS expectations without instructing everyone to wait despite worsening or concerning symptoms.","id":"rh-heavy-periods-talk-4"},{"cue":"I might want a baby later. Does that affect the choice?","response":"Yes, that is important. We should choose a treatment that fits your plans and explain what it means for fertility and contraception. Some procedures affect future fertility much more than medicines, so that discussion must come before a decision.","simple":"Your pregnancy plans matter. Let’s choose with future fertility and contraception in mind.","why":"Do not assume completed fertility or imply every bleeding treatment prevents pregnancy.","id":"rh-heavy-periods-talk-5"},{"cue":"What happens if the first treatment does not work?","response":"We will agree when to review the bleeding, how you are feeling and the blood results. If it is not helping, we can reassess the cause and discuss another treatment or specialist advice. Please seek help sooner for very heavy bleeding, faintness, serious breathlessness or a new concerning pattern.","simple":"We will review symptoms and blood results, then adjust or seek specialist advice if needed. Severe bleeding or illness needs help sooner.","why":"Name actual review/result ownership and complete the urgency advice for the assessed severity, rather than promise indefinite repeat prescriptions.","id":"rh-heavy-periods-talk-6"}],"variations":[{"label":"Persistent bleeding between periods","change":"The person now reports persistent intermenstrual bleeding or risk factors for endometrial pathology.","action":"Reassess rather than simply continue the ordinary low-risk pathway. Offer appropriate hysteroscopy/investigation under NG88; consider biopsy at hysteroscopy for high-risk contexts and use NG12 when cancer is suspected.","phrase":"Bleeding between periods changes which tests may help. Let’s review the assessment rather than assume it is the same problem."},{"label":"Pregnancy is possible or acute loss causes illness","change":"A missed/atypical period, positive pregnancy test, pain, collapse or severe ongoing bleeding changes the context.","action":"Assess pregnancy-related causes and clinical stability urgently using the correct pathway. Suspected ectopic pregnancy, instability or severe bleeding is not a routine HMB medication consultation.","phrase":"These symptoms need a different and more urgent assessment. We should not treat them as an ordinary heavy period."},{"label":"Fibroids, treatment failure or future fertility complicates the choice","change":"A larger fibroid, pressure symptoms, failed treatment or fertility priorities changes options.","action":"Use appropriate imaging/specialist review and individual treatment choices. Explain procedure-related fertility implications and contraception after ablation; do not choose surgery by bleeding volume alone.","phrase":"Let’s review what is causing the bleeding and how each option fits your future plans before deciding."}],"pitfalls":["Do not dismiss impact, miss anaemia/acute illness or label pregnancy-related bleeding as an ordinary period.","Do not use routine hormone tests or one imaging test as the answer for every pattern.","Do not pressure someone into an LNG-IUS, ignore contraindications or overlook fertility and contraception.","Do not reassure concerning bleeding on the basis of an expected treatment settling-in period alone."],"safetyNet":["Very heavy bleeding with faintness/collapse, severe breathlessness, chest pain or marked illness needs urgent/emergency help according to severity.","New persistent intermenstrual/postcoital bleeding, concerning pain or possible pregnancy requires reassessment rather than a routine repeat prescription.","Contact the practice if results/contact are missed, treatment is not helping or adverse effects occur; agree actual agent-specific warnings."],"followUp":"Track the full blood count and any cause-directed investigation; communicate results and act on anaemia. Agree treatment-specific review, acceptable bleeding/side-effect expectations and earlier-help advice. If symptoms persist or a new pattern appears, revisit diagnosis, preferences and referral rather than simply renew treatment.","reviewed":"2026-11-14","tags":["heavy periods","HMB","menorrhagia","anaemia","LNG-IUS","tranexamic acid","fertility","intermenstrual bleeding"],"links":[{"label":"NICE NG88: heavy menstrual bleeding","url":"https://www.nice.org.uk/guidance/ng88","use":"Assessment, FBC, investigations, options and fertility discussions."},{"label":"NHS: heavy periods","url":"https://www.nhs.uk/conditions/heavy-periods/","use":"Patient explanation of impact, causes and treatment."},{"label":"NICE NG12: suspected cancer","url":"https://www.nice.org.uk/guidance/ng12","use":"Concerning bleeding and appropriate assessment/referral."},{"label":"NICE NG126: early-pregnancy complications","url":"https://www.nice.org.uk/guidance/ng126","use":"A different pathway when pregnancy-related bleeding/pain is possible."}],"retrieval":{"question":"What must you establish before recommending one treatment for heavy periods, and how would you respond if an LNG-IUS is declined?","answer":"Assess severity, pattern/red flags, pregnancy possibility, anaemia and pathology risk, actual medicines/risks and fertility priorities. Arrange FBC and cause-directed investigation. Explain a suitable recommendation; if LNG-IUS is declined/unsuitable, offer appropriate alternatives after agent checks. Agree result ownership, review and deterioration advice.","checks":["Assessed impact, pregnancy, urgency and anaemia","Selected investigation/treatment using the actual risk and fertility context","Respected preference and owned follow-up"]}},{"id":"rh-early-pregnancy","title":"Early-pregnancy pain and bleeding: act safely while the diagnosis is uncertain","summary":"Recognise ectopic risk, arrange the right immediate assessment and explain scans, uncertainty and follow-up without false reassurance.","presentation":"A 29-year-old with a positive pregnancy test, approximately seven weeks since the last period, reports light vaginal bleeding and one-sided lower abdominal pain. No scan has yet confirmed the pregnancy location. She is distressed and asks whether this is definitely a miscarriage. She initially reports no collapse, severe ongoing pain or heavy bleeding, but needs prompt assessment; stability must be checked rather than assumed remotely.","assessment":["Establish current location/contact details if remote, pain severity/location and onset, bleeding amount, shoulder-tip pain, faintness/collapse, dizziness and systemic illness. Assess observations and clinical stability in the appropriate setting; significant pain/bleeding or instability requires the acute route.","Clarify positive test, last period and dating uncertainty, previous scan and whether an intrauterine pregnancy was actually confirmed. Pregnancy symptoms, passage of tissue or absence of known risk factors cannot alone exclude ectopic pregnancy.","Ask relevant pregnancy/ectopic/miscarriage history, fertility treatment, actual contraception and medicines, relevant medical/surgical history and support. A pregnancy can be possible despite non-specific gastrointestinal/urinary symptoms or no previous positive home test.","Acknowledge distress, avoid assumptions about whether the pregnancy was planned or wanted, ask consent for examination/scans and discuss communication/support preferences. Do not require a complete routine history before time-critical action."],"priorities":["Pain and bleeding with an unlocated early pregnancy needs an appropriate assessment pathway, not a remote definitive diagnosis.","Provide clear urgency, practical handover and ownership until pregnancy location/outcome is established."],"management":[{"step":"1. Change the route for acute danger","detail":"NG126 recommends direct A&E referral for haemodynamic instability or significant concern about pain/bleeding. Severe pain, collapse/faintness, pallor or heavy bleeding can indicate a serious complication; arrange emergency help as clinically indicated. Do not ask the person to drive or wait for a routine scan when unwell."},{"step":"2. Arrange assessment now in the ordinary scenario","detail":"At about seven weeks with pain and bleeding and no confirmed location, arrange early-pregnancy assessment or out-of-hours gynaecology according to clinical urgency. A positive test with abdominal/pelvic/cervical motion tenderness on examination requires immediate referral under NG126. Lack of risk factors does not exclude ectopic pregnancy; do not simply repeat a home test in a week for this scenario."},{"step":"3. Explain investigations and their limits","detail":"Specialist assessment generally includes appropriate ultrasound, often transvaginal with consent, to identify location and viability. If unacceptable, discuss transabdominal scanning and its limitations. Early or uncertain findings can require a repeat scan at a guideline-appropriate interval; last-period dates or one early scan alone must not establish a false miscarriage diagnosis."},{"step":"4. Own an unknown-location pathway","detail":"A pregnancy of unknown location may be ectopic until location is established. Do not use serum hCG alone to determine location. Clinical symptoms take priority over previous hCG results; serial measurements are usually taken as near as possible to 48 hours apart, no earlier, and interpreted by the responsible service with the full pathway. Give written 24-hour access advice and continue follow-up until a definitive outcome."},{"step":"5. Keep treatment eligibility separate from reassurance","detail":"Do not give progesterone automatically before location is known. Current NG126 offers vaginal micronised progesterone 400 mg twice daily for scan-confirmed intrauterine pregnancy with bleeding and a previous miscarriage; if fetal heartbeat is confirmed, continue to 16 completed weeks, with actual prescribing responsibility and suitability checks. Confirmed miscarriage has its own shared expectant/medical/surgical choices and follow-up, not an assumed treatment from symptoms alone."},{"step":"6. Use the current anti-D pathway","detail":"NG126 changed in June 2026: do not offer anti-D for ectopic pregnancy, miscarriage or threatened miscarriage up to and including 11+6 weeks. For RhD-negative people at 12+0 to 12+6 weeks, offer at least 250 IU for medical/surgical management of ectopic pregnancy or miscarriage; consider it for threatened miscarriage with heavy or recurrent bleeding. Use ultrasound dating if discrepant with last-period dates. Explain the blood-product nature when suitable. Different gestation/other contexts need the relevant current policy; do not use an old blanket rule."},{"step":"7. Give support and close the handover","detail":"Explain the reason for assessment, destination, timing, transport and what may happen. Check access, language, chosen support and emotional needs. Confirm the receiving service/contact plan and who reviews scans/blood results. New/worsening symptoms override waiting for planned tests; avoid promising either a healthy pregnancy or inevitable loss."}],"discussion":[{"cue":"Does bleeding mean I have definitely lost the pregnancy?","response":"Bleeding does not tell us the answer on its own. Because you also have pain and we have not confirmed where the pregnancy is, we need an assessment to check for important causes, including an ectopic pregnancy. I cannot safely confirm the outcome from this call.","simple":"We cannot tell the outcome from bleeding alone. Pain and an unconfirmed location mean you need assessment.","why":"Communicate uncertainty and a clear action without diagnosing miscarriage or offering false reassurance.","id":"rh-early-pregnancy-talk-1"},{"cue":"What is an ectopic pregnancy, and why does it matter today?","response":"It means a pregnancy is developing outside the womb, most often in a fallopian tube. It can cause internal bleeding, so we must consider it with these symptoms. I recommend early-pregnancy assessment now through the appropriate service, and emergency care if you become severely unwell.","simple":"An ectopic pregnancy is outside the womb and can cause dangerous bleeding. We need the right assessment now.","why":"Explain the clinical reason for urgency without suggesting it is already confirmed.","id":"rh-early-pregnancy-talk-2"},{"cue":"I have no risk factors. Could I just wait?","response":"An ectopic pregnancy can happen without known risk factors. Your pain and bleeding still need assessment. Let’s arrange where and when you will be seen rather than rely on the absence of a previous problem.","simple":"No known risk factors does not rule it out. These symptoms still need assessment and a clear arrangement.","why":"Avoid a reassuring history being used to cancel assessment of the actual symptoms.","id":"rh-early-pregnancy-talk-3"},{"cue":"What if the scan is too early to give an answer?","response":"Sometimes the first scan does not give a definite answer. The team may arrange further scans or blood tests and must explain who will review them. If the location is still unknown, new or worsening pain or bleeding needs fresh advice even if an earlier result seemed reassuring.","simple":"An early scan may need follow-up. We must track the answer, and worsening symptoms need review sooner.","why":"Do not equate a non-diagnostic scan or changing hCG with a safe, confirmed intrauterine pregnancy.","id":"rh-early-pregnancy-talk-4"},{"cue":"Could I have progesterone now to protect the pregnancy?","response":"It helps in a specific situation: bleeding with a previous miscarriage and a pregnancy confirmed inside the womb by a scan. The assessment comes first here because we do not yet know the location. If you meet the criteria, the team can discuss the correct treatment and who will prescribe and review it.","simple":"Progesterone has specific criteria, including a scan confirming the pregnancy is in the womb. We need the assessment first.","why":"Retain scan-confirmed location and previous-miscarriage eligibility rather than offer a universal preventive prescription.","id":"rh-early-pregnancy-talk-5"},{"cue":"I am frightened. What should I do while waiting to be seen?","response":"Let’s confirm the assessment arrangement and a number you can use at any time if symptoms change. Severe or increasing pain, faintness or collapse, shoulder-tip pain or heavy bleeding needs urgent reassessment; if you are severely unwell, call 999. We can also discuss who you would like with you and how to get there safely.","simple":"We will confirm where to go and a 24-hour contact. Worsening pain or bleeding needs help sooner; collapse or severe illness needs 999.","why":"Match the actual symptoms and route, give practical support and do not let a waiting list replace an acute safety plan.","id":"rh-early-pregnancy-talk-6"}],"variations":[{"label":"Sudden severe pain, pallor or collapse","change":"The person becomes acutely unwell or there is significant concern about bleeding or circulatory compromise.","action":"Arrange emergency assessment/ambulance and appropriate immediate support. Confirm location/callback if remote, avoid self-driving and do not delay for routine tests, records or the standard early-pregnancy appointment.","phrase":"This change needs emergency help now. I will help arrange an ambulance; let’s confirm exactly where you are."},{"label":"Pregnancy remains of unknown location after initial assessment","change":"No definite location is established, and serial hCG/scan follow-up is planned.","action":"Retain responsible-service follow-up until location/outcome is known, with serial hCG/ultrasound interpreted through NG126. Prioritise new symptoms over reassuring previous tests and provide 24-hour access instructions.","phrase":"The location is still not confirmed. We need to complete the follow-up, and new or worsening symptoms need review straight away."},{"label":"Scan-confirmed intrauterine pregnancy and a previous miscarriage","change":"Bleeding continues, but a scan confirms an intrauterine pregnancy and the person has a previous miscarriage.","action":"Discuss the specific NG126 vaginal micronised progesterone offer, actual suitability/prescribing and follow-up; continue to 16 completed weeks if fetal heartbeat is confirmed. Use the current gestation-specific anti-D policy when relevant, not an outdated automatic injection rule.","phrase":"The scan and your previous miscarriage history change which treatment may help. Let’s agree the prescription, review and earlier-help plan."}],"pitfalls":["Do not diagnose miscarriage, exclude ectopic pregnancy or promise viability from bleeding, dates, risk-factor absence or one hCG result.","Do not place a painful seven-week unlocated pregnancy on the less-than-six-week painless-bleeding expectant pathway.","Do not prescribe progesterone without its actual criteria or use outdated anti-D guidance.","Do not leave serial tests or an uncertain scan without a responsible service and 24-hour deterioration route."],"safetyNet":["Severe/worsening abdominal pain, faintness/collapse, pallor, shoulder-tip pain or heavy bleeding requires urgent reassessment; severe illness/collapse needs emergency help/999.","Do not wait for a planned blood test or scan if symptoms worsen, regardless of a previous reassuring result.","Give the actual 24-hour early-pregnancy/gynaecology contact and emergency route, and check that the person can access assessment safely."],"followUp":"Confirm that the receiving service has the referral and the person knows where/when to attend. Assign review of every scan/hCG and continued follow-up until location/outcome is established, with emotional support and a chosen contact route. Treatment-specific follow-up is agreed only once the diagnosis/pathway is known; a positive home test or initial scan is not closure.","reviewed":"2026-11-14","tags":["early pregnancy","ectopic","bleeding","miscarriage","pregnancy of unknown location","progesterone","anti-D","urgent referral"],"links":[{"label":"NICE NG126: initial assessment and referral","url":"https://www.nice.org.uk/guidance/ng126/chapter/Symptoms-and-signs-of-ectopic-pregnancy-and-initial-assessment","use":"Current symptoms, instability and early-pregnancy referral criteria."},{"label":"NICE NG126: ultrasound and unknown location","url":"https://www.nice.org.uk/guidance/ng126/chapter/Diagnosis-of-viable-intrauterine-pregnancy-and-of-tubal-ectopic-pregnancy","use":"Scan uncertainty, symptoms and hCG follow-up."},{"label":"NICE NG126: miscarriage management","url":"https://www.nice.org.uk/guidance/ng126/chapter/Management-of-miscarriage","use":"Threatened-miscarriage progesterone criteria and confirmed-loss choices."},{"label":"NICE NG126: anti-D, updated 2026","url":"https://www.nice.org.uk/guidance/ng126/chapter/Anti-D-immunoglobulin-prophylaxis","use":"Revised gestation- and management-specific prophylaxis recommendations."},{"label":"NHS: ectopic pregnancy","url":"https://www.nhs.uk/conditions/ectopic-pregnancy/","use":"Patient explanations and emergency help-seeking."}],"retrieval":{"question":"How would you manage pain and bleeding at about seven weeks before pregnancy location is confirmed?","answer":"Assess stability and acute danger first; significant pain/bleeding or instability takes the acute route. Arrange appropriate early-pregnancy/gynaecology assessment, explain uncertainty and possible ectopic pregnancy, and do not diagnose the outcome remotely. Track scan/hCG and location with the responsible service, provide 24-hour advice and act sooner for deterioration. Progesterone and anti-D have specific current criteria, not automatic use.","checks":["Recognised acute danger and arranged the right assessment","Explained uncertainty without false reassurance","Owned follow-up and used current treatment criteria"]}}]},{"id":"dermatology","title":"Skin and acne","description":"Changing lesions, cellulitis and acne: proportionate diagnosis, prescribing, patient concerns, meaningful review and urgent changes.","icon":"13","reviewed":"2026-11-14","cases":[{"id":"skin-changing-lesion","title":"A changing skin lesion: explain a suspected-cancer referral clearly","summary":"Assess the actual lesion, avoid reassurance from a poor image or absent pain, and track the diagnostic pathway.","presentation":"A 46-year-old woman has a pigmented lesion that has increased in size and developed an irregular shape over recent months. It does not hurt. The clinician has arranged an appropriate direct skin assessment; in this ordinary scenario the suspicious change meets the NG12 weighted-checklist referral threshold. She asks for a cream or reassurance from a phone photograph.","assessment":["Clarify what changed, when and how quickly: size, shape, colour, bleeding/oozing, inflammation, sensation and any new growth. Ask about relevant previous skin cancer, family history, sun exposure and immune suppression without using their absence to rule out disease.","Assess the lesion appropriately, including site, size and features, with trained dermoscopy when available under the pathway. A low-quality photograph or remote impression cannot safely replace a needed examination. Consider nodular or non-pigmented lesions as well as classical pigmented changes.","Use the NG12 weighted seven-point checklist in its intended context, alongside clinical judgement. Two points each: change in size, irregular shape, irregular colour. One point each: diameter at least 7 mm, inflammation, oozing, change in sensation.","Explore what the person thinks the lesion means, cancer worry, access and communication needs. Obtain consent for appropriate clinical photography and use authorised secure systems; this learning site is not a place for identifiable images."],"priorities":["Recommend the correct assessment/referral from suspicious features rather than wait for pain or a home-treatment response.","Explain suspicion versus diagnosis and retain ownership until specialist assessment/outcome is known."],"management":[{"step":"1. Assess before reassuring","detail":"Arrange a suitable examination when lesion identity or features are uncertain. Document the actual change, site and relevant findings. Do not diagnose benignity from lack of pain, a small size alone or a blurred patient image."},{"step":"2. Apply the relevant NG12 pathway","detail":"Refer a suspicious pigmented lesion with a weighted seven-point score of at least 3 using a suspected-cancer pathway. Also refer if dermoscopy suggests melanoma; consider the pathway for a lesion suggesting nodular melanoma, including non-pigmented lesions. In the ordinary scenario, change in size plus irregular shape scores 4."},{"step":"3. Avoid a treatment trial that delays diagnosis","detail":"Do not use a cream, freezing or another destructive/cosmetic treatment as a substitute for the indicated diagnostic pathway. Excision/biopsy arrangements must follow the appropriate trained specialist/local pathway, not an unplanned removal that loses diagnostic information."},{"step":"4. Explain what the referral means","detail":"State the concern and reason plainly without confirming melanoma. Explain that many lesions have other explanations, but suspicious change needs timely specialist assessment. Use the actual local pathway rather than promise a universal appointment interval or a definite procedure."},{"step":"5. Arrange and track the next step","detail":"Send an adequate referral with actual findings and any authorised images required. Confirm receipt, realistic contact expectations and who reviews the specialist response. Address travel/work/language barriers and make a backup contact route without handing responsibility entirely to patient chasing."},{"step":"6. Review changes and unresolved outcomes","detail":"Give a route for reporting further rapid change, bleeding, ulceration or other concerns while waiting; assess acute significant bleeding separately. Confirm the final diagnosis and required follow-up rather than mark the issue closed when a referral is sent. Offer appropriate sun-protection/skin-awareness advice without implying it treats the current lesion."}],"discussion":[{"cue":"It does not hurt. Does that mean it is harmless?","response":"Pain is not a reliable way to decide whether a skin lesion is harmless. The change in size and shape is what matters here. I recommend the appropriate specialist assessment rather than reassure you just because it is painless.","simple":"A painless lesion can still need checking. Its change in size and shape is why I recommend assessment.","why":"Connect the actual suspicious features to the recommendation; do not imply every painless mole is cancer.","id":"skin-changing-lesion-talk-1"},{"cue":"Can you tell from the photograph that it is fine?","response":"The photograph helps show what you have noticed, but it may not show enough detail to make a safe decision. We should use an appropriate skin assessment and the referral pathway if the features are suspicious.","simple":"The photograph may not show enough. We need the right examination and pathway for these changes.","why":"State the limits of remote images without delaying an already indicated referral for unnecessary extra steps.","id":"skin-changing-lesion-talk-2"},{"cue":"Does a cancer referral mean you have diagnosed melanoma?","response":"No. It means the changes need prompt specialist assessment for an important possible cause. The specialist assessment is how we find out. I will explain the arrangements and make sure the outcome is followed up.","simple":"It is a referral to check a concern, not a confirmed diagnosis. We will arrange and track the assessment.","why":"Balance uncertainty and urgency without either a false diagnosis or reassurance that undermines referral.","id":"skin-changing-lesion-talk-3"},{"cue":"Could I try a cream for a few weeks first?","response":"A cream would not answer the concern about this changing lesion. I do not want to delay the assessment or alter it before the right team has reviewed it. Let’s arrange that next step and discuss any symptoms separately.","simple":"A cream will not settle this concern. Let’s arrange assessment rather than delay it with a treatment trial.","why":"Keep the diagnostic priority clear and avoid destructive/cosmetic treatment of a suspicious lesion.","id":"skin-changing-lesion-talk-4"},{"cue":"I cannot easily take time off. Can we put the referral off?","response":"I understand that attending is difficult. The assessment still matters. What is the main obstacle? We can check the available arrangements and support, while keeping the referral moving.","simple":"What makes attending hardest? Let’s check practical options without leaving the lesion unassessed.","why":"Explore the actual barrier, check service capacity and avoid an open-ended delay.","id":"skin-changing-lesion-talk-5"},{"cue":"What if nobody contacts me?","response":"The practice will track the referral and specialist response. Let’s agree when and how you should hear using the actual service, and who to contact if that does not happen. Please tell us about further concerning changes while waiting rather than assume sending the referral has completed the assessment.","simple":"We will track the referral and agree a contact plan. Call if contact fails or the lesion changes further.","why":"Retain team ownership and give a clear contingency rather than patient chasing alone.","id":"skin-changing-lesion-talk-6"}],"variations":[{"label":"A rapidly growing non-pigmented nodule","change":"The lesion is not a typical dark mole but is growing and suggests nodular melanoma.","action":"Use clinical judgement and the NG12 nodular-melanoma recommendation; do not use absent pigment or a low classical checklist score as a rule-out.","phrase":"This does not have to look like a dark mole to need urgent specialist assessment."},{"label":"A different suspected skin cancer","change":"Features suggest squamous cell or basal cell carcinoma instead.","action":"Use the relevant NG12 pathway: consider suspected-cancer referral for SCC; BCC is usually non-urgent unless delay could significantly affect outcome because of site/size or other particular concern. Do not label all skin-cancer referrals as having identical urgency.","phrase":"The appearance suggests a different type of skin problem, so we should use the right assessment pathway for it."},{"label":"The image is inadequate or the lesion cannot be assessed remotely","change":"A phone/video consultation does not establish the features safely.","action":"Arrange appropriate examination without false reassurance. Where the supplied clinical concern already warrants referral, do not use a repeated photograph request to create avoidable delay.","phrase":"I cannot safely settle this from the image. Let’s arrange the assessment needed to make the next decision."}],"pitfalls":["Do not rule out concern because a lesion is painless, small, non-pigmented or occurs without known risk factors.","Do not replace a suspicious-lesion pathway with a cream, freezing or unplanned cosmetic removal.","Do not equate suspected-cancer referral with confirmed cancer or leave the diagnostic loop unowned."],"safetyNet":["Report further rapid change, bleeding, ulceration or other concerning symptoms while waiting, using the agreed clinical route.","Significant uncontrolled bleeding or acute illness needs urgent assessment rather than waiting for a referral appointment.","If expected contact is missed, contact the practice; the team must continue tracking unresolved suspicious findings."],"followUp":"Confirm referral receipt and actual contact arrangements, review the specialist diagnosis and complete any onward plan. Document how unresolved concern is tracked and how the person can report a change or failed contact. No universal appointment or biopsy promise is made.","reviewed":"2026-11-14","tags":["skin lesion","mole","melanoma","seven-point checklist","suspected cancer","photograph","referral"],"links":[{"label":"NICE NG12: skin cancer pathways","url":"https://www.nice.org.uk/guidance/ng12","use":"Weighted checklist, dermoscopy, nodular melanoma, SCC and BCC referral context."},{"label":"NHS: moles","url":"https://www.nhs.uk/conditions/moles/","use":"Patient explanations of concerning changes and assessment."}],"retrieval":{"question":"What would you say to someone who wants to wait because their changing lesion does not hurt?","answer":"Explain that pain does not determine risk; assess the actual changes and use the relevant NG12 pathway. The example size/shape changes score 4. Explain suspicion versus diagnosis, arrange/track assessment, address attendance barriers and give a change/contact contingency. Do not delay with a cream or destructive treatment.","checks":["Used actual features and the correct pathway","Explained the concern without diagnosing from appearance alone","Owned referral, practical arrangements and follow-up"]}},{"id":"skin-cellulitis","title":"Cellulitis: a suitable antibiotic plan with an early reassessment threshold","summary":"Check the diagnosis and severity, select an appropriate regimen and explain what improvement should look like.","presentation":"A 45-year-old man has a unilateral warm, tender and swollen lower-leg area. Appropriate examination supports uncomplicated cellulitis in this ordinary scenario. He is clinically stable, can take oral medicines and has no features suggesting sepsis, necrotising infection, DVT or orbital involvement. Allergy, medicine history and prescribing suitability are checked before choosing treatment.","assessment":["Establish site, onset, spread, warmth, tenderness, swelling, skin break/injury and possible exposures. Assess severity, systemic symptoms, observations and pain out of proportion; redness can be less visible on darker skin.","Consider alternative diagnoses such as eczema/contact dermatitis, an inflammatory bite reaction, gout, superficial thrombophlebitis or DVT. A red/swollen leg is not automatically a bacterial infection.","Review diabetes, oedema/venous insufficiency, immunosuppression, recurrent episodes, actual medicines/allergy, renal/hepatic suitability, previous antibiotics/culture and relevant MRSA or unusual-pathogen risks.","Assess eye/nose proximity, possible deeper infection, ability to take treatment and access to review. Explore expectations about how quickly the skin returns to normal and any barriers to taking the actual course."],"priorities":["Confirm the likely diagnosis and choose the right care setting before applying a routine oral regimen.","Explain the actual antibiotic, early-help thresholds and the difference between improvement and complete skin recovery."],"management":[{"step":"1. Choose the care setting","detail":"Refer to hospital for suspected serious conditions such as sepsis, necrotising fasciitis, orbital cellulitis, osteomyelitis or septic arthritis. Severe illness, infection near eyes/nose, uncommon pathogens, spread despite oral treatment or inability to take oral therapy warrants appropriate referral/specialist advice under NG141."},{"step":"2. Treat the assessed infection appropriately","detail":"Offer an antibiotic for cellulitis/erysipelas. Oral treatment is first-line when oral medicines can be taken and severity does not require IV therapy. Check the actual agent, allergy, site, exposure, previous results, comorbidity and local guidance. A standard lower-leg course is not the same as eye/nose infection treatment."},{"step":"3. Make the prescription concrete","detail":"As a guideline example for a suitable adult with uncomplicated cellulitis, NG141 lists oral flucloxacillin 500 mg to 1 g four times daily for 5 to 7 days. Choose the actual dose/course for the assessed person and local pathway; alternatives and special sites have different choices. Give actual administration and adverse-effect advice rather than leave a dose range for the person to choose."},{"step":"4. Support recovery and monitor the extent","detail":"Consider marking the edge with a single-use surgical marker and documenting findings to help assess progress; account for less visible redness on darker skin. Discuss appropriate pain relief and elevation where relevant, and address predisposing oedema/eczema/other conditions. Use microbiology in selected circumstances, not a routine swab of intact skin."},{"step":"5. Set an early review threshold","detail":"Reassess for rapid/significant worsening at any time, systemic illness, severe pain out of proportion, or no start of improvement within 2 to 3 days. Some initial spreading may occur, but this must not become a blanket reason to ignore deterioration. Check diagnosis, complications, adherence, previous antibiotics and any relevant results before changing treatment."},{"step":"6. Avoid unnecessary prolongation","detail":"Skin can take time to return to normal after the antibiotic course. Do not automatically extend/change treatment just for residual colour if the clinical picture is improving; assess the whole response. If IV antibiotics are used, review by 48 hours and consider an oral switch when appropriate. Own any result and review plan."}],"discussion":[{"cue":"Is every red, swollen leg cellulitis?","response":"No. Several conditions can look similar, so we need the history and examination before choosing treatment. In this assessed situation the findings support cellulitis, but a change or poor response means we should reconsider the diagnosis and check for complications.","simple":"Not every red leg is an infection. We assess it and reconsider if the course does not fit.","why":"Avoid automatic antibiotics and preserve reassessment of alternatives such as DVT.","id":"skin-cellulitis-talk-1"},{"cue":"Can I use leftover antibiotics?","response":"Please do not. We need a medicine and course that fit the infection site, your allergy and other health factors. I will explain your actual prescription, how to take it and which side effects need advice.","simple":"Let’s use the right prescribed medicine and course for you, rather than leftovers.","why":"Convert a broad guideline range into an individual prescription, not patient-selected dosing.","id":"skin-cellulitis-talk-2"},{"cue":"Will the redness disappear by tomorrow?","response":"It may take time for the skin to look normal, even after treatment. What matters is that the overall problem starts improving. Seek review sooner if it worsens significantly or you feel unwell, and contact us if it has not started improving within two to three days.","simple":"The skin may take longer to look normal. Worsening needs earlier review; no improvement in 2 to 3 days needs reassessment.","why":"Set a response threshold without promising rapid cosmetic recovery or normalising all spread.","id":"skin-cellulitis-talk-3"},{"cue":"What if it becomes much more painful or I get shivery?","response":"Severe or rapidly worsening pain, especially pain that seems out of proportion, or becoming generally very unwell needs urgent assessment. Do not wait for the routine review or simply finish the tablets first. Severe illness or collapse needs emergency help.","simple":"Marked pain or feeling very unwell needs urgent review. Collapse or severe illness needs emergency help now.","why":"Identify a potentially serious changed pathway, including deeper infection/sepsis, rather than dose escalation by telephone alone.","id":"skin-cellulitis-talk-4"},{"cue":"What else can I do to help?","response":"We can discuss suitable pain relief, elevation of the affected leg and care for any skin break or underlying swelling. Let’s also check the medicine schedule is manageable and that you can reach us if it is not improving.","simple":"We can agree pain relief, leg elevation and skin/swelling care, alongside the antibiotic and review plan.","why":"Keep supportive measures individual and avoid treating them as a replacement for antibiotics when indicated.","id":"skin-cellulitis-talk-5"},{"cue":"If the skin is still discoloured at the end, do I need more tablets?","response":"Not automatically. Skin changes can take longer to settle than the infection. We should look at pain, warmth, swelling, spread and how you feel, then decide whether this is recovery or needs another assessment.","simple":"Residual colour alone does not automatically need more antibiotics. Let’s review the whole response.","why":"Avoid unassessed antibiotic extension while retaining a route for persistent active infection or an alternative diagnosis.","id":"skin-cellulitis-talk-6"}],"variations":[{"label":"Systemic illness or pain out of proportion","change":"Pain or illness escalates, with concern for sepsis or deeper infection.","action":"Arrange urgent hospital/emergency assessment for suspected serious infection rather than wait for the 2–3-day response threshold or issue a routine repeat course.","phrase":"This change could be more serious. You need urgent assessment now rather than wait for the tablets to work."},{"label":"Infection near the eye or nose","change":"The site changes to periorbital/near-eye or near-nose infection.","action":"Assess for orbital or other serious complications, use NG141 special-site antibiotics and consider hospital/specialist advice. Eye pain, vision change or orbital signs changes urgency.","phrase":"The site changes the risks and treatment. We need the appropriate eye/specialist assessment rather than use the usual leg-infection plan."},{"label":"No improvement or a recurrent red leg","change":"There is no start of improvement by 2–3 days, or the diagnosis/treatment course is atypical.","action":"Reassess diagnosis, complications, adherence, site/exposure, resistance and underlying conditions. Use appropriate tests and specialist advice rather than automatically extend/change antibiotics.","phrase":"Let’s reassess the leg and treatment response so we can decide what needs to change safely."}],"pitfalls":["Do not diagnose every red swollen leg as cellulitis or rely on redness alone across different skin tones.","Do not wait through systemic deterioration, disproportionate pain or orbital features because a review is booked.","Do not leave the person to choose a dose from a range, prescribe leftovers or extend therapy only for residual colour."],"safetyNet":["Rapid/significant worsening, severe pain out of proportion, serious systemic illness or collapse needs urgent/emergency assessment; suspected sepsis/deeper infection is not a routine follow-up problem.","Seek reassessment if there is no start of improvement within 2–3 days or the course becomes atypical.","Use the actual antibiotic’s advice for allergy/severe adverse effects and agree how to contact the team for intolerance or failed review."],"followUp":"Agree the actual prescription and review/contact arrangements, with a no-improvement threshold of 2–3 days and earlier action for deterioration. Track any indicated culture/result. Reassess persistent symptoms in context, and address underlying skin/oedema conditions after acute care rather than automatically repeat antibiotics.","reviewed":"2026-11-14","tags":["cellulitis","red leg","flucloxacillin","antibiotic","sepsis","pain out of proportion","oedema"],"links":[{"label":"NICE NG141: cellulitis and erysipelas","url":"https://www.nice.org.uk/guidance/ng141","use":"Antibiotic/site choices, reassessment and referral."},{"label":"NHS: cellulitis","url":"https://www.nhs.uk/conditions/cellulitis/","use":"Patient symptoms, recovery, elevation and emergency advice."}],"retrieval":{"question":"What should you explain when starting an assessed uncomplicated cellulitis plan, and what overrides the routine review?","answer":"Confirm diagnosis/setting, check prescribing risks and give the actual antibiotic directions. Explain supportive care and that skin recovery can lag; no start of improvement by 2–3 days needs reassessment. Rapid worsening, systemic illness, disproportionate pain or orbital/deeper infection concern needs urgent action sooner. Review the whole response before extending antibiotics.","checks":["Checked diagnosis, severity and actual antibiotic suitability","Gave early reassessment and severity-matched urgent action","Distinguished clinical improvement from complete skin recovery"]}},{"id":"skin-acne","title":"Acne: explain a treatment course and protect confidence as well as skin","summary":"Choose a suitable regimen, teach realistic use and review, and respond to scarring or psychological distress.","presentation":"A 24-year-old has assessed mild-to-moderate acne affecting confidence and social life. Short, irregular use of over-the-counter products has not helped. In the ordinary scenario there are no nodules, established scarring or acute mental-health danger; pregnancy/pregnancy planning, medicines and product suitability are checked before agreeing a first-line course.","assessment":["Assess acne type, distribution and severity, duration, scarring/pigment change and previous actual products, courses and use. Consider another diagnosis or a contributing medicine/condition when the story suggests it.","Ask about effect on confidence, relationships, work/school and wellbeing without minimising it because the skin looks mild. Assess significant distress, self-harm/suicide risk or body-image concerns and arrange appropriate support/urgent care when indicated.","Establish pregnancy possibility/plans, breastfeeding when relevant, medicines, allergy and other contraindications. Topical retinoids and oral tetracyclines are contraindicated in pregnancy and when planning pregnancy under NG198; choose an appropriate alternative, not a copied standard regimen.","Explore treatment expectations, skin sensitivity, practical application and preference about antibiotics/hormonal options. Explain that acne is not proof of poor hygiene and avoid blame or unsupported restrictive-diet claims."],"priorities":["Choose an evidence-based course that the person can actually use, with realistic time to benefit.","Consider psychological impact, scarring and referral alongside antimicrobial/pregnancy safety."],"management":[{"step":"1. Assess severity and risk before prescribing","detail":"Use NG198 severity and the actual skin/wellbeing assessment to select treatment. Diagnostic uncertainty, nodulocystic/conglobate acne, scarring or significant persistent distress may require specialist input; acne fulminans needs same-day on-call dermatology referral for assessment within 24 hours."},{"step":"2. Agree a suitable first-line course","detail":"Offer a 12-week first-line course chosen from NG198 according to severity, preference and contraindications. For a suitable non-pregnant person not planning pregnancy, fixed topical adapalene/benzoyl peroxide is one listed option; it is not suitable for every context. Benzoyl peroxide alone can be an alternative when listed combinations are contraindicated or the person wishes to avoid a retinoid or antibiotic."},{"step":"3. Teach actual application and expected response","detail":"Give product-specific amount, area, timing and skin/eye precautions. Positive effects may take 6–8 weeks to become noticeable. For irritation-prone topical options, NG198 supports starting alternate-day or short-contact application and progressing to the standard application if tolerated. Distinguish manageable irritation from a severe reaction requiring review."},{"step":"4. Use antibiotics with stewardship","detail":"Do not use topical-antibiotic monotherapy, oral-antibiotic monotherapy or combine a topical antibiotic with an oral antibiotic for acne. Moderate/severe disease may need an appropriate oral antibiotic with the correct non-antibiotic topical regimen after suitability checks. Explain resistance and avoid indefinite antibiotic continuation."},{"step":"5. Review at 12 weeks and act on the response","detail":"Review improvement and side effects. For an oral-antibiotic regimen, if clear consider stopping the antibiotic while continuing topical treatment; if improved but not clear, consider up to 12 further weeks with topical treatment. Antibiotic treatment beyond six months should be exceptional, reviewed three-monthly and stopped as soon as possible. Use the current failure/referral pathway rather than repeat an ineffective course indefinitely."},{"step":"6. Escalate appropriately and use current isotretinoin safeguards","detail":"Refer/consider referral according to severity, scarring, persistent pigmentary change, failed appropriate courses or psychological impact. Isotretinoin requires expertise and current MHRA safeguards, including pregnancy prevention where relevant and mental-health/sexual-function assessment and monitoring. January 2026 MHRA guidance removed the automatic second-prescriber requirement for under-18s but retained other safeguards and updated risk materials; do not teach the superseded rule or routine unsupervised primary-care initiation."},{"step":"7. Support skin care and wellbeing","detail":"Discuss gentle appropriate cleansing, non-comedogenic products and avoiding picking. Give actual product photosensitivity/bleaching advice as relevant. Provide a route for side effects, worsening or distress before the booked review; treatment must not leave mental-health risk unattended."}],"discussion":[{"cue":"Is it my fault because I do not wash enough?","response":"No. Acne is not a sign that you are dirty. Harsh scrubbing can irritate the skin. Let’s choose suitable skin care and a treatment plan, and talk about how it is affecting you.","simple":"It is not a sign of poor hygiene. Gentle skin care and the right treatment are more helpful than scrubbing.","why":"Reduce blame and invite psychological impact rather than give hygiene moralising.","id":"skin-acne-talk-1"},{"cue":"Can I tell in a week whether the treatment works?","response":"It often takes six to eight weeks before a noticeable benefit, so we should agree a proper course and review at twelve weeks. I will show you how to use the actual product and what to do if it irritates your skin.","simple":"Benefit may take 6–8 weeks. We will explain the product and review the course at 12 weeks.","why":"Set realistic expectations without telling someone to tolerate severe reactions or distress until the review.","id":"skin-acne-talk-2"},{"cue":"The cream stings. Should I apply more to make it work faster?","response":"Please do not increase it beyond the directions. With some products we can start less often or use short-contact application, then build up if tolerated. We should check which product you have and how severe the reaction is before adjusting it.","simple":"More is not better. Let’s check the product and reaction, then agree a tolerable, safe application plan.","why":"Use actual product guidance and distinguish irritation from a serious reaction.","id":"skin-acne-talk-3"},{"cue":"Could I just have antibiotics on their own?","response":"That is not the recommended acne approach. If an oral antibiotic is appropriate, it needs the right accompanying treatment and a planned review. We should choose a regimen for your severity and health, rather than continue antibiotics indefinitely.","simple":"Antibiotics should not be used alone for acne. Let’s choose the right combination and review plan.","why":"Preserve NG198 stewardship and avoid oral/topical antibiotic duplication.","id":"skin-acne-talk-4"},{"cue":"I might try for a baby soon. Does that change the choice?","response":"Yes. Some acne treatments must not be used in pregnancy or when planning pregnancy, including topical retinoids and oral tetracyclines. Let’s review your actual medicines and choose a suitable plan before starting.","simple":"Pregnancy plans change which treatments are suitable. We need to check the actual products and alternatives first.","why":"Do not copy the ordinary topical-retinoid option into a different pregnancy context.","id":"skin-acne-talk-5"},{"cue":"It looks mild to other people, but I am avoiding everyone.","response":"The effect on your life matters, even if someone else thinks the skin looks mild. Could you tell me how it has been affecting you? We should consider both the skin treatment and the support you need, and check whether there are any immediate safety concerns.","simple":"How it affects you matters. Tell me more so we can plan skin treatment and the right support together.","why":"Respond to distress, assess risk and consider appropriate referral without promising an automated score or a particular drug.","id":"skin-acne-talk-6"}],"variations":[{"label":"Pregnancy, planning pregnancy or breastfeeding","change":"The person’s reproductive/feeding context changes treatment suitability.","action":"Review every actual product and use current NG198/prescribing advice. Topical retinoids and oral tetracyclines are contraindicated in pregnancy/planning; breastfeeding has additional product-specific restrictions. Do not merely reduce the same unsuitable dose.","phrase":"Your plans change which products are safe. Let’s choose a suitable treatment rather than continue the old one automatically."},{"label":"Nodules, scarring or failed courses","change":"Acne is nodulocystic, is causing scarring or has not responded to appropriate completed courses.","action":"Use the appropriate NG198 referral pathway and document previous actual treatment. If isotretinoin is considered, use current specialist expertise and MHRA safety arrangements, not an outdated under-18 two-prescriber rule or an automatic prescription.","phrase":"These features mean specialist options may help. Let’s arrange the right assessment with a clear record of what you have tried."},{"label":"Severe distress or a sudden severe inflammatory illness","change":"There is significant mental-health risk, or a presentation suggesting acne fulminans.","action":"Assess immediate safety and arrange appropriate urgent mental-health care when needed. Suspected acne fulminans needs same-day on-call dermatology referral, assessed within 24 hours. Do not leave either problem waiting for a routine 12-week review.","phrase":"This needs help sooner than the routine treatment review. Let’s arrange the right urgent assessment now."}],"pitfalls":["Do not dismiss psychological impact because acne appears mild or blame hygiene/diet without evidence.","Do not promise immediate benefit, use antibiotic monotherapy/dual antibiotic combinations or extend antibiotics indefinitely.","Do not miss pregnancy/plans, scarring, severe distress or acne fulminans.","Do not teach superseded isotretinoin approval rules or overlook current pregnancy/mental-health/sexual-function safeguards."],"safetyNet":["Severe reaction, rapidly worsening illness or significant psychological distress needs earlier review; immediate danger requires urgent/emergency support.","Do not wait twelve weeks for a potentially unsafe product in pregnancy/planning or a serious adverse effect.","Report scarring, marked worsening or inability to use the agreed course so the plan can be reviewed rather than abandoned silently."],"followUp":"Agree actual product use, a 12-week review and earlier access for adverse effects/worsening/distress. Review response, use and wellbeing, apply antibiotic stop/extension criteria and document a referral when indicated. Track specialist contact and any safety monitoring instead of assuming referral or a prescription completes care.","reviewed":"2026-11-14","tags":["acne","adapalene","benzoyl peroxide","antibiotics","pregnancy","scarring","isotretinoin","confidence"],"links":[{"label":"NICE NG198: acne vulgaris","url":"https://www.nice.org.uk/guidance/ng198","use":"Treatment combinations, timelines, pregnancy considerations, referral and review."},{"label":"MHRA: isotretinoin requirements, January 2026","url":"https://www.gov.uk/drug-safety-update/isotretinoin-changes-to-prescribing-guidance-and-additional-risk-minimisation-measures","use":"Current prescribing expertise, revised under-18 measures and continuing risk monitoring."},{"label":"NHS: acne","url":"https://www.nhs.uk/conditions/acne/","use":"Patient explanations, treatment and psychological support."}],"retrieval":{"question":"How would you explain a first acne course so the person can use it safely and knows when the plan changes?","answer":"Assess severity, wellbeing, scarring and pregnancy/prescribing context; choose a suitable NG198 12-week regimen. Explain actual application, irritation support and 6–8-week time to benefit, with earlier access for problems. Avoid antibiotic monotherapy/duplication, review at 12 weeks and refer for relevant severity, failure or distress. Use current MHRA safeguards for isotretinoin.","checks":["Chose the actual regimen using severity and safety context","Explained use, benefit timing and review","Addressed distress/scarring and appropriate escalation"]}}]}];
